// ============================================================
//  TTRPG Discord Bot — single file edition
//  Requires: discord.js, better-sqlite3, dotenv
// ============================================================

require('dotenv').config();
const { Client, GatewayIntentBits, SlashCommandBuilder, PermissionFlagsBits, MessageFlags, REST, Routes } = require('discord.js');

// Refusals said often enough that they deserve one home.
const MSG_NO_ACCESS_FULL = '❌ I can\'t access this channel. Check my View Channel and Send Messages permissions.';
const MSG_NO_ACCESS = '❌ I can\'t access this channel.';
const MSG_NO_ACCESS_HERE = '❌ I can\'t access this channel. Check my View Channel and Send Messages permissions here.';
const MSG_PICK_TEXT = '❌ Pick a text channel or thread.';

const Database = require('better-sqlite3');
const path = require('path');

// ─────────────────────────────────────────────
//  DATABASE
// ─────────────────────────────────────────────

const fs = require('fs');
// Always write to the persistent volume path, fall back to local for dev
const DB_PATH = '/app/data/ttrpg.db';
const dbDir = path.dirname(DB_PATH);
if (!fs.existsSync(dbDir)) fs.mkdirSync(dbDir, { recursive: true });
const db = new Database(DB_PATH);
console.log('Database path:', DB_PATH);
db.pragma('journal_mode = WAL');

// ── Schema migrations ─────────────────────────────────────────────────────────
// The backup channel holds one file: the newest. This remembers which post that
// is, so each backup can replace the last rather than piling up.
// setInterval starts counting from process start, so on a server that deploys
// often the 24-hour timer never reached zero and no automatic backup ever ran.
// The last run is stored instead, and checked shortly after boot — so the cycle
// is a real day rather than a day of uninterrupted uptime.
// The last error each background job reported, so a repeated failure is
// announced once rather than every cycle. A table rather than a column per job,
// because job names carry spaces and brackets and there is one per schedule.
try { db.exec(`CREATE TABLE IF NOT EXISTS job_failures (
  guild_id TEXT NOT NULL, job TEXT NOT NULL, message TEXT, at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, job)
)`); } catch (e) { console.error('job_failures schema', e); }
// The audit's own catch: this mirror shipped writing to a column npcs
// never had — the same phantom class as the chars table, caught here
// before a live spend found it. Column first, then a ONE-TIME backfill:
// the flag matters because "spent to zero" and "never filled" are the
// same value, and a per-boot backfill would quietly refill spent pools
// on every redeploy, which is rest's job and nobody else's.
try { db.exec('CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT)'); } catch {}
try {
  if (!db.prepare("SELECT 1 FROM meta WHERE k='npc_rr_backfill_1'").get()) {
    db.exec('UPDATE npcs SET rerolls_current = lck WHERE rerolls_current = 0 AND lck > 0');
    db.prepare("INSERT INTO meta (k, v) VALUES ('npc_rr_backfill_1', '1')").run();
  }
} catch {}
// Rest restore amounts. Stored as text tokens so GMs can use either form:
//   "100%" = percentage of that resource's max   |   "3" = flat, set the value to exactly 3
// Defaults: Long rest = full (100%). Short rest = HP only (50%), no rerolls/heal.
try { db.exec("ALTER TABLE guild_config ADD COLUMN lrest_hp TEXT DEFAULT '100%'"); } catch {}
try { db.exec("ALTER TABLE guild_config ADD COLUMN lrest_rerolls TEXT DEFAULT '100%'"); } catch {}
try { db.exec("ALTER TABLE guild_config ADD COLUMN lrest_heal TEXT DEFAULT '100%'"); } catch {}
try { db.exec("ALTER TABLE guild_config ADD COLUMN srest_hp TEXT DEFAULT '50%'"); } catch {}
try { db.exec("ALTER TABLE guild_config ADD COLUMN srest_rerolls TEXT DEFAULT '0%'"); } catch {}
try { db.exec("ALTER TABLE guild_config ADD COLUMN srest_heal TEXT DEFAULT '0%'"); } catch {}
try { db.exec("ALTER TABLE characters ADD COLUMN class TEXT DEFAULT NULL"); } catch {}
try { db.exec("ALTER TABLE characters ADD COLUMN weapon1 TEXT DEFAULT NULL"); } catch {}
try { db.exec("ALTER TABLE characters ADD COLUMN weapon2 TEXT DEFAULT NULL"); } catch {}
try { db.exec("ALTER TABLE characters ADD COLUMN weapon1emoji TEXT DEFAULT '⚔️'"); } catch {}
try { db.exec("ALTER TABLE characters ADD COLUMN weapon2emoji TEXT DEFAULT '🗡️'"); } catch {}
try { db.exec("CREATE TABLE IF NOT EXISTS weapons (guild_id TEXT NOT NULL, name TEXT NOT NULL, PRIMARY KEY (guild_id, name))"); } catch {}
// What a weapon lets you fight with. Stored as pipe-separated stat keys, the
// same shape activities use — empty means no restriction, which is what every
// weapon on an existing server already is.
try { db.exec("ALTER TABLE fights ADD COLUMN atk_mode TEXT DEFAULT 'normal'"); } catch {}
try { db.exec("ALTER TABLE fights ADD COLUMN def_mode TEXT DEFAULT 'normal'"); } catch {}
try { db.exec("ALTER TABLE fights ADD COLUMN rr_state TEXT DEFAULT '{}'"); } catch {}
// The queue must survive the Discord message: a post can fail, be deleted, or
// land somewhere nobody reads. These two make the database the record of truth.
// Why a GM turned a sheet down, so the player knows what to change.
// The emoji columns carry a default (⚔️/🗡️), so their value can't tell us whether
// a player actually picked one. These record that they did, per slot, so a sheet
// can be required to be finished before a GM ever sees it.
// The ALTER only succeeds on the boot that introduces the column, so the
// backfill beside it runs exactly once. Without it, every character approved
// before this existed would be told to choose an emoji they already have the
// moment they next edited their sheet.
try {
  db.exec('ALTER TABLE characters ADD COLUMN weapon1emoji_set INTEGER DEFAULT 0');
  db.exec("UPDATE characters SET weapon1emoji_set=1 WHERE weapon1 IS NOT NULL AND TRIM(weapon1) <> '' AND weapon1emoji IS NOT NULL");
  console.log('[migrate] existing weapon 1 emoji choices preserved');
} catch {}
try {
  db.exec('ALTER TABLE characters ADD COLUMN weapon2emoji_set INTEGER DEFAULT 0');
  db.exec("UPDATE characters SET weapon2emoji_set=1 WHERE weapon2 IS NOT NULL AND TRIM(weapon2) <> '' AND weapon2emoji IS NOT NULL");
  console.log('[migrate] existing weapon 2 emoji choices preserved');
} catch {}

// ── Quest timing ─────────────────────────────────────────────────────────────
// A quest runs on a stopwatch: started_at is when the current stretch began,
// elapsed_ms is everything banked before the last pause. Elapsed time is
// therefore (elapsed_ms + now - started_at) while running, or just elapsed_ms
// while paused — so a pause can't lose time and a restart can't invent it.
try { db.exec(`CREATE TABLE IF NOT EXISTS quest_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  guild_id TEXT NOT NULL, number INTEGER NOT NULL,
  at_ms INTEGER NOT NULL, kind TEXT NOT NULL, text TEXT, actor TEXT,
  wall_at INTEGER NOT NULL
)`); } catch (e) { console.error('quest_events schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS quest_summaries (
  guild_id TEXT NOT NULL, number INTEGER NOT NULL, user_id TEXT NOT NULL,
  quest_name TEXT NOT NULL, url TEXT, duration_ms INTEGER NOT NULL DEFAULT 0,
  ended_at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, number, user_id)
)`); } catch (e) { console.error('quest_summaries schema', e); }
// Where the command PDFs are published, which repository they come from, the
// message currently holding them, and the file versions last seen — so a poll
// can tell "nothing has changed" from "there is a new build".
// The last thing that went wrong, so a repeated failure is reported once rather
// than every quarter of an hour — and so it is reported at all. Logging to the
// console meant a misconfigured repo failed silently for anyone not reading
// Railway's output.
// When it last looked and what it concluded. Without this there is no way to
// tell "hasn't tried yet" from "tried and found nothing new" from "tried and
// failed" — which leaves a manual push as the only way to learn anything.
// A second home for the player book alone, posted quietly — no ping, no
// notification — so a reference channel stays current without nagging anyone.
// Where the fallen are remembered, and the fact of a death itself. A dead
// character keeps its whole record — the sheet, the deeds, the standing — so
// the memorial can be rebuilt and a resurrection loses nothing.
// The GM copy carries the full account and the revive button; the public one is
// the story without the bookkeeping. Both message ids are kept so a revival can
// clear the pair.
// A forum where each approved character gets a page of their own. The thread is
// the character's; the bot only needs to know which thread belongs to whom so it
// can link to it.
// Standing buttons a GM plants in a channel; the ledger only exists so
// `once:true` can hold a player to a single press (T, 2026-08-16).
// Temporary targets: something to swing at that lives in a channel, not
// on the roster. No HP — the GM's judgement is the death check (T,
// 2026-08-16). Disposable by design: nothing to clean up afterwards.
// Titles and associations, for players and NPCs alike — one table each,
// keyed by fighter id, so a knight and a shopkeeper are recorded the same
// way (T, 2026-08-19). Titles are earned or granted; associations are the
// banners someone stands under.
try { db.exec(`CREATE TABLE IF NOT EXISTS subject_titles (
  guild_id TEXT NOT NULL, subject_id TEXT NOT NULL, title TEXT NOT NULL,
  source TEXT, granted_by TEXT, at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, subject_id, title)
)`); } catch (e) { console.error('subject_titles schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS subject_assocs (
  guild_id TEXT NOT NULL, subject_id TEXT NOT NULL, name TEXT NOT NULL,
  note TEXT, at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, subject_id, name)
)`); } catch (e) { console.error('subject_assocs schema', e); }

try { db.exec(`CREATE TABLE IF NOT EXISTS temp_targets (
  guild_id TEXT NOT NULL, message_id TEXT NOT NULL,
  channel_id TEXT NOT NULL, name TEXT NOT NULL,
  dc INTEGER, stat TEXT, dice TEXT, secret INTEGER NOT NULL DEFAULT 0,
  owner TEXT, dead INTEGER NOT NULL DEFAULT 0, hits INTEGER NOT NULL DEFAULT 0,
  created_by TEXT, at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, message_id)
)`); } catch (e) { console.error('temp_targets schema', e); }

try { db.exec(`CREATE TABLE IF NOT EXISTS button_presses (
  guild_id TEXT NOT NULL, message_id TEXT NOT NULL, user_id TEXT NOT NULL,
  at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, message_id, user_id)
)`); } catch (e) { console.error('button_presses schema', e); }
// One chronicle thread per adventurer; a quest's tale is mirrored into the
// thread of everyone who was there (T, 2026-08-16).
try { db.exec(`CREATE TABLE IF NOT EXISTS chronicle_threads (
  guild_id TEXT NOT NULL, user_id TEXT NOT NULL,
  thread_id TEXT NOT NULL, at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, user_id)
)`); } catch (e) { console.error('chronicle_threads schema', e); }
// The character thread's block layout: starter = sheet, plus three
// bot-owned blocks (inventory · lore · dice) edited in place. Hashes let
// the hourly sweep skip blocks that haven't changed — near-zero traffic
// at rest, per T's strain question.
// A duel is a proposal until a GM signs it off. One open proposal per player,
// so the board can't be papered with them.
try { db.exec(`CREATE TABLE IF NOT EXISTS duels (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  guild_id TEXT NOT NULL, channel_id TEXT NOT NULL, opener TEXT NOT NULL,
  fighters TEXT NOT NULL DEFAULT '[]', terms TEXT,
  state TEXT NOT NULL DEFAULT 'open',
  msg_id TEXT, approval_msg_id TEXT,
  created_at INTEGER NOT NULL, decided_by TEXT, decided_at INTEGER, reason TEXT
)`); } catch (e) { console.error('duels schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS char_pages (
  guild_id TEXT NOT NULL, user_id TEXT NOT NULL,
  thread_id TEXT NOT NULL, url TEXT, title TEXT, at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, user_id)
)`); } catch (e) { console.error('char_pages schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS deaths (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  guild_id TEXT NOT NULL, subject_id TEXT NOT NULL, name TEXT NOT NULL,
  order_name TEXT, rank_name TEXT, cause TEXT, quote TEXT, flavour TEXT,
  deeds TEXT, merits INTEGER DEFAULT 0, renown INTEGER DEFAULT 0,
  killed_by TEXT, at INTEGER NOT NULL, msg_id TEXT
)`); } catch (e) { console.error('deaths schema', e); }
// Who is running this one, how they run a table, and — for an instance — which
// quest it was copied from. A quest row is a single party on a single clock, so
// two GMs running the same adventure need two rows; instance_of ties them
// together for the board without merging them.
// An NPC keeps the same records a player does. The page tables are keyed on a
// plain id string, so the fighter id ("npc:Cave Orc") slots straight in — only
// the balances need somewhere to live, since those hang off `characters`.
// An NPC carries what it fights with, the same as a player — otherwise weapon
// stat restrictions could never apply to the side the bot plays.
// Which stat the auto-pilot should reach for. Without this it always takes the
// highest, so a character who fights with finesse over force had no say.
// Hero used to occupy the class slot, which meant a Hero could be nothing else.
// As a flag it sits alongside a class and a knight order, and a GM can toggle
// it without rewriting the sheet. The backfill runs on the boot that adds the
// column, moving anyone whose class said Hero across and freeing that slot.
try {
  db.exec('ALTER TABLE characters ADD COLUMN is_hero INTEGER DEFAULT 0');
  db.exec("UPDATE characters SET is_hero=1, class=NULL WHERE class='Hero' COLLATE NOCASE");
  console.log('[migrate] existing Heroes moved to the hero flag');
} catch {}
try {
  db.exec('ALTER TABLE npcs ADD COLUMN is_hero INTEGER DEFAULT 0');
  db.exec("UPDATE npcs SET is_hero=1, class=NULL WHERE class='Hero' COLLATE NOCASE");
} catch {}
// One reroll per roll. A saved roll is marked the moment it is rerolled, so a
// second attempt on the same result is refused rather than letting someone
// chain rerolls until the dice agree with them.
// Character creation budget, per guild. Defaults match the shipped rules.
// The flat part of the max-HP formula: max HP = CON + hp_base.
// Scheduled recovery: everyone not out on a quest is restored every N hours.
// (autorest_channel: added once, never used — recovery announcements go to
//  the channel the schedule was set in. Left in place so an old database
//  does not have to change; nothing reads it.)
try {
  // Webhooks are bound to the channel they were created in. Storing one per NPC
  // meant every later roll posted back to the ORIGINAL channel, wherever the
  // command was actually run. Key them by channel instead.
  db.exec(`CREATE TABLE IF NOT EXISTS npc_webhooks (
    guild_id TEXT NOT NULL,
    channel_id TEXT NOT NULL,
    npc_name TEXT NOT NULL,
    webhook_id TEXT NOT NULL,
    webhook_token TEXT NOT NULL,
    avatar_url TEXT,
    PRIMARY KEY (guild_id, channel_id, npc_name)
  )`);
  try { db.exec('ALTER TABLE npc_webhooks ADD COLUMN avatar_url TEXT'); } catch {}
} catch (e) { console.error('npc_webhooks schema', e); }
try { db.exec("ALTER TABLE fights ADD COLUMN log_state TEXT DEFAULT '{}'"); } catch {}
try { db.exec("ALTER TABLE fights ADD COLUMN effect_state TEXT DEFAULT '{}'"); } catch {}
try {
  // Unified event log for merit changes (kind='merit'). Amount is signed; reason
  // is free text; quest_number links quest-driven awards. Read by /standing merit history.
  db.exec(`CREATE TABLE IF NOT EXISTS history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    guild_id TEXT NOT NULL,
    kind TEXT NOT NULL,
    user_id TEXT,
    amount INTEGER,
    reason TEXT,
    quest_number INTEGER,
    actor_id TEXT,
    created_at INTEGER NOT NULL
  )`);
  db.exec('CREATE INDEX IF NOT EXISTS idx_history_guild_user ON history (guild_id, user_id, id)');
  db.exec('CREATE INDEX IF NOT EXISTS idx_history_guild_kind ON history (guild_id, kind, id)');
  // Last finished fight per channel, so a GM can re-post the recap with /fight log.
  db.exec(`CREATE TABLE IF NOT EXISTS fight_archive (
    guild_id TEXT NOT NULL,
    channel_id TEXT NOT NULL,
    log_state TEXT NOT NULL DEFAULT '{}',
    roster TEXT NOT NULL DEFAULT '[]',
    ended_at INTEGER NOT NULL,
    PRIMARY KEY (guild_id, channel_id)
  )`);
} catch (e) { console.error('history schema', e); }
// Renown is a currency: earned from quests, encounters and activities, and spent
// again. Merits are a lifetime tally that only ever climbs, so the two can't
// share a column.
// Writing and deleting activities is always GM-only; this decides whether
// players may start one themselves. Locked to GMs until a server says otherwise.
// Runs used to be one-per-channel. They are now one per player per channel so
// several people can play alongside each other and one leaving doesn't disturb
// the rest. SQLite can't alter a primary key, so an old table is dropped —
// anything mid-run at deploy time is lost, which is the right trade for a
// throwaway activity.
try {
  const cols = db.prepare('PRAGMA table_info(story_runs)').all().map(c => c.name);
  if (cols.length && (!cols.includes('user_id') || !cols.includes('is_demo') || !cols.includes('busy'))) {
    db.exec('DROP TABLE story_runs');
    console.log('[activity] story_runs rebuilt for per-player runs');
  }
} catch {}
try { db.exec(`CREATE TABLE IF NOT EXISTS renown_log (
  guild_id TEXT NOT NULL, user_id TEXT NOT NULL, delta INTEGER NOT NULL,
  reason TEXT, at INTEGER NOT NULL
)`); } catch {}
try {
  db.exec(`CREATE TABLE IF NOT EXISTS ranks (
    guild_id TEXT NOT NULL,
    name TEXT NOT NULL,
    threshold INTEGER NOT NULL DEFAULT 0,
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (guild_id, name)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS quests (
    guild_id TEXT NOT NULL,
    number INTEGER NOT NULL,
    name TEXT NOT NULL,
    lore TEXT,
    objectives TEXT,
    details TEXT,
    rewards TEXT,
    merit_reward INTEGER NOT NULL DEFAULT 0,
    party_size INTEGER,
    party_hard INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'open',
    run_channel_id TEXT,
    post_channel_id TEXT,
    post_message_id TEXT,
    created_by TEXT,
    created_at INTEGER,
    PRIMARY KEY (guild_id, number)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS quest_members (
    guild_id TEXT NOT NULL,
    number INTEGER NOT NULL,
    user_id TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'applied',
    PRIMARY KEY (guild_id, number, user_id)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS quest_counter (
    guild_id TEXT NOT NULL PRIMARY KEY,
    last INTEGER NOT NULL DEFAULT 0
  )`);
} catch (e) { console.error('quest schema', e); }

db.exec(`
  CREATE TABLE IF NOT EXISTS characters (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL, order_name TEXT DEFAULT NULL,
    class TEXT DEFAULT NULL, weapon1 TEXT DEFAULT NULL, weapon2 TEXT DEFAULT NULL,
    weapon1emoji TEXT DEFAULT '⚔️', weapon2emoji TEXT DEFAULT '🗡️',
    str INTEGER DEFAULT 0, con INTEGER DEFAULT 0, dex INTEGER DEFAULT 0,
    wis INTEGER DEFAULT 0, lck INTEGER DEFAULT 0,
    hp_current INTEGER DEFAULT 0, rerolls_current INTEGER DEFAULT 0, profile_enabled INTEGER DEFAULT 1,
    PRIMARY KEY (guild_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS merit_trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    guild_id TEXT NOT NULL, from_user TEXT NOT NULL, to_user TEXT NOT NULL,
    amount INTEGER NOT NULL, reason TEXT,
    state TEXT NOT NULL DEFAULT 'pending', msg_id TEXT, src_channel TEXT,
    created_at INTEGER NOT NULL, decided_by TEXT, decided_at INTEGER
  );
  CREATE TABLE IF NOT EXISTS inventory (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL,
    item TEXT NOT NULL, note TEXT, source TEXT, added_by TEXT, at INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS lore (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL,
    body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending',
    reason TEXT, submitted_at INTEGER, decided_by TEXT, decided_at INTEGER,
    msg_id TEXT, src_channel TEXT,
    PRIMARY KEY (guild_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS roll_tally (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL,
    sides INTEGER NOT NULL, nat INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (guild_id, user_id, sides, nat)
  );
  CREATE TABLE IF NOT EXISTS stories (
    guild_id TEXT NOT NULL, name TEXT NOT NULL, author_id TEXT,
    start_scene TEXT NOT NULL DEFAULT 'start', tally TEXT, created_at INTEGER,
    PRIMARY KEY (guild_id, name)
  );
  CREATE TABLE IF NOT EXISTS story_scenes (
    guild_id TEXT NOT NULL, story TEXT NOT NULL, scene TEXT NOT NULL,
    say TEXT, npc TEXT, roll TEXT, dc INTEGER,
    outcomes TEXT NOT NULL DEFAULT '{}',
    ranges TEXT NOT NULL DEFAULT '[]',
    choices TEXT NOT NULL DEFAULT '[]',
    gauntlet TEXT, nat20 TEXT, nat1 TEXT,
    gain INTEGER NOT NULL DEFAULT 0, cash_tally INTEGER NOT NULL DEFAULT 0,
    ending INTEGER NOT NULL DEFAULT 0,
    merits INTEGER NOT NULL DEFAULT 0, rewards TEXT,
    ord INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (guild_id, story, scene)
  );
  CREATE TABLE IF NOT EXISTS story_runs (
    guild_id TEXT NOT NULL, channel_id TEXT NOT NULL, user_id TEXT NOT NULL,
    story TEXT NOT NULL, scene TEXT NOT NULL,
    started_at INTEGER,
    tally_state TEXT NOT NULL DEFAULT '{}',
    gauntlet_at INTEGER NOT NULL DEFAULT 0,
    is_demo INTEGER NOT NULL DEFAULT 0,
    busy INTEGER NOT NULL DEFAULT 0,
    steps INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (guild_id, channel_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS autorest_schedules (
    guild_id TEXT NOT NULL, name TEXT NOT NULL,
    hours INTEGER NOT NULL DEFAULT 6,
    hp TEXT NOT NULL DEFAULT '100%',
    rerolls TEXT NOT NULL DEFAULT '100%',
    heal TEXT NOT NULL DEFAULT '100%',
    channel TEXT, last_run INTEGER, enabled INTEGER NOT NULL DEFAULT 1,
    PRIMARY KEY (guild_id, name)
  );
  CREATE TABLE IF NOT EXISTS export_requests (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL,
    payload TEXT NOT NULL, fmt TEXT NOT NULL DEFAULT 'text',
    src_channel TEXT, msg_id TEXT, requested_at INTEGER,
    PRIMARY KEY (guild_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS import_requests (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL,
    payload TEXT NOT NULL,
    src_channel TEXT, msg_id TEXT, ch_id TEXT, requested_at INTEGER,
    PRIMARY KEY (guild_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS profile_saves (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL, slot_name TEXT NOT NULL,
    snapshot TEXT NOT NULL, saved_at TEXT NOT NULL,
    PRIMARY KEY (guild_id, user_id, slot_name)
  );
  CREATE TABLE IF NOT EXISTS roll_history (
    guild_id TEXT NOT NULL, channel_id TEXT NOT NULL, user_id TEXT NOT NULL,
    notation TEXT NOT NULL, label TEXT DEFAULT NULL, saved_at TEXT NOT NULL,
    PRIMARY KEY (guild_id, channel_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS guild_config (
    guild_id TEXT PRIMARY KEY, gm_role_id TEXT DEFAULT NULL, heal_charges INTEGER DEFAULT 3, npc_channel_id TEXT DEFAULT NULL
  );
  CREATE TABLE IF NOT EXISTS heal_charges (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL, current INTEGER DEFAULT 3,
    PRIMARY KEY (guild_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS player_tags (
    guild_id TEXT NOT NULL, user_id TEXT NOT NULL, tag_name TEXT NOT NULL,
    PRIMARY KEY (guild_id, user_id, tag_name)
  );
  CREATE TABLE IF NOT EXISTS custom_tags (
    guild_id TEXT NOT NULL, tag_name TEXT NOT NULL, emoji TEXT NOT NULL,
    PRIMARY KEY (guild_id, tag_name)
  );
  CREATE TABLE IF NOT EXISTS weapons (
    guild_id TEXT NOT NULL,
    name TEXT NOT NULL,
    PRIMARY KEY (guild_id, name)
  );
  CREATE TABLE IF NOT EXISTS npc_categories (
    guild_id TEXT NOT NULL,
    name TEXT NOT NULL,
    PRIMARY KEY (guild_id, name)
  );
  CREATE TABLE IF NOT EXISTS npc_category_members (
    guild_id TEXT NOT NULL,
    category TEXT NOT NULL,
    npc_name TEXT NOT NULL,
    PRIMARY KEY (guild_id, category, npc_name)
  );
  CREATE TABLE IF NOT EXISTS npcs (
    guild_id TEXT NOT NULL,
    name TEXT NOT NULL,
    order_name TEXT DEFAULT NULL,
    str INTEGER DEFAULT 0,
    con INTEGER DEFAULT 0,
    dex INTEGER DEFAULT 0,
    wis INTEGER DEFAULT 0,
    lck INTEGER DEFAULT 0,
    hp_current INTEGER DEFAULT 0,
    image_url TEXT DEFAULT NULL,
    webhook_id TEXT DEFAULT NULL,
    webhook_token TEXT DEFAULT NULL,
    PRIMARY KEY (guild_id, name)
  );
  CREATE TABLE IF NOT EXISTS fights (
    guild_id TEXT NOT NULL,
    channel_id TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'idle',
    turn_order TEXT NOT NULL DEFAULT '[]',
    turn_index INTEGER NOT NULL DEFAULT 0,
    phase TEXT NOT NULL DEFAULT 'attack',
    current_target TEXT DEFAULT NULL,
    atk_roll INTEGER DEFAULT NULL,
    atk_nat INTEGER DEFAULT NULL,
    atk_stat TEXT DEFAULT NULL,
    atk_mode TEXT DEFAULT 'normal',
    atk_sides INTEGER DEFAULT 20,
    def_roll INTEGER DEFAULT NULL,
    def_nat INTEGER DEFAULT NULL,
    def_stat TEXT DEFAULT NULL,
    def_mode TEXT DEFAULT 'normal',
    def_sides INTEGER DEFAULT 20,
    hp_state TEXT NOT NULL DEFAULT '{}',
    effect_state TEXT NOT NULL DEFAULT '{}',
    PRIMARY KEY (guild_id, channel_id)
  );
`);

// Columns added to `fights` after it first shipped. These sit AFTER the CREATE
// above (not with the migrations at the top of the file) because on a brand-new
// database the top-of-file ALTERs run before the table exists and are swallowed,
// leaving a fresh install without auto_npc / rr_state / log_state.
// (fights.auto_npc / rr_state / log_state / effect_state are added higher up —
//  a second ALTER for the same column always throws, so these were never live.)
// Practice bouts: HP at or below which a fighter bows out. 0 = a real fight.
// Approval routing: one forum, a thread per approval type. approval_routes is
// a JSON map {forum, sheets, trades, duels, lore, exports} of channel ids. The
// per-item *ch_id columns pin each posted request to wherever it actually
// landed, so jump links and supersede-edits survive a routing change.
// Audit routing: same shape for the roll mirror — a JSON map
// {forum, players, gms, npcs, say} of channel ids.
// Written props: a per-guild scroll font, stored as bytes so it survives
// redeploys (the Railway filesystem does not).
// A shelf for the props: every /gm scroll's named PDF is also filed here.
// A 5e sheet carries two more abilities and the numbers that hang off a class.
// Added for every server; a Knightfall sheet simply never reads them.
// A 5e character can be dying rather than dead: three saves either way.
// These two spent their whole life failing: the table is `characters`,
// there is no `chars`, and the catch swallowed "no such table" on every
// boot — so the columns never existed while upsertChar injected defaults
// for them. First live fight to trip the injection died on the write.
// And a monster needs the four numbers a statblock leads with.
// The library. A monster or a spell written once and drawn on for ever —
// either from the SRD set that ships here, or from whatever a GM imports.
try { db.exec(`CREATE TABLE IF NOT EXISTS library_monsters (
  guild_id TEXT NOT NULL, name TEXT NOT NULL,
  ac INTEGER, hp INTEGER, attack INTEGER, damage TEXT,
  str INTEGER, dex INTEGER, con INTEGER, int INTEGER, wis INTEGER, cha INTEGER,
  kind TEXT, cr TEXT, notes TEXT, source TEXT, added_by TEXT, at INTEGER,
  PRIMARY KEY (guild_id, name)
)`); } catch (e) { console.error('library_monsters schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS library_spells (
  guild_id TEXT NOT NULL, name TEXT NOT NULL,
  level INTEGER, school TEXT, casting_time TEXT, range_text TEXT,
  components TEXT, duration TEXT, concentration INTEGER DEFAULT 0,
  body TEXT, source TEXT, added_by TEXT, at INTEGER,
  PRIMARY KEY (guild_id, name)
)`); } catch (e) { console.error('library_spells schema', e); }

// The question bank. Questions live here because a draw, and the dropdown
// that hand-picks them, must answer instantly; the forum copy is for reading.
try { db.exec(`CREATE TABLE IF NOT EXISTS quiz_questions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  guild_id TEXT NOT NULL, category TEXT NOT NULL, tags TEXT,
  question TEXT NOT NULL, answers TEXT NOT NULL,
  difficulty TEXT NOT NULL DEFAULT 'normal',
  explain TEXT, thread_id TEXT, message_id TEXT,
  author_id TEXT, created_at INTEGER NOT NULL
)`); } catch (e) { console.error('quiz_questions schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS quiz_categories (
  guild_id TEXT NOT NULL, name TEXT NOT NULL, thread_id TEXT,
  PRIMARY KEY (guild_id, name)
)`); } catch (e) { console.error('quiz_categories schema', e); }
// What each player has already been asked, so a draw can prefer the new.
try { db.exec(`CREATE TABLE IF NOT EXISTS quiz_seen (
  guild_id TEXT NOT NULL, user_id TEXT NOT NULL, question_id INTEGER NOT NULL,
  right_answer INTEGER NOT NULL DEFAULT 0, at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, user_id, question_id)
)`); } catch (e) { console.error('quiz_seen schema', e); }
// A set a GM saved: the same draw, repeatable.
try { db.exec(`CREATE TABLE IF NOT EXISTS quiz_sets (
  guild_id TEXT NOT NULL, name TEXT NOT NULL, spec TEXT NOT NULL,
  author_id TEXT, created_at INTEGER NOT NULL,
  PRIMARY KEY (guild_id, name)
)`); } catch (e) { console.error('quiz_sets schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS npc_pages (
  guild_id TEXT NOT NULL, name TEXT NOT NULL,
  thread_id TEXT, message_id TEXT, at INTEGER,
  PRIMARY KEY (guild_id, name)
)`); } catch (e) { console.error('npc_pages schema', e); }
// One thread per category, holding every NPC in it as a message. npc_pages
// keeps its (guild_id, name) key: thread_id now points at the category
// thread and message_id at that NPC's own message inside it.
try { db.exec(`CREATE TABLE IF NOT EXISTS npc_category_threads (
  guild_id TEXT NOT NULL, category TEXT NOT NULL,
  thread_id TEXT, at INTEGER,
  PRIMARY KEY (guild_id, category)
)`); } catch (e) { console.error('npc_category_threads schema', e); }
// The portrait forum mirrors the page forum: the same categories, the same
// thread names, so a GM looking for a face looks in the same place they look
// for the statblock. Kept in its own table because a category has a thread in
// each forum and they are not the same thread.
// One row per migrated face: which message in which thread now hosts it.
// The migration is idempotent by this record — a live post is kept, a
// re-homed NPC's post is moved, a hand-deleted one is replaced.
try { db.exec(`CREATE TABLE IF NOT EXISTS npc_portrait_posts (
  guild_id TEXT NOT NULL, npc_name TEXT NOT NULL,
  thread_id TEXT, message_id TEXT, at INTEGER,
  PRIMARY KEY (guild_id, npc_name)
)`); } catch (e) { console.error('npc_portrait_posts schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS npc_portrait_threads (
  guild_id TEXT NOT NULL, category TEXT NOT NULL,
  thread_id TEXT, at INTEGER,
  PRIMARY KEY (guild_id, category)
)`); } catch (e) { console.error('npc_portrait_threads schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS dc_drafts (
  guild_id TEXT NOT NULL, token TEXT NOT NULL, ids TEXT, npcs TEXT, reveal TEXT,
  created_at INTEGER NOT NULL, PRIMARY KEY (guild_id, token)
)`); } catch (e) { console.error('dc_drafts schema', e); }
try { db.exec(`CREATE TABLE IF NOT EXISTS dc_cards (
  guild_id TEXT NOT NULL, message_id TEXT NOT NULL,
  s_flavour TEXT, f_flavour TEXT, s_sanction TEXT, f_sanction TEXT,
  created_at INTEGER NOT NULL, PRIMARY KEY (guild_id, message_id)
)`); } catch (e) { console.error('dc_cards schema', e); }
// The on_fail / on_success marks moved off the customId and onto the card:
// free text in an id overflows Discord's 100-char ceiling, and a colon in it
// shifts every field after it in the split.
// A card can bind the fight in its channel: the target's own fight buttons
// wait until this card is pressed, and a failed bound check can skip their
// turn. Cleared on resolution; a pruned card simply stops holding.
// Grappling: which attack-phase roll is pending, and who holds whom.
try { db.exec("ALTER TABLE fights ADD COLUMN grapples TEXT DEFAULT '{}'"); } catch {}
// Quest board forum + GM planning mirror.
// The questline pipeline: a stage per quest, tag ids per guild, run records.
try { db.exec(`CREATE TABLE IF NOT EXISTS npc_orders (
  guild_id TEXT NOT NULL, prefix TEXT NOT NULL, image_url TEXT NOT NULL,
  set_by TEXT, set_at INTEGER, PRIMARY KEY (guild_id, prefix)
)`); } catch (e) { console.error('npc_orders schema', e); }
db.exec(`CREATE TABLE IF NOT EXISTS quest_runs (
  guild_id TEXT NOT NULL,
  root_number INTEGER NOT NULL,
  number INTEGER NOT NULL,
  completed_at INTEGER NOT NULL,
  gm_id TEXT,
  party TEXT,
  npcs TEXT
)`);
db.exec(`CREATE TABLE IF NOT EXISTS gm_profiles (
  guild_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  style TEXT,
  brief TEXT,
  available INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (guild_id, user_id)
)`);

