function getChar(gid, uid) {
  return db.prepare('SELECT * FROM characters WHERE guild_id=? AND user_id=?').get(gid, uid);
}
// Mirror a fighter's new sheet HP into any active fight that contains them,
// so mid-fight heals / GM adjustments aren't overwritten on the next resolve.
function syncFightHp(gid, fid, newHp) {
  const fights = db.prepare("SELECT channel_id, hp_state FROM fights WHERE guild_id=? AND state='active'").all(gid);
  for (const f of fights) {
    const hpState = JSON.parse(f.hp_state || '{}');
    if (Object.prototype.hasOwnProperty.call(hpState, fid)) {
      hpState[fid] = newHp;
      db.prepare('UPDATE fights SET hp_state=? WHERE guild_id=? AND channel_id=?')
        .run(JSON.stringify(hpState), gid, f.channel_id);
    }
  }
}

// ── History / audit log ───────────────────────────────────────────────────────
// One row per meaningful event. kind='merit' for now; the shape is generic so
// other event kinds can be added later without a migration.
function logHistory(gid, { kind, userId = null, amount = null, reason = null, questNumber = null, actorId = null }) {
  db.prepare(`INSERT INTO history (guild_id, kind, user_id, amount, reason, quest_number, actor_id, created_at)
              VALUES (?,?,?,?,?,?,?,?)`).run(gid, kind, userId, amount, reason, questNumber, actorId, Date.now());
}
// Recent merit events for one player, newest first.
function getMeritHistory(gid, uid, limit = 20) {
  return db.prepare("SELECT * FROM history WHERE guild_id=? AND kind='merit' AND user_id=? ORDER BY id DESC LIMIT ?").all(gid, uid, limit);
}
// Recent merit events server-wide, newest first.
function getRecentMeritHistory(gid, limit = 20) {
  return db.prepare("SELECT * FROM history WHERE guild_id=? AND kind='merit' ORDER BY id DESC LIMIT ?").all(gid, limit);
}

// ── Fight archive (last finished fight per channel, for /fight log) ────────────
// Every fight ends through here, so this is where the throwaway cast is
// swept: temporary NPCs that fought in it are deleted, and only those —
// anyone still standing in another fight is left alone.
function sweepTempFighters(gid, roster) {
  let swept = 0;
  try {
    const busy = fightingNpcNames(gid);
    for (const fid of roster || []) {
      if (!isNpcFighter(fid)) continue;
      const nm = npcNameFromFighter(fid);
      const n = getNpc(gid, nm);
      if (!n?.is_temp || busy.has(nm)) continue;
      db.prepare('DELETE FROM npcs WHERE guild_id=? AND name=?').run(gid, nm);
      swept++;
    }
  } catch {}
  return swept;
}

function archiveFight(gid, cid, logState, roster, floor = 0) {
  db.prepare(`INSERT INTO fight_archive (guild_id, channel_id, log_state, roster, ended_at, floor_hp)
              VALUES (?,?,?,?,?,?)
              ON CONFLICT(guild_id, channel_id) DO UPDATE SET log_state=excluded.log_state, roster=excluded.roster, ended_at=excluded.ended_at, floor_hp=excluded.floor_hp`)
    .run(gid, cid, JSON.stringify(logState || {}), JSON.stringify(roster || []), Date.now(), floor || 0);
  // The archive keeps the record; the temporary fighters themselves go.
  const gone = sweepTempFighters(gid, roster);
  if (gone) console.log(`[temp-npc] ${gone} swept after the fight in ${cid}`);
}
function getArchivedFight(gid, cid) {
  return db.prepare('SELECT * FROM fight_archive WHERE guild_id=? AND channel_id=?').get(gid, cid);
}

// ── Quest archive read (completed quests a player was on) ──────────────────────
function getPlayerCompletedQuests(gid, uid) {
  return db.prepare(`SELECT q.number, q.name, q.merit_reward
                     FROM quests q JOIN quest_members m
                     ON q.guild_id=m.guild_id AND q.number=m.number
                     WHERE q.guild_id=? AND m.user_id=? AND m.state='party' AND q.status='completed'
                     ORDER BY q.number DESC`).all(gid, uid);
}

function upsertChar(gid, uid, fields) {
  // Any write that lifts someone above nought ends their dying, so a heal,
  // a rest or a GM's hand all clear the tally without each remembering to.
  if (fields && fields.hp_current != null && (Number(fields.hp_current) || 0) > 0
      && fields.death_success == null && fields.death_fail == null) {
    fields = { ...fields, death_success: 0, death_fail: 0 };
  }
  const ex = getChar(gid, uid);
  if (!ex) {
    db.prepare(`INSERT INTO characters (guild_id,user_id,order_name,str,con,dex,wis,lck,hp_current,rerolls_current,profile_enabled) VALUES (?,?,?,?,?,?,?,?,?,?,?)`)
      .run(gid, uid, fields.order_name??null, fields.str??0, fields.con??0, fields.dex??0, fields.wis??0, fields.lck??0, fields.hp_current??0, fields.rerolls_current??0, fields.profile_enabled??1);
  } else {
    const sets = Object.entries(fields).map(([k])=>`${k}=?`).join(',');
    db.prepare(`UPDATE characters SET ${sets} WHERE guild_id=? AND user_id=?`).run(...Object.values(fields), gid, uid);
  }
  if ('hp_current' in fields) syncFightHp(gid, uid, fields.hp_current);
  return getChar(gid, uid);
}

// ── Merits & ranks ───────────────────────────────────────────────────────────
// Both tables answer to a fighter id: a bare user id for a player,
// npc:Name for an NPC. Everything above them reads the same either way.
function getTitles(gid, sid) {
  return db.prepare('SELECT title, source FROM subject_titles WHERE guild_id=? AND subject_id=? ORDER BY at').all(gid, sid);
}
function getAssocs(gid, sid) {
  return db.prepare('SELECT name, note FROM subject_assocs WHERE guild_id=? AND subject_id=? ORDER BY at').all(gid, sid);
}
function grantTitle(gid, sid, title, { source = null, by = null } = {}) {
  db.prepare(`INSERT INTO subject_titles (guild_id, subject_id, title, source, granted_by, at)
              VALUES (?,?,?,?,?,?) ON CONFLICT(guild_id, subject_id, title) DO NOTHING`)
    .run(gid, sid, title, source, by, Date.now());
}
function revokeTitle(gid, sid, title) {
  return db.prepare('DELETE FROM subject_titles WHERE guild_id=? AND subject_id=? AND title=? COLLATE NOCASE')
    .run(gid, sid, title).changes;
}
function addAssoc(gid, sid, name, note = null) {
  db.prepare(`INSERT INTO subject_assocs (guild_id, subject_id, name, note, at)
              VALUES (?,?,?,?,?) ON CONFLICT(guild_id, subject_id, name) DO UPDATE SET note=excluded.note`)
    .run(gid, sid, name, note, Date.now());
}
function removeAssoc(gid, sid, name) {
  return db.prepare('DELETE FROM subject_assocs WHERE guild_id=? AND subject_id=? AND name=? COLLATE NOCASE')
    .run(gid, sid, name).changes;
}
// The one rendering both forums and /char show share, so a title never
// reads differently depending on where you found it.
function titlesLine(gid, sid) {
  const t = getTitles(gid, sid), a = getAssocs(gid, sid);
  if (!t.length && !a.length) return null;
  const out = [];
  if (t.length) out.push(`\u{1F3C5} ${t.map(x => `**${x.title}**${x.source ? ` _(${x.source})_` : ''}`).join(' \u00b7 ')}`);
  if (a.length) out.push(`\u{1F6E1}\uFE0F ${a.map(x => `**${x.name}**${x.note ? ` _(${x.note})_` : ''}`).join(' \u00b7 ')}`);
  return out.join('\n');
}
function charTitlesBody(gid, uid) {
  const body = titlesLine(gid, uid);
  return ['\u{1F3F7}\uFE0F **Titles & Associations**', body || '_None yet._'].join('\n').slice(0, 1900);
}

function getMerits(gid, uid) {
  return getChar(gid, uid)?.merits ?? 0;
}
// Change a player's merit total by delta (can be negative). Ensures a character row exists.
// Move a player's renown and record why. Returns the new balance, or null when
// a spend is refused for want of funds.
function addRenown(gid, uid, delta, reason = null, { allowNegative = false } = {}) {
  const now = adjustBalance(gid, uid, 'renown', delta, { allowNegative });
  if (now === null) return null;
  db.prepare('INSERT INTO renown_log (guild_id,user_id,delta,reason,at) VALUES (?,?,?,?,?)')
    .run(gid, uid, delta, reason, Date.now());
  return now;
}
function getRenown(gid, uid) { return pageSubject(gid, uid)?.renown ?? 0; }
function renownHistory(gid, uid, limit = 15) {
  return db.prepare('SELECT * FROM renown_log WHERE guild_id=? AND user_id=? ORDER BY at DESC LIMIT ?').all(gid, uid, limit);
}

// A page subject: either a player's sheet or an NPC, shaped the same way so
// standing, inventory and roll history don't need to know which they have.
function pageSubject(gid, id) {
  if (isNpcFighter(id)) {
    const npc = getNpc(gid, npcNameFromFighter(id));
    if (!npc) return null;
    return { ...npc, isNpc: true, user_id: id, displayName: npc.name,
      hp_current: npc.hp_current, rerolls_current: npc.rerolls_current ?? npc.lck ?? 0 };
  }
  const ch = getChar(gid, id);
  return ch ? { ...ch, isNpc: false, user_id: id } : null;
}
// Move a balance for either kind. NPC balances live on the npcs row.
function adjustBalance(gid, id, column, delta, { allowNegative = false } = {}) {
  if (isNpcFighter(id)) {
    const name = npcNameFromFighter(id);
    const npc = getNpc(gid, name);
    if (!npc) return null;
    const next = (npc[column] ?? 0) + delta;
    if (next < 0 && !allowNegative) return null;
    db.prepare(`UPDATE npcs SET ${column}=? WHERE guild_id=? AND name=?`).run(Math.max(0, next), gid, name);
    return Math.max(0, next);
  }
  const cur = getChar(gid, id)?.[column] ?? 0;
  const next = cur + delta;
  if (next < 0 && !allowNegative) return null;
  upsertChar(gid, id, { [column]: Math.max(0, next) });
  return Math.max(0, next);
}

function addMerits(gid, uid, delta) {
  const now = adjustBalance(gid, uid, 'merits', delta, { allowNegative: true }) ?? 0;
  if (delta) bookLog(gid, 'ranks', `🎖️ <@${uid}> ${delta > 0 ? 'earned' : 'lost'} **${Math.abs(delta)}** merit${Math.abs(delta) === 1 ? '' : 's'} — now **${now}**.`);
  return now;
}
function getRanks(gid) {
  return db.prepare('SELECT name, threshold, sort_order FROM ranks WHERE guild_id=? ORDER BY sort_order, threshold').all(gid);
}
function setRank(gid, name, threshold, sortOrder) {
  const ex = db.prepare('SELECT name FROM ranks WHERE guild_id=? AND name=?').get(gid, name);
  if (ex) db.prepare('UPDATE ranks SET threshold=?, sort_order=? WHERE guild_id=? AND name=?').run(threshold, sortOrder, gid, name);
  else db.prepare('INSERT INTO ranks (guild_id, name, threshold, sort_order) VALUES (?,?,?,?)').run(gid, name, threshold, sortOrder);
}
function removeRank(gid, name) {
  return db.prepare('DELETE FROM ranks WHERE guild_id=? AND name=?').run(gid, name).changes;
}
// Given a merit total, the highest rank whose threshold is met, and the next rank (if any).
function rankProgress(gid, merits) {
  const ranks = getRanks(gid); // ascending by sort/threshold
  let current = null, next = null;
  for (const r of ranks) {
    if (merits >= r.threshold) current = r;
    else { next = r; break; }
  }
  return { current, next, ranks };
}

// ── Quests ───────────────────────────────────────────────────────────────────
// The lowest free number: a deleted quest's number returns to the pool, so
// the board never grows gaps. When a number is RECYCLED, the dead quest's
// leftovers are neutralised first — its run-ledger rows are tombstoned to
// root 0 (unreachable by any live quest, but the gm_id credit inside them
// still counts) and any stray events/summaries from pre-hygiene deletes are
// purged — so the reborn number starts with a clean history.
function nextQuestNumber(gid) {
  const taken = db.prepare('SELECT number FROM quests WHERE guild_id=? ORDER BY number').all(gid);
  let n = 1;
  for (const r of taken) { if (r.number === n) n++; else if (r.number > n) break; }
  const maxN = taken.length ? taken[taken.length - 1].number : 0;
  if (n <= maxN) { // recycling a gap — scrub what the dead quest left behind
    db.prepare('UPDATE quest_runs SET root_number=0, number=0 WHERE guild_id=? AND (root_number=? OR number=?)').run(gid, n, n);
    db.prepare('DELETE FROM quest_events WHERE guild_id=? AND number=?').run(gid, n);
    db.prepare('DELETE FROM quest_summaries WHERE guild_id=? AND number=?').run(gid, n);
  }
  return n;
}
function createQuest(gid, fields) {
  const number = nextQuestNumber(gid);
  db.prepare(`INSERT INTO quests
    (guild_id, number, name, lore, objectives, details, rewards, merit_reward, party_size, party_hard, status, run_channel_id, post_channel_id, post_message_id, created_by, created_at)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(
    gid, number, fields.name, fields.lore ?? null, fields.objectives ?? null, fields.details ?? null,
    fields.rewards ?? null, fields.merit_reward ?? 0, fields.party_size ?? null, fields.party_hard ? 1 : 0,
    'open', fields.run_channel_id ?? null, fields.post_channel_id ?? null, null, fields.created_by ?? null, Date.now());
  return number;
}
function getQuest(gid, number) {
  return db.prepare('SELECT * FROM quests WHERE guild_id=? AND number=?').get(gid, number);
}
function updateQuest(gid, number, fields) {
  const sets = Object.keys(fields).map(k => `${k}=?`).join(',');
  db.prepare(`UPDATE quests SET ${sets} WHERE guild_id=? AND number=?`).run(...Object.values(fields), gid, number);
  return getQuest(gid, number);
}
function deleteQuest(gid, number) {
  db.prepare('DELETE FROM quest_members WHERE guild_id=? AND number=?').run(gid, number);
  db.prepare('DELETE FROM quest_events WHERE guild_id=? AND number=?').run(gid, number);
  db.prepare('DELETE FROM quest_summaries WHERE guild_id=? AND number=?').run(gid, number);
  return db.prepare('DELETE FROM quests WHERE guild_id=? AND number=?').run(gid, number).changes;
}
function listQuests(gid, status) {
  if (status) return db.prepare('SELECT * FROM quests WHERE guild_id=? AND status=? ORDER BY number').all(gid, status);
  return db.prepare('SELECT * FROM quests WHERE guild_id=? ORDER BY number').all(gid);
}
function getQuestMembers(gid, number, state) {
  if (state) return db.prepare('SELECT user_id FROM quest_members WHERE guild_id=? AND number=? AND state=?').all(gid, number, state).map(r => r.user_id);
  return db.prepare('SELECT user_id, state FROM quest_members WHERE guild_id=? AND number=?').all(gid, number);
}
function setQuestMember(gid, number, uid, state) {
  const ex = db.prepare('SELECT user_id FROM quest_members WHERE guild_id=? AND number=? AND user_id=?').get(gid, number, uid);
  if (ex) db.prepare('UPDATE quest_members SET state=? WHERE guild_id=? AND number=? AND user_id=?').run(state, gid, number, uid);
  else db.prepare('INSERT INTO quest_members (guild_id, number, user_id, state) VALUES (?,?,?,?)').run(gid, number, uid, state);
}
function removeQuestMember(gid, number, uid) {
  return db.prepare('DELETE FROM quest_members WHERE guild_id=? AND number=? AND user_id=?').run(gid, number, uid).changes;
}
// "#001-Goblin Cave"
// What to tell the fighter whose turn it is. Written out at three separate
// fight-start points before this, which is why only one of them learned about
// /roll fight:true when that arrived.
function turnPrompt(f) {
  return f.isNpc
    ? ' _(a GM acts with `npc:`)_'
    : '\n_`/fight atk stat:str target:@player` — or `/roll dice:2d6+3 fight:true target:@player` for a custom roll._';
}

// A fight's turn order and HP map are stored as JSON and read back constantly.
// One accessor each, so a shape change lands in one place rather than 24.
const fightOrder = (fight) => JSON.parse(fight?.turn_order || '[]');
const fightHp = (fight) => JSON.parse(fight?.hp_state || '{}');
// Where sheets, lore, exports and merit trades all queue for a GM.
const approvalChannelId = (gid) => getConfig(gid)?.approval_channel_id || null;

// ── Approval routing ─────────────────────────────────────────────────────────
// One forum, a thread per approval type — configured by /config channels approvalforum,
// stored as JSON in guild_config.approval_routes. Every producer asks for its
// own type's destination; the single approval channel remains the fallback, so
// a server that never touches the forum behaves exactly as it always has.
// Where players' feedback lands: one thread per category in a GM-only
// forum. Seven to begin with; `/feedback category add` grows the list and
// the new thread appears at once (T, 2026-08-16).
const FEEDBACK_TYPES_BASE = {
  general:    { name: '\u{1F4AC} General',    about: 'Anything that does not fit the other rooms.' },
  quests:     { name: '\u{1F5FA}\uFE0F Quests',     about: 'Runs, pacing, rewards, the board itself.' },
  encounters: { name: '\u2694\uFE0F Encounters', about: 'Fights, foes, difficulty, the shape of a scene.' },
  system:     { name: '\u{1F3DB}\uFE0F System',     about: 'The world, its rules of play, how it hangs together.' },
  mechanics:  { name: '\u{1F3B2} Mechanics',  about: 'Dice, stats, crits, carries \u2014 the maths of it.' },
  ddice:      { name: '\u{1F916} DDice bot',  about: 'The bot itself \u2014 bugs, papercuts, wishes.' },
  gms:        { name: '\u{1F451} GMs',        about: 'How the game is run, and by whom.' },
};
// Custom categories live in config, keyed by a slug so their thread ids
// survive a rename.
function feedbackCats(gid) {
  try { const o = JSON.parse(getConfig(gid)?.feedback_cats || '[]'); return Array.isArray(o) ? o : []; }
  catch { return []; }
}
function feedbackTypes(gid) {
  const out = { ...FEEDBACK_TYPES_BASE };
  for (const c of feedbackCats(gid)) out[c.key] = { name: `\u{1F4CC} ${c.name}`, about: 'Added by a GM.' };
  return out;
}
function feedbackRoutes(gid) {
  try { const o = JSON.parse(getConfig(gid)?.feedback_routes || 'null'); return (o && typeof o === 'object') ? o : null; }
  catch { return null; }
}
// The plan writes feedback_routes.forum itself (json:'forum', same idiom
// as approvals and roll-audit), so the mender just mends. The legacy
// feedback_forum column is read once for anyone who ran the interim build.
async function ensureFeedbackThreads(client, gid) {
  const cfg = getConfig(gid);
  if (!feedbackRoutes(gid)?.forum && cfg?.feedback_forum) {
    setConfig(gid, { feedback_routes: JSON.stringify({ forum: cfg.feedback_forum }) });
  }
  return ensureForumThreads(client, gid, { configKey: 'feedback_routes', types: feedbackTypes(gid), routesOf: feedbackRoutes });
}
function feedbackDestination(gid, type) {
  const r = feedbackRoutes(gid);
  return (r && r[type]) || null;
}

const APPROVAL_TYPES = {
  sheets:  { name: '📋 Character Sheets', about: 'New and edited sheets, budget refusals and resubmissions land here.' },
  trades:  { name: '🤝 Merit Trades',     about: 'Player-to-player merit offers wait here for a GM to sign off.' },
  duels:   { name: '⚔️ Duels',            about: 'Challenges sent up for a GM to allow or decline.' },
  lore:    { name: '📜 Lore',             about: 'Character lore submitted for a GM to read.' },
  loredoc: { name: '📄 Lore Docs',      about: 'Requests to update a lore document — links for a GM to look over.' },
  exports: { name: '📤 Sheet Exports',    about: 'Sheets a player asked to take away, released by a GM.' },
};
function approvalRoutes(gid) {
  const raw = getConfig(gid)?.approval_routes;
  if (!raw) return null;
  try { const o = JSON.parse(raw); return o && typeof o === 'object' ? o : null; }
  catch { return null; }
}
function approvalDestination(gid, type) {
  const r = approvalRoutes(gid);
  return (r && r[type]) || approvalChannelId(gid) || null;
}
// Forum threads nap after their auto-archive window, and a sleeping thread
// swallows sends and edits — wake it before touching it.
async function wakeThread(ch) {
  if (ch?.isThread?.() && ch.archived) await ch.setArchived(false).catch(() => {});
  return ch;
}
// Fetch a type's destination ready to post in.
async function approvalChannelFor(client, gid, type) {
  const id = approvalDestination(gid, type);
  if (!id) return null;
  return wakeThread(await client.channels.fetch(id));
}

// Resolve the `number:` option to a quest, or answer the refusal. Twelve
// subcommands opened with the same four lines; this is those four lines.
async function requireQuest(interaction, gid, forcedNumber = null) {
  const number = forcedNumber ?? interaction.options?.getInteger?.('number');
  const quest = getQuest(gid, number);
  if (!quest) {
    await interaction.reply({ content: `❌ No quest #${String(number).padStart(3, '0')}.`, ephemeral: true });
    return null;
  }
  return quest;
}

// An instance keeps the adventure's number and adds which run it is:
// #002.2-Testing the waters · Blackfen party. The row still has its own
// number underneath — that's what commands take — but nobody has to read
// #014 and work out it's the same story.
function questTag(quest) {
  const root = quest.instance_of ?? quest.number;
  // A run's NAME already carries the whole convention — "<Quest> Run 001
  // <GM>" — composed at launch, so no dot-suffix rides on top of it.
  const seq = '';
  const label = quest.run_label ? ` • ${quest.run_label}` : '';
  return `#${String(root).padStart(3, '0')}${seq}-${quest.name}${label}`;
}
// "12 Jan 2026" — for history timestamps (epoch ms)
function formatHistDate(ms) {
  return new Date(ms).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function setStatAndDerive(gid, uid, stat, val) {
  let ch = getChar(gid, uid);
  if (!ch) { upsertChar(gid, uid, {}); ch = getChar(gid, uid); }
  const upd = { [stat]: val };
  if (stat === 'con') upd.hp_current = val + 2;
  if (stat === 'lck') upd.rerolls_current = val;
  upsertChar(gid, uid, upd);
  return getChar(gid, uid);
}
// Saving a fresh roll clears the reroll mark — the new result is rerollable,
// the old one is gone.
function saveRoll(gid, cid, uid, notation, label) {
  db.prepare(`INSERT OR REPLACE INTO roll_history (guild_id,channel_id,user_id,notation,label,saved_at,rerolled)
              VALUES (?,?,?,?,?,datetime('now'),0)`).run(gid, cid, uid, notation, label ?? null);
}
function markRerolled(gid, cid, uid) {
  db.prepare('UPDATE roll_history SET rerolled=1 WHERE guild_id=? AND channel_id=? AND user_id=?').run(gid, cid, uid);
}
function getLastRoll(gid, cid, uid) {
  return db.prepare('SELECT * FROM roll_history WHERE guild_id=? AND channel_id=? AND user_id=?').get(gid, cid, uid);
}
function getConfig(gid) {
  let c = db.prepare('SELECT * FROM guild_config WHERE guild_id=?').get(gid);
  if (!c) { db.prepare('INSERT INTO guild_config (guild_id) VALUES (?)').run(gid); c = db.prepare('SELECT * FROM guild_config WHERE guild_id=?').get(gid); }
  return c;
}
function setConfig(gid, fields) {
  getConfig(gid);
  const sets = Object.entries(fields).map(([k])=>`${k}=?`).join(',');
  db.prepare(`UPDATE guild_config SET ${sets} WHERE guild_id=?`).run(...Object.values(fields), gid);
}
function getHealCharges(gid, uid, max) {
  let r = db.prepare('SELECT * FROM heal_charges WHERE guild_id=? AND user_id=?').get(gid, uid);
  if (!r) { db.prepare('INSERT INTO heal_charges (guild_id,user_id,current) VALUES (?,?,?)').run(gid, uid, max); r = db.prepare('SELECT * FROM heal_charges WHERE guild_id=? AND user_id=?').get(gid, uid); }
  return r;
}
function setHealCharges(gid, uid, cur) {
  db.prepare('INSERT OR REPLACE INTO heal_charges (guild_id,user_id,current) VALUES (?,?,?)').run(gid, uid, cur);
}
// The character card, in one place so every reader of it agrees.
function buildCharCard(ch, displayName, healNow, maxCharges, gid) {
  const rules = rulesFor(gid);
  // A 5e sheet says different things, so it gets its own face: scores with
  // their modifiers, AC and proficiency where a Knightfall card shows
  // rerolls and an order.
  if (rules.id === 'dnd5e') {
    const mod = (st) => { const m = rules.statBonus(ch, st); return m >= 0 ? `+${m}` : `${m}`; };
    const out = [`🗡️  **${displayName}**`,
      ch.char_class ? `⚔️  Level ${ch.level ?? 1} ${ch.char_class}` : `⚔️  Level ${ch.level ?? 1}`,
      `❤️  HP          ${ch.hp_current} / ${rules.maxHp(ch)}`,
      `🛡️  AC          ${rules.targetNumber(ch)}`,
      `➕  Proficiency  +${rules.profBonus(ch)}`, ''];
    for (const st of rules.stats) out.push(`　 ${rules.labels[st]}  ${String(ch[st] ?? 10).padStart(2)}  (${mod(st)})`);
    let prof = null;
    try { prof = JSON.parse(ch.proficient || '{}'); } catch {}
    if (prof?.saves?.length) out.push('', `💪 Saves: ${prof.saves.map(x => rules.labels[x] || x).join(', ')}`);
    if (prof?.skills?.length) out.push(`🎯 Skills: ${prof.skills.join(', ')}`);
    const cs = typeof rules.caster === 'function' ? rules.caster(ch) : null;
    if (cs) {
      out.push('', `✨ Spell save **DC ${rules.spellSaveDC(ch)}** · attack **+${rules.spellAttack(ch)}**`);
      if (ch.concentrating) out.push(`🧠 Concentrating on **${ch.concentrating}**`);
    }
    const conds = conditionsOf(ch);
    if (conds.length) out.push('', `🩹 ${conds.join(', ')}`);
    const bits5 = [];
    if (Number(ch.temp_hp)) bits5.push(`🛡️ ${ch.temp_hp} temp HP`);
    if (Number(ch.inspiration)) bits5.push('✨ inspiration');
    const pp = typeof rules.passive === 'function' ? rules.passive(ch, 'perception') : null;
    if (pp) bits5.push(`👁️ passive Perception ${pp}`);
    const atk5 = typeof rules.attacksPerAction === 'function' ? rules.attacksPerAction(ch) : 1;
    if (atk5 > 1) bits5.push(`⚔️ ${atk5} attacks`);
    if (bits5.length) out.push('', bits5.join(' · '));
    if (ch.weapon1dice || ch.weapon2dice) {
      out.push('', [ch.weapon1 && `${ch.weapon1} ${ch.weapon1dice || '1d8'}`,
                    ch.weapon2 && `${ch.weapon2} ${ch.weapon2dice || '1d8'}`].filter(Boolean).join('  ·  '));
    }
    return out;
  }
  const lines = [`⚔️  **${displayName}**`,
    ch.order_name ? `${KNIGHT_EMOJIS[ch.order_name] ?? '⚪'}  ${ch.order_name}` : 'No order set'];
  if (ch.class) lines.push(`🏅  ${ch.class}`);
  lines.push(`❤️  HP          ${ch.hp_current} / ${maxHp(ch, gid)}`,
             `🔄  Rerolls      ${ch.rerolls_current} / ${maxRerolls(ch)}`);
  if (isWhiteKnight(ch)) lines.push(`🛡️  Heal         ${healNow} / ${maxCharges}`);
  lines.push('', `💪  STR         ${ch.str}`, `🫀  CON         ${ch.con}`, `⚡  DEX         ${ch.dex}`,
             `🧠  WIS         ${ch.wis}`, `🍀  LCK         ${ch.lck}`);
  if (ch.weapon1 || ch.weapon2) {
    lines.push('');
    if (ch.weapon1) lines.push(`${ch.weapon1emoji ?? '⚔️'}  ${ch.weapon1}`);
    if (ch.weapon2) lines.push(`${ch.weapon2emoji ?? '🗡️'}  ${ch.weapon2}`);
  }
  return lines;
}

// ── Character pages ───────────────────────────────────────────────────────────
// Inventory, standing, lore and roll history: the things a character accumulates
// over a lifetime that aren't on the stat block.

// ── Merit trading ─────────────────────────────────────────────────────────────
// Merit changes hands between players — payment, tribute, a debt settled — but
// never without a GM seeing it, so a trade is a proposal until one signs it off.
function createMeritTrade(gid, from, to, amount, reason, srcChannel) {
  const r = db.prepare(`INSERT INTO merit_trades (guild_id,from_user,to_user,amount,reason,src_channel,created_at)
                        VALUES (?,?,?,?,?,?,?)`).run(gid, from, to, amount, reason, srcChannel, Date.now());
  return getMeritTrade(gid, r.lastInsertRowid);
}
function getMeritTrade(gid, id) {
  return db.prepare('SELECT * FROM merit_trades WHERE guild_id=? AND id=?').get(gid, id);
}
function setMeritTrade(gid, id, fields) {
  const keys = Object.keys(fields || {});
  if (keys.length) db.prepare(`UPDATE merit_trades SET ${keys.map(k => `${k}=?`).join(',')} WHERE guild_id=? AND id=?`)
    .run(...keys.map(k => fields[k]), gid, id);
  return getMeritTrade(gid, id);
}
function pendingMeritTrades(gid) {
  return db.prepare(`SELECT * FROM merit_trades WHERE guild_id=? AND state='pending' ORDER BY created_at`).all(gid);
}
function meritTradeButtons(id) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`tradeok:${id}`).setLabel('Approve trade').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`tradeno:${id}`).setLabel('Refuse').setStyle(ButtonStyle.Danger),
  );
}

function addItem(gid, uid, item, { note = null, source = null, by = null } = {}) {
  // The ledger was always in the data — source, giver, timestamp. Now it
  // reaches a shelf where somebody can read it.
  try {
    bookLog(gid, 'items', `🧳 <@${uid}> received **${item}**${note ? ` — _${note}_` : ''}${by ? ` · from <@${by}>` : ''}${source ? ` · ${source}` : ''}`);
  } catch {}
  db.prepare('INSERT INTO inventory (guild_id,user_id,item,note,source,added_by,at) VALUES (?,?,?,?,?,?,?)')
    .run(gid, uid, item, note, source, by, Date.now());
}
function listItems(gid, uid) {
  return db.prepare('SELECT * FROM inventory WHERE guild_id=? AND user_id=? ORDER BY at DESC').all(gid, uid);
}
function removeItem(gid, id, uid) {
  return db.prepare('DELETE FROM inventory WHERE guild_id=? AND id=? AND user_id=?').run(gid, id, uid).changes > 0;
}

// Every natural die a character has ever rolled, kept per die size so a d20's
// twenty and a d6's six don't land in the same bucket.
function tallyRoll(gid, uid, nat, sides) {
  if (!uid || !Number.isFinite(nat) || !Number.isFinite(sides)) return;
  db.prepare(`INSERT INTO roll_tally (guild_id,user_id,sides,nat,count) VALUES (?,?,?,?,1)
              ON CONFLICT(guild_id,user_id,sides,nat) DO UPDATE SET count = count + 1`)
    .run(gid, uid, sides, nat);
}
function rollTally(gid, uid, sides = 20) {
  const rows = db.prepare('SELECT nat, count FROM roll_tally WHERE guild_id=? AND user_id=? AND sides=? ORDER BY nat').all(gid, uid, sides);
  const by = {}; let total = 0;
  for (const r of rows) { by[r.nat] = r.count; total += r.count; }
  return { by, total };
}
// Everything a character has ever rolled, across every die size.
function rollTallyAll(gid, uid) {
  const rows = db.prepare('SELECT sides, nat, count FROM roll_tally WHERE guild_id=? AND user_id=? ORDER BY sides, nat').all(gid, uid);
  const bySize = {}; let total = 0;
  for (const r of rows) {
    const b = (bySize[r.sides] = bySize[r.sides] || { by: {}, total: 0, sum: 0 });
    b.by[r.nat] = r.count; b.total += r.count; b.sum += r.nat * r.count;
    total += r.count;
  }
  return { bySize, total };
}

// Merit and renown movements, newest first, from the two logs they live in.
function standingEvents(gid, uid, limit = 20) {
  const merits = db.prepare(`SELECT amount AS delta, reason, created_at AS at, 'merit' AS kind FROM history
                             WHERE guild_id=? AND kind='merit' AND user_id=? ORDER BY created_at DESC LIMIT ?`).all(gid, uid, limit);
  const renown = db.prepare(`SELECT delta, reason, at, 'renown' AS kind FROM renown_log
                             WHERE guild_id=? AND user_id=? ORDER BY at DESC LIMIT ?`).all(gid, uid, limit);
  return [...merits, ...renown].sort((a, b) => (b.at || 0) - (a.at || 0)).slice(0, limit);
}

function getLore(gid, uid) { return db.prepare('SELECT * FROM lore WHERE guild_id=? AND user_id=?').get(gid, uid); }
function setLore(gid, uid, fields) {
  if (!getLore(gid, uid)) db.prepare('INSERT INTO lore (guild_id,user_id,body) VALUES (?,?,?)').run(gid, uid, fields.body ?? '');
  const keys = Object.keys(fields || {});
  if (keys.length) db.prepare(`UPDATE lore SET ${keys.map(k => `${k}=?`).join(',')} WHERE guild_id=? AND user_id=?`)
    .run(...keys.map(k => fields[k]), gid, uid);
  return getLore(gid, uid);
}
function loreButtons(uid) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`loreok:${uid}`).setLabel('Approve lore').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`loreno:${uid}`).setLabel('Reject').setStyle(ButtonStyle.Danger),
  );
}

