// One category for the table, one for the GMs. The permissions sit on the
// CATEGORY, so every channel inside inherits them — and anything added later
// is private by being put in the right place, rather than by remembering.
async function ensureSetupCategory(guild, gid, name, gmOnly) {
  const { ChannelType, PermissionFlagsBits } = require('discord.js');
  let cat = guild.channels.cache.find(c => c.type === ChannelType.GuildCategory && c.name === name);
  if (!cat) {
    const overwrites = [];
    if (gmOnly) {
      overwrites.push({ id: guild.roles.everyone.id, deny: [PermissionFlagsBits.ViewChannel] });
      for (const rid of getGmRoleIds(gid)) overwrites.push({ id: rid, allow: [PermissionFlagsBits.ViewChannel] });
      const me = guild.members.me?.id;
      if (me) overwrites.push({ id: me, allow: [PermissionFlagsBits.ViewChannel] });
    }
    cat = await guild.channels.create({ name, type: ChannelType.GuildCategory,
      permissionOverwrites: overwrites.length ? overwrites : undefined });
  } else if (gmOnly) {
    // It already exists — make sure it is actually shut, and that the GM
    // roles named since can see in.
    try {
      await cat.permissionOverwrites.edit(guild.roles.everyone.id, { ViewChannel: false });
      for (const rid of getGmRoleIds(gid)) await cat.permissionOverwrites.edit(rid, { ViewChannel: true });
    } catch { /* no permission to adjust — the channels still land inside */ }
  }
  return cat;
}

// Make one channel, or adopt the one already there. Returns what happened so
// the reply can be honest about it.
async function setupOneChannel(guild, gid, plan, category) {
  const { ChannelType, PermissionFlagsBits } = require('discord.js');
  const cfg = getConfig(gid) || {};
  // One config holds a whole map rather than a bare id — the audit forum
  // keeps its shelves beside it — so read and write that one in its shape.
  const readId = (v) => {
    if (!plan.json) return v;
    try { return JSON.parse(v || '{}')[plan.json] || null; } catch { return null; }
  };
  const writeId = (id) => setConfig(gid, plan.json
    ? { [plan.key]: JSON.stringify({ ...(JSON.parse(cfg[plan.key] || '{}')), [plan.json]: id }) }
    : { [plan.key]: id });
  // Already pointed at something live? Leave it entirely alone.
  const existingId = readId(cfg[plan.key]);
  if (existingId) {
    const ch = await guild.channels.fetch(existingId).catch(() => null);
    if (ch) return { state: 'kept', id: ch.id, name: plan.name };
  }
  // A channel already named for this purpose is adopted rather than doubled.
  const named = guild.channels.cache.find(c => c.name === plan.name
    && c.type === (plan.forum ? ChannelType.GuildForum : ChannelType.GuildText));
  if (named) {
    writeId(named.id);
    return { state: 'adopted', id: named.id, name: plan.name };
  }
  // No overwrites of its own: it inherits from the category it is put in,
  // which is what keeps the two sections honest.
  const made = await guild.channels.create({
    name: plan.name,
    type: plan.forum ? ChannelType.GuildForum : ChannelType.GuildText,
    parent: category?.id ?? null,
    topic: plan.about.slice(0, 1000),
  });
  writeId(made.id);
  return { state: 'made', id: made.id, name: plan.name };
}

// A category named when an NPC is created is made if it is new — so the
// first enemy you write brings "Enemy" into being, and everyone after joins
// it. Matching is case-insensitive, so "enemy" does not become a second one.
function fileNpcByCategory(interaction, gid, npcName) {
  const raw = (interaction.options?.getString?.('category') || '').trim().slice(0, 60);
  if (!raw) return null;
  const known = getCategories(gid).find(c => c.toLowerCase() === raw.toLowerCase());
  const cat = known || raw;
  if (!known) createCategory(gid, cat);
  assignNpcToCategory(gid, npcName, cat);
  return { cat, made: !known };
}

// ── The NPC forum ────────────────────────────────────────────
// A thread per NPC, tagged with the categories they belong to — so Discord's
// own filter does the sorting, and an NPC in three categories is still one
// page rather than three. The npcs table stays the truth; this is the copy.

// Discord allows a forum twenty tags. Categories beyond that simply go
// untagged rather than the whole thing failing.
async function ensureNpcTags(forum, gid) {
  const want = getCategories(gid).slice(0, 20);
  const have = forum.availableTags || [];
  const missing = want.filter(c => !have.some(t => t.name.toLowerCase() === c.toLowerCase()));
  if (missing.length && have.length + missing.length <= 20) {
    try {
      await forum.setAvailableTags([...have.map(t => ({ name: t.name, emoji: t.emoji, moderated: t.moderated })),
        ...missing.map(c => ({ name: c.slice(0, 20) }))]);
    } catch (err) { console.error('[npcforum] tags -', err?.message || err); }
  }
  const map = {};
  for (const t of (await forum.fetch().catch(() => forum)).availableTags || []) map[t.name.toLowerCase()] = t.id;
  return map;
}

// What an NPC's page says. Their statblock the way this server's rules read
// it, their categories, their face, and whatever lore has been written.
function npcPageBody(gid, npc) {
  const rules = rulesFor(gid);
  const cats = getCategoriesForNpc(gid, npc.name);
  const lines = [`🎭 **${npc.name}**${npc.order_name ? ` — ${KNIGHT_EMOJIS[npc.order_name] ?? '⚪'} ${npc.order_name}` : ''}`];
  if (rules.defence === 'ac') {
    const mod = (st) => { const m = rules.statBonus(npc, st); return m >= 0 ? `+${m}` : `${m}`; };
    lines.push(`🛡️ AC **${rules.targetNumber(npc)}** · ❤️ **${npc.hp_current}${npc.max_hp ? ` / ${npc.max_hp}` : ''}**`
      + `${npc.attack_bonus != null ? ` · ⚔️ **+${npc.attack_bonus}**` : ''}${npc.damage_dice ? ` · 🎲 ${npc.damage_dice}` : ''}`);
    lines.push(rules.stats.map(st => `${rules.labels[st]} ${npc[st] ?? 10} (${mod(st)})`).join(' · '));
  } else {
    lines.push(rules.stats.map(st => `${rules.labels[st]} ${npc[st] ?? 0}`).join(' ')
      + ` | ❤️ ${npc.hp_current}/${maxHpFromCon(gid, npc.con)}`);
  }
  if (cats.length) lines.push(`📁 ${cats.join(' · ')}`);
  const face = npcFace(gid, npc);
  if (face) lines.push(face);
  if (npc.lore) lines.push('', String(npc.lore).slice(0, 900));
  // The same titles and associations a player's page shows, in the same
  // words — an NPC's standing reads like a knight's.
  const tl = titlesLine(gid, npcFighterId(npc.name));
  if (tl) lines.push('', tl);

  return lines.join('\n').slice(0, 1990);
}

// The thread for one category, made if it is not there yet. The category is
// the thread's name and its applied tag, so the forum's own filter and the
// thread list say the same thing.
const NPC_THREAD_TABLES = { pages: 'npc_category_threads', portraits: 'npc_portrait_threads' };
async function ensureCategoryThread(client, forum, gid, category, tagMap, kind = 'pages') {
  // Whitelisted, never interpolated from anything a user typed.
  const table = NPC_THREAD_TABLES[kind] || NPC_THREAD_TABLES.pages;
  let row = null;
  try { row = db.prepare(`SELECT thread_id FROM ${table} WHERE guild_id=? AND category=?`).get(gid, category); } catch {}
  if (row?.thread_id) {
    const th = await client.channels.fetch(row.thread_id).catch(() => null);
    if (th?.isThread?.() && th.parentId === forum.id) { await wakeThread(th); return th; }
    // Deleted by hand — forget it and make another.
    try { db.prepare(`DELETE FROM ${table} WHERE guild_id=? AND category=?`).run(gid, category); } catch {}
  }
  const tag = tagMap[category.toLowerCase()];
  const thread = await forum.threads.create({
    name: category.slice(0, 100),
    autoArchiveDuration: 10080,
    appliedTags: tag ? [tag] : undefined,
    message: { content: kind === 'portraits'
      ? `🖼 **${category}** — post a picture here with the NPC's name as the caption, and they will wear it.`
      : `📁 **${category}** — every NPC in this category, an entry apiece.`,
      allowedMentions: { parse: [] } },
  }).catch(() => null);
  if (!thread) return null;
  try {
    db.prepare(`INSERT INTO ${table} (guild_id, category, thread_id, at) VALUES (?,?,?,?)
                ON CONFLICT(guild_id, category) DO UPDATE SET thread_id=excluded.thread_id, at=excluded.at`)
      .run(gid, category, thread.id, Date.now());
  } catch {}
  return thread;
}

// Make the entry, or bring it up to date. Best-effort throughout: an NPC is
// saved whether or not the forum takes them.
async function mirrorNpcSheet(client, gid, name) {
  const forumId = getConfig(gid)?.npc_forum;
  if (!forumId) return null;
  const npc = getNpc(gid, name);
  if (!npc) return null;
  if (npc.is_temp) return null;                 // temporary: no page, by design
  const forum = await client.channels.fetch(forumId).catch(() => null);
  if (!forum || forum.type !== 15) return null;

  // One NPC, one thread: the thread IS the page, its tags ARE the
  // categories, and Discord's own tag filter does the searching. The old
  // shape (thread per category, NPC as a message) could never be filtered
  // — tags stick to threads, never to messages.
  const tagMap = await ensureNpcTags(forum, gid);
  const cats = getCategoriesForNpc(gid, name);
  const applied = cats.map(c => tagMap[c.toLowerCase()]).filter(Boolean).slice(0, 5);
  const body = npcPageBody(gid, npc);

  let row = null;
  try { row = db.prepare('SELECT * FROM npc_pages WHERE guild_id=? AND name=?').get(gid, name); } catch {}
  let thread = row?.thread_id ? await client.channels.fetch(row.thread_id).catch(() => null) : null;
  if (thread && !thread.isThread?.()) thread = null;
  // A row can point at an OLD category thread ("Gold Knight") rather than
  // the NPC's own. Editing there re-feeds the retired shape — so a name
  // mismatch reads as "no thread yet": build theirs, overwrite the row.
  if (thread && thread.name !== name.slice(0, 100)) thread = null;

  if (!thread) {
    thread = await forum.threads.create({
      name: name.slice(0, 100),
      message: { content: body, allowedMentions: { parse: [] } },
      appliedTags: applied,
    }).catch(() => null);
    if (!thread) return null;
    // A forum starter message shares its thread's id.
    db.prepare(`INSERT INTO npc_pages (guild_id, name, thread_id, message_id, at) VALUES (?,?,?,?,?)
                ON CONFLICT(guild_id, name) DO UPDATE SET thread_id=excluded.thread_id,
                  message_id=excluded.message_id, at=excluded.at`)
      .run(gid, name, thread.id, thread.id, Date.now());
    return thread;
  }

  await wakeThread(thread);
  if (thread.name !== name.slice(0, 100)) await thread.setName(name.slice(0, 100)).catch(() => {});
  const haveTags = [...(thread.appliedTags || [])].sort().join(',');
  if (haveTags !== [...applied].sort().join(',')) await thread.setAppliedTags(applied).catch(() => {});
  const msg = await thread.messages.fetch(row.message_id || thread.id).catch(() => null);
  if (msg) { await msg.edit({ content: body, allowedMentions: { parse: [] } }).catch(() => {}); return thread; }
  const m = await thread.send({ content: body, allowedMentions: { parse: [] } }).catch(() => null);
  if (m) db.prepare('UPDATE npc_pages SET message_id=?, at=? WHERE guild_id=? AND name=?').run(m.id, Date.now(), gid, name);
  return thread;
}

// The portrait forum, laid out to match the page forum: a thread per
// category, same names, same tags. A GM hunting for a face looks where they
// look for the statblock.
//
// A text channel is still accepted — servers set one before this was a forum
// and captioned uploads there work exactly as they always did — so this is a
// no-op unless the configured channel is a forum.
async function ensurePortraitThreads(client, gid) {
  const id = getConfig(gid)?.npc_channel_id;
  if (!id) return 0;
  const forum = await client.channels.fetch(id).catch(() => null);
  if (!forum || forum.type !== 15) return 0;
  const tagMap = await ensureNpcTags(forum, gid);
  let made = 0;
  // Categories, then every known order, then the catch-all. Orders carry no
  // forum tag — the 20-available-tags ceiling belongs to categories.
  const wanted = [...new Set([...getCategories(gid), ...knownOrders(gid), NPC_NO_CATEGORY])];
  for (const cat of wanted) {
    const th = await ensureCategoryThread(client, forum, gid, cat, tagMap, 'portraits').catch(() => null);
    if (th) made++;
  }
  return made;
}

// Lay the whole forum out again: every NPC into their category's thread,
// then close whatever per-NPC threads the old layout left standing. Safe to
// run twice — the second pass finds nothing to close.
async function rebuildNpcForum(client, gid) {
  const forumId = getConfig(gid)?.npc_forum;
  if (!forumId) return { written: 0, closed: 0 };
  const forum = await client.channels.fetch(forumId).catch(() => null);
  if (!forum || forum.type !== 15) return { written: 0, closed: 0 };

  const before = db.prepare('SELECT DISTINCT thread_id FROM npc_pages WHERE guild_id=? AND thread_id IS NOT NULL')
    .all(gid).map(r => r.thread_id);

  // Per-NPC threads now: tags exist for every category, then the roster
  // walk gives each NPC their thread. Category threads in THIS forum are a
  // retired shape — any still recorded are closed below; the portrait
  // forum keeps its category/order threads untouched.
  try { await ensureNpcTags(forum, gid); } catch {}
  try {
    for (const r of db.prepare('SELECT category, thread_id FROM npc_category_threads WHERE guild_id=?').all(gid)) {
      const th = await client.channels.fetch(r.thread_id).catch(() => null);
      if (th?.isThread?.() && th.parentId === forum.id) await th.delete().catch(() => {});
      if (th?.parentId === forum.id || !th) db.prepare('DELETE FROM npc_category_threads WHERE guild_id=? AND category=?').run(gid, r.category);
    }
  } catch {}

  // The page map is deliberately NOT cleared first. mirrorNpcSheet already
  // knows how to move an entry — it deletes the old message when the thread
  // changes and edits in place when it has not. Wiping the map instead makes
  // every NPC look new, so a second run posts a fresh entry beside the one
  // already there and orphans it: the whole forum duplicated, quietly, on
  // the second press.
  let written = 0;
  for (const npcRow of getAllNpcs(gid)) {
    const th = await mirrorNpcSheet(client, gid, npcRow.name).catch(() => null);
    if (th) written++;
  }

  // Only now is the keep-list knowable: the category threads are the ones
  // the pass above just used.
  await ensurePortraitThreads(client, gid).catch(() => 0);

  const keep = new Set(db.prepare('SELECT thread_id FROM npc_category_threads WHERE guild_id=?')
    .all(gid).map(r => r.thread_id));
  let closed = 0;
  for (const tid of before) {
    if (keep.has(tid)) continue;
    const th = await client.channels.fetch(tid).catch(() => null);
    if (th?.isThread?.() && th.parentId === forum.id) {
      await th.delete('NPC pages folded into category threads').catch(() => {});
      closed++;
    }
  }
  return { written, closed };
}

// Fire and forget: a page is never worth delaying a command for.
function touchNpcPage(gid, name) {
  (async () => { try { await mirrorNpcSheet(client, gid, name); }
    catch (err) { console.error('[npcforum]', err?.message || err); } })();
}

// ── The library ───────────────────────────────────────────────
// One entry a line. The name comes first; everything after it is a field
// named in plain words, separated by pipes, in any order. Anything the
// parser doesn't recognise is kept as a note rather than thrown away — a
// GM's own wording is worth more than a tidy refusal.
function parseLibraryLine(line) {
  const raw = String(line || '').trim();
  const m = /^\[(MONSTER|SPELL)\]\s*(.+)$/i.exec(raw);
  if (!m) return null;
  const kind = m[1].toLowerCase();
  const parts = m[2].split('|').map(x => x.trim()).filter(Boolean);
  if (!parts.length) return null;
  const out = { kind, name: parts[0].slice(0, 80), notes: [] };
  for (const p of parts.slice(1)) {
    const f = /^([a-z_ ]+?)\s+(.+)$/i.exec(p);
    if (!f) { out.notes.push(p); continue; }
    const key = f[1].toLowerCase().trim().replace(/\s+/g, '_');
    const val = f[2].trim();
    switch (key) {
      case 'ac': case 'armour_class': case 'armor_class': out.ac = parseInt(val); break;
      case 'hp': case 'hit_points': out.hp = parseInt(val); break;
      case 'attack': case 'to_hit': out.attack = parseInt(val.replace('+', '')); break;
      case 'damage': case 'dmg': out.damage = val.slice(0, 40); break;
      case 'cr': case 'challenge': out.cr = val.slice(0, 12); break;
      case 'type': case 'kind': out.type = val.slice(0, 60); break;
      case 'level': out.level = /cantrip/i.test(val) ? 0 : parseInt(val); break;
      case 'school': out.school = val.slice(0, 30); break;
      case 'time': case 'casting_time': out.casting_time = val.slice(0, 40); break;
      case 'range': out.range_text = val.slice(0, 40); break;
      case 'components': case 'comp': out.components = val.slice(0, 40); break;
      case 'duration': out.duration = val.slice(0, 60);
        if (/concentration/i.test(val)) out.concentration = 1; break;
      case 'str': case 'dex': case 'con': case 'int': case 'wis': case 'cha': {
        // A statblock usually gives all six in one breath — "str 8 dex 14
        // con 10 …" — so read every pair in the field, not just the first.
        const runs = [...p.matchAll(/\b(str|dex|con|int|wis|cha)\s+(\d{1,2})\b/gi)];
        for (const r of runs) out[r[1].toLowerCase()] = parseInt(r[2]);
        break;
      }
      default: out.notes.push(p);
    }
  }
  // A statblock can also give its six abilities in one run: "str 8 dex 14 ..."
  for (const n of [...out.notes]) {
    const runs = [...n.matchAll(/\b(str|dex|con|int|wis|cha)\s+(\d{1,2})\b/gi)];
    if (runs.length >= 3) {
      for (const r of runs) out[r[1].toLowerCase()] = parseInt(r[2]);
      out.notes = out.notes.filter(x => x !== n);
    }
  }
  out.notes = out.notes.join(' · ').slice(0, 600) || null;
  if (kind === 'monster' && (out.ac == null || out.hp == null)) return { ...out, error: 'needs at least `ac` and `hp`' };
  if (kind === 'spell' && out.level == null) return { ...out, error: 'needs a `level` (0 for a cantrip)' };
  return out;
}

// Read a whole paste: every line that looks like an entry, and a tally of
// what could not be read, so nothing fails silently.
function importLibrary(gid, uid, text, { source = 'imported', replace = false } = {}) {
  const added = [], skipped = [], bad = [];
  for (const line of String(text || '').split(/\r?\n/)) {
    if (!line.trim() || line.trim().startsWith('#')) continue;
    const e = parseLibraryLine(line);
    if (!e) { if (/^\[/.test(line.trim())) bad.push(`${line.trim().slice(0, 50)} — unreadable`); continue; }
    if (e.error) { bad.push(`${e.name} — ${e.error}`); continue; }
    try {
      if (e.kind === 'monster') {
        const exists = db.prepare('SELECT name FROM library_monsters WHERE guild_id=? AND name=? COLLATE NOCASE').get(gid, e.name);
        if (exists && !replace) { skipped.push(e.name); continue; }
        db.prepare(`INSERT INTO library_monsters
          (guild_id,name,ac,hp,attack,damage,str,dex,con,int,wis,cha,kind,cr,notes,source,added_by,at)
          VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
          ON CONFLICT(guild_id,name) DO UPDATE SET ac=excluded.ac, hp=excluded.hp, attack=excluded.attack,
            damage=excluded.damage, str=excluded.str, dex=excluded.dex, con=excluded.con, int=excluded.int,
            wis=excluded.wis, cha=excluded.cha, kind=excluded.kind, cr=excluded.cr, notes=excluded.notes`)
          .run(gid, e.name, e.ac ?? null, e.hp ?? null, e.attack ?? null, e.damage ?? null,
               e.str ?? 10, e.dex ?? 10, e.con ?? 10, e.int ?? 10, e.wis ?? 10, e.cha ?? 10,
               e.type ?? null, e.cr ?? null, e.notes, source, uid, Date.now());
      } else {
        const exists = db.prepare('SELECT name FROM library_spells WHERE guild_id=? AND name=? COLLATE NOCASE').get(gid, e.name);
        if (exists && !replace) { skipped.push(e.name); continue; }
        db.prepare(`INSERT INTO library_spells
          (guild_id,name,level,school,casting_time,range_text,components,duration,concentration,body,source,added_by,at)
          VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)
          ON CONFLICT(guild_id,name) DO UPDATE SET level=excluded.level, school=excluded.school,
            casting_time=excluded.casting_time, range_text=excluded.range_text, components=excluded.components,
            duration=excluded.duration, concentration=excluded.concentration, body=excluded.body`)
          .run(gid, e.name, e.level ?? 0, e.school ?? null, e.casting_time ?? null, e.range_text ?? null,
               e.components ?? null, e.duration ?? null, e.concentration ?? 0, e.notes, source, uid, Date.now());
      }
      added.push(e.name);
    } catch (err) { bad.push(`${e.name} — ${err?.message || err}`); }
  }
  return { added, skipped, bad };
}

// What a caster has spent, as a map of spell level to count.
function slotsSpent(ch) {
  try { return JSON.parse(ch?.slots_used || '{}') || {}; } catch { return {}; }
}
// One line per spell level: ● for a slot in hand, ○ for one spent.
function slotLines(rules, ch) {
  // Self-guarding, like conditionMode: a ruleset without slots has nothing
  // to draw, whoever asks. A helper should not depend on its caller's care.
  if (typeof rules.slots !== 'function') return [];
  const have = rules.slots(ch);
  const spent = slotsSpent(ch);
  const out = [];
  have.forEach((n, i) => {
    if (!n) return;
    const lvl = i + 1, used = Math.min(n, Number(spent[lvl]) || 0);
    out.push(`　 **${lvl}**  ${'●'.repeat(n - used)}${'○'.repeat(used)}   ${n - used} of ${n}`);
  });
  return out;
}

async function handleSpell(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const rules = rulesFor(gid);
  if (rules.id !== 'dnd5e') {
    return interaction.reply({ ephemeral: true, content: `❌ Spell slots belong to 5e; this server plays by **${rules.name}**.` });
  }
  const sub = interaction.options.getSubcommand();
  const who = interaction.options.getUser?.('user');
  const targetId = (sub === 'slots' && who) ? who.id : uid;
  const ch = getChar(gid, targetId);
  if (!ch) return interaction.reply({ content: '❌ No character there yet.', ephemeral: true });
  const caster = rules.caster(ch);
  const nm = await getDisplayName(interaction.guild, targetId);

  if (sub === 'slots') {
    if (!caster) return interaction.reply({ ephemeral: true, content: `📖 **${nm}** casts no spells${ch.char_class ? ` — a ${ch.char_class} works by other means` : ''}.` });
    const lines = [`📖 **${nm}** · ${ch.char_class} ${ch.level ?? 1}`,
      `✨ Spell save **DC ${rules.spellSaveDC(ch)}** · attack **+${rules.spellAttack(ch)}** · cast off **${rules.labels[caster.ability]}**`];
    const prep = rules.prepareCount(ch);
    if (prep) lines.push(`📜 Prepares **${prep}** spells`);
    const rows = slotLines(rules, ch);
    lines.push('', ...(rows.length ? rows : ['　 _No slots yet._']));
    if (caster.kind === 'pact') lines.push('', '_Pact magic — these come back on a **short** rest._');
    if (ch.concentrating) lines.push('', `🧠 Concentrating on **${ch.concentrating}**`);
    return interaction.reply({ content: lines.join('\n'), ephemeral: sub === 'slots' && !!who });
  }

  if (sub === 'cast') {
    if (!caster) return interaction.reply({ content: '❌ You cast no spells.', ephemeral: true });
    const lvl = interaction.options.getInteger('level');
    if (lvl === 0) {
      // A cantrip costs nothing and grows on its own at 5th, 11th and 17th.
      const name0 = (interaction.options.getString('name') || '').trim().slice(0, 80);
      const tier = rules.cantripTier(ch);
      return interaction.reply({ content: [
        `✨ **${nm}** casts${name0 ? ` **${name0}**` : ' a cantrip'} — no slot spent.`,
        `📐 At level ${ch.level ?? 1} its dice are at **tier ${tier}** of four.`,
        `✨ Save **DC ${rules.spellSaveDC(ch)}** · attack **+${rules.spellAttack(ch)}**`].join('\n') });
    }
    const have = rules.slots(ch);
    const there = Number(have[lvl - 1]) || 0;
    if (!there) return interaction.reply({ ephemeral: true, content: `❌ You have no **level ${lvl}** slots at all${caster.kind === 'pact' ? ' — pact magic casts at one level only' : ''}.` });
    const spent = slotsSpent(ch);
    const used = Number(spent[lvl]) || 0;
    if (used >= there) return interaction.reply({ ephemeral: true, content: `❌ Every **level ${lvl}** slot is spent. ${caster.kind === 'pact' ? 'A short rest brings them back.' : 'They return on a long rest.'}` });
    spent[lvl] = used + 1;
    const name = (interaction.options.getString('name') || '').trim().slice(0, 80);
    const conc = interaction.options.getBoolean('concentration') ?? false;
    const patch = { slots_used: JSON.stringify(spent) };
    const lines = [`✨ **${nm}** casts${name ? ` **${name}**` : ''} at **level ${lvl}** — ${there - used - 1} of ${there} left.`];
    if (conc) {
      if (ch.concentrating) lines.push(`🧠 **${ch.concentrating}** slips away — only one spell at a time.`);
      patch.concentrating = name || `a level ${lvl} spell`;
      lines.push(`🧠 Concentrating on **${patch.concentrating}**.`);
    }
    upsertChar(gid, targetId, patch);
    lines.push(`✨ Save **DC ${rules.spellSaveDC(ch)}** · attack **+${rules.spellAttack(ch)}**`);
    return interaction.reply({ content: lines.join('\n') });
  }

  if (sub === 'prepare') {
    const cap = rules.prepareCount(ch);
    if (!cap) {
      return interaction.reply({ ephemeral: true, content: caster
        ? `❌ A ${ch.char_class} does not prepare spells — they know the ones they know.`
        : '❌ You cast no spells.' });
    }
    let list = [];
    try { list = JSON.parse(ch.prepared_spells || '[]') || []; } catch {}
    if (interaction.options.getBoolean('clear')) {
      upsertChar(gid, targetId, { prepared_spells: '[]' });
      return interaction.reply({ content: `📜 **${nm}** clears their prepared spells — ${cap} may be readied.` });
    }
    const add = (interaction.options.getString('add') || '').trim().slice(0, 60);
    const drop = (interaction.options.getString('drop') || '').trim().toLowerCase();
    if (add) {
      if (list.some(x => x.toLowerCase() === add.toLowerCase())) {
        return interaction.reply({ content: `❌ **${add}** is already prepared.`, ephemeral: true });
      }
      if (list.length >= cap) {
        return interaction.reply({ ephemeral: true, content:
          `❌ You may hold **${cap}** ready and already have that many. Drop one first — \`/spell prepare drop:\`.` });
      }
      list.push(add);
    }
    if (drop) {
      const before = list.length;
      list = list.filter(x => x.toLowerCase() !== drop);
      if (list.length === before) return interaction.reply({ content: `❌ **${drop}** was not prepared.`, ephemeral: true });
    }
    upsertChar(gid, targetId, { prepared_spells: JSON.stringify(list) });
    const lines = [`📜 **${nm}** · ${list.length} of **${cap}** prepared`];
    lines.push(list.length ? list.map(x => `　• ${x}`).join('\n') : '　 _Nothing readied yet._');
    return interaction.reply({ content: lines.join('\n') });
  }

  if (sub === 'concentration') {
    if (interaction.options.getBoolean('drop')) {
      if (!ch.concentrating) return interaction.reply({ content: '🧠 You were not holding anything.', ephemeral: true });
      upsertChar(gid, targetId, { concentrating: null });
      return interaction.reply({ content: `🧠 **${nm}** lets **${ch.concentrating}** go.` });
    }
    return interaction.reply({ ephemeral: true, content: ch.concentrating
      ? `🧠 Concentrating on **${ch.concentrating}**. A blow that lands asks for a CON save — DC 10, or half the damage, whichever is harder.`
      : '🧠 You are not concentrating on anything.' });
  }
}

// Gaining a level. The proficiency bonus, the hit points and the hit dice
// all follow from it, so the only thing to decide is the number.
async function handleLevelUp(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const r = rulesFor(gid);
  if (r.id !== 'dnd5e') {
    return interaction.reply({ ephemeral: true, content: `❌ Levels belong to 5e; this server plays by **${r.name}**.` });
  }
  const who = interaction.options.getUser('user');
  let targetId = uid;
  if (who && who.id !== uid) {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs level someone else up.', ephemeral: true });
    targetId = who.id;
  }
  const ch = getChar(gid, targetId);
  if (!ch) return interaction.reply({ content: '❌ No character there yet.', ephemeral: true });
  const from = Math.max(1, Number(ch.level) || 1);
  const to = interaction.options.getInteger('to') ?? from + 1;
  if (to <= from) return interaction.reply({ content: `❌ They are already level **${from}**.`, ephemeral: true });
  if (to > 20) return interaction.reply({ content: '❌ Twenty is the ceiling.', ephemeral: true });

  const before = { hp: r.maxHp(ch), prof: r.profBonus(ch) };
  const after = { ...ch, level: to };
  const gainedHp = r.maxHp(after) - before.hp;
  upsertChar(gid, targetId, {
    level: to,
    hp_current: (Number(ch.hp_current) || 0) + gainedHp,   // the new hit points arrive full
    hit_dice_left: Math.min(r.hitDiceTotal(after), (Number(ch.hit_dice_left) ?? from) + (to - from)),
  });
  const fresh = getChar(gid, targetId);
  const nm = await getDisplayName(interaction.guild, targetId);
  const lines = [`⭐ **${nm}** reaches **level ${to}**${ch.char_class ? ` · ${ch.char_class}` : ''}.`,
    `❤️ HP **${fresh.hp_current} / ${r.maxHp(fresh)}** _(+${gainedHp})_`,
    `🎲 Hit dice **${fresh.hit_dice_left} / ${r.hitDiceTotal(fresh)}** (d${fresh.hit_die || 8})`];
  const nowProf = r.profBonus(fresh);
  if (nowProf !== before.prof) lines.push(`➕ Proficiency is now **+${nowProf}**.`);
  if ([4, 8, 12, 16, 19].includes(to)) lines.push('🌟 An **ability score improvement** is due at this level — or a feat, if your table uses them.');
  const atks = r.attacksPerAction(fresh);
  if (atks > r.attacksPerAction({ ...fresh, level: from })) lines.push(`⚔️ **Extra attack** — ${atks} swings to an action now.`);
  return interaction.reply({ content: lines.join('\n') });
}

// A monster, from its statblock. The four numbers at the top of any entry
// — AC, hit points, attack bonus, damage — are what the table actually
// needs; the six abilities are optional and default to average.
async function handleNpcCreate5e(interaction) {
  const gid = interaction.guild.id;
  const rules = rulesFor(gid);
  if (rules.id !== 'dnd5e') {
    return interaction.reply({ ephemeral: true, content: `❌ This server plays by **${rules.name}**. \`/npc create\` makes one here.` });
  }
  const name = interaction.options.getString('name').trim().slice(0, 80);
  if (getNpc(gid, name)) return interaction.reply({ content: `❌ **${name}** already exists.`, ephemeral: true });
  const dmg = interaction.options.getString('damage').trim();
  if (!/^\d*d\d+([+-]\d+)?$/i.test(dmg)) {
    return interaction.reply({ ephemeral: true, content: '❌ Damage looks like `1d8`, `2d6+3` or `1d12+4`.' });
  }
  const hp = interaction.options.getInteger('hp');
  const row = {
    armour_class: interaction.options.getInteger('ac'),
    attack_bonus: interaction.options.getInteger('attack'),
    damage_dice: dmg, max_hp: hp, hp_current: hp,
  };
  for (const st of rules.stats) row[st] = interaction.options.getInteger(st) ?? 10;
  upsertNpc(gid, name, row);
  const filed5 = fileNpcByCategory(interaction, gid, name);
  touchNpcPage(gid, name);
  const npc = getNpc(gid, name);
  const mod = (st) => { const m = rules.statBonus(npc, st); return m >= 0 ? `+${m}` : `${m}`; };
  return interaction.reply({ content: [
    `✅ **${name}** stands ready.`,
    `🛡️ AC **${row.armour_class}** · ❤️ HP **${hp}** · ⚔️ attack **+${row.attack_bonus}** · 🎲 damage **${dmg}**`,
    rules.stats.map(st => `${rules.labels[st]} ${npc[st]} (${mod(st)})`).join(' · '),
    filed5 ? `📁 Filed under **${filed5.cat}**${filed5.made ? ' — a new category' : ''}.` : null,
  ].filter(Boolean).join('\n') });
}

// A 5e sheet in one command. Scores in, everything derived: modifiers,
// proficiency from level, hit points from the class die and CON.
async function handleCreate5e(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const r = rulesFor(gid);
  if (r.id !== 'dnd5e') {
    return interaction.reply({ ephemeral: true, content:
      `❌ This server plays by **${r.name}**. \`/char create\` makes a character here — or an admin can set the rules with \`/config channels ruleset\` before anyone plays.` });
  }
  if (getChar(gid, uid)) {
    return interaction.reply({ content: '❌ You already have a character. `/char edit` changes one field at a time.', ephemeral: true });
  }
  const name = interaction.options.getString('name').trim().slice(0, 60);
  const cls = interaction.options.getString('class') || null;
  const level = interaction.options.getInteger('level') ?? 1;
  const die = cls ? (DND_HIT_DICE[cls] ?? 8) : 8;
  const scores = {};
  for (const st of r.stats) scores[st] = interaction.options.getInteger(st);

  // Proficiencies are written as they are said: "str, con" or "athletics, stealth".
  const listOf = (raw) => String(raw || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
  const saves = listOf(interaction.options.getString('saves')).filter(x => r.stats.includes(x));
  const skills = listOf(interaction.options.getString('skills')).filter(x => r.skills[x]);
  const badSkills = listOf(interaction.options.getString('skills')).filter(x => !r.skills[x]);
  if (badSkills.length) {
    return interaction.reply({ ephemeral: true, content:
      `❌ I don't know the skill${badSkills.length > 1 ? 's' : ''} **${badSkills.join(', ')}**. The eighteen are: ${Object.keys(r.skills).join(', ')}.` });
  }

  const row = { name, level, char_class: cls, hit_die: die,
    armour_class: interaction.options.getInteger('ac') ?? null,
    proficient: JSON.stringify({ saves, skills }), ...scores };
  row.hp_current = r.maxHp({ ...row });
  row.hit_dice_left = r.hitDiceTotal(row);
  upsertChar(gid, uid, row);
  const ch = getChar(gid, uid);
  const mod = (st) => { const m = r.statBonus(ch, st); return m >= 0 ? `+${m}` : `${m}`; };
  const lines = [`✅ **${name}** is made — ${cls ? `level ${level} ${cls}` : `level ${level}`}.`, '',
    r.stats.map(st => `${r.labels[st]} ${ch[st]} (${mod(st)})`).join(' · '), '',
    `❤️ HP **${ch.hp_current}** · 🛡️ AC **${r.targetNumber(ch)}** · ➕ Proficiency **+${r.profBonus(ch)}**`];
  if (saves.length) lines.push(`💪 Save proficiency: ${saves.map(x => r.labels[x]).join(', ')}`);
  if (skills.length) lines.push(`🎯 Skills: ${skills.join(', ')}`);
  return interaction.reply({ content: lines.join('\n') });
}

// Deception, away from the sword. A straight WIS contest between two
// characters that works anywhere — a market square, a throne room, a tavern
// — and needs no fight to exist. Both roll at once, so it resolves in one
// message; ties go to the target, exactly as the fight version words it.
// Winning leaves them rolling flat on their very next action: inside a live
// fight that is the fooled flag the combat engine already honours, and
// outside one it is a mark on their sheet, spent by whatever they roll next.
async function handleDeception(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id, cid = interactionChannelId(interaction);
  const target = interaction.options.getUser('target');
  if (target.id === uid) return interaction.reply({ content: '🎭 You cannot deceive yourself — not with dice, anyway.', ephemeral: true });
  const me = getChar(gid, uid), them = getChar(gid, target.id);
  const gate = sheetGate(gid, uid);
  if (gate) return interaction.reply({ content: gate, ephemeral: true });
  if (!me) return interaction.reply({ content: '❌ You need a character sheet — `/char create`.', ephemeral: true });
  if (!them) return interaction.reply({ content: `❌ **${await getDisplayName(interaction.guild, target.id)}** has no character sheet yet.`, ephemeral: true });
  const barD = abilityNeeds(gid, 'feint');
  if (belowBar(me, barD)) return interaction.reply({ content: `🎭 Deception takes **${barD.label} ${barD.need}+** — a poor liar only convinces themselves.`, ephemeral: true });
  if (deceptionSpent(gid, uid)) {
    return interaction.reply({ ephemeral: true, content:
      '🎭 That trick is spent — make an ordinary stat roll before trying another. A lie only sells once until you fight straight.' });
  }

  const claim = interaction.options.getString('claim');
  const flavour = interaction.options.getString('flavour');
  const myMode = applyNextMark(gid, uid, applySignatureMode(me, 'wis', 'normal'));
  const theirMode = applyNextMark(gid, target.id, applySignatureMode(them, 'wis', 'normal'));
  const roll = (row, mode) => {
    const notation = `1d20+${row.wis ?? 0}`;
    const r = mode === 'adv' ? rollAdvantage(notation) : mode === 'dis' ? rollDisadvantage(notation) : rollNotation(notation);
    return { r, nat: mode === 'normal' ? r.rolls[0] : r.chosen };
  };
  const a = roll(me, myMode), d = roll(them, theirMode);
  spendDeception(gid, uid);   // one trick per honest roll
  noteHonestRoll(gid, target.id);   // answering honestly re-arms the target's own
  const myName = await getDisplayName(interaction.guild, uid);
  const theirName = await getDisplayName(interaction.guild, target.id);
  const fooled = a.r.total > d.r.total;   // ties go to the target, as in a fight

  const lines = ['─────────────────────────────',
    `🎭  **Deception** — **${myName}** vs **${theirName}**`];
  if (claim) lines.push(`_“${claim}”_`);
  lines.push('',
    `${myName} (**WIS** deception): ${fightTotalStr(a.r.total, a.nat, 20)}`,
    `${theirName} (**WIS** insight): ${fightTotalStr(d.r.total, d.nat, 20)}`, '');
  if (fooled) {
    const f = getFight(gid, cid);
    if (f?.state === 'active' && fightOrder(f).includes(target.id)) {
      setEffectFlag(gid, cid, target.id, 'fooled');
      lines.push(`🎭 **${theirName}** believes it — their next action in this fight is a straight d20.`);
    } else {
      upsertChar(gid, target.id, { next_mark: 'flat' });
      lines.push(`🎭 **${theirName}** believes it — their very next roll, anywhere, is a straight d20.`);
    }
  } else {
    lines.push(`👁️ **${theirName}** sees straight through it.`);
  }
  if (flavour) lines.push('', `_${flavour}_`);
  const result = a.r;   // shorthand below, as every other roll site writes it
  recordRoll(gid, { userId: uid, channelId: cid, interaction, result,
    input: '/deception', rollLine: lines[3], context: `deception vs ${theirName}` });
  return interaction.reply({ content: lines.join('\n'), allowedMentions: { parse: [] } });
}

// ✍️ Answer — a writing box, so a quiz can want words rather than a pick
// from four. Nothing may await before showModal.
function handleStoryAskButton(interaction) {
  const [, owner, sceneName] = interaction.customId.split(':');
  if (interaction.user.id !== owner) {
    return interaction.reply({ content: '🎮 That is someone else\'s run. Start your own with `/activity run`.', ephemeral: true });
  }
  const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
  const modal = new ModalBuilder().setCustomId(`storyans:${sceneName}`).setTitle('Your answer');
  modal.addComponents(new ActionRowBuilder().addComponents(
    new TextInputBuilder().setCustomId('answer').setLabel('Answer').setStyle(TextInputStyle.Short)
      .setRequired(true).setMaxLength(200).setPlaceholder('Type it as you would say it')));
  return interaction.showModal(modal);
}

// The answer comes back: judge it, keep the score, and walk on.
async function handleStoryAnswerModal(interaction) {
  const gid = interaction.guild.id, cid = interactionChannelId(interaction), uid = interaction.user.id;
  const sceneName = interaction.customId.split(':').slice(1).join(':');
  const found = activeSceneFor(interaction, uid, sceneName);
  if (found.error) return interaction.reply({ content: found.error, ephemeral: true });
  const { run, sc } = found;
  const given = interaction.fields.getTextInputValue('answer');
  const wanted = JSON.parse(sc.answers || '[]');
  const right = wanted.length ? wanted.some(w => sameAnswer(given, w)) : true;

  setRun(gid, cid, uid, {
    quiz_asked: (run.quiz_asked ?? 0) + 1,
    quiz_right: (run.quiz_right ?? 0) + (right ? 1 : 0),
  });
  let next = right ? (sc.right_to || sc.wrong_to) : (sc.wrong_to || sc.right_to);
  if (!right && quizModeOf(gid, run.story) === 'retry') next = sc.scene;   // round again
  noteQuizSeen(gid, uid, sc, right);
  noteQuizAnswer(gid, cid, uid, run, { question: sc.say, given, right, explain: sc.explain });
  const silent = quizModeOf(gid, run.story) === 'silent';
  const head = silent
    ? `· **${given}** — _answer recorded._`
    : right
      ? `✅ **${given}** — correct.`
      : `❌ **${given}** — not this time.${wanted.length ? ` _(wanted: ${wanted[0]})_` : ''}`
        + (sc.explain ? `\n_${sc.explain}_` : '');
  await interaction.reply({ content: head });
  if (!next) return;
  const nextSc = getScene(gid, run.story, next);
  if (!nextSc) return;
  setRun(gid, cid, uid, { scene: next });
  const channel = await interactionChannel(interaction);
  if (channel) await postScene(interaction.guild, cid, getRun(gid, cid, uid), nextSc);
}

// The slash twin of the gmr / gmrs chat shorthands — same roll, same audit
// mirror; ‘secret’ lands as an ephemeral reply instead of a DM.
async function runGmRollSlash(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can use GM rolls.', ephemeral: true });
  const notation = interaction.options.getString('notation');
  const label = interaction.options.getString('label');
  const flavour = interaction.options.getString('flavour');
  const secret = interaction.options.getBoolean('secret') ?? false;
  const mode = interaction.options.getString('roll') || 'normal';
  const result = mode === 'adv' ? rollAdvantage(notation) : mode === 'dis' ? rollDisadvantage(notation) : rollNotation(notation);
  if (!result) return interaction.reply({ content: '❌ Invalid notation. Try `/gm roll notation:1d20+5 label:perception`.', ephemeral: true });
  const critType = detectCrit(result, mode);
  const rollLine = buildRollLine(result, mode, critType);
  const lc = critPrefix(critType);
  const lines = [];
  if (label) lines.push(`${lc}**${label}**`);
  lines.push(rollLine);
  if (flavour) {
    lines.push('', '─────────────────────────────');
    lines.push(`**${label ?? 'roll'}** — ${totalStr(result.total, critType)}`);
    lines.push(`*${flavour}*`);
  }
  const content = lines.join('\n');
  mirrorRoll(gid, {
    userId: uid, channelId: interactionChannelId(interaction), messageId: null,
    input: `/gm roll ${notation}${label ? ' ' + label : ''}${secret ? ' 🔒' : ''}`, rollLine,
    context: secret ? 'GM roll · 🔒 secret' : 'GM roll',
  });
  if (secret) return interaction.reply({ content: `🔒 **Secret GM Roll**\n${content}`, ephemeral: true });
  return interaction.reply({ content });
}

// /gm check — the setup mirror. Unset first (with the command that sets each),
// then the set ones with links, every stored id fetch-verified.
async function handleCheck(interaction) {
  // The fold (2026-08-15): check is a GROUP of leaves. The shim keeps the
  // old boolean grammar alive for registrations still propagating — a leaf
  // outranks a boolean, `status` (or bare) falls through to the report.
  const checkLeaf = interaction.options?.getSubcommandGroup?.(false) === 'check'
    ? interaction.options.getSubcommand() : null;
  const opt = (name) => checkLeaf ? checkLeaf === name : !!interaction.options?.getBoolean?.(name);
  // `run:true` builds whatever the code knows about and this server hasn't
  // got yet — the one switch to pull after an update adds a book.
  if (opt('pages')) return rebuildCharPages(interaction);
  if (opt('portraits')) return runPortraitMigration(interaction);
  if (opt('migrations')) {
    // The deploy ledger, in Discord instead of Railway screenshots: every
    // one-time reshape with the counts it stamped when it ran.
    const FLAGS = [['npc_rr_backfill_1', 'NPC reroll backfill'], ['run_rename_2', 'Run christening'],
      ['npc_threads_2', 'NPC threads'], ['char_threads_1', 'Character threads'], ['gm_forum_lock_1', 'GM forum + lock']];
    const rows = FLAGS.map(([k, label]) => {
      let v = null; try { v = db.prepare('SELECT v FROM meta WHERE k=?').get(k)?.v; } catch {}
      return v ? `✅ **${label}** — ${v === '1' ? 'done' : v}` : `❌ **${label}** — pending (runs next boot)`;
    });
    return interaction.reply({ ephemeral: true, content: ['📋 **Migration ledger**', ...rows,
      '_v1 flags (run_rename_1, npc_threads_1) are retired and ignored._'].join('\n') });
  }
  if (opt('order')) {
    // A hand-arranged server is a choice the bot must respect: the
    // diagnostic ASKS before it sorts. Keep = report only, touch nothing.
    const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
    return interaction.reply({ ephemeral: true,
      content: '⚙️ Sidebar diagnostic — how should it run?\n• **Apply plan order** repositions the DDice channels to the setup plan, then reports.\n• **Keep my layout** touches nothing and just reports the current sequences.',
      components: [new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`gmorder:apply:${interaction.user.id}`).setLabel('Apply plan order').setStyle(ButtonStyle.Danger),
        new ButtonBuilder().setCustomId(`gmorder:keep:${interaction.user.id}`).setLabel('Keep my layout — report only').setStyle(ButtonStyle.Secondary),
      )] });
  }
  if (opt('restart')) return runFullRestart(interaction);
  if (opt('build')) return runFullSetup(interaction);
  if (opt('run')) return runSetupRepair(interaction);
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ The setup check is for GMs.', ephemeral: true });
  await interaction.deferReply({ ephemeral: true });
  const cfg = getConfig(gid) || {};
  const routes = (k) => { try { return JSON.parse(cfg[k] || '{}'); } catch { return {}; } };
  const auditR = routes('audit_routes');
  const apprR = routes('approval_routes');
  const planBooks = routes('quest_plan_books');
  const checks = [
    ['📌 Quest board forum', cfg.quest_forum, '`/config channels questforum channel:#forum`', null, 'questforum'],
    ['🗺️ GM quest planning forum', cfg.quest_plan_forum, '`/config channels questplanning channel:#gm-forum`',
      Object.keys(planBooks).length ? `${Object.keys(planBooks).length} books` : null, 'questplanning'],
    ['⚔️ Quest instance forum', cfg.quest_instance_forum, '`/config channels questinstances channel:#` (optional — a thread per running party)',
      null, 'questinstances'],
    ['🧵 Quest threads forum', cfg.quest_thread_forum, '`/config channels questthreads channel:#` (optional — threads default into the planning forum)',
      cfg.quest_thread_forum ? 'per-quest threads + stage tags' : null, 'questthreads'],
    ['📜 Roll audit', auditR.forum ?? cfg.roll_audit_channel_id,
      '`/config channels rollauditforum forum:#forum` (books) · or `/config channels rollaudit channel:#`',
      auditR.forum ? 'books' : (cfg.roll_audit_channel_id ? 'single channel' : null), 'rollaudit'],
    ['📖 Character pages forum', cfg.char_forum, '`/config channels charforum channel:#forum`', null, 'charforum'],
    ['⚖️ Approvals', apprR.forum ?? cfg.approval_channel_id,
      '`/config channels approvalforum forum:#forum` · or `/config channels approvals channel:#`',
      apprR.forum ? 'threads per type' : (cfg.approval_channel_id ? 'single channel' : null), 'approvals'],
    ['🪶 Memorial — GM record', cfg.memorial_channel, '`/config channels memorial channel:#`', null, 'memorial'],
    ['🕯️ Memorial — public hall', cfg.memorial_public_channel, '`/config channels memorial public:#`', null],
    ['📜 Quest log', cfg.quest_log_channel, '`/config channels questlog channel:#`', null, 'questlog'],
    ['🖼️ NPC portrait bank', cfg.npc_channel_id, '`/config channels npcchannel channel:#`', null, 'npcchannel'],
    ['📚 GM docs (the PDFs)', cfg.docs_channel, '`/config channels docs channel:# repo:owner/name`', null],
    ['📜 Scroll library', cfg.scroll_archive_id, '`/config channels scrollarchive channel:#` — a forum gives per-GM threads', null, 'scrollarchive'],
    ['💾 Backups', cfg.backup_channel_id, '`/gm backup auto channel:#`', null],
  ];
  const unset = [], set = [];
  for (const [label, id, cmd, note] of checks) {
    if (!id) { unset.push(`• ${label} — ${cmd}`); continue; }
    let ok = false;
    try { const ch = await interaction.client.channels.fetch(id); ok = !!ch; } catch { /* gone or hidden */ }
    if (ok) set.push(`• ${label} — <#${id}>${note ? ` · ${note}` : ''}`);
    else set.push(`⚠️ ${label} — set but unreachable (deleted, or hidden from me) — re-run ${cmd}`);
  }
  const lines = ['🧭 **Channel & forum check**', ''];
  // Permission audit — read-only, names what `run` would repair.
  try {
    const meS = interaction.guild.members.me;
    const chansS = await interaction.guild.channels.fetch();
    const badS = [];
    for (const ch of chansS.values()) {
      if (!ch || ch.type === 4) continue;
      const permsS = ch.permissionsFor(meS);
      const miss = CHANNEL_PERMS.filter(k2 => { try { return !permsS?.has(k2); } catch { return false; } });
      if (miss.length) badS.push(`${ch.name} (${miss.slice(0, 3).join(', ')})`);
    }
    lines.push(badS.length
      ? `\u26A0\uFE0F Permissions missing in **${badS.length}** channel(s): ${badS.slice(0, 8).join(' \u00B7 ')}${badS.length > 8 ? ' \u2026' : ''} \u2014 \`/gm check run\` repairs what it can`
      : '\u2705 Permissions correct in every channel.', '');
  } catch {}
  if (unset.length) { lines.push(`❌ **Not set** (${unset.length})`, ...unset, ''); }
  else lines.push('✅ Everything channel-backed is configured.', '');
  if (set.length) { lines.push(`✅ **Set** (${set.length})`, ...set); }
  await interaction.editReply({ content: lines.join('\n').slice(0, 2000) });
  // Up to five pickers for the unset channel configs — a pick runs the real
  // config branch, tags, books, threads and all. Forum configs filter to forums.
  try {
    const FORUMS = new Set(['charforum', 'questforum', 'questplanning', 'questthreads', 'rollauditforum', 'approvalforum']);
    const missing = checks.filter(r => !r[1] && r[4]).slice(0, 5);
    if (missing.length) {
      const { ActionRowBuilder, ChannelSelectMenuBuilder, ChannelType } = require('discord.js');
      const selects = missing.map(r => new ActionRowBuilder().addComponents(
        new ChannelSelectMenuBuilder().setCustomId(`checkset:${r[4]}`)
          .setPlaceholder(`${r[0].replace(/^\S+\s/, '').slice(0, 60)} — pick a ${FORUMS.has(r[4]) ? 'forum' : 'channel'}`)
          .setChannelTypes(r[4] === 'scrollarchive' ? [ChannelType.GuildText, ChannelType.GuildForum]
            : FORUMS.has(r[4]) ? [ChannelType.GuildForum] : [ChannelType.GuildText])));
      await interaction.followUp({ ephemeral: true, components: selects,
        content: `🔧 **Quick setup** — pick a channel to run each config right here${checks.filter(r => !r[1] && r[4]).length > 5 ? ' (more appear once these are set)' : ''}:` });
    }
  } catch (err) { console.error('[check] selects failed -', err?.message || err); }
  return;
}

async function handleGmRoll(message, rest, secret) {
  const gid = message.guild.id, uid = message.author.id;
  if (!(await isGm(message.guild, uid))) return message.reply('❌ Only GMs can use GM rolls.');
  const parsed = parseRollInput(rest, null);
  if (!parsed) return message.reply('❌ Invalid notation. Try `gmr 1d20+5 perception`.');
  const result = rollNotation(parsed.notation);
  if (!result) return message.reply('❌ Could not parse dice notation.');
  const critType = detectCrit(result, 'normal');
  const rollLine = buildRollLine(result, 'normal', critType);
  const lc = critPrefix(critType);
  const lines = [];
  if (parsed.label) lines.push(`${lc}**${parsed.label}**`);
  lines.push(rollLine);
  if (parsed.flavour) {
    lines.push('', '─────────────────────────────');
    lines.push(`**${parsed.label??'roll'}** — ${totalStr(result.total, critType)}`);
    lines.push(`*${parsed.flavour}*`);
  }
  const content = lines.join('\n');

  // Mirror GM rolls to the audit channel too — including secret ones, so other
  // GMs can see them. Secret rolls stay hidden from players (DM + private
  // audit channel); only the audit copy is marked so it's clear it was secret.
  mirrorRoll(gid, {
    userId: uid, channelId: message.channel.id, messageId: message.id,
    input: message.content, rollLine,
    context: secret ? 'GM roll · 🔒 secret' : 'GM roll',
  });

  if (secret) {
    try {
      await message.author.send(`🔒 **Secret GM Roll**\n${content}`);
      await message.reply('🔒 Roll sent to your DMs.');
    } catch { await message.reply('❌ Could not DM you. Check your privacy settings.'); }
  } else {
    await message.reply(content);
  }
}


function parseSheetImport(text) {
  // Strip code block markers
  const clean = text.replace(/```/g, '').trim();
  if (!clean.includes('[TTRPG SHEET]')) return null;

  const lines = clean.split('\n');
  const data = {};
  lines.forEach(line => {
    const [key, ...rest] = line.split(':');
    if (key && rest.length) data[key.trim()] = rest.join(':').trim();
  });

  // Validate required fields
  const required = ['STR','CON','DEX','WIS','LCK'];
  for (const f of required) {
    if (data[f] === undefined || isNaN(parseInt(data[f]))) return null;
  }

  return {
    order_name: data['ORDER'] || null,
    class: data['CLASS'] || null,
    str: parseInt(data['STR']),
    con: parseInt(data['CON']),
    dex: parseInt(data['DEX']),
    wis: parseInt(data['WIS']),
    lck: parseInt(data['LCK']),
    hp_current: data['HP'] ? parseInt(data['HP']) : null,
    rerolls_current: data['REROLLS'] ? parseInt(data['REROLLS']) : null,
    weapon1: data['WEAPON1'] || null,
    weapon1emoji: data['WEAPON1EMOJI'] || null,
    weapon2: data['WEAPON2'] || null,
    weapon2emoji: data['WEAPON2EMOJI'] || null,
  };
}

async function handleSheetImport(message, parsed) {
  // Sheets arrive from any channel the bot can read — text, thread, forum post,
  // or the text chat inside a voice or stage channel. Only a DM has no guild.
  if (!message.guild) return message.reply('❌ Import a sheet in a server channel, not a DM — I need to know which server it belongs to.').catch(()=>{});
  const gid = message.guild.id, uid = message.author.id;

  // Check if GM is importing for someone else via mention
  const mentionMatch = message.content.match(/<@!?(\d+)>/);
  let targetId = uid;
  if (mentionMatch && mentionMatch[1] !== uid) {
    if (!(await isGm(message.guild, uid))) return message.reply('\u274c Only GMs can import sheets for other players.');
    targetId = mentionMatch[1];
  }

  // Pasting a sheet rewrites everything — respect the approval lock, and send it
  // back to the queue afterwards, so it can't be used to sidestep a GM.
  const isGmImporter = await isGm(message.guild, uid);
  // A pasted sheet is a whole character, so both rules apply in full.
  if (!isGmImporter) {
    const problems = sheetSubmissionProblems(gid, { ...(getChar(gid, targetId) || {}), ...parsed });
    if (problems.length) return refuseStatBudget({ src: message, gid, uid, problems, stats: parsed,
      jumpId: message.id, reply: async (c) => message.reply(c).catch(() => null) });
  }
  {
    const lock = sheetEditLock(gid, uid, targetId, isGmImporter);
    if (lock) return message.reply(lock);
  }

  const KNIGHTS = ['White Knight','Black Knight','Gold Knight','Grey Knight','Blue Knight','Purple Knight','Green Knight','Red Knight'];

  // Validate order
  if (parsed.order_name && !KNIGHTS.includes(parsed.order_name)) {
    parsed.order_name = null;
  }

  // Apply stats — derive HP max and reroll max from CON and LCK
  const hpMax = maxHpFromCon(gid, parsed.con);
  const rerollMax = parsed.lck;

  // Use imported current values if valid, otherwise max out
  // A brand-new character always starts at full. Only a re-import over an
  // existing sheet keeps the pasted figures — that's a restore, not a creation,
  // and an exported block carries whatever HP the character happened to be on.
  const isNewSheet = !getChar(gid, targetId);
  const hpCurrent = (!isNewSheet && parsed.hp_current !== null && parsed.hp_current <= hpMax)
    ? parsed.hp_current : hpMax;
  const rerollsCurrent = (!isNewSheet && parsed.rerolls_current !== null && parsed.rerolls_current <= rerollMax)
    ? parsed.rerolls_current : rerollMax;

  upsertChar(gid, targetId, {
    order_name: parsed.order_name,
    class: parsed.class || null,
    str: parsed.str, con: parsed.con, dex: parsed.dex,
    wis: parsed.wis, lck: parsed.lck,
    hp_current: hpCurrent,
    rerolls_current: rerollsCurrent,
    weapon1: parsed.weapon1 || null,
    weapon1emoji: validateWeaponEmoji(message.guild, parsed.weapon1emoji) || '⚔️',
    weapon2: parsed.weapon2 || null,
    weapon2emoji: validateWeaponEmoji(message.guild, parsed.weapon2emoji) || '🗡️',
    // An exported sheet carries the emoji the character already had, so a
    // paste counts as a choice — otherwise a re-import would un-finish a sheet.
    ...(parsed.weapon1emoji ? { weapon1emoji_set: 1 } : {}),
    ...(parsed.weapon2emoji ? { weapon2emoji_set: 1 } : {}),
  });

  // Handle heal charges for White Knight
  const updatedChar = getChar(gid, targetId);
  if (isWhiteKnight(updatedChar)) {
    const cfg = getConfig(gid);
    setHealCharges(gid, targetId, cfg.heal_charges ?? 3);
  } else {
    setHealCharges(gid, targetId, 0);
  }

  const targetName = targetId === uid ? 'Your' : `<@${targetId}>'s`;
  const orderLine = parsed.order_name ? `${KNIGHT_EMOJIS[parsed.order_name]??'⚪'} ${parsed.order_name}` : 'No order';
  const lines = [
    `\u2705 ${targetName} character sheet imported.`,
    orderLine,
    `\u2764\ufe0f HP: **${hpCurrent} / ${hpMax}**`,
    `\U0001f504 Rerolls: **${rerollsCurrent} / ${rerollMax}**`,
    '',
    `\U0001f4aa STR ${parsed.str}  \U0001fac0 CON ${parsed.con}  \u26a1 DEX ${parsed.dex}  \U0001f9e0 WIS ${parsed.wis}  \U0001f340 LCK ${parsed.lck}`,
  ];
  await finishSheetEdit({
    src: message, gid, callerId: uid, targetId, isGmCaller: isGmImporter,
    content: lines.join('\n'),
    reply: async (c) => message.reply(c).catch(() => null),
  });
}

async function handleTag(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const sub = interaction.options.getSubcommand();

  // All tag commands are GM only
  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can manage tags.', ephemeral: true });

  if (sub === 'assign') {
    const targetUser = interaction.options.getUser('user');
    const tagName = interaction.options.getString('tag');
    const available = getAllAvailableTags(gid);
    if (!available.includes(tagName))
      return interaction.reply({ content: `❌ Unknown tag. Available: ${available.join(', ')}`, ephemeral: true });
    assignTag(gid, targetUser.id, tagName);
    const emoji = resolveTagEmoji(gid, tagName);
    return interaction.reply({ content: `${emoji} **${tagName}** assigned to <@${targetUser.id}>.` });
  }

  if (sub === 'remove') {
    const targetUser = interaction.options.getUser('user');
    const tagName = interaction.options.getString('tag');
    removeTag(gid, targetUser.id, tagName);
    return interaction.reply({ content: `✅ **${tagName}** removed from <@${targetUser.id}>.` });
  }

  if (sub === 'list') {
    const targetUser = interaction.options.getUser('user') || interaction.user;
    const tags = getPlayerTags(gid, targetUser.id);
    if (!tags.length) return interaction.reply({ content: `<@${targetUser.id}> has no tags assigned.`, ephemeral: true });
    const lines = tags.map(t => `${resolveTagEmoji(gid, t)}  ${t}`);
    return interaction.reply({ content: `**Tags for <@${targetUser.id}>:**\n${lines.join('\n')}`, ephemeral: true });
  }

  if (sub === 'custom') {
    const action = interaction.options.getString('action');

    if (action === 'create') {
      const emoji = interaction.options.getString('emoji');
      const name = interaction.options.getString('name');
      if (!emoji || !name) return interaction.reply({ content: '❌ Please provide both an emoji and a name.', ephemeral: true });

      // Validate emoji format
      const isUnicodeEmoji = /^\p{Emoji}/u.test(emoji);
      const isCustomEmoji = /^<a?:[a-zA-Z0-9_]+:\d+>$/.test(emoji);
      const looksLikeName = /^:[a-zA-Z0-9_]+:$/.test(emoji);

      if (looksLikeName) {
        return interaction.reply({
          content: `❌ **${emoji}** looks like an emoji name, not the emoji itself.\n\nTo get the correct format:\n1. Type \`\\${emoji}\` in any channel and send it\n2. Discord will show the full ID like \`<:name:123456789>\`\n3. Copy that and use it as the emoji`,
          ephemeral: true
        });
      }

      if (!isUnicodeEmoji && !isCustomEmoji) {
        return interaction.reply({
          content: `❌ Invalid emoji format. Use either:\n• A standard emoji: \`⚔️\`\n• A server emoji ID: \`<:emojiname:123456789012345678>\`\n\nTo get a server emoji ID, type \`\\:emojiname:\` in chat and copy the result.`,
          ephemeral: true
        });
      }

      addCustomTag(gid, name, emoji);
      return interaction.reply({ content: `${emoji} Custom tag **${name}** created.` });
    }

    if (action === 'delete') {
      const name = interaction.options.getString('name');
      if (!name) return interaction.reply({ content: '❌ Please provide the tag name to delete.', ephemeral: true });
      deleteCustomTag(gid, name);
      return interaction.reply({ content: `✅ Custom tag **${name}** deleted and removed from all players.` });
    }

    if (action === 'list') {
      const customs = getCustomTags(gid);
      const presets = Object.entries(PRESET_TAGS).map(([n,e]) => `${e}  ${n} *(preset)*`);
      const customLines = customs.map(t => `${t.emoji}  ${t.tag_name}`);
      const all = [...presets, ...customLines];
      if (!all.length) return interaction.reply({ content: 'No tags defined for this server.', ephemeral: true });
      return interaction.reply({ content: `**Available Tags:**\n${all.join('\n')}`, ephemeral: true });
    }
  }
}

async function handleStat(interaction) {
  const lines = [
    '**Strength** (**STR**) – Physical power, melee combat.',
    '',
    '**Constitution** (**CON**) – Durability, health.',
    '',
    '**Dexterity** (**DEX**) – Agility, ranged/finesse combat.',
    '',
    '**Wisdom** (**WIS**) – Insight, tactical awareness.',
    '',
    '**Luck** (**LUCK**) – Fortune, chance-based effects.',
  ];
  return interaction.reply({ content: lines.join('\n'), ephemeral: false });
}

// ─────────────────────────────────────────────
//  BOT CLIENT
// ─────────────────────────────────────────────

const client = new Client({
  intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent, GatewayIntentBits.GuildMembers],
});

// A server that invites the bot AFTER it booted was getting no commands at
// all, because registration only ever ran in the ready loop over servers it
// was already in. Registering on arrival is the whole fix: a new table can
// use the bot the moment it lands, without waiting for a restart.
client.on('guildCreate', async (guild) => {
  console.log(`➕ Joined ${guild.name} (${guild.id}) — registering commands`);
  await registerSlashCommands(guild.id).catch(console.error);
  // Say hello somewhere they will see it, with the two steps that follow.
  try {
    const where = guild.systemChannel
      ?? guild.channels.cache.find(c => c.isTextBased?.() && c.permissionsFor(guild.members.me)?.has('SendMessages'));
    if (where) {
      await where.send({ content: [
        '🎲 **DDice is here.** Two steps and this server is ready:',
        '',
        '**1.** Make a role for your GMs, then `/config mechanics gmrole role:@GM`',
        '**2.** `/gm check build` — builds every channel and forum, wires them, and fills them',
        '',
        '_Playing 5e? `/config channels ruleset system:dnd5e` before anyone makes a character, then `/library srd`._',
        '_`/help` lists everything, and `/gm check status` shows what is still waiting._',
        ...(() => {
          // A bot cannot grant itself permissions — Discord's rule, not
          // ours — so arrival names anything missing while an admin is
          // still looking. Existing servers are never audited unprompted;
          // /gm check build surfaces gaps there on demand.
          const NEEDED = ['ManageChannels','ManageThreads','ManageRoles','ManageWebhooks','ManageMessages',
            'SendMessages','SendMessagesInThreads','CreatePublicThreads','EmbedLinks','AttachFiles',
            'AddReactions','ReadMessageHistory'];
          const me = guild.members.me;
          const missing = NEEDED.filter(p2 => !me?.permissions?.has?.(p2));
          return missing.length ? ['',
            `⚠️ **Missing permissions:** ${missing.join(', ')} — grant these to the DDice role or forums, sheets and portraits cannot be built.`] : [];
        })(),
      ].join('\n') });
    }
  } catch { /* no channel it may speak in — the commands are what matter */ }
});

// A channel born after setup gets the same permissions as the rest —
// PERMISSIONS ONLY, never position (T, 2026-08-15).
client.on('channelCreate', async (channel) => {
  try {
    const guild = channel.guild; if (!guild) return;
    const me = guild.members.me; if (!me) return;
    const perms = channel.permissionsFor(me);
    const missing = CHANNEL_PERMS.filter(k => { try { return !perms?.has(k); } catch { return false; } });
    const grantable = missing.filter(k => me.permissions.has(k));
    if (!grantable.length || !perms?.has('ManageRoles')) return;
    const allow = {}; for (const k of grantable) allow[k] = true;
    await channel.permissionOverwrites.edit(me.id, allow, { reason: 'DDice self-repair (new channel)' }).catch(() => {});
  } catch {}
});

client.once('clientReady', async () => {  // 'ready' is deprecated in favour of clientReady
  console.log(`✅ Bot online as ${client.user.tag}`);
  // Re-register commands for each guild with current NPC list
  for (const guild of client.guilds.cache.values()) {
    await registerSlashCommands(guild.id).catch(console.error);
  }
  // One-time reshapes run here, in the room actually named ready — not
  // riding registration, where they first landed by a bad anchor.
  runRenameMigration(client).catch(err => console.error('[run-rename]', err?.message || err));
  npcThreadMigration(client).catch(err => console.error('[npc-threads]', err?.message || err));
  forumSetupMigration(client).catch(err => console.error('[gm-forum]', err?.message || err));
  bootMend(client).catch(err => console.error('[mend]', err?.message || err));
  charThreadMigration(client).catch(err => console.error('[char-threads]', err?.message || err));
  startCharBlockSweep(client);
  startBackupScheduler();
  console.log('✅ Backup scheduler started');
});

async function routeButton(interaction) {
    if (interaction.customId.startsWith('confirm:') || interaction.customId.startsWith('cancel:')) {
      return handleConfirmButton(interaction);
    }
    if (interaction.customId.startsWith('storyask:')) return handleStoryAskButton(interaction);
    if (interaction.customId.startsWith('storyroll:')) return handleStoryRollButton(interaction);
    if (interaction.customId.startsWith('storypick:')) return handleStoryPickButton(interaction);
    if (interaction.customId.startsWith('storyrr:')) return handleStoryRerollButton(interaction);
    if (interaction.customId.startsWith('storygo:')) return handleStoryCarryOnButton(interaction);
    if (interaction.customId.startsWith('loreok:') || interaction.customId.startsWith('loreno:')) return handleLoreButton(interaction);
    if (interaction.customId.startsWith('tradeok:') || interaction.customId.startsWith('tradeno:')) return handleMeritTradeButton(interaction);
    if (interaction.customId.startsWith('revive:')) return handleReviveButton(interaction);
    if (/^duel(join|out|send|cancel|ok|no):/.test(interaction.customId)) return handleDuelButton(interaction);
    if (interaction.customId.startsWith('qapply:') || interaction.customId.startsWith('qwithdraw:')) {
      const [kind, numRaw] = interaction.customId.split(':');
      const quest = getQuest(interaction.guild.id, parseInt(numRaw));
      if (!quest) return interaction.reply({ content: '❌ That run is gone.', ephemeral: true });
      const res = kind === 'qapply'
        ? await questApply(interaction.guild, quest, interaction.user.id)
        : await questWithdraw(interaction.guild, quest, interaction.user.id);
      return interaction.reply({ content: res.error ?? res.ok, ephemeral: true });
    }
    if (interaction.customId.startsWith('npclist:')) {
      if (!(await isGm(interaction.guild, interaction.user.id))) {
        return interaction.reply({ content: '❌ The NPC roster is a GM view.', ephemeral: true });
      }
      const parts = interaction.customId.split(':');
      const pg = buildNpcPage(interaction.guild.id,
        { page: parseInt(parts[1]) || 0, compact: parts[2] === 'c', cat: parts.slice(3).join(':') });
      if (!pg) return interaction.reply({ content: '❌ That category is gone now.', ephemeral: true });
      return interaction.update({ content: pg.content, components: npcPageRows(pg) });
    }
    if (interaction.customId.startsWith('dcroll:')) return runDcRollPress(interaction);
    if (interaction.customId.startsWith('promoteok:')) {
      if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs promote.', ephemeral: true });
      const uid2 = interaction.customId.split(':')[1];
      const merits2 = getMerits(interaction.guild.id, uid2);
      const { current } = rankProgress(interaction.guild.id, merits2);
      if (!current) return interaction.reply({ content: '❌ They no longer meet any rank\'s threshold.', ephemeral: true });
      const ch2 = getChar(interaction.guild.id, uid2);
      if (ch2?.rank_name === current.name) return interaction.reply({ content: `✅ Already **${current.name}**.`, ephemeral: true });
      upsertChar(interaction.guild.id, uid2, { rank_name: current.name });
      bookLog(interaction.guild.id, 'ranks', `🎖️ <@${uid2}> promoted to **${current.name}** by <@${interaction.user.id}> (${merits2} merits).`);
      const nm2 = await getDisplayName(interaction.guild, uid2);
      return interaction.reply({ content: `🎉 **${nm2}** is now **${current.name}**! _(pressed by <@${interaction.user.id}>)_` });
    }
    if (interaction.customId.startsWith('sheetview:')) {
      const uid3 = interaction.customId.split(':')[1];
      const ch3 = getChar(interaction.guild.id, uid3);
      if (!ch3) return interaction.reply({ content: '❌ No sheet on file.', ephemeral: true });
      const cfg3 = getConfig(interaction.guild.id);
      const heal3 = getHealCharges(interaction.guild.id, uid3, cfg3.heal_charges ?? 3);
      const nm3 = await getDisplayName(interaction.guild, uid3);
      return interaction.reply({ ephemeral: true,
        content: buildCharCard(ch3, nm3, heal3.current, cfg3.heal_charges ?? 3, interaction.guild.id).join('\n') });
    }
    if (interaction.customId.startsWith('fdef:') || ['fsave', 'finsight', 'fresolve', 'frr'].includes(interaction.customId)) {
      // A press walks the exact slash path — the branch's own gates (turn,
      // phase, pending kind, roll ownership, tokens) do all the deciding.
      if (interaction.customId.startsWith('fdef:')) {
        return handleFight(interaction, { sub: 'def', stat: interaction.customId.split(':')[1] });
      }
      const map = { fsave: 'save', finsight: 'insight', fresolve: 'resolve', frr: 'rr' };
      return handleFight(interaction, map[interaction.customId]);
    }
    if (interaction.customId.startsWith('questok:') || interaction.customId.startsWith('questkick:') || interaction.customId.startsWith('questpost:')) {
      const [kind, num, userId] = interaction.customId.split(':');
      const number = parseInt(num);
      if (kind === 'questpost') return handleQuest(interaction, { sub: 'post', number });
      return handleQuest(interaction, { sub: kind === 'questok' ? 'approve' : 'kick', number, userId });
    }
    if (interaction.customId.startsWith('queststage:')) {
      const gid = interaction.guild.id;
      if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs advance the pipeline.', ephemeral: true });
      const number = parseInt(interaction.customId.split(':')[1]);
      const quest = getQuest(gid, number);
      if (!quest) return interaction.reply({ content: '❌ That quest no longer exists.', ephemeral: true });
      const next = quest.stage === 'concept' ? 'awaiting' : quest.stage === 'awaiting' ? 'approved' : null;
      if (!next) return interaction.reply({ content: '✅ Past the hand-set stages — `/quest post` opens the board from here.', ephemeral: true });
      updateQuest(gid, number, { stage: next, stage_at: Date.now() });
      const fresh = getQuest(gid, number);
      // Answer the press by updating the button in place, then sync the rest.
      await interaction.update({ components: questStageRow(fresh) });
      await syncQuestPipeline(interaction.client, interaction.guild, gid, fresh);
      const S = QUEST_STAGES.find(([k]) => k === next);
      await announceStage(interaction.client, gid, fresh, `${S[1]} Stage → **${S[2]}** — <@${interaction.user.id}>.`);
      return;
    }
    if (interaction.customId.startsWith('gmorder:')) {
      const [, choice, owner] = interaction.customId.split(':');
      if (interaction.user.id !== owner) {
        return interaction.reply({ ephemeral: true, content: '❌ This prompt belongs to whoever ran the check.' });
      }
      if (!(await isGm(interaction.guild, interaction.user.id))) {
        return interaction.reply({ ephemeral: true, content: '❌ GMs only.' });
      }
      return runOrderReport(interaction, choice === 'keep' ? 'keep' : 'apply');
    }
    if (interaction.customId.startsWith('questlaunch:')) {
      const gidL = interaction.guild.id;
      if (!(await isGm(interaction.guild, interaction.user.id))) {
        return interaction.reply({ ephemeral: true, content: '❌ Launching is the GM\'s hand.' });
      }
      const num = parseInt(interaction.customId.split(':')[1], 10);
      const listing = getQuest(gidL, num);
      if (!listing || listing.instance_of || !(getConfig(gidL)?.quest_spinoff ?? 0)) {
        return interaction.reply({ ephemeral: true, content: '❌ This is not a launchable listing.' });
      }
      await interaction.deferReply();
      const r = await launchListing(interaction, gidL, listing);
      if (r.err) return interaction.editReply({ content: r.err });
      return interaction.editReply({ content:
        `🚀 **${questTag(r.born)}** launched — **${r.staged}** aboard.`
        + (r.room ? ` ⚔ <#${r.room.id}>` : '') });
    }
    if (interaction.customId.startsWith('questapply:') || interaction.customId.startsWith('questwithdraw:')) {
      return handleQuestButton(interaction);
    }
    if (interaction.customId.startsWith('sheetok:') || interaction.customId.startsWith('sheetno:')) {
      return handleSheetApprovalButton(interaction);
    }
    if (interaction.customId.startsWith('impok:') || interaction.customId.startsWith('impno:')) {
      return handleImportRequestButton(interaction);
    }
    if (interaction.customId.startsWith('exportok:') || interaction.customId.startsWith('exportno:')) {
      return handleExportRequestButton(interaction);
    }
    // The lore-doc BUTTONS live here in the button lane — they were first
    // filed under modal traffic, so presses timed out unacknowledged
    // ("didn't respond in time", live 2026-08-14). Their modals
    // (loredocm/loredonm) stay in the modal lane where they belong.
    if (interaction.customId === 'tgtatk') {
      const gidT = interaction.guild.id, uidT = interaction.user.id;
      const t = db.prepare('SELECT * FROM temp_targets WHERE guild_id=? AND message_id=?').get(gidT, interaction.message.id);
      if (!t) return interaction.reply({ ephemeral: true, content: '\u274C That target is long gone.' });
      if (t.dead) return interaction.reply({ ephemeral: true, content: `\u274C **${t.name}** has already fallen.` });
      if (t.owner && t.owner !== uidT) return interaction.reply({ ephemeral: true, content: '\u274C That one is not addressed to you.' });

      let line, total, passed = null;
      if (t.dice) {
        const rolled = rollNotation(t.dice);
        if (!rolled) return interaction.reply({ ephemeral: true, content: '\u274C That expression no longer reads.' });
        total = rolled.total;
        const mod = rolled.modifier ? ` ${rolled.modifier > 0 ? '+' : ''}${rolled.modifier}` : '';
        line = `**${t.dice}** \u2014 [${rolled.rolls.join(', ')}]${mod} = **${total}**`;
      } else {
        const ch = getChar(gidT, uidT);
        if (!ch) return interaction.reply({ ephemeral: true, content: '\u274C You need a character sheet \u2014 `/char create`.' });
        const r = rollDcCheck({ stat: t.stat === 'x' ? null : t.stat, dc: t.dc || 10, flat: t.stat === 'x', subject: ch, sig: ch });
        if (!r) return interaction.reply({ ephemeral: true, content: '\u274C That check would not roll.' });
        total = r.total; passed = t.dc ? r.passed : null;
        line = r.rollLine;
      }
      if (t.dc && passed === null) passed = total >= t.dc;
      db.prepare('UPDATE temp_targets SET hits=hits+1 WHERE guild_id=? AND message_id=?').run(gidT, interaction.message.id);

      const nmT = await getDisplayName(interaction.guild, uidT).catch(() => 'Someone');
      await logButtonPress(interaction, gidT, uidT, `${t.name}: ${total}${t.dc ? ` vs DC ${t.dc}` : ''}`, passed);
      await interaction.reply({ content: [
        `\u2694\uFE0F <@${uidT}> strikes at **${t.name}**`,
        line,
        t.dc ? (passed ? '\u2705 **A telling blow.**' : '\u274C **It glances off.**') : '',
      ].filter(Boolean).join('\n'), allowedMentions: { users: [uidT] } });

      // The GM's verdict — the only death check there is. In the channel by
      // default so the table feels it; in the GM channel when `secret`.
      const { ActionRowBuilder: TR, ButtonBuilder: TB, ButtonStyle: TS } = require('discord.js');
      const ask = [`\u{1F5E1}\uFE0F **${t.name}** \u2014 struck by ${nmT} for **${total}**${t.dc ? ` vs DC ${t.dc}` : ''}. Does it fall?`];
      const rowT = new TR().addComponents(
        new TB().setCustomId(`tgtdie:${interaction.message.id}:1`).setLabel('\u{1FAA6} It falls').setStyle(TS.Danger),
        new TB().setCustomId(`tgtdie:${interaction.message.id}:0`).setLabel('\u{1F6E1}\uFE0F It holds').setStyle(TS.Secondary));
      const gmChId = t.secret ? (getConfig(gidT)?.quest_log_gm || getConfig(gidT)?.roll_audit_channel_id) : null;
      const dest = gmChId ? await interaction.client.channels.fetch(gmChId).catch(() => null) : interaction.channel;
      await (dest || interaction.channel).send({ content: ask.join('\n'), components: [rowT], allowedMentions: { parse: [] } }).catch(() => {});
      return;
    }

    if (interaction.customId.startsWith('tgtdie:')) {
      if (!(await isGm(interaction.guild, interaction.user.id)))
        return interaction.reply({ ephemeral: true, content: '\u274C That call is the GM\'s.' });
      const [, msgId, fellS] = interaction.customId.split(':');
      const gidT = interaction.guild.id;
      const t = db.prepare('SELECT * FROM temp_targets WHERE guild_id=? AND message_id=?').get(gidT, msgId);
      if (!t) return interaction.reply({ ephemeral: true, content: '\u274C That target is long gone.' });
      const fell = fellS === '1';
      if (fell) {
        db.prepare('UPDATE temp_targets SET dead=1 WHERE guild_id=? AND message_id=?').run(gidT, msgId);
        // Its own button dies with it, so nobody swings at a corpse.
        const ch = await interaction.client.channels.fetch(t.channel_id).catch(() => null);
        const m = ch ? await ch.messages.fetch(msgId).catch(() => null) : null;
        if (m?.editable) await m.edit({ content: `\u{1FAA6} ~~**${t.name}**~~ \u2014 fallen after ${t.hits} hit${t.hits === 1 ? '' : 's'}.`, components: [] }).catch(() => {});
        try { noteQuestActivity(gidT, t.channel_id, 'combat', `${t.name} falls after ${t.hits} hit${t.hits === 1 ? '' : 's'}`, interaction.user.id); } catch {}
      }
      await interaction.update({ content: `${interaction.message.content}\n${fell ? '\u{1FAA6} **It falls.**' : '\u{1F6E1}\uFE0F **It holds.**'}`, components: [] }).catch(() => {});
      return;
    }

    if (interaction.customId === 'btnfb') {
      // The planted feedback button opens the same picker /feedback send
      // does — one path, one voice.
      const gidB = interaction.guild.id;
      const types = feedbackTypes(gidB);
      const { ActionRowBuilder: FR, StringSelectMenuBuilder: FS } = require('discord.js');
      const menu = new FS().setCustomId('fbcat').setPlaceholder('Which room?')
        .addOptions(Object.entries(types).slice(0, 25).map(([k, t]) => ({ label: t.name.slice(0, 100), value: k, description: t.about?.slice(0, 100) })));
      return interaction.reply({ ephemeral: true, content: '\u{1F4DD} **Feedback** \u2014 pick a room, then score it and say your piece. Only the GMs will see it.',
        components: [new FR().addComponents(menu)] });
    }

    if (interaction.customId.startsWith('btnchk:') || interaction.customId.startsWith('btnroll:')) {
      const gidB = interaction.guild.id, uidB = interaction.user.id;
      const parts = interaction.customId.split(':');
      // …:<once>:<owner> — 'any' means the floor is open, an id means it
      // was addressed and only they may press.
      // …:<dc>:<once>:<owner> on both kinds now.
      const owner = parts[parts.length - 1];
      const once = parts[parts.length - 2] === '1';
      const pressDc = parseInt(parts[parts.length - 3], 10) || 0;
      if (owner && owner !== 'any' && owner !== uidB)
        return interaction.reply({ ephemeral: true, content: '\u274C That one is not addressed to you.' });
      if (once && !buttonPressGate(gidB, interaction.message.id, uidB))
        return interaction.reply({ ephemeral: true, content: '\u274C You have had your go at this one.' });

      if (parts[0] === 'btnchk') {
        const stat = parts[1], dc = pressDc;
        const ch = getChar(gidB, uidB);
        if (!ch) return interaction.reply({ ephemeral: true, content: '\u274C You need a character sheet \u2014 `/char create`.' });
        const r = rollDcCheck({ stat: stat === 'x' ? null : stat, dc, flat: stat === 'x', subject: ch, sig: ch });
        if (!r) return interaction.reply({ ephemeral: true, content: '\u274C That check would not roll.' });
        const face = stat === 'x' ? 'flat d20' : STAT_LABELS[stat];
        await logButtonPress(interaction, gidB, uidB, `${face} ${r.total}${dc ? ` vs DC ${dc}` : ''}`, dc ? r.passed : null);
        return interaction.reply({ content: [
          `\u{1F3AF} <@${uidB}> \u2014 **${face}**${dc ? ` vs **DC ${dc}**` : ''}`,
          r.rollLine,
          r.passed ? '\u2705 **Passed.**' : '\u274C **Failed.**',
        ].join('\n'), allowedMentions: { users: [uidB] } });
      }

      const dice = parts[1];
      const rolled = rollNotation(dice);
      if (!rolled) return interaction.reply({ ephemeral: true, content: '\u274C That expression no longer reads.' });
      const faces = rolled.rolls.join(', ');
      const mod = rolled.modifier ? ` ${rolled.modifier > 0 ? '+' : ''}${rolled.modifier}` : '';
      const verdict = pressDc ? (rolled.total >= pressDc ? '\n\u2705 **Passed.**' : '\n\u274C **Failed.**') : '';
      await logButtonPress(interaction, gidB, uidB, `${dice} = ${rolled.total}${pressDc ? ` vs DC ${pressDc}` : ''}`, pressDc ? rolled.total >= pressDc : null);
      return interaction.reply({ content: `\u{1F3B2} <@${uidB}> rolled **${dice}**${pressDc ? ` vs **DC ${pressDc}**` : ''} \u2014 [${faces}]${mod} = **${rolled.total}**${verdict}`,
        allowedMentions: { users: [uidB] } });
    }

    if (interaction.customId.startsWith('fbq:')) {
      // Anyone in the run may speak; the press and everything after is
      // ephemeral, so the party never sees who did.
      const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
      const m = new ModalBuilder().setCustomId(interaction.customId).setTitle('Feedback on this quest');
      m.addComponents(
        new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('scale')
          .setLabel('Score the quest 1-10').setPlaceholder('8').setStyle(TextInputStyle.Short).setRequired(true).setMaxLength(2)),
        new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('body')
          .setLabel('How did it play?').setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(1500)),
      );
      return interaction.showModal(m);
    }
    if (interaction.customId.startsWith('loredoc:')) {
      const owner = interaction.customId.split(':')[1];
      if (interaction.user.id !== owner) {
        return interaction.reply({ ephemeral: true, content: '❌ This button belongs to the page\'s owner.' });
      }
      const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
      const m = new ModalBuilder().setCustomId(`loredocm:${owner}`).setTitle('Request a lore doc update');
      m.addComponents(
        new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('link').setLabel('Link to your doc')
          .setPlaceholder('https://docs.google.com/… — any shareable link').setStyle(TextInputStyle.Short).setRequired(true)),
        new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('notes').setLabel('Anything the GM should know')
          .setStyle(TextInputStyle.Paragraph).setRequired(false)),
      );
      return interaction.showModal(m);
    }
    if (interaction.customId.startsWith('loredocok:') || interaction.customId.startsWith('loredocno:')) {
      const owner = interaction.customId.split(':')[1];
      // Deny must stay un-acked for its modal; approve acks instantly and
      // does its slow work (name fetch, card edit, DM) behind the defer.
      if (interaction.customId.startsWith('loredocok:')) {
        try { await interaction.deferUpdate(); } catch {}
      }
      if (!(await isGm(interaction.guild, interaction.user.id))) {
        const msg = { ephemeral: true, content: '❌ GM hands only.' };
        return (interaction.deferred || interaction.replied) ? interaction.followUp(msg) : interaction.reply(msg);
      }
      if (interaction.customId.startsWith('loredocno:')) {
        const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
        const m = new ModalBuilder().setCustomId(`loredonm:${owner}:${interaction.message.id}`).setTitle('Deny — tell them why');
        m.addComponents(new ActionRowBuilder().addComponents(
          new TextInputBuilder().setCustomId('reason').setLabel('Reason (sent to the player)').setStyle(TextInputStyle.Paragraph).setRequired(true)));
        return interaction.showModal(m);
      }
      // Approval now WRITES: the card's link becomes their lore doc, and
      // the page refreshes on the spot — a player who watched the ✅ land
      // shouldn't wait an hour to see it (Imigun, 2026-08-14). A newer
      // approval simply replaces the link; re-pressing is idempotent.
      const docUrl = (interaction.message.content.match(/🔗 (\S+)/) || [])[1] || null;
      if (docUrl) {
        upsertChar(interaction.guild.id, owner, { lore_doc_url: docUrl });
        ensureCharPage(interaction.client, interaction.guild, owner, null, 'all').catch(() => {});
      }
      const gmName = await getDisplayName(interaction.guild, interaction.user.id);
      await interaction.editReply({ content: interaction.message.content + `\n✅ **Approved** by ${gmName}`, components: [] }).catch(() => {});
      const u = await interaction.client.users.fetch(owner).catch(() => null);
      const dmOk = u ? await u.send(`✅ Your lore doc request was approved by **${gmName}** — they\'ll fold it into your page.`).then(() => true).catch(() => false) : false;
      if (!dmOk) await interaction.followUp({ ephemeral: true, content: '⚠️ Could not DM them — their DMs are closed.' }).catch(() => {});
      return;
    }
    return;
}

client.on('interactionCreate', async interaction => {
  // Handle autocomplete for NPC name fields
  if (interaction.isAutocomplete()) {
    try {
      const focusedOption = interaction.options.getFocused(true);
      console.log(`Autocomplete: cmd=${interaction.commandName} sub=${interaction.options.getSubcommand(false)} focused=${focusedOption.name} value=${focusedOption.value}`);

      // Quest number autocomplete — shows "#001-Goblin Cave" filtered by status per subcommand
      // Any weapon slot, on any command, offers what the server actually has —
      // so an NPC can only be handed a weapon whose stat rules are known.
      if (focusedOption.name === 'weapon1' || focusedOption.name === 'weapon2') {
        const v = String(focusedOption.value || '').toLowerCase();
        const rows = db.prepare('SELECT * FROM weapons WHERE guild_id=? ORDER BY name').all(interaction.guild.id);
        const pick = rows.filter(w => w.name.toLowerCase().includes(v)).slice(0, 25);
        return interaction.respond(pick.map(w => {
          const a = w.atk_stats ? parseStatList(w.atk_stats).map(x => x.toUpperCase()).join('/') : 'any';
          const d = w.def_stats ? parseStatList(w.def_stats).map(x => x.toUpperCase()).join('/') : 'any';
          return { name: `${w.name} — ⚔️${a} 🛡️${d}`.slice(0, 100), value: w.name };
        })).catch(()=>{});
      }

      // /instance name: the listings, shown as "Name · #012" with the
      // NUMBER as the value, so twins can never ambiguate. run: that
      // listing's runs newest-first, values are run_seq.
      if (interaction.commandName === 'instance' && focusedOption.name === 'name') {
        const v = String(focusedOption.value || '').toLowerCase();
        const ls = db.prepare('SELECT number, name FROM quests WHERE guild_id=? AND instance_of IS NULL').all(interaction.guild.id)
          .filter(q => (q.name || '').toLowerCase().includes(v)).slice(0, 25)
          .map(q => ({ name: `${q.name} · #${String(q.number).padStart(3, '0')}`.slice(0, 100), value: String(q.number) }));
        return await interaction.respond(ls);
      }
      if (interaction.commandName === 'instance' && focusedOption.name === 'run') {
        const picked = resolveListingByName(interaction.guild.id, interaction.options.getString('name') || '');
        if (picked.err) return await interaction.respond([]);
        const runs = db.prepare('SELECT number, run_seq, name, status FROM quests WHERE guild_id=? AND instance_of=? ORDER BY run_seq DESC')
          .all(interaction.guild.id, picked.listing.number).slice(0, 25)
          .map(r => ({ name: `Run ${String(r.run_seq).padStart(3, '0')} · #${String(r.number).padStart(3, '0')}${r.status === 'active' ? ' · active' : ''}`.slice(0, 100), value: r.run_seq }));
        return await interaction.respond(runs);
      }
      if (interaction.commandName === 'quest' && focusedOption.name === 'number') {
        const sub = interaction.options.getSubcommand(false);
        let quests = listQuests(interaction.guild.id);
        if (sub === 'apply') quests = quests.filter(q => q.status === 'open');
        else if (sub === 'start') quests = quests.filter(q => q.status === 'open');
        else if (sub === 'complete') quests = quests.filter(q => q.status !== 'completed');
        const v = String(focusedOption.value).toLowerCase();
        const choices = quests
          .filter(q => questTag(q).toLowerCase().includes(v) || String(q.number).includes(v))
          .slice(0, 25)
          .map(q => ({ name: `${questTag(q)} · ${questStatusBadge(q.status)}`.slice(0, 100), value: q.number }));
        return await interaction.respond(choices);
      }

      // Which feedback rooms a GM may retire — the seven built-ins never
      // appear, since they cannot be removed.
      if (interaction.commandName === 'feedback') {
        const q = String(focusedOption.value || '').toLowerCase();
        const opts = feedbackCats(interaction.guild.id)
          .filter(c => !q || c.name.toLowerCase().includes(q))
          .slice(0, 25).map(c => ({ name: c.name, value: c.name }));
        return interaction.respond(opts).catch(() => {});
      }
      // Rank name autocomplete (/standing rank remove, /standing rank promote)
      if ((interaction.commandName === 'standing' && focusedOption.name === 'rank') ||
          (interaction.commandName === 'standing' && focusedOption.name === 'name' && interaction.options.getSubcommand(false) === 'remove')) {
        const v = String(focusedOption.value).toLowerCase();
        const choices = getRanks(interaction.guild.id)
          .filter(r => r.name.toLowerCase().includes(v))
          .slice(0, 25)
          .map(r => ({ name: `${r.name} (${r.threshold})`.slice(0, 100), value: r.name }));
        return await interaction.respond(choices);
      }

      if (interaction.commandName === 'gm' && (focusedOption.name === 'npc' || focusedOption.name === 'npcs')) {
        const v = String(focusedOption.value).toLowerCase();
        const choices = [{ name: 'all', value: 'all' },
          ...getAllNpcs(interaction.guild.id).map(n => ({ name: n.name.slice(0,100), value: n.name }))]
          .filter(c => c.name.toLowerCase().includes(v)).slice(0, 25);
        return await interaction.respond(choices);
      }

      // ─ Naming something that exists should always offer a list ─
      const acPick = (items, v) => items
        .filter(x => !v || String(x).toLowerCase().includes(v))
        .slice(0, 25).map(x => ({ name: String(x).slice(0, 100), value: String(x).slice(0, 100) }));

      // The question bank: categories, tags in use, and questions themselves —
      // typed words filter, which is the whole point of keeping them in a table.
      // The eighteen skills, filtered as you type.
      if (focusedOption.name === 'add' || focusedOption.name === 'remove') {
        const rules = rulesFor(interaction.guild.id);
        if (rules.conditions) {
          const v = String(focusedOption.value || '').toLowerCase();
          const hits = Object.keys(rules.conditions).filter(x => !v || x.includes(v)).slice(0, 25);
          return await interaction.respond(hits.map(x => ({ name: x, value: x })));
        }
      }
      // Anything in the library, monsters and spells alike.
      if (interaction.commandName === 'library' && focusedOption.name === 'name') {
        const v = String(focusedOption.value || '').toLowerCase();
        const sub = interaction.options.getSubcommand(false);
        let rows = [];
        try {
          const mons = db.prepare('SELECT name, cr FROM library_monsters WHERE guild_id=? ORDER BY name').all(interaction.guild.id)
            .map(r => ({ name: `\u{1f409} ${r.name}${r.cr ? ` (CR ${r.cr})` : ''}`, value: r.name }));
          const spells = sub === 'summon' ? [] :
            db.prepare('SELECT name, level FROM library_spells WHERE guild_id=? ORDER BY name').all(interaction.guild.id)
              .map(r => ({ name: `\u2728 ${r.name} (${r.level ? 'lvl ' + r.level : 'cantrip'})`, value: r.name }));
          rows = [...mons, ...spells];
        } catch {}
        const hits = rows.filter(r => !v || r.value.toLowerCase().includes(v)).slice(0, 25);
        return await interaction.respond(hits.map(r => ({ name: r.name.slice(0, 100), value: r.value.slice(0, 100) })));
      }
      if (focusedOption.name === 'skill') {
        const rules = rulesFor(interaction.guild.id);
        const v = String(focusedOption.value || '').toLowerCase();
        const hits = Object.keys(rules.skills || {}).filter(x => !v || x.includes(v)).slice(0, 25);
        return await interaction.respond(hits.map(x => ({
          name: `${x.replace(/\b\w/g, c => c.toUpperCase())} (${rules.labels[rules.skills[x]]})`.slice(0, 100), value: x })));
      }
      // NPC categories: the ones this server uses, plus whatever is typed —
      // naming a new one here is how it comes into being.
      if (interaction.commandName === 'npc' && focusedOption.name === 'category') {
        const v = String(focusedOption.value || '').toLowerCase();
        const typed = String(focusedOption.value || '').trim();
        const known = getCategories(interaction.guild.id);
        const hits = known.filter(x => !v || x.toLowerCase().includes(v)).slice(0, 24);
        if (typed && !known.some(x => x.toLowerCase() === v)) hits.unshift(typed);
        // A server with none yet gets somewhere to start.
        const seed = known.length ? [] : ['Enemy', 'Ally', 'Vendor', 'Quest'];
        return await interaction.respond([...hits, ...seed].slice(0, 25)
          .map(x => ({ name: x.slice(0, 100), value: x.slice(0, 100) })));
      }
      if (interaction.commandName === 'quiz' && focusedOption.name === 'category') {
        const v = String(focusedOption.value || '').toLowerCase();
        const known = quizCategories(interaction.guild.id).map(c => c.name);
        const typed = String(focusedOption.value || '').trim();
        const hits = known.filter(x => !v || x.toLowerCase().includes(v)).slice(0, 24);
        // A new category is legal — offer what they typed as its own option.
        if (typed && !known.some(x => x.toLowerCase() === v)) hits.unshift(`${typed}`);
        return await interaction.respond(hits.slice(0, 25).map(x => ({ name: x.slice(0, 100), value: x.slice(0, 100) })));
      }
      if (interaction.commandName === 'quiz' && (focusedOption.name === 'tag' || focusedOption.name === 'tags')) {
        const v = String(focusedOption.value || '').toLowerCase();
        const last = v.split(',').pop().trim();
        const done = v.includes(',') ? v.slice(0, v.lastIndexOf(',') + 1) : '';
        const hits = quizTags(interaction.guild.id).filter(x => !last || x.toLowerCase().includes(last)).slice(0, 25);
        return await interaction.respond(hits.map(x => ({ name: (done + ' ' + x).trim().slice(0, 100), value: (done + x).slice(0, 100) })));
      }
      if (interaction.commandName === 'quiz' && focusedOption.name === 'set') {
        const v = String(focusedOption.value || '').toLowerCase();
        let rows = [];
        try { rows = db.prepare("SELECT name, spec FROM quiz_sets WHERE guild_id=? AND name NOT LIKE '%draft:%' ORDER BY created_at DESC").all(interaction.guild.id); } catch {}
        const hits = rows.filter(r => !v || r.name.toLowerCase().includes(v));
        return await interaction.respond(hits.slice(0, 25).map(r => {
          let bits = '';
          try { const sp = JSON.parse(r.spec); bits = ` — ${sp.count ?? 5}${sp.category ? ' · ' + sp.category : ''}${sp.difficulty ? ' · ' + sp.difficulty : ''}`; } catch {}
          return { name: `${r.name}${bits}`.slice(0, 100), value: r.name.slice(0, 100) };
        }));
      }
      if (interaction.commandName === 'quiz' && focusedOption.name === 'id') {
        const v = String(focusedOption.value || '').toLowerCase();
        let rows = [];
        try { rows = db.prepare('SELECT id, category, question FROM quiz_questions WHERE guild_id=? ORDER BY id DESC').all(interaction.guild.id); } catch {}
        const hits = rows.filter(r => !v || String(r.id) === v || r.question.toLowerCase().includes(v) || r.category.toLowerCase().includes(v));
        return await interaction.respond(hits.slice(0, 25).map(r => ({
          name: `#${r.id} · ${r.category} — ${r.question}`.slice(0, 100), value: r.id })));
      }

      // An activity by name — read, run or delete.
      if (interaction.commandName === 'activity' && focusedOption.name === 'name') {
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(listStories(interaction.guild.id).map(r => r.name), v));
      }
      // A category by name, wherever it's asked for — including the
      // categorydelete sub, where the option is called 'name'.
      if (interaction.commandName === 'npc' && focusedOption.name === 'name'
          && interaction.options.getSubcommandGroup(false) === 'category'
          && ['delete', 'rename'].includes(interaction.options.getSubcommand(false))) {
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(getCategories(interaction.guild.id), v));
      }
      // Which NPC /npc edit is changing.
      if (interaction.commandName === 'npc' && focusedOption.name === 'name'
          && !interaction.options.getSubcommandGroup(false)
          && ['edit', 'rename'].includes(interaction.options.getSubcommand(false))) {
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(getAllNpcs(interaction.guild.id).map(n => n.name), v));
      }
      // The NPC being filed into or out of a category.
      if (interaction.commandName === 'npc' && focusedOption.name === 'npc') {
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(getAllNpcs(interaction.guild.id).map(n => n.name), v));
      }
      // A weapon from the server list — stats and remove both ask by name.
      if (interaction.commandName === 'char' && focusedOption.name === 'name'
          && interaction.options.getSubcommandGroup(false) === 'weapon') {
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(getWeapons(interaction.guild.id), v));
      }
      // A tag that exists on this server.
      // Deleting a custom tag picks an existing one; creating invents a new
      // name, so nothing is suggested there.
      if (interaction.commandName === 'char' && focusedOption.name === 'name'
          && interaction.options.getSubcommand(false) === 'custom') {
        if (interaction.options.getString('action') !== 'delete') return await interaction.respond([]);
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(getCustomTags(interaction.guild.id).map(t => t.tag_name), v));
      }
      if (interaction.commandName === 'char' && focusedOption.name === 'tag') {
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(getCustomTags(interaction.guild.id).map(t => t.tag_name), v));
      }
      // An item the player in the OTHER option is actually carrying.
      if (interaction.commandName === 'char' && focusedOption.name === 'item') {
        const v = String(focusedOption.value || '').toLowerCase();
        const who = interaction.options.getUser('user')?.id ?? interaction.user.id;
        const names = [...new Set(listItems(interaction.guild.id, who).map(r => r.item))];
        return await interaction.respond(acPick(names, v));
      }
      // A recovery schedule by name.
      if (interaction.commandName === 'config' && focusedOption.name === 'name') {
        const v = String(focusedOption.value || '').toLowerCase();
        return await interaction.respond(acPick(listSchedules(interaction.guild.id).map(r => r.name), v));
      }
      if (interaction.commandName === 'npc' && focusedOption.name === 'category') {
        const v = String(focusedOption.value).toLowerCase();
        const choices = getCategories(interaction.guild.id)
          .filter(c => c.toLowerCase().includes(v))
          .slice(0, 25)
          .map(c => ({ name: c.slice(0, 100), value: c }));
        return await interaction.respond(choices);
      }

      if (interaction.commandName === 'quest' && (focusedOption.name === 'number' || focusedOption.name === 'from')) {
        const typed = String(focusedOption.value ?? '').toLowerCase();
        const rows = db.prepare('SELECT number, name, status FROM quests WHERE guild_id=? ORDER BY number DESC LIMIT 100').all(interaction.guild.id);
        const choices = rows
          .filter(q => !typed || String(q.number).includes(typed) || (q.name || '').toLowerCase().includes(typed))
          .slice(0, 25)
          .map(q => ({ name: `${questTag(q)} (${q.status})`.slice(0, 100), value: q.number }));
        // An honest empty state beats Discord's "No options match your search".
        if (!choices.length) return await interaction.respond([{
          name: rows.length ? '— nothing matches that — clear it to see every quest —'
                            : '— no quests on this server yet — /quest create makes the first —',
          value: 0 }]);
        return await interaction.respond(choices);
      }
      if ((interaction.commandName === 'npc'
           || interaction.commandName === 'quest') && focusedOption.name === 'name') {
        const focused = focusedOption.value;
        const npcs = getAllNpcs(interaction.guild.id);
        const filtered = npcs
          .filter(n => n.name.toLowerCase().includes(focused.toLowerCase()))
          .slice(0, 25)
          .map(n => ({ name: n.name, value: n.name }));
        console.log(`Autocomplete responding with ${filtered.length} NPCs`);
        return await interaction.respond(filtered);
      }
      // Comma-aware NPC lists (/npc heal names, /fight refill npcs):
      // complete the segment after the last comma, offer "all"
      if ((interaction.commandName === 'npc' && focusedOption.name === 'names') ||
          (interaction.commandName === 'fight' && focusedOption.name === 'npcs')) {
        const typed = (focusedOption.value || '').toString();
        const lastComma = typed.lastIndexOf(',');
        const head = lastComma === -1 ? '' : typed.slice(0, lastComma + 1) + ' ';
        const seg = (lastComma === -1 ? typed : typed.slice(lastComma + 1)).trim().toLowerCase();
        const already = new Set(lastComma === -1 ? [] : parseNpcNames(typed.slice(0, lastComma + 1)).map(s => s.toLowerCase()));
        const npcs = getAllNpcs(interaction.guild.id).filter(n => !already.has(n.name.toLowerCase()));
        const choices = npcs
          .filter(n => n.name.toLowerCase().includes(seg))
          .slice(0, 24)
          .map(n => ({ name: (head + n.name).slice(0, 100), value: (head + n.name).slice(0, 100) }));
        if (!head && 'all'.startsWith(seg)) choices.unshift({ name: 'all — every NPC on the server', value: 'all' });
        return await interaction.respond(choices.slice(0, 25));
      }
      // Fight NPC fields — suggest server NPC names
      if ((interaction.commandName === 'fight' || (interaction.commandName === 'roll' && focusedOption.name === 'target_npc')) &&
          (focusedOption.name === 'npc' || focusedOption.name === 'target_npc' || focusedOption.name === 'redirect_npc')) {
        const focused = (focusedOption.value || '').toString().toLowerCase();
        const npcs = getAllNpcs(interaction.guild.id);
        const filtered = npcs
          .filter(n => n.name.toLowerCase().includes(focused))
          .slice(0, 25)
          .map(n => ({ name: n.name, value: n.name }));
        return await interaction.respond(filtered);
      }
      // Weapon name autocomplete — server weapon list + whatever the user is typing
      if (interaction.commandName === 'char' && (focusedOption.name === 'weapon1' || focusedOption.name === 'weapon2')) {
        const focused = (focusedOption.value || '').toString();
        const weapons = getWeapons(interaction.guild.id);
        const matches = weapons.filter(w => w.toLowerCase().includes(focused.toLowerCase()));
        const choices = matches.slice(0, 24).map(w => ({ name: w, value: w }));
        // Always let the player keep their own free text as the first option
        if (focused.trim() && !weapons.some(w => w.toLowerCase() === focused.toLowerCase())) {
          choices.unshift({ name: `✏️ Use: ${focused.slice(0, 80)}`, value: focused.slice(0, 100) });
        }
        return await interaction.respond(choices.slice(0, 25));
      }
    } catch (err) { console.error('Autocomplete error:', err); }
    return;
  }

  // Handle confirmation buttons
  if (interaction.isModalSubmit?.()) {
    if (interaction.customId.startsWith('questcreate:')) {
      const gidq = interaction.guild.id;
      if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs can manage quests.', ephemeral: true });
      const [, m, p, h, ...styleParts] = interaction.customId.split(':');
      return finishQuestCreate(interaction, gidq, interaction.user.id, {
        name: interaction.fields.getTextInputValue('name'),
        objectives: interaction.fields.getTextInputValue('objectives') || null,
        lore: interaction.fields.getTextInputValue('lore') || null,
        details: interaction.fields.getTextInputValue('details') || null,
        rewards: interaction.fields.getTextInputValue('rewards') || null,
        merit_reward: parseInt(m) || 0,
        party_size: p ? parseInt(p) : null,
        party_hard: h === '1',
        gm_style: styleParts.join(':') || null,
      });
    }
    if (interaction.customId.startsWith('questedit:')) {
      const gidq = interaction.guild.id;
      if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs can manage quests.', ephemeral: true });
      const number = parseInt(interaction.customId.split(':')[1]);
      const quest = getQuest(gidq, number);
      if (!quest) return interaction.reply({ content: '❌ That quest no longer exists.', ephemeral: true });
      const name = interaction.fields.getTextInputValue('name').trim();
      if (!name || name.length > 80) return interaction.reply({ content: '❌ Quest name must be 1–80 characters.', ephemeral: true });
      // Thread renames and refreshes can outlast the 3-second window.
      await interaction.deferReply();
      updateQuest(gidq, number, { name,
        objectives: interaction.fields.getTextInputValue('objectives') || null,
        lore: interaction.fields.getTextInputValue('lore') || null,
        details: interaction.fields.getTextInputValue('details') || null,
        rewards: interaction.fields.getTextInputValue('rewards') || null });
      const fresh = getQuest(gidq, number);
      // A renamed quest renames its threads — best-effort.
      for (const tid of [fresh.plan_thread_id, fresh.post_channel_id]) {
        if (!tid) continue;
        try {
          const th = await interaction.client.channels.fetch(tid);
          if (th?.isThread?.()) { if (th.archived) await wakeThread(th); await th.setName(`#${number} — ${name}`.slice(0, 100)); }
        } catch { /* best-effort */ }
      }
      await refreshQuestPost(interaction.client, interaction.guild, fresh);
      await syncQuestBook(interaction.client, interaction.guild, gidq, fresh);
      await questAnnounce(interaction.client, fresh, '✏️ Quest edited.', { board: false });
      return interaction.editReply({ content: `✏️ **${questTag(fresh)}** updated.\n\n${await renderQuest(interaction.guild, fresh)}` });
    }
    if (interaction.customId === 'activitycreate') {
      const gid2 = interaction.guild.id;
      if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs can add activities.', ephemeral: true });
      const r = storeActivityScript(gid2, interaction.user.id, interaction.fields.getTextInputValue('script'));
      return interaction.reply(r.error
        ? { content: `❌ **Couldn't read that activity.** ${r.error}\n_Your script is still in the paste window — press Dismiss, fix it, and try again (or paste it straight into chat)._`, ephemeral: true }
        : { content: r.saved });
    }
    if (interaction.customId.startsWith('npcsay:')) return handleNpcSayModal(interaction);
    if (interaction.customId === 'scrollwrite') return handleScrollModal(interaction);
    if (interaction.customId === 'importpaste') return handleImportPasteModal(interaction);
    if (interaction.customId.startsWith('loreda:') || interaction.customId.startsWith('loredx:')) {
      const owner = interaction.customId.split(':')[1];
      if (!await isGm(interaction.guild, interaction.user.id)) {
        return interaction.reply({ ephemeral: true, content: '❌ Only GMs decide lore doc requests.' });
      }
      const gmName = interaction.member?.displayName ?? interaction.user.username;
      if (interaction.customId.startsWith('loreda:')) {
        await interaction.update({ content: interaction.message.content + `\n✅ **Approved** by ${gmName}`, components: [] }).catch(() => {});
        const u = await interaction.client.users.fetch(owner).catch(() => null);
        if (u) await u.send(`✅ Your lore doc request in **${interaction.guild.name}** was approved by ${gmName}.`).catch(() => {});
        return;
      }
      const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
      const m = new ModalBuilder().setCustomId(`loredxm:${owner}:${interaction.message.id}`).setTitle('Deny lore doc request');
      m.addComponents(new ActionRowBuilder().addComponents(
        new TextInputBuilder().setCustomId('reason').setLabel('Why? (sent to the player)').setStyle(TextInputStyle.Paragraph).setRequired(true)));
      return interaction.showModal(m);
    }
    if (interaction.customId.startsWith('loredxm:')) {
      const [, owner, msgId] = interaction.customId.split(':');
      if (!await isGm(interaction.guild, interaction.user.id)) {
        return interaction.reply({ ephemeral: true, content: '❌ Only GMs decide lore doc requests.' });
      }
      const gmName = interaction.member?.displayName ?? interaction.user.username;
      const reason = interaction.fields.getTextInputValue('reason').trim();
      const card = await interaction.channel?.messages?.fetch(msgId).catch(() => null);
      if (card?.editable) await card.edit({ content: card.content + `\n❌ **Denied** by ${gmName} — ${reason}`, components: [] }).catch(() => {});
      const u = await interaction.client.users.fetch(owner).catch(() => null);
      if (u) await u.send(`❌ Your lore doc request in **${interaction.guild.name}** was denied by ${gmName}: ${reason}`).catch(() => {});
      return interaction.reply({ ephemeral: true, content: '✅ Denied and the player has been told.' });
    }
    if (interaction.customId.startsWith('loredonm:')) {
      if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.followUp({ ephemeral: true, content: '❌ GM hands only.' });
      const [, owner, msgId] = interaction.customId.split(':');
      const reason = interaction.fields.getTextInputValue('reason').trim();
      const gmName = await getDisplayName(interaction.guild, interaction.user.id);
      const card = await interaction.channel?.messages?.fetch(msgId).catch(() => null);
      if (card) await card.edit({ content: card.content + `\n❌ **Denied** by ${gmName} — ${reason}`, components: [] }).catch(() => {});
      const u = await interaction.client.users.fetch(owner).catch(() => null);
      const dmOk = u ? await u.send(`❌ Your lore doc request was denied by **${gmName}**: ${reason}`).then(() => true).catch(() => false) : false;
      return interaction.reply({ ephemeral: true, content: dmOk ? '✅ Denied and the player has been told.' : '✅ Denied — their DMs are closed, so tell them yourself.' });
    }
    if (interaction.customId.startsWith('loredocm:')) {
      const owner = interaction.customId.split(':')[1];
      if (interaction.user.id !== owner) return interaction.reply({ ephemeral: true, content: '❌ Not yours.' });
      const gidL = interaction.guild.id;
      let dest = approvalDestination(gidL, 'loredoc');
      if (!dest && approvalRoutes(gidL)?.forum) {
        await ensureApprovalThreads(interaction.client, gidL).catch(() => null);
        dest = approvalDestination(gidL, 'loredoc');
      }
      if (!dest) return interaction.reply({ ephemeral: true, content: '❌ No approvals home is set — a GM needs `/config channels approvalforum` first.' });
      let ch = await interaction.client.channels.fetch(dest).catch(() => null);
      if (!ch) {
        // A route can go STALE — the thread it names deleted after being
        // recorded (live "unreachable", 2026-08-14). Absence and death heal
        // the same way: drop the dead key, let the mender rebuild, retry.
        try {
          const r0 = approvalRoutes(gidL) || {};
          if (r0.loredoc) { delete r0.loredoc; setConfig(gidL, { approval_routes: JSON.stringify(r0) }); }
        } catch {}
        await ensureApprovalThreads(interaction.client, gidL).catch(() => null);
        dest = approvalDestination(gidL, 'loredoc');
        ch = dest ? await interaction.client.channels.fetch(dest).catch(() => null) : null;
      }
      if (!ch) return interaction.reply({ ephemeral: true, content: '❌ The Lore Docs home can\'t be reached even after a rebuild — ask a GM to check the approvals forum (`/gm check build`).' });
      const link = interaction.fields.getTextInputValue('link').trim();
      const notes = (interaction.fields.getTextInputValue('notes') || '').trim();
      const pg = getCharPage(gidL, owner);
      const gmRole = getConfig(gidL)?.gm_role_id;
      await ch.send({ content: [
          `📄 **Lore doc request** — <@${owner}>${gmRole ? ` <@&${gmRole}>` : ''}`,
          `🔗 ${link}`,
          notes ? `📝 ${notes}` : '',
          pg?.thread_id ? `🏷️ Their page: <#${pg.thread_id}>` : '',
        ].filter(Boolean).join('\n'),
        allowedMentions: { users: [owner], roles: gmRole ? [gmRole] : [] },
        components: [(() => {
          const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
          return new ActionRowBuilder().addComponents(
            new ButtonBuilder().setCustomId(`loredocok:${owner}`).setLabel('✅ Approve').setStyle(ButtonStyle.Success),
            new ButtonBuilder().setCustomId(`loredocno:${owner}`).setLabel('❌ Deny').setStyle(ButtonStyle.Danger));
        })()] }).catch(() => null);
      return interaction.reply({ ephemeral: true, content: '✅ Sent to the GMs — they\'ll look it over in the Lore Docs approvals.' });
    }
    if (interaction.customId.startsWith('fbm:') || interaction.customId.startsWith('fbq:')) {
      const isQuest = interaction.customId.startsWith('fbq:');
      const key = isQuest ? 'quests' : interaction.customId.slice(4);
      const raw = interaction.fields.getTextInputValue('scale').replace(/[^0-9]/g, '');
      const scale = parseInt(raw || '0', 10);
      if (!scale || scale < 1 || scale > 10)
        return interaction.reply({ ephemeral: true, content: '\u274C The score needs to be a number from 1 to 10.' });
      const body = interaction.fields.getTextInputValue('body').trim();
      const extra = isQuest ? `\u{1F5FA}\uFE0F On quest **${decodeURIComponent(interaction.customId.slice(4))}**` : '';
      const posted = await postFeedbackCard(interaction, interaction.guild.id, key, scale, body, extra);
      return interaction.reply({ ephemeral: true, content: posted
        ? '\u2705 Sent to the GMs \u2014 thank you. No one else can see it.'
        : '\u274C The feedback room could not be reached \u2014 ask a GM to run `/gm check build`.' });
    }
    if (interaction.customId === 'loresubmit') return handleLoreSubmit(interaction);
    if (interaction.customId.startsWith('gmkill:')) return handleGmKillModal(interaction);
    if (interaction.customId.startsWith('lorereject:')) return handleLoreRejectModal(interaction);
    if (interaction.customId.startsWith('traderej:')) return handleMeritTradeRejectModal(interaction);
    if (interaction.customId.startsWith('quizadd:')) return handleQuizAddModal(interaction);
    if (interaction.customId.startsWith('storyans:')) return handleStoryAnswerModal(interaction);
    if (interaction.customId.startsWith('dcform:')) return handleDcFormSubmit(interaction);
    if (interaction.customId.startsWith('duelrej:')) return handleDuelRejectModal(interaction);
    if (interaction.customId.startsWith('sheetreject:')) return handleSheetRejectModal(interaction);
    if (interaction.customId.startsWith('exportreject:')) return handleExportRejectModal(interaction);
    if (interaction.customId.startsWith('importreject:')) return handleImportRejectModal(interaction);
    return;
  }

  // A target picked from the menu executes the strike directly — the same
  // path as a fully-typed /fight atk, via runFightAttack. The picker message
  // is ephemeral so only its invoker can ever see it; the ownership guard is
  // belt-and-braces against a forged component (GMs pass for NPC actors).
  if (interaction.isChannelSelectMenu?.() && interaction.customId.startsWith('checkset:')) {
    const { PermissionFlagsBits } = require('discord.js');
    if (!interaction.memberPermissions?.has?.(PermissionFlagsBits.ManageGuild)) {
      return interaction.reply({ content: '❌ Server configuration takes **Manage Server**.', ephemeral: true });
    }
    const key = interaction.customId.split(':')[1];
    const channel = await interaction.guild.channels.fetch(interaction.values[0]).catch(() => null);
    if (!channel) return interaction.reply({ content: '❌ Couldn\'t read that channel.', ephemeral: true });
    return handleConfig(interaction, { sub: key, channel });
  }
  if (interaction.isStringSelectMenu?.() && interaction.customId === 'fbcat') {
    const key = interaction.values[0];
    const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
    const m = new ModalBuilder().setCustomId(`fbm:${key}`).setTitle('Feedback for the GMs');
    m.addComponents(
      new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('scale')
        .setLabel('Score it 1-10').setPlaceholder('7').setStyle(TextInputStyle.Short).setRequired(true).setMaxLength(2)),
      new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('body')
        .setLabel('Your feedback').setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(1500)),
    );
    return interaction.showModal(m);
  }
  if (interaction.isStringSelectMenu?.() && interaction.customId.startsWith('fighttarget:')) {
    try {
      const [, actorId, stat, mode, flavEnc] = interaction.customId.split(':');
      if (interaction.user.id !== actorId && !(await isGm(interaction.guild, interaction.user.id))) {
        return interaction.reply({ content: '🎯 That choice is not yours to make.', ephemeral: true });
      }
      const gid = interaction.guild.id;
      const cid = interactionChannelId(interaction);
      const targetId = interaction.values[0];
      const flavour = decodeURIComponent(flavEnc || '') || null;
      return await runFightAttack({ interaction, gid, cid, actorId, targetId, stat, mode, flavour });
    } catch (err) {
      console.error('[fighttarget]', err?.message || err, '\n', err?.stack || '');
      try { await interaction.followUp({ content: `⚠️ That pick hit an error:\n\`${err?.message || err}\``, ephemeral: true }); } catch {}
      return;
    }
  }

  if (interaction.isButton()) {
    // Every button dispatch was outside a try, so anything they threw became an
    // unhandled rejection: Discord showed "This interaction failed" and nothing
    // was logged anywhere. A silent button is undebuggable.
    try {
      return await routeButton(interaction);
    } catch (err) {
      const msg = err?.message || String(err);
      console.error('[button]', interaction.customId, '→', msg, '\n', err?.stack || '');
      const tell = { content: `⚠️ That button hit an error:\n\`${msg}\``, ephemeral: true };
      try {
        if (interaction.replied || interaction.deferred) await interaction.followUp(tell);
        else await interaction.reply(tell);
      } catch {}
      return;
    }
  }

  if (!interaction.isChatInputCommand()) return;
  try {
    if (interaction.commandName === 'dnd') return await handleDnd(interaction);
    if (interaction.commandName === 'library') return await handleLibrary(interaction);
    if (interaction.commandName === 'spell') return await handleSpell(interaction);
    if (interaction.commandName === 'quiz') return await handleQuiz(interaction);
    if (interaction.commandName === 'deception') return await handleDeception(interaction);
    if (interaction.commandName === 'duel') return await handleDuel(interaction);
    if (interaction.commandName === 'gm') {
      const gmGroup = interaction.options.getSubcommandGroup(false);
      if (gmGroup === 'test') return await handleGmTest(interaction);
      if (gmGroup === 'backup') return await handleBackup(interaction);
      const gmSub = interaction.options.getSubcommand();
      if (gmSub === 'search') return await handleGmSearch(interaction);
      if (gmSub === 'queue') return await handleGmQueue(interaction);
      if (gmSub === 'kill') { const r = await handleGmKill(interaction);
        ensureCharPage(interaction.client, interaction.guild, interaction.options?.getUser?.('user')?.id ?? interaction.user.id, null).catch(() => {});
        return r; }  // the Fallen tag follows the deed
      if (gmSub === 'revive') { const r = await handleGmRevive(interaction);
        ensureCharPage(interaction.client, interaction.guild, interaction.options?.getUser?.('user')?.id ?? interaction.user.id, null).catch(() => {});
        return r; }
      if (gmSub === 'heal') return await handleGmHeal(interaction);
      if (gmSub === 'questwipe') return await runGmQuestWipe(interaction);
      if (gmSub === 'check' || interaction.options.getSubcommandGroup(false) === 'check') return await handleCheck(interaction);
      if (gmSub === 'scroll') return await handleScroll(interaction);
      if (gmSub === 'dicereport') return await handleDiceReport(interaction);
      if (interaction.options.getSubcommandGroup(false) === 'override') {
        if (!(await isGm(interaction.guild, interaction.user.id))) {
          return interaction.reply({ content: '❌ Overrides are for GMs.', ephemeral: true });
        }
        if (gmSub === 'interject') return await gmInterject(interaction);
        if (gmSub === 'skip') {
          const f = getFight(interaction.guild.id, interaction.channelId);
          if (!f || f.state !== 'active') return interaction.reply({ ephemeral: true, content: '❌ No fight is running in this channel.' });
          await interaction.deferReply();
          const who = await gmSkipTurn(interaction.guild, interaction.guild.id, interaction.channelId,
            interaction.options.getString('reason') || null);
          return interaction.editReply({ content: who
            ? `⏭ **${who}**'s turn passed by your hand.`
            : '❌ The fight ended before the skip landed.' });
        }
      }
      if (gmSub === 'dc') return await runGmDcCheck(interaction);
      if (gmSub === 'reroll') return await runGmReroll(interaction);
      if (gmSub === 'roll') return await runGmRollSlash(interaction);
    }
    if (interaction.commandName === 'activity') return await handleStory(interaction);
    if (interaction.commandName === 'config') return await handleConfig(interaction);
    if (interaction.commandName === 'char') {
      const cg = interaction.options.getSubcommandGroup(false);
      if (cg === 'weapon') return await handleWeapon(interaction);
      if (cg === 'tag') return await handleTag(interaction);
      if (cg === 'profile') return await handleProfile(interaction);
      if (!cg && interaction.options.getSubcommand(false) === 'stat') return await handleStat(interaction);
      return await handleChar(interaction);   // the view group's leaves keep their names — handleChar dispatches them as ever
    }
    if (interaction.commandName === 'fight') return await handleFight(interaction);
    if (interaction.commandName === 'npc') {
      const npcSub = interaction.options.getSubcommand(false);
      if (npcSub === 'say' || npcSub === 'roll') return await handlePr(interaction);
      return await handleNpc(interaction);
    }
    if (interaction.commandName === 'help') return await handleHelp(interaction);
    if (interaction.commandName === 'roll') return await handleRollSlash(interaction);
    if (interaction.commandName === 'standing') {
      const sg = interaction.options.getSubcommandGroup(false);
      if (sg === 'renown') return await handleRenown(interaction);
      if (sg === 'merit') return await handleMerit(interaction);
      if (sg === 'rank') return await handleRank(interaction);
      if (sg === 'title' || sg === 'association') return await handleTitles(interaction, sg);
    }
    if (interaction.commandName === 'instance') return await handleInstance(interaction);
    if (interaction.commandName === 'target') return await handleTarget(interaction);
    if (interaction.commandName === 'button') return await handleButton(interaction);
    if (interaction.commandName === 'feedback') return await handleFeedback(interaction);
    if (interaction.commandName === 'quest') return await handleQuest(interaction);
  } catch (err) {
    console.error(`[${interaction.commandName}] error:`, err);
    // Build a helpful error message
    let msg = '❌ Something went wrong';
    if (err.code === 50013) msg = '❌ I don\'t have permission to do that. Check my role permissions.';
    else if (err.code === 50001) msg = '❌ I can\'t access that channel.';
    else if (err.code === 10003) msg = '❌ That channel no longer exists.';
    else if (err.code === 50035) msg = '❌ Invalid input — please check the values you entered.';
    else if (err.message?.includes('Missing Permissions')) msg = '❌ I\'m missing permissions for that action.';
    else if (err.message) msg = `❌ ${err.message.slice(0, 150)}`;
    const payload = { content: msg, ephemeral: true };
    if (interaction.replied || interaction.deferred) interaction.followUp(payload).catch(()=>{});
    else interaction.reply(payload).catch(()=>{});
  }
});

// ── Bare stat shorthand ───────────────────────────────────────────────────────
// Type a stat name to quick-roll 1d20+stat with no prefix. Optional ? prefix for
// a success check, optional suffix:
//   a / d          → fresh roll with advantage / disadvantage   (wisa, dexd)
//   rr / rra / rrd → reroll your last roll (1 token)            (strrr, conrra)
// followed by an optional label / flavour after a space or newline.
//
// The catch: str / con / dex / wis / lck are ordinary words in TTRPG chat, so a
// message that merely *started* with one got rolled — "Dex or strength can both
// be used to throw things" came back as a DEX check labelled with the rest of
// the sentence. A plain stat with no prefix and no suffix must therefore be the
// entire message and nothing else.
//
// Everything unambiguous keeps its label, because no ordinary word looks like
// it: "strrr atk", "dexd guard", "wisa sneak", "?dex atk". For a label on a
// plain stat, use a prefix — `r str atk` or `?str atk`.
//
// Returns null when the message is just conversation.
function parseStatShorthand(content) {
  const m = content.match(new RegExp(`^(\\?)?(${STAT_WORD_RE})(rra|rrd|rr|a|d)?(?:([ \\t][\\s\\S]*)|(\\n[\\s\\S]*))?$`, 'i'));
  if (!m) return null;
  const sc = m[1] === '?';
  const stat = resolveStatWord(m[2]);
  const suffix = (m[3] || '').toLowerCase(); // '', 'a', 'd', 'rr', 'rra', 'rrd'
  const trailing = (m[4] ?? m[5] ?? '').replace(/^[ \t]+/, '');
  // The ambiguous form — bare stat word, no prefix, no suffix — only fires on an
  // exact match. Anything trailing means this is a sentence, not a roll.
  if (!sc && !suffix && trailing.trim()) return null;
  const isReroll = suffix.startsWith('rr');
  const mode = (suffix === 'a' || suffix === 'rra') ? 'adv'
             : (suffix === 'd' || suffix === 'rrd') ? 'dis'
             : 'normal';
  // Fresh roll: hand handleRoll the stat name so it resolves to 1d20+stat.
  // Reroll: the label/flavour ride along; the suffix only selects adv/dis.
  const payload = isReroll ? trailing : (stat + (trailing ? ' ' + trailing : ''));
  return { sc, stat, suffix, mode, isReroll, payload };
}

client.on('messageCreate', async message => {
  if (message.author.bot) return;
  const content = message.content.trim();


  // NPC portrait bank — captioned uploads in the configured forum or channel
  if (message.guild && message.attachments.size > 0) {
    const cfg = getConfig(message.guild.id);
    // Only speak inside the portrait bank. This used to answer every image
    // posted anywhere on the server with a warning that no bank was set — and
    // then return, which swallowed the rest of messageCreate for any message
    // carrying an attachment.
    const bankId = cfg.npc_channel_id;
    const inBank = !!bankId && (message.channel.id === bankId
      // A forum bank holds a thread per category, so the upload lands in a
      // child of the forum rather than in the forum itself. Which thread does
      // not matter: the caption names the NPC, and being forgiving here beats
      // refusing a portrait posted one thread over.
      || message.channel.parentId === bankId);
    if (inBank) {
      // Tracing: an avatar upload that does nothing is impossible to diagnose
      // otherwise. These lines show in the Railway logs.
      console.log(`[npcimg] attachment in ${message.channel.id}; bank=${bankId}; text="${message.content}"`);
      const npcName = message.content.trim();
      if (!npcName) {
        console.error('[npcimg] message.content is EMPTY — if you did type a name, the Message Content Intent is disabled in the Developer Portal.');
        await message.reply('⚠️ I can\'t read the message text. Either add the NPC\'s name as the caption, or — if you did — a bot admin needs to enable **Message Content Intent** in the Discord Developer Portal.').catch(()=>{});
        return;
      }
      const npc = getNpc(message.guild.id, npcName);
      if (!npc) {
        // Not an NPC's exact name — a bare ORDER or CATEGORY label sets the
        // shared face every wearer without a portrait of their own puts on.
        // Orders checked first (the nine colours outrank a category that
        // happens to share a name); membership gates the set either way.
        const gidF = message.guild.id;
        const orderMembers = ordersWithMembers(gidF).get(npcName.toLowerCase()) ?? 0;
        const catMatch = getCategories(gidF).find(c => c.toLowerCase() === npcName.toLowerCase());
        const catMembers = catMatch
          ? db.prepare('SELECT COUNT(*) AS c FROM npc_category_members WHERE guild_id=? AND category=?').get(gidF, catMatch).c
          : 0;
        const label = orderMembers ? npcName : (catMembers ? catMatch : null);
        if (label) {
          setOrderImage(gidF, label, message.attachments.first().url, message.author.id);
          // Everyone the chain now dresses in this face gets fresh
          // webhooks; personal faces are never touched.
          let worn = 0;
          for (const n of getAllNpcs(gidF)) {
            if (!n.image_url && sharedFaceLabelFor(gidF, n) === label) {
              clearNpcWebhooks(gidF, n.name); worn++;
            }
          }
          await message.reply(`✅ ${orderMembers ? 'Order' : 'Category'} face set for **${label}** — worn by ${worn} NPC${worn === 1 ? '' : 's'} without a face of their own.`).catch(() => {});
          return;
        }
        console.error(`[npcimg] no match for caption "${npcName}" in guild ${message.guild.id}`);
        await message.reply('❌ No NPC, order, or category named **' + npcName + '** — caption an NPC\'s exact name for a personal face, or a bare order/category name for a shared one.').catch(() => {});
        return;
      }
      const imageUrl = message.attachments.first().url;
      setNpcImage(message.guild.id, npcName, imageUrl);
      setNpcWebhook(message.guild.id, npcName, null, null);
      clearNpcWebhooks(message.guild.id, npc.name); // recreate everywhere with the new avatar
      console.log(`[npcimg] avatar set for "${npc.name}"`);
      message.react('✅').catch(()=>{});
      await message.reply(`✅ Avatar set for **${npc.name}**.`).catch(()=>{});
      return; // Don't process as commands
    }
  }

  // Sheet import detection — check before prefix matching
  // Pasted scenario script — GM only, and validated before anything is stored.
  if (/^\s*\[(STORY|ACTIVITY)\]/im.test(content)) {
    if (!(await isGm(message.guild, message.author.id))) return message.reply('❌ Only GMs can add activities.');
    const r = storeActivityScript(message.guild.id, message.author.id, content);
    return message.reply(r.error ? `❌ **Couldn't read that activity.** ${r.error}` : r.saved);
  }

  if (content.includes('[TTRPG SHEET]')) {
    const parsed = parseSheetImport(content);
    if (parsed) {
      try { return await handleSheetImport(message, parsed); }
      catch (err) { console.error(err); return message.reply('\u274c Failed to import sheet.'); }
    }
  }


  // Bare dice notation — check before prefix matching so 1d20 works with no prefix
  const earlyBareMatch = content.match(/^(\d+d\d+(?:[+-]\d+)?)([ \t].*)?([\s\S]*)?$/i);
  if (earlyBareMatch) {
    const sameLineRest = (earlyBareMatch[2] ?? '').trim();
    const flavourRest = earlyBareMatch[3] ?? '';
    const bareRest = earlyBareMatch[1] + (sameLineRest ? ' ' + sameLineRest : '') + flavourRest;
    try { return await handleRoll(message, bareRest, 'normal', false); }
    catch (err) { console.error(err); return message.reply('\u274c Something went wrong.'); }
  }

  // An activity waiting on a roll takes precedence: "wis I cast into the deep
  // pools" answers the scene and prints the rest as flavour. Falls through when
  // nothing is running, or the stat isn't one this step accepts.
  try { if (await tryActivityTypedRoll(message, content)) return; }
  catch (err) { console.error('[activity] typed roll failed:', err?.message || err); }

  // Bare stat shorthand — see parseStatShorthand for the matching rules.
  const statShort = parseStatShorthand(content);
  if (statShort) {
    try { return await handleRoll(message, statShort.payload, statShort.mode, statShort.isReroll, statShort.sc); }
    catch (err) { console.error(err); return message.reply('❌ Something went wrong.'); }
  }

  // Bare (unprefixed) commands must not swallow ordinary chat: without a ! or ?
  // prefix, a command word can't be followed immediately by another letter.
  // "Hmm" / "hey" / "rest" / "right" are conversation; "!h @user", "r1d20",
  // "heal @user" and "hp +5" are commands.
  const match = content.match(/^(!|\?)(gmrs?|lrest|srest|hpfull|hphalf|rerolls|roll|rra|rrd|rr|ra|rd|r|heal|hp|h)([\s\S]*)/i)
    || content.match(/^()(gmrs?|lrest|srest|hpfull|hphalf|rerolls|roll|rra|rrd|rr|ra|rd|r|heal|hp|h)(?![A-Za-z])([\s\S]*)/i);
  if (!match) return;
  const prefix = match[1];
  const successCheck = prefix === '?';
  const raw = match[2].toLowerCase();
  // Preserve newlines for flavour text — only trim leading spaces on first line
  const rest = (match[3] ?? '').replace(/^[ \t]+/, '');
  try {
    if (raw==='r'||raw==='roll') return handleRoll(message, rest, 'normal', false, successCheck);
    if (raw==='ra') return handleRoll(message, rest, 'adv', false, successCheck);
    if (raw==='rd') return handleRoll(message, rest, 'dis', false, successCheck);
    if (raw==='rr') return handleRoll(message, rest, 'normal', true, successCheck);
    if (raw==='rra') return handleRoll(message, rest, 'adv', true, successCheck);
    if (raw==='rrd') return handleRoll(message, rest, 'dis', true, successCheck);
    if (raw==='heal'||raw==='h') return handleHeal(message, rest);
    if (raw==='hp') return handleHp(message, rest);
    if (raw==='rerolls') return handleRerolls(message, rest);
    if (raw==='lrest') return handleRest(message, rest, 'lrest');
    if (raw==='srest') return handleRest(message, rest, 'srest');
    if (raw==='hpfull') return handleRest(message, rest, 'hpfull');
    if (raw==='hphalf') return handleRest(message, rest, 'hphalf');
    if (raw==='gmr') return handleGmRoll(message, rest, false);
    if (raw==='gmrs') return handleGmRoll(message, rest, true);
  } catch (err) {
    console.error(err);
    message.reply('❌ Something went wrong.');
  }
});

// ─────────────────────────────────────────────
//  REGISTER SLASH COMMANDS + LOGIN
// ─────────────────────────────────────────────

// Whole commands that belong to one system only. A guild's picker carries
// its own game: the filter runs per-guild at registration, and the runtime
// gates stay as the backstop — subcommands (like /npc manage create5e) register
// with their command and cannot be hidden per-ruleset, only refused.
const DND5E_ONLY = ['dnd', 'spell', 'library'];
const KNIGHTFALL_ONLY = ['duel', 'deception', 'standing'];

async function registerSlashCommands(guildId) {
  const rest = new REST({ version: '10' }).setToken(process.env.DISCORD_TOKEN);
  try {
    let commands = slashCommands;
    if (guildId) {
      // One system per picker. rulesFor defaults to Knightfall, so a brand
      // new guild starts without the 5e three; setting the ruleset
      // re-registers and the picker flips with it.
      const system = rulesFor(guildId).id;
      const hidden = system === 'dnd5e' ? KNIGHTFALL_ONLY : DND5E_ONLY;
      commands = commands.filter(cmd => !hidden.includes(cmd.name));

      const npcList = getAllNpcs(guildId);
      const categories = getCategories(guildId);
      const uncategorised = getUncategorisedNpcs(guildId);

      if (npcList.length > 0 || categories.length > 0) {
        commands = commands.map(cmd => {
          if (cmd.name !== 'pr') return cmd;
          const json = JSON.parse(JSON.stringify(cmd.toJSON()));

          json.options.forEach(sub => {
            if (sub.name === 'roll' || sub.name === 'reroll') {
              // Set category choices — All + each category + Uncategorised
              const catOpt = sub.options?.find(o => o.name === 'category');
              if (catOpt) {
                const catChoices = [
                  { name: 'All', value: 'all' },
                  ...categories.map(c => ({ name: c, value: c })),
                  { name: 'Uncategorised', value: 'Uncategorised' }
                ].slice(0, 25);
                catOpt.choices = catChoices;
              }

              // NPC names with category prefix — categorised first, then uncategorised
              const nameOpt = sub.options?.find(o => o.name === 'name');
              if (nameOpt && npcList.length > 0) {
                nameOpt.autocomplete = false;
                const categorised = [];
                const uncatNpcs = [];
                npcList.forEach(n => {
                  const cats = getCategoriesForNpc(guildId, n.name);
                  if (cats.length > 0) {
                    cats.forEach(c => categorised.push({ name: `[${c}] ${n.name}`, value: n.name }));
                  } else {
                    uncatNpcs.push({ name: n.name, value: n.name });
                  }
                });
                const seen = new Set();
                nameOpt.choices = [...categorised, ...uncatNpcs].filter(c => {
                  if (seen.has(c.value)) return false;
                  seen.add(c.value); return true;
                }).slice(0, 25);
              }
            }
          });
          return { toJSON: () => json };
        });
      }

    }
    if (guildId) {
      // Guild-scoped: NPC name choices are per-server, so they must not be
      // pushed globally or one server's NPCs appear in every other server.
      // Guild updates also appear instantly instead of taking up to an hour.
      await rest.put(Routes.applicationGuildCommands(process.env.CLIENT_ID, guildId), { body: commands.map(c => c.toJSON()) });
    } else {
      // Boot-time global registration uses the generic command set (no NPC choices).
      await rest.put(Routes.applicationCommands(process.env.CLIENT_ID), { body: commands.map(c => c.toJSON()) });
    }
    console.log('✅ Slash commands registered.');
  } catch (err) { console.error('Failed to register slash commands:', err); }
}

// Commands are registered per-guild (see the ready handler) so that NPC name
// choices stay server-specific. Any previously-registered GLOBAL commands would
// show up as duplicates alongside them, so clear the global set on boot.
async function clearGlobalCommands() {
  try {
    const rest = new REST({ version: '10' }).setToken(process.env.DISCORD_TOKEN);
    const existing = await rest.get(Routes.applicationCommands(process.env.CLIENT_ID));
    if (Array.isArray(existing) && existing.length) {
      await rest.put(Routes.applicationCommands(process.env.CLIENT_ID), { body: [] });
      console.log(`🧹 Cleared ${existing.length} global command(s) — guild commands are authoritative.`);
    }
  } catch (err) { console.error('Could not clear global commands:', err?.message || err); }
}

(async () => {
  console.log('Starting up...');
  await clearGlobalCommands();
  startAutoRest(client);
  startQuestClock(client);
  startDocsWatch(client);
  client.login(process.env.DISCORD_TOKEN);
})();

// Keep the process alive if a stray promise rejects or a handler throws async.
// Better to log and keep serving other channels than to crash the whole bot.
process.on('unhandledRejection', (reason) => {
  console.error('UNHANDLED REJECTION:', reason);
});
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION:', err);
});
// ─────────────────────────────────────────────
//  FIGHT SYSTEM
// ─────────────────────────────────────────────

const STAT_LABELS = { str:'STR', con:'CON', dex:'DEX', wis:'WIS', lck:'LCK' };

// ── The ruleset ────────────────────────────────────────────────────
// What a system decides, in one place: its stats, how HP comes from them,
// how a roll is built, what two rolls make, and what a stat must reach
// before an ability opens. Everything else in this file — quests, NPCs,
// scrolls, activities, quizzes, the audit shelves — is system-agnostic and
// asks none of these questions.
const RULES_KNIGHTFALL = {
  id: 'knightfall',
  name: 'Knightfall',
  // The stats a sheet carries, in the order they are shown.
  stats: STATS,
  labels: STAT_LABELS,
  // A stat is added to the die whole — no modifier arithmetic here.
  statBonus: (row, stat) => Number(row?.[stat]) || 0,
  // HP is CON plus whatever the server sets as everyone's floor.
  hpStat: 'con',
  maxHp: (row, base) => (Number(row?.con) || 0) + base,
  // One damage for a hit, one more for a natural maximum, one more for the
  // defender's natural 1 — four at the very worst.
  damage: (atkRoll, atkNat, atkSides, defRoll, defNat, defSides) => {
    // T's rules doc (Atk Fumble / Crit Def, 2026-08-15), layered on the
    // original damage table:
    //   nat-1 attack  -> fails automatically, whatever the totals say.
    //   nat-20 defence -> parries automatically — UNLESS the attack was
    //     also a nat 20, in which case the totals decide as ever.
    //   Damage when a hit lands: 1, +1 for an attacking 20, +1 for a
    //     defending 1, 4 when both — unchanged.
    if (atkNat === 1) return { hit: false, dmg: 0, detail: 'fumbled' };
    if (defNat === defSides && atkNat !== atkSides) return { hit: false, dmg: 0, detail: 'parried' };
    const hit = atkRoll >= defRoll;
    if (!hit) return { hit, dmg: 0 };
    let dmg = 1;
    if (atkNat === atkSides) dmg += 1;
    if (defNat === 1) dmg += 1;
    if (atkNat === atkSides && defNat === 1) dmg += 1;
    return { hit, dmg };
  },
  // Two rolls decide a blow between them; nobody has a target number.
  defence: 'opposed',
  profBonus: () => 0,
  // What a stat must reach before an ability is available at all.
  gates: { deflect: ['str', 4], disarm: ['dex', 4], feint: ['wis', 4], insight: ['wis', 4], heal: ['wis', 5] },
  // What progress is called here.
  vocabulary: { currency: 'renown', standing: 'merits', rank: 'rank' },
};

// ── Dungeons & Dragons, fifth edition (SRD) ──────────────────────────
// Only what the SRD releases under Creative Commons is built in. Anything
// from the Player's Handbook alone — most subclasses, backgrounds, feats —
// is written by GMs through the same custom routes the bot already has.
const DND_STATS = ['str', 'dex', 'con', 'int', 'wis', 'cha'];
const DND_LABELS = { str: 'STR', dex: 'DEX', con: 'CON', int: 'INT', wis: 'WIS', cha: 'CHA' };
// The eighteen SRD skills, and the ability each one leans on.
const DND_SKILLS = {
  acrobatics: 'dex', 'animal handling': 'wis', arcana: 'int', athletics: 'str',
  deception: 'cha', history: 'int', insight: 'wis', intimidation: 'cha',
  investigation: 'int', medicine: 'wis', nature: 'int', perception: 'wis',
  performance: 'cha', persuasion: 'cha', religion: 'int',
  'sleight of hand': 'dex', stealth: 'dex', survival: 'wis',
};

const RULES_DND5E = {
  id: 'dnd5e',
  name: 'D&D 5e (SRD)',
  stats: DND_STATS,
  labels: DND_LABELS,
  skills: DND_SKILLS,
  // A score of 10 is average and adds nothing; every two points either way
  // is a point of modifier.
  modifier: (score) => Math.floor(((Number(score) || 10) - 10) / 2),
  statBonus: (row, stat) => Math.floor(((Number(row?.[stat]) || 10) - 10) / 2),
  // +2 at levels 1–4, and another point every four levels after.
  profBonus: (row) => 2 + Math.floor((Math.max(1, Number(row?.level) || 1) - 1) / 4),
  // Hit die plus CON modifier at first level, then the die's average
  // (rounded up) plus the modifier for every level after.
  hpStat: 'con',
  maxHp: (row) => {
    const lvl = Math.max(1, Number(row?.level) || 1);
    const die = Number(row?.hit_die) || 8;
    const con = Math.floor(((Number(row?.con) || 10) - 10) / 2);
    return die + con + (lvl - 1) * (Math.floor(die / 2) + 1 + con);
  },
  // An attack is rolled against a number, not against another roll.
  defence: 'ac',
  // A statblock states its Armour Class; a character's comes from armour or
  // from DEX. Never guess it from a stat that was written for other rules.
  targetNumber: (row) => Number(row?.armour_class) || (10 + Math.floor(((Number(row?.dex) || 10) - 10) / 2)),
  // What a monster adds to hit, and rolls for damage — straight off its
  // statblock rather than out of a class and a level it doesn't have.
  monsterAttack: (row) => (row?.attack_bonus == null ? null : Number(row.attack_bonus)),
  monsterDamage: (row) => String(row?.damage_dice || '').trim() || null,
  // Natural 20 always hits and always crits; natural 1 always misses.
  resolveAttack: ({ nat, total, ac }) => {
    if (nat === 20) return { hit: true, crit: true };
    if (nat === 1) return { hit: false, crit: false };
    return { hit: total >= ac, crit: false };
  },
  // Weapon dice plus the modifier; a crit rolls the dice twice and leaves
  // the modifier alone.
  weaponDamage: ({ dice = '1d8', mod = 0, crit = false, roll }) => {
    const m = /^(\d*)d(\d+)$/i.exec(String(dice).trim());
    if (!m) return { total: Math.max(0, mod), detail: `${mod}` };
    const n = (parseInt(m[1]) || 1) * (crit ? 2 : 1);
    const sides = parseInt(m[2]);
    const rolls = [];
    for (let i = 0; i < n; i++) rolls.push(roll ? roll(sides) : 1 + Math.floor(Math.random() * sides));
    const sum = rolls.reduce((a, b) => a + b, 0);
    return { total: Math.max(0, sum + mod), rolls,
      detail: `${n}d${sides}${crit ? ' (crit)' : ''} [${rolls.join(', ')}]${mod ? (mod > 0 ? ` +${mod}` : ` ${mod}`) : ''}` };
  },
  // The same question the exchange asks Knightfall, answered the 5e way:
  // the "defence roll" is the target's AC, a natural 20 always hits and
  // crits, and damage is the weapon's dice plus the modifier.
  damage: (atkRoll, atkNat, atkSides, defRoll, defNat, defSides, ctx = {}) => {
    const { hit, crit } = RULES_DND5E.resolveAttack({ nat: atkNat, total: atkRoll, ac: defRoll });
    if (!hit) return { hit, dmg: 0, crit: false, detail: null };
    const d = RULES_DND5E.weaponDamage({ dice: ctx.weaponDice || '1d8', mod: ctx.mod || 0, crit, roll: ctx.roll });
    return { hit, dmg: d.total, crit, detail: d.detail };
  },
  // How this character's magic works, or null if it doesn't.
  caster: (row) => DND_CASTERS[row?.char_class] || null,
  // The slots they have, as an array indexed from spell level 1. A half
  // caster reads the full table at half their level and has nothing at
  // first; a warlock's pact magic is its own small, sharp thing.
  slots: (row) => {
    const c = DND_CASTERS[row?.char_class];
    if (!c) return [];
    const lvl = Math.max(1, Number(row?.level) || 1);
    if (c.kind === 'full') return DND_SLOTS_FULL[lvl - 1] || [];
    if (c.kind === 'half') {
      const eff = Math.floor(lvl / 2);
      return eff < 1 ? [] : (DND_SLOTS_FULL[eff - 1] || []);
    }
    // Pact magic: a handful of slots, all at the same level, back on a short rest.
    const n = lvl >= 17 ? 4 : lvl >= 11 ? 3 : lvl >= 2 ? 2 : 1;
    const slotLevel = Math.min(5, Math.ceil(lvl / 2));
    const out = [];
    for (let i = 1; i < slotLevel; i++) out.push(0);
    out.push(n);
    return out;
  },
  // 8 + proficiency + the casting ability's modifier.
  spellSaveDC: (row) => {
    const c = DND_CASTERS[row?.char_class];
    if (!c) return null;
    return 8 + RULES_DND5E.profBonus(row) + RULES_DND5E.statBonus(row, c.ability);
  },
  // Proficiency + the casting ability's modifier.
  spellAttack: (row) => {
    const c = DND_CASTERS[row?.char_class];
    if (!c) return null;
    return RULES_DND5E.profBonus(row) + RULES_DND5E.statBonus(row, c.ability);
  },
  // How many spells a preparing caster may have ready: the ability modifier
  // plus their level, or half their level for a paladin. Never fewer than one.
  prepareCount: (row) => {
    const c = DND_CASTERS[row?.char_class];
    if (!c?.prepares) return null;
    if (!RULES_DND5E.slots(row).length) return null;   // a paladin at first level has no magic yet
    const lvl = Math.max(1, Number(row?.level) || 1);
    const base = c.kind === 'half' ? Math.floor(lvl / 2) : lvl;
    return Math.max(1, base + RULES_DND5E.statBonus(row, c.ability));
  },
  // A blow that lands on a concentrating caster: DC 10, or half the damage
  // taken, whichever is the harder.
  concentrationDC: (damage) => Math.max(10, Math.floor((Number(damage) || 0) / 2)),
  // The SRD conditions. Each says what it does to the creature carrying it
  // and to anyone swinging at them — which is most of how they matter.
  conditions: {
    blinded:      { self: 'dis', against: 'adv' },
    charmed:      { self: null,  against: null },
    deafened:     { self: null,  against: null },
    frightened:   { self: 'dis', against: null },
    grappled:     { self: null,  against: null },
    incapacitated:{ self: null,  against: null },
    invisible:    { self: 'adv', against: 'dis' },
    paralyzed:    { self: 'dis', against: 'adv' },
    petrified:    { self: 'dis', against: 'adv' },
    poisoned:     { self: 'dis', against: null },
    prone:        { self: 'dis', against: 'adv' },
    restrained:   { self: 'dis', against: 'adv' },
    stunned:      { self: 'dis', against: 'adv' },
    unconscious:  { self: 'dis', against: 'adv' },
    exhaustion:   { self: 'dis', against: null },
  },
  // A second swing at fifth level for those who fight for a living, a third
  // and fourth for the Fighter alone.
  attacksPerAction: (row) => {
    const lvl = Math.max(1, Number(row?.level) || 1);
    const cls = row?.char_class;
    if (cls === 'Fighter') return lvl >= 20 ? 4 : lvl >= 11 ? 3 : lvl >= 5 ? 2 : 1;
    if (['Barbarian', 'Paladin', 'Ranger', 'Monk'].includes(cls)) return lvl >= 5 ? 2 : 1;
    return 1;
  },
  // Half against resistance, double against vulnerability, none at all
  // against immunity — written on the sheet as "fire, cold" or "x2 fire".
  applyResistance: (row, type, dmg) => {
    if (!type) return { dmg, note: null };
    const raw = String(row?.resist || '').toLowerCase();
    if (!raw) return { dmg, note: null };
    const t = String(type).toLowerCase();
    if (new RegExp(`(^|,)\\s*immune\\s+${t}\\s*(,|$)`).test(raw)) return { dmg: 0, note: `immune to ${t}` };
    if (new RegExp(`(^|,)\\s*x2\\s+${t}\\s*(,|$)`).test(raw)) return { dmg: dmg * 2, note: `vulnerable to ${t}` };
    if (new RegExp(`(^|,)\\s*${t}\\s*(,|$)`).test(raw)) return { dmg: Math.floor(dmg / 2), note: `resists ${t}` };
    return { dmg, note: null };
  },
  // Ten plus the skill's modifier — what a GM checks against without asking.
  passive: (row, skill) => {
    const ab = RULES_DND5E.skills[skill];
    if (!ab) return null;
    let prof = {};
    try { prof = JSON.parse(row?.proficient || '{}') || {}; } catch {}
    const trained = (prof.skills || []).includes(skill);
    return 10 + RULES_DND5E.statBonus(row, ab) + (trained ? RULES_DND5E.profBonus(row) : 0);
  },
  // A cantrip's dice grow at 5th, 11th and 17th level.
  cantripTier: (row) => {
    const lvl = Math.max(1, Number(row?.level) || 1);
    return lvl >= 17 ? 4 : lvl >= 11 ? 3 : lvl >= 5 ? 2 : 1;
  },
  // A character carries one hit die per level, spent on a short rest.
  hitDiceTotal: (row) => Math.max(1, Number(row?.level) || 1),
  // A long rest fills you and returns half your dice, rounded down, never
  // less than one.
  longRestDice: (row) => Math.max(1, Math.floor((Math.max(1, Number(row?.level) || 1)) / 2)),
  // Nothing here is gated on a raw score; proficiency is the currency.
  gates: {},
  vocabulary: { currency: 'gold', standing: 'experience', rank: 'level' },
};

// The full caster's slots, level 1 to 20 — the SRD table, read straight.
// Each row is how many slots of spell level 1–9 that character level has.
const DND_SLOTS_FULL = [
  [2], [3], [4, 2], [4, 3], [4, 3, 2], [4, 3, 3], [4, 3, 3, 1], [4, 3, 3, 2],
  [4, 3, 3, 3, 1], [4, 3, 3, 3, 2], [4, 3, 3, 3, 2, 1], [4, 3, 3, 3, 2, 1],
  [4, 3, 3, 3, 2, 1, 1], [4, 3, 3, 3, 2, 1, 1], [4, 3, 3, 3, 2, 1, 1, 1],
  [4, 3, 3, 3, 2, 1, 1, 1], [4, 3, 3, 3, 2, 1, 1, 1, 1], [4, 3, 3, 3, 3, 1, 1, 1, 1],
  [4, 3, 3, 3, 3, 2, 1, 1, 1], [4, 3, 3, 3, 3, 2, 2, 1, 1],
];
// Who casts how, and off which ability.
const DND_CASTERS = {
  Bard:     { kind: 'full', ability: 'cha', prepares: false },
  Cleric:   { kind: 'full', ability: 'wis', prepares: true },
  Druid:    { kind: 'full', ability: 'wis', prepares: true },
  Sorcerer: { kind: 'full', ability: 'cha', prepares: false },
  Wizard:   { kind: 'full', ability: 'int', prepares: true },
  Paladin:  { kind: 'half', ability: 'cha', prepares: true },
  Ranger:   { kind: 'half', ability: 'wis', prepares: false },
  Warlock:  { kind: 'pact', ability: 'cha', prepares: false },
};

// The SRD's twelve classes and the die each one rolls for hit points.
const DND_HIT_DICE = {
  Barbarian: 12, Fighter: 10, Paladin: 10, Ranger: 10,
  Bard: 8, Cleric: 8, Druid: 8, Monk: 8, Rogue: 8, Warlock: 8,
  Sorcerer: 6, Wizard: 6,
};

const RULESETS = { knightfall: RULES_KNIGHTFALL, dnd5e: RULES_DND5E };

// Which rules a server plays by. One answer today; the hook is here so a
// second ruleset is a lookup rather than a rewrite.
// What an ability asks of a fighter: { stat, need, label } from the ruleset,
// so the bar moves with the system while each refusal keeps its own voice.
function abilityNeeds(gid, ability) {
  const r = rulesFor(gid);
  const [stat, need] = r.gates?.[ability] || ['wis', 0];
  return { stat, need, label: r.labels[stat] || String(stat).toUpperCase() };
}
// True when they fall short of it.
function belowBar(row, bar) { return (Number(row?.[bar.stat]) || 0) < bar.need; }

function rulesFor(gid) {
  let id = null;
  try { id = getConfig(gid)?.ruleset || null; } catch { /* before config exists */ }
  return RULESETS[id] || RULES_KNIGHTFALL;
}

const STAT_EMOJIS = { str:'💪', con:'🫀', dex:'⚡', wis:'🧠', lck:'🍀' };
const STAT_NAMES  = { str:'Strength', con:'Constitution', dex:'Dexterity', wis:'Wisdom', lck:'Luck' };

function fightTotalStr(total, nat, sides) {
  const isCrit = nat === sides;
  const isFail = nat === 1;
  if (isCrit) return `🟡 **${total}**`;
  if (isFail) return `🔴 **${total}**`;
  return `**${total}**`;
}

// The damage model belongs to the ruleset; this stays as the one door every
// resolution comes through.
function resolveDamage(atkRoll, atkNat, atkSides, defRoll, defNat, defSides, gid = null, ctx = {}) {
  return rulesFor(gid).damage(atkRoll, atkNat, atkSides, defRoll, defNat, defSides, ctx);
}

// What a fighter swings with, in dice. Knightfall has no weapon dice — its
// damage is a ladder — so this only ever matters under a ruleset that asks.
function weaponDiceFor(gid, row) {
  // A monster swings what its statblock says; a character swings their weapon.
  const m = String(row?.damage_dice || '').trim();
  if (/^\d*d\d+([+-]\d+)?$/i.test(m)) return m.replace(/[+-]\d+$/, '') || '1d8';
  const d = String(row?.weapon1dice || '').trim();
  return /^\d*d\d+$/i.test(d) ? d : '1d8';
}
// The flat bonus riding on a monster's damage, e.g. the +2 of 1d8+2.
function damageBonusFor(row) {
  const m = /([+-]\d+)$/.exec(String(row?.damage_dice || '').trim());
  return m ? parseInt(m[1]) : null;
}

// ── Carry-over combat effects (nat-1 attack / nat-20 defence) ─────────────────
// effect_state is a JSON map { fid: { flatDef?: true, atkBonus?: N } } stored on
// the fight row, mirroring hp_state / rr_state. Effects are SET when an exchange
// resolves and CONSUMED on the affected fighter's next matching roll.
//
//   nat-1 attack  → attacker's NEXT defence is a flat d20 (no stat)   { flatDef:true }
//   nat-20 defence (that blocks) → defender's NEXT attack gets +2,    { atkBonus:2 }
//     UNLESS the incoming attack was itself a nat 20.
// Pull and clear an attacker's pending +N bonus. Returns the bonus (0 if none).
function consumeAtkBonus(gid, cid, fid) {
  // Unified carry: rollBonus applies to the fighter's next roll of EITHER
  // kind. A fight already in flight may hold the pre-rule atkBonus key —
  // honoured once, then gone.
  const fight = getFight(gid, cid);
  if (!fight) return 0;
  const all = JSON.parse(fight.effect_state || '{}');
  const bonus = all[fid]?.rollBonus ?? all[fid]?.atkBonus ?? 0;
  if (bonus) {
    delete all[fid].rollBonus; delete all[fid].atkBonus;
    upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
  }
  return bonus;
}
// Pull and clear a GM-forced stat for a fighter's next roll (set by
// /gm override interject stat:). Returns the stat name or null.
function consumeGmStat(gid, cid, fid) {
  const fight = getFight(gid, cid);
  if (!fight) return null;
  const all = JSON.parse(fight.effect_state || '{}');
  const st = all[fid]?.gmStat ?? null;
  if (st) {
    delete all[fid].gmStat;
    upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
  }
  return st;
}
// Pull and clear a defender's pending flat-d20 penalty. Returns true if it applied.
function consumeFlatDef(gid, cid, fid) {
  const fight = getFight(gid, cid);
  const all = JSON.parse(fight.effect_state || '{}');
  const flat = !!all[fid]?.flatDef;
  if (flat && all[fid]) {
    delete all[fid].flatDef;
    if (!Object.keys(all[fid]).length) delete all[fid];
    upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
  }
  return flat;
}
// After an exchange resolves, set any new carry-over effects. atkNat/defNat are
// the natural dice; `blocked` is true when the defence stopped the attack.
function applyExchangeEffects(gid, cid, attackerId, defenderId, atkNat, defNat) {
  const fight = getFight(gid, cid);
  const all = JSON.parse(fight.effect_state || '{}');
  const ensure = (fid) => (all[fid] = all[fid] || {});
  const notes = [];
  // Nat-1 attack: the attacker fumbles — their next defence is a flat d20.
  if (atkNat === 1) {
    ensure(attackerId).flatDef = true;
    notes.push('flat_def');
  }
  // T's rules doc (2026-08-15): a defending 20 ALWAYS banks the +2
  // riposte on the next attack — the old mutual-20 exception applied to
  // the PARRY (handled in damage), never to this carry. No attacker-side
  // next-roll carry exists; an attacking 20 pays out as damage instead.
  if (defNat === 20) {
    ensure(defenderId).rollBonus = 2;
    notes.push('atk_bonus');
  }
  upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
  return notes;
}
// Drop all effects for a fighter (used when they leave the fight).
function clearEffects(gid, cid, fid) {
  const fight = getFight(gid, cid);
  if (!fight) return;
  const all = JSON.parse(fight.effect_state || '{}');
  if (all[fid]) { delete all[fid]; upsertFight(gid, cid, { effect_state: JSON.stringify(all) }); }
}
// Human-readable lines for newly-applied effects (notes from applyExchangeEffects).
function effectNoteLines(notes, atkName, defName) {
  const out = [];
  if (notes.includes('flat_def')) out.push(`🎲 **Natural 1!** ${atkName} fumbles — their next defence is a flat d20.`);
  if (notes.includes('atk_bonus')) out.push(`✨ **Natural 20 defence!** ${defName} turns it aside and gains **+2** on their next attack.`);
  return out;
}

// ── Fighter identity helpers (mixed players + NPCs) ───────────────────────────
// A fighter id is either a Discord user id (all digits) or "npc:<Name>".
const NPC_PREFIX = 'npc:';
function isNpcFighter(id) { return typeof id === 'string' && id.startsWith(NPC_PREFIX); }
function npcFighterId(name) { return NPC_PREFIX + name; }
function npcNameFromFighter(id) { return isNpcFighter(id) ? id.slice(NPC_PREFIX.length) : null; }

// Resolve a fighter id to { id, name, stats, isNpc }. stats has str/con/dex/wis/lck.
async function resolveFighter(guild, gid, fid) {
  if (isNpcFighter(fid)) {
    const name = npcNameFromFighter(fid);
    const npc = getNpc(gid, name);
    return {
      id: fid, name, isNpc: true,
      stats: npc ? { str:npc.str, con:npc.con, dex:npc.dex, wis:npc.wis, lck:npc.lck } : { str:0,con:0,dex:0,wis:0,lck:0 },
      maxHp: npc ? maxHpFromCon(gid, npc.con) : 0,
    };
  }
  const member = await guild.members.fetch(fid).catch(()=>null);
  const name = member?.nickname || member?.user.username || fid;
  const char = getChar(gid, fid);
  return {
    id: fid, name, isNpc: false,
    stats: char ? { str:char.str, con:char.con, dex:char.dex, wis:char.wis, lck:char.lck } : { str:0,con:0,dex:0,wis:0,lck:0 },
    maxHp: char ? maxHp(char, gid) : 0,
  };
}

// Persist a fighter's current HP to the right table (character vs npc).
function setFighterHp(gid, fid, hp) {
  if (isNpcFighter(fid)) {
    upsertNpc(gid, npcNameFromFighter(fid), { hp_current: hp });
  } else {
    upsertChar(gid, fid, { hp_current: hp });
  }
}

// Parse "@Alice @Bob" (or raw ids) into an ordered, de-duplicated list of user ids.
function parsePlayerMentions(str) {
  if (!str) return [];
  const ids = [];
  const re = /<@!?(\d+)>|\b(\d{15,21})\b/g;
  let m;
  while ((m = re.exec(str)) !== null) {
    const id = m[1] || m[2];
    if (id && !ids.includes(id)) ids.push(id);
  }
  return ids;
}

// Parse "Goblin, Cave Orc, Boss" into a trimmed, de-duplicated list of names.
function parseNpcNames(str) {
  if (!str) return [];
  const names = [];
  for (const raw of str.split(',')) {
    const n = raw.trim();
    if (n && !names.includes(n)) names.push(n);
  }
  return names;
}

// Pick the stat an auto fighter rolls with — always the highest of STR/DEX,
// for both attack and defence (ties go to STR).
// ── Weapon stat restrictions ─────────────────────────────────────────────────
// A gunlance is fired, not swung: it may attack with WIS and defend with DEX.
// A weapon with nothing set restricts nothing, so servers that never touch this
// carry on exactly as before.
function getWeaponRow(gid, name) {
  if (!name) return null;
  return db.prepare('SELECT * FROM weapons WHERE guild_id=? AND name=? COLLATE NOCASE').get(gid, String(name).trim());
}
const parseStatList = (v) => String(v || '').split('|').map(x => resolveStatWord(x)).filter(Boolean);

// Which stats this fighter may use, given what they are carrying. Returns null
// when nothing restricts them — a different answer from "an empty list", which
// would mean they can do nothing at all.
function allowedFightStats(gid, subject, kind) {
  if (!subject) return null;
  const col = kind === 'def' ? 'def_stats' : 'atk_stats';
  const carried = [subject.weapon1, subject.weapon2].filter(Boolean);
  if (!carried.length) return null;
  const rows = carried.map(w => getWeaponRow(gid, w)).filter(Boolean);
  if (!rows.length) return null;
  // A weapon with no restriction set frees the hand holding it.
  if (rows.some(r => !String(r[col] || '').trim())) return null;
  const allowed = [...new Set(rows.flatMap(r => parseStatList(r[col])))];
  return allowed.length ? allowed : null;
}

// The refusal, naming what they can use instead.
function weaponStatRefusal(gid, subject, kind, stat) {
  const allowed = allowedFightStats(gid, subject, kind);
  if (!allowed || allowed.includes(stat)) return null;
  const what = kind === 'def' ? 'defend' : 'attack';
  const carried = [subject.weapon1, subject.weapon2].filter(Boolean).map(w => `**${w}**`).join(' and ');
  return `❌ You can't ${what} with **${STAT_LABELS[stat] ?? stat.toUpperCase()}** carrying ${carried}.\n`
    + `_Allowed: ${allowed.map(x => `**${STAT_LABELS[x]}**`).join(', ')}._`;
}

// The auto-pilot picks the best stat it is actually allowed to use, rather than
// always reaching for STR or DEX.
function autoFightStat(stats, allowed = null, prefer = null) {
  const pool = (allowed && allowed.length) ? allowed : ['str', 'dex'];
  // A stated preference wins, but only where the weapon permits it — so setting
  // one can never break a weapon's rules, it just quietly does nothing there.
  const want = resolveStatWord(prefer);
  if (want && (!allowed || allowed.includes(want))) return want;
  return pool.reduce((best, k) => ((stats?.[k] ?? 0) > (stats?.[best] ?? 0) ? k : best), pool[0]);
}

// Everything the auto-pilot needs to know about one fighter, in one call: what
// they are carrying, what they would rather use, and what they are best at.
function chooseAutoStat(gid, id, stats, kind) {
  const subject = pageSubject(gid, id);
  return autoFightStat(stats, allowedFightStats(gid, subject, kind),
    subject?.[kind === 'def' ? 'preferred_def' : 'preferred_atk']);
}
// Roll a d20 + modifier, returning { nat, total }.
function autoRoll(mod, adv = false) {
  if (adv) {
    const a = rollDie(20), b = rollDie(20);
    const nat = Math.max(a, b);
    return { nat, total: nat + mod, adv: true, dropped: Math.min(a, b) };
  }
  const nat = rollDie(20);
  return { nat, total: nat + mod };
}

// Default: auto NPCs only spend a reroll token when the natural die was this or lower.
const NPC_RR_NAT_MAX = 8;
// Per-guild override via /config mechanics npcreroll (0 disables auto rerolls entirely).
function getNpcRrThreshold(gid) {
  const v = getConfig(gid)?.npc_rr_threshold;
  return (v === null || v === undefined) ? NPC_RR_NAT_MAX : v;
}
// One-line summary of a Hero's signature stat, e.g. "⭐  Signature  STR (advantage)".
// Returns null when the row isn't a Hero or has no signature set.
function signatureLine(row, pad = false) {
  if (!isHero(row) || !row?.signature_stat) return null;
  const stat = String(row.signature_stat).toLowerCase();
  const emoji = STAT_EMOJIS[stat] ?? '⭐';
  const name = STAT_NAMES[stat] ?? (STAT_LABELS[stat] ?? stat.toUpperCase());
  const active = hasSignatureAdvantage(row, stat);
  const suffix = active ? 'advantage' : `advantage *(inactive — needs ${SIGNATURE_MIN}+)*`;
  return pad ? `  ${emoji}: ${name} ${active ? 'advantage' : `advantage (inactive — needs ${SIGNATURE_MIN}+)`}`
             : `${emoji}:  ${name} ${suffix}`;
}

// ── NPC HP visibility ─────────────────────────────────────────────────────────
// Players shouldn't know an NPC's HP pool, but damage dealt should still be
// obvious. When hidden we report the damage and a coarse condition instead of
// exact numbers. GMs see real figures via /npc show, /npc list and /fight hp.
function npcStatsVisible(gid) {
  return !!getConfig(gid)?.npc_stats_visible;
}
// ── Practice bouts ────────────────────────────────────────────────────────────
// A friendly spar stops short of real harm: a fighter bows out the moment they
// reach the floor instead of being driven to 0 and beyond, and damage never
// carries anyone below it. The floor lives on the fight row, so a channel can
// run a real fight before and after a bout without any global switch. Every
// downstream check compares against the floor rather than a literal 0 — in a
// real fight the floor is 0 and behaviour is exactly as it always was.
const PRACTICE_FLOOR = 2;
const NO_ACTIVE_FIGHT = '❌ No active fight in this channel.';
function fightFloor(fight) {
  const v = Number(fight?.floor_hp ?? 0);
  return Number.isFinite(v) && v > 0 ? v : 0;
}
// Apply damage without pushing a sparring partner below the floor.
function applyFightDamage(prevHp, dmg, floor) {
  const raw = prevHp - dmg;
  return floor > 0 ? Math.max(floor, raw) : raw;
}
// Vocabulary swap so a bout doesn't read like a killing.
function fightWords(floor) {
  return floor > 0
    ? { icon: '🏳️', out: 'yields the bout', win: 'takes the bout', noun: 'bout',  started: 'Practice bout started!' }
    : { icon: '💀', out: 'has been knocked down', win: 'wins the fight', noun: 'fight', started: 'Fight started!' };
}
// Banner so nobody mistakes a spar for the real thing.
function practiceBanner(floor) {
  return floor > 0
    ? `🏳️ **Practice bout** — friendly sparring. Fighters bow out at **${floor} HP** and are never driven below it.`
    : null;
}

// Coarse health descriptor from a ratio — enough to follow a fight's momentum.
// `floor` is the bout cut-off (0 in a real fight).
function hpCondition(cur, max, floor = 0) {
  if (cur <= floor) return floor > 0 ? '🏳️ yielded' : '💀 down';
  const pct = max > 0 ? cur / max : 1;
  if (pct >= 0.85) return '💚 unhurt';
  if (pct >= 0.55) return '💛 wounded';
  if (pct >= 0.25) return '🧡 badly hurt';
  return '❤️‍🩹 near death';
}
// The "X → Y" line after damage. For hidden NPCs: damage plus condition only.
// "1d20+3 → [3] +3 = 6" gives an NPC's stat away — strip the modifier while NPC
// stats are hidden, leaving the natural die and the final total. One copy, so a
// second roll path can't quietly leak what the first hides.
function maskNpcRollLine(gid, rollLine) {
  if (npcStatsVisible(gid)) return rollLine;
  return rollLine
    .replace(/(\d+d\d+)[+-]\d+/g, '$1')
    .replace(/\]\s*[+-]\d+\s*=/g, '] =');
}


// The NPC block printed under a roll card. `cur` supplies the live reroll/LCK
// figures — the reroll path passes the refreshed row, everyone else the same one.
function npcCardFooter(gid, npc, cur = npc, reveal = false) {
  const lines = ['─────────────────────────────', `⚔️  ${npc.name}`];
  if (npc.order_name) lines.push(`${KNIGHT_EMOJIS[npc.order_name]??'⚪'}  ${npc.order_name}`);
  if (!reveal && !npcStatsVisible(gid)) {
    lines.push(`❤️  ${hpCondition(npc.hp_current, maxHpFromCon(gid, npc.con))}`);
  } else {
    lines.push(`❤️  HP${pad(npc.hp_current)} / ${maxHpFromCon(gid, npc.con)}`);
    lines.push(`🔄  Rerolls${pad(cur.lck)} / ${npc.lck}`);
    lines.push('');
    lines.push(`💪  STR${pad(npc.str)}`);
    lines.push(`🫀  CON${pad(npc.con)}`);
    lines.push(`⚡  DEX${pad(npc.dex)}`);
    lines.push(`🧠  WIS${pad(npc.wis)}`);
    lines.push(`🍀  LCK${pad(cur.lck)}`);
  }
  return lines;
}

function hpChangeLine(gid, isNpc, name, prevHp, newHp, maxHpVal, floor = 0) {
  if (isNpc && !npcStatsVisible(gid)) {
    return `❤️ ${name}: ${hpCondition(newHp, maxHpVal, floor)}`;
  }
  return `❤️ ${name} HP: **${prevHp} → ${newHp}**`;
}

// Once a sheet is approved, EVERY sheet field is GM-only — stats, order, class,
// weapons and weapon emojis alike. Returns an error string, or null if allowed.
function sheetEditLock(gid, callerId, targetId, isGmCaller) {
  if (!approvalEnabled(gid)) return null;      // feature off
  if (targetId !== callerId) return null;      // GM editing someone else (already gated)
  if (isGmCaller) return null;                 // GMs may always edit
  const own = getChar(gid, callerId);
  if (own?.approval_state === 'approved') {
    return '🔒 Your sheet is approved — only a GM can change it now. Ask a GM for any edits.';
  }
  // 'pending' is deliberately editable: a player who spots a mistake while
  // waiting can fix it, and the edit retires the old request and queues a fresh
  // one. A pending sheet can't be rolled with either way, so nothing is gained
  // by freezing it — and freezing it stranded anyone who mis-typed a stat.
  return null;
}

// ── Character sheet approval ──────────────────────────────────────────────────
// approval_state: null = legacy sheet (pre-feature, treated as approved),
// 'pending' = awaiting a GM, 'approved' = usable, 'rejected' = blocked.
// Approval is only enforced once a GM has set an approval channel or the
// approval forum; without either the whole feature stays dormant so existing
// servers are unaffected.
function approvalEnabled(gid) {
  return !!approvalDestination(gid, 'sheets');
}
function sheetApproved(gid, ch) {
  if (!ch) return false;
  if (!approvalEnabled(gid)) return true;          // feature off → everything works
  if (!ch.approval_state) return true;             // sheet predates the feature
  return ch.approval_state === 'approved';
}
// Guard for player actions that need a usable sheet. Returns an error string, or null.
// Is this character out of the story? Asked by everything that would otherwise
// let the fallen keep playing — rolls, quests, and scheduled recovery.
// Everything that hangs off a character id. An NPC's id is derived from its
// name, so without this a deleted "Cave Orc" would hand its inventory, dice,
// standing and death count to the next NPC of the same name.
function purgeSubjectRecords(gid, id) {
  const counts = {};
  for (const [table, col] of [['inventory', 'user_id'], ['roll_tally', 'user_id'],
                              ['renown_log', 'user_id'], ['lore', 'user_id'],
                              ['deaths', 'subject_id'], ['quest_members', 'user_id'],
                              ['quest_summaries', 'user_id'], ['heal_charges', 'user_id'],
                              ['subject_titles', 'subject_id'], ['subject_assocs', 'subject_id']]) {
    try { counts[table] = db.prepare(`DELETE FROM ${table} WHERE guild_id=? AND ${col}=?`).run(gid, id).changes; }
    catch { counts[table] = 0; }
  }
  try { counts.history = db.prepare('DELETE FROM history WHERE guild_id=? AND user_id=?').run(gid, id).changes; }
  catch { counts.history = 0; }
  return counts;
}

// A typed message has no ephemeral reply, so a death refusal goes by DM where
// possible: being told your character is dead in front of the table, every time
// you forget, is its own small punishment.
async function replyQuietly(message, content) {
  try { await message.author.send(content); return true; }
  catch { await message.reply(content).catch(()=>{}); return false; }
}

// The refusal a dead character gets, whoever they are. NPCs could still speak,
// roll and fight after being killed — only player sheets were ever checked.
function deathGate(gid, id) {
  const subject = pageSubject(gid, id);
  if (!subject?.died_at) return null;
  const fell = `<t:${Math.floor(Number(subject.died_at) / 1000)}:R>`;
  return isNpcFighter(id)
    ? `🕯️ **${subject.name}** fell ${fell} and takes no further part. \`/gm revive npc:${subject.name}\` brings them back.`
    : `🕯️ **${subject.displayName ?? 'That character'}** fell ${fell} and can no longer act. A GM can bring them back with \`/gm revive\`.`;
}

function isFallen(gid, id) {
  return !!pageSubject(gid, id)?.died_at;
}

function sheetGate(gid, uid) {
  const ch = getChar(gid, uid);
  if (!ch) return null;                            // "no sheet" handled by callers
  // The fallen take no more actions until a GM says otherwise.
  if (ch.died_at) return '🕯️ Your character has fallen. A GM can bring them back with `/gm revive`.';
  if (sheetApproved(gid, ch)) return null;         // single source of truth
  if (ch.approval_state === 'pending') return '⏳ Your character sheet is **awaiting GM approval** — you can\'t roll or fight until it\'s approved.';
  return '🚫 Your character sheet was **rejected** by a GM.'
    + (ch.approval_reason ? `\n💬 **Reason:** ${ch.approval_reason}` : '')
    + '\nFix it with `/char set` or `/char create` and it goes straight back for another look — or `/char submit` to send it again unchanged.';
}
// ── Character sheet exports ───────────────────────────────────────────────────
// With approvals on, /char export doesn't hand the sheet straight back. The
// export block goes to the approval channel for a GM to read, and the player
// only receives it once a GM presses Release. This is deliberately separate from
// sheet approval: exporting is not a sheet edit, so it never touches
// approval_state and never stops anyone rolling. One live request per player —
// a new export supersedes the last, the same way a re-submitted sheet does.
function setExportRequest(gid, uid, payload, fmt, srcChannel) {
  db.prepare(`INSERT INTO export_requests (guild_id, user_id, payload, fmt, src_channel, msg_id, requested_at)
              VALUES (?,?,?,?,?,NULL,?)
              ON CONFLICT(guild_id, user_id) DO UPDATE SET
                payload=excluded.payload, fmt=excluded.fmt, src_channel=excluded.src_channel,
                msg_id=NULL, requested_at=excluded.requested_at`)
    .run(gid, uid, payload, fmt || 'text', srcChannel || null, Date.now());
}
function getExportRequest(gid, uid) {
  return db.prepare('SELECT * FROM export_requests WHERE guild_id=? AND user_id=?').get(gid, uid);
}
function getImportRequest(gid, uid) {
  return db.prepare('SELECT * FROM import_requests WHERE guild_id=? AND user_id=?').get(gid, uid);
}
function setImportRequest(gid, uid, payload, srcChannel) {
  db.prepare(`INSERT INTO import_requests (guild_id, user_id, payload, src_channel, requested_at)
              VALUES (?,?,?,?,?)
              ON CONFLICT(guild_id, user_id) DO UPDATE SET payload=excluded.payload,
                src_channel=excluded.src_channel, msg_id=NULL, ch_id=NULL, requested_at=excluded.requested_at`)
    .run(gid, uid, JSON.stringify(payload), srcChannel, Date.now());
}
function setImportRequestMsg(gid, uid, msgId, chId) {
  db.prepare('UPDATE import_requests SET msg_id=?, ch_id=? WHERE guild_id=? AND user_id=?').run(msgId, chId, gid, uid);
}
function clearImportRequest(gid, uid) {
  db.prepare('DELETE FROM import_requests WHERE guild_id=? AND user_id=?').run(gid, uid);
}

function setExportRequestMsg(gid, uid, msgId, chId = null) {
  db.prepare('UPDATE export_requests SET msg_id=?, ch_id=? WHERE guild_id=? AND user_id=?').run(msgId, chId, gid, uid);
}
function clearExportRequest(gid, uid) {
  db.prepare('DELETE FROM export_requests WHERE guild_id=? AND user_id=?').run(gid, uid);
}
function exportButtons(uid) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`exportok:${uid}`).setLabel('Release to player').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`exportno:${uid}`).setLabel('Decline').setStyle(ButtonStyle.Danger),
  );
}

// Post an export request to the approval channel. Returns the channel id, or
// null if it couldn't be delivered.
async function requestSheetExport(interaction, gid, uid, payload, fmt) {
  const chId = approvalDestination(gid, 'exports');
  if (!chId) return null;
  const nm = await getDisplayName(interaction.guild, uid);
  const roles = getGmRoleIds(gid);
  const ping = roles.length ? roles.map(r => `<@&${r}>`).join(' ') + ' ' : '';
  const prev = getExportRequest(gid, uid);
  setExportRequest(gid, uid, payload, fmt, interactionChannelId(interaction));
  const head = [
    `${ping}📤 **Sheet export requested**`,
    `👤 <@${uid}> (**${nm}**)${fmt !== 'text' ? '  ·  🖼️ image requested' : ''}`,
    '─────────────────────────────',
    'Release sends this to the player; decline and they get nothing.',
  ].join('\n');
  try {
    const channel = await approvalChannelFor(interaction.client, gid, 'exports');
    // Retire the player's previous request so only one is live at a time —
    // in whichever channel it was actually posted to.
    if (prev?.msg_id) {
      try {
        const oldCh = (prev.ch_id && prev.ch_id !== channel.id)
          ? await wakeThread(await interaction.client.channels.fetch(prev.ch_id)) : channel;
        const old = await oldCh.messages.fetch(prev.msg_id);
        await old.edit({ content: `~~📤 Export request from <@${uid}>~~\n↩️ *Superseded — they exported again; see the newer request below.*`, components: [] });
      } catch {}
    }
    // The block can be long, so the request header and the sheet go separately
    // and the buttons ride on the last message.
    await channel.send({ content: head, allowedMentions: { roles } });
    const msg = await channel.send({
      content: payload.length > 1900
        ? payload.slice(0, 1820) + '\n…\n_✂️ trimmed here — the player receives the whole thing on release._'
        : payload,
      components: [exportButtons(uid)], allowedMentions: { parse: [] } });
    setExportRequestMsg(gid, uid, msg.id, channel.id);
    return channel.id;
  } catch { clearExportRequest(gid, uid); return null; }
}

function approvalButtons(uid) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`sheetok:${uid}`).setLabel('Approve').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`sheetno:${uid}`).setLabel('Reject').setStyle(ButtonStyle.Danger),
  );
}
// Post an approval request to the configured channel, pinging every GM role.
// `src` is anything with .client / .guild / .channelId — a ChatInputInteraction
// or a plain Message, since sheets arrive by slash command and by paste.
async function requestSheetApproval(src, gid, uid, submitMessageId = null) {
  const chId = approvalDestination(gid, 'sheets');
  if (!chId) return null;
  const ch = getChar(gid, uid);
  if (!ch) return null;
  const nm = await getDisplayName(src.guild, uid);
  const roles = getGmRoleIds(gid);
  const ping = roles.length ? roles.map(r => `<@&${r}>`).join(' ') + ' ' : '';
  const lines = [
    `${ping}📋 **Sheet approval requested**`,
    `👤 <@${uid}> (**${nm}**)`,
    '─────────────────────────────',
    `💪 STR ${ch.str ?? 0}   🛡️ CON ${ch.con ?? 0}   ⚡ DEX ${ch.dex ?? 0}`,
    `🦉 WIS ${ch.wis ?? 0}   🍀 LCK ${ch.lck ?? 0}`,
    `❤️ HP ${ch.hp_current ?? 0} / ${maxHp(ch, gid)}   🔄 Rerolls ${ch.rerolls_current ?? 0} / ${maxRerolls(ch)}`,
    ch.order_name ? `${KNIGHT_EMOJIS[ch.order_name] ?? '⚪'} ${ch.order_name}` : null,
    ch.class ? `🎖️ ${ch.class}` : null,
    (ch.weapon1 || ch.weapon2) ? `⚔️ ${[ch.weapon1, ch.weapon2].filter(Boolean).join(' · ')}` : null,
  ].filter(Boolean);
  // Jump link back to where the sheet was submitted, so a GM can see the context.
  const srcCh = interactionChannelId(src);
  // Works for any channel a sheet can be posted in — text, thread, forum post,
  // announcement, or the text chat inside a voice or stage channel.
  upsertChar(gid, uid, { approval_src_channel: srcCh || null, approval_requested_at: Date.now() });
  let jumpId = submitMessageId;
  if (!jumpId && typeof src.fetchReply === 'function') {
    try { const rep = await src.fetchReply(); jumpId = rep?.id ?? null; } catch {}
  }
  if (srcCh && jumpId) lines.push(`\n[↗ Jump to submission](https://discord.com/channels/${gid}/${srcCh}/${jumpId})`);
  try {
    const channel = await approvalChannelFor(src.client, gid, 'sheets');
    // Editing a pending sheet re-queues it. Retire the previous request so the
    // channel holds one live entry per player instead of a pile of stale ones
    // with working buttons.
    const oldId = ch.approval_msg_id;
    if (oldId) {
      try {
        const oldCh = (ch.approval_ch_id && ch.approval_ch_id !== channel.id)
          ? await wakeThread(await src.client.channels.fetch(ch.approval_ch_id)) : channel;
        const old = await oldCh.messages.fetch(oldId);
        await old.edit({ content: `~~📋 Sheet approval request for <@${uid}>~~\n↩️ *Superseded — they edited the sheet again; see the newer request below.*`, components: [] });
      } catch {}
    }
    const msg = await channel.send({ content: lines.join('\n'), components: [approvalButtons(uid)],
      allowedMentions: { roles } });
    upsertChar(gid, uid, { approval_msg_id: msg.id, approval_ch_id: channel.id, approval_post_ok: 1 });
    return channel.id;
  } catch (err) {
    // The sheet stays pending either way — the player is locked out, so a
    // failure here must never be silent. Flagged for /config channels approvals list.
    console.error('[approvals] could not post request for', uid, '-', err?.message || err);
    upsertChar(gid, uid, { approval_post_ok: 0 });
    return null;
  }
}

// Does this edit put the sheet (back) in the approval queue? Any change a player
// makes to their OWN sheet does, while approvals are on. Without this, /char set,
// /char profile load and a pasted sheet were each a way to build a character the GMs
// never saw: they only checked the edit *lock*, which lets a sheet with no
// approval_state through, and nothing ever moved it to 'pending'.
// Every sheet still waiting on a GM, oldest first — the record of truth behind
// /config channels approvals list:true.
function listPendingSheets(gid) {
  return db.prepare(`SELECT user_id, approval_requested_at, approval_src_channel, approval_post_ok
                     FROM characters WHERE guild_id=? AND approval_state='pending'
                     ORDER BY COALESCE(approval_requested_at, 0) ASC`).all(gid);
}

function sheetNeedsResubmit(gid, callerId, targetId, isGmCaller) {
  if (!approvalEnabled(gid)) return false;   // feature off
  if (isGmCaller) return false;              // GM edits are sign-off in themselves
  return targetId === callerId;              // players editing someone else is already blocked
}

// Shared tail for every player-writable sheet edit. `reply` posts the message and
// returns it (or null) so the approval post can link back. Set link:false when
// the reply is ephemeral — a jump link to it would be dead for the GM.
async function finishSheetEdit({ src, gid, callerId, targetId, isGmCaller, content, reply, link = true }) {
  if (!sheetNeedsResubmit(gid, callerId, targetId, isGmCaller)) {
    // A GM building a sheet from nothing shouldn't leave it looking like a
    // pre-feature legacy sheet — approve it outright, as /char create does.
    if (approvalEnabled(gid) && isGmCaller && !getChar(gid, targetId)?.approval_state) {
      upsertChar(gid, targetId, { approval_state: 'approved' });
    }
    return reply(content);
  }
  // /char set writes freely within the ceiling, so a sheet can sit part-spent.
  // It just can't reach the GMs that way — hold it back and say what's missing.
  const short = sheetSubmissionProblems(gid, getChar(gid, targetId));
  if (short.length) {
    const note = statBudgetReply(gid, short, getChar(gid, targetId)) + '\n_Saved, but not sent to the GMs yet._';
    const out = await reply(content + '\n\n' + note);
    // `link: false` marks a caller whose reply is ephemeral (/char profile load).
    // The refusal belongs where they're working, so post it there as well.
    let inChannel = out;
    if (!link) {
      try {
        const ch = src.channel ?? await src.client.channels.fetch(interactionChannelId(src));
        if (ch?.send) inChannel = await ch.send({ content: `<@${targetId}> ${note}`, allowedMentions: { users: [targetId] } });
      } catch {}
    }
    // Same event as an outright refusal — copy it to the GMs with a jump link.
    await refuseStatBudget({ src, gid, uid: targetId, problems: short, stats: getChar(gid, targetId),
      jumpId: inChannel?.id ?? null, reply: async () => inChannel });
    return out;
  }
  upsertChar(gid, targetId, { approval_state: 'pending', approval_reason: null });
  const chId = approvalDestination(gid, 'sheets');
  const sent = await reply(content + (chId
    ? `\n\n⏳ **Sent to <#${chId}> for GM approval.** You can't roll or fight until it's signed off. Spotted a mistake? Edit it and it goes back to the front of the queue.\n📬 You'll get a DM as soon as they do.`
    : '\n\n⚠️ No approval channel set — ask a GM to check `/config channels approvals`.'));
  const posted = await requestSheetApproval(src, gid, targetId, link ? (sent?.id ?? null) : null);
  if (!posted) await warnApprovalUnreachable(src, gid, targetId);
  return sent;
}

// The queue post didn't land — the sheet is pending, so the player can't roll and
// no GM has been told. Ping the GM roles where the sheet was actually submitted
// so it's tracked somewhere, whatever kind of channel that is.
async function warnApprovalUnreachable(src, gid, uid) {
  const roles = getGmRoleIds(gid);
  const ping = roles.length ? roles.map(r => `<@&${r}>` ).join(' ') + ' ' : '';
  const chId = approvalDestination(gid, 'sheets');
  const text = `${ping}⚠️ **A sheet is waiting for approval but I couldn't post it to ${chId ? `<#${chId}>` : 'the approval channel'}.**\n`
    + `👤 <@${uid}> is locked out until a GM decides.\n`
    + `Check I can **View Channel** and **Send Messages** there, then see \`/config channels approvals list:true\`.`;
  try {
    const ch = src.channel ?? await src.client.channels.fetch(interactionChannelId(src));
    if (ch?.send) await ch.send({ content: text, allowedMentions: { roles } });
  } catch (err) { console.error('[approvals] fallback warning failed:', err?.message || err); }
}

// ── Hero signature stat ───────────────────────────────────────────────────────
// A Hero (GM-assigned class) may have one designated stat with 5+ points. Rolls
// using that stat are made with advantage. The 5-point floor is checked live, so
// if the stat later drops below 5 the advantage simply stops applying.
const SIGNATURE_MIN = 5;
function isHero(row) {
  // The flag is authoritative; the old class value is still honoured so a sheet
  // written before the change keeps working if the backfill never ran.
  return !!row?.is_hero || String(row?.class || '').toLowerCase() === 'hero';
}

// ── Duels ────────────────────────────────────────────────────────────────────
// A player raises a challenge, others attach themselves, and when the opener is
// happy it goes to the GMs as one message. Nothing starts a fight until a GM
// says so.
const DUEL_LIVE = ['open', 'pending'];

function openDuelFor(gid, uid) {
  return db.prepare(`SELECT * FROM duels WHERE guild_id=? AND opener=? AND state IN ('open','pending')`).get(gid, uid);
}
function getDuel(gid, id) {
  return db.prepare('SELECT * FROM duels WHERE guild_id=? AND id=?').get(gid, id);
}
function setDuel(gid, id, fields) {
  const keys = Object.keys(fields || {});
  if (keys.length) db.prepare(`UPDATE duels SET ${keys.map(k => `${k}=?`).join(',')} WHERE guild_id=? AND id=?`)
    .run(...keys.map(k => fields[k]), gid, id);
  return getDuel(gid, id);
}
const duelFighters = (d) => { try { return JSON.parse(d?.fighters || '[]'); } catch { return []; } };

// Is this player already committed to a duel someone else opened?
function duelElsewhere(gid, uid, exceptId = null) {
  const rows = db.prepare(`SELECT * FROM duels WHERE guild_id=? AND state IN ('open','pending')`).all(gid);
  return rows.find(d => d.id !== exceptId && duelFighters(d).includes(uid)) || null;
}

async function renderDuel(guild, d) {
  const names = [];
  for (const uid of duelFighters(d)) names.push(`<@${uid}>`);
  const lines = [
    `⚔️ **Duel** — raised by <@${d.opener}>`,
    d.terms ? `📜 ${d.terms}` : '_No terms set._',
    '',
    names.length ? `**Standing in:** ${names.join(' · ')}` : '_Nobody has stepped up yet._',
  ];
  if (d.state === 'pending') lines.push('', '⏳ _With the GMs._');
  if (d.state === 'approved') lines.push('', '✅ _Approved._');
  if (d.state === 'declined') lines.push('', `🚫 _Declined${d.reason ? ` — ${d.reason}` : ''}._`);
  if (d.state === 'cancelled') lines.push('', '↩️ _Withdrawn._');
  return lines;
}

function duelButtons(d) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  if (d.state !== 'open') return [];
  const many = duelFighters(d).length >= 2;
  return [new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`dueljoin:${d.id}`).setLabel('Stand in').setStyle(ButtonStyle.Primary),
    new ButtonBuilder().setCustomId(`duelout:${d.id}`).setLabel('Step out').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId(`duelsend:${d.id}`).setLabel(many ? 'Send to the GMs' : 'Send (needs 2)')
      .setStyle(ButtonStyle.Success).setDisabled(!many),
    new ButtonBuilder().setCustomId(`duelcancel:${d.id}`).setLabel('Withdraw').setStyle(ButtonStyle.Danger),
  )];
}

// Redraw the proposal in place, so the post is always current.
async function refreshDuel(client, guild, d) {
  if (!d?.msg_id) return;
  try {
    const ch = await client.channels.fetch(d.channel_id);
    const msg = await ch.messages.fetch(d.msg_id);
    const lines = await renderDuel(guild, d);
    await msg.edit({ content: lines.join('\n'), components: duelButtons(d), allowedMentions: { parse: [] } });
  } catch (err) { console.error('[duel] could not refresh:', err?.message || err); }
}

// ── Character pages (forum) ──────────────────────────────────────────────────
function getCharPage(gid, uid) {
  return db.prepare('SELECT * FROM char_pages WHERE guild_id=? AND user_id=?').get(gid, uid);
}
function setCharPage(gid, uid, threadId, url, title) {
  db.prepare(`INSERT INTO char_pages (guild_id,user_id,thread_id,url,title,at) VALUES (?,?,?,?,?,?)
              ON CONFLICT(guild_id,user_id) DO UPDATE SET thread_id=excluded.thread_id,
              url=excluded.url, title=excluded.title, at=excluded.at`)
    .run(gid, uid, threadId, url, title, Date.now());
}
function clearCharPage(gid, uid) {
  db.prepare('DELETE FROM char_pages WHERE guild_id=? AND user_id=?').run(gid, uid);
}
// A link to hang off a sheet, or nothing if they have no page.
function charPageLink(gid, uid, label = 'Character page') {
  const pg = getCharPage(gid, uid);
  return pg?.url ? `[${label}](${pg.url})` : null;
}

// Create the forum post for a character, or move an existing one's link along.
// Best-effort by design: a missing forum, a lost permission or a locked channel
// should never stop a sheet being approved.
// The eight knight orders — Kalidale Guard is a force, not an order, and
// Siege Knight is a class; neither wears an order tag.
const CHAR_TAG_ORDERS = ['White Knight','Black Knight','Gold Knight','Grey Knight','Blue Knight','Purple Knight','Green Knight','Red Knight'];
const CHAR_TAG_CLASSES = ['Vanguard','Defender','Siege Knight'];
const CHAR_TAG_FALLEN = 'Fallen';
const CHAR_TAG_HERO = 'Hero';
// T's exact wording, posted after the blocks in every character thread.
const CHAR_THREAD_NOTICE = 'If you would like to adjust your lore doc please contact a Moderator or Expeditioner. Thank you!';

// Every filterable label the character forum carries: 8 + 3 + 1 = 12 of
// Discord's 20. Additive — never removes a tag someone added by hand.
// The three living blocks below the sheet. Same voice as /char show, so a
// thread reads like the sheet command frozen in amber and kept honest.
function charInvBody(gid, uid) {
  const items = listItems(gid, uid);
  if (!items.length) return '🎒 **Inventory** — empty.';
  return ['🎒 **Inventory**', ...items.map(i =>
    `\`#${i.id}\` **${i.item}**${i.note ? ` — ${i.note}` : ''}${i.source ? `  _(${i.source})_` : ''}`)].join('\n').slice(0, 1900);
}
function charLoreBody(gid, uid) {
  const rows = db.prepare("SELECT body FROM lore WHERE guild_id=? AND user_id=? AND state='approved' ORDER BY submitted_at").all(gid, uid);
  // The in-bot lore stays a SHORT INTRO; the full story lives in the doc,
  // which gets its own titled section beneath (T's shape).
  const parts = rows.length
    ? ['📖 **Lore**', ...rows.map(r => r.body)]
    : ['📖 **Lore** — none approved yet.'];
  const doc = getChar(gid, uid)?.lore_doc_url;
  if (doc) parts.push('📄 **Lore doc**\n' + doc);
  return parts.join('\n\n').slice(0, 1900);
}
function charStandingBody(gid, uid) {
  const merits = getMerits(gid, uid), renown = getRenown(gid, uid);
  const lines = [`🏅 **Standing** — **${merits}** merit${merits === 1 ? '' : 's'} · **${renown}** renown`];
  const rows = db.prepare('SELECT delta, reason FROM renown_log WHERE guild_id=? AND user_id=? ORDER BY at DESC LIMIT 8').all(gid, uid);
  for (const r of rows) lines.push(`${r.delta > 0 ? '+' : ''}${r.delta}${r.reason ? ` — ${r.reason}` : ''}`);
  if (rows.length) lines.splice(1, 0, '');
  return lines.join('\n').slice(0, 1900);
}

function charRollsBody(gid, uid) {
  const rows = db.prepare('SELECT sides, nat, count FROM roll_tally WHERE guild_id=? AND user_id=?').all(gid, uid);
  const per = {};
  for (const r of rows) {
    const p = per[r.sides] ??= { total: 0, sum: 0, low: 0, high: 0 };
    p.total += r.count;
    p.sum += r.nat * r.count;
    if (r.nat === 1) p.low += r.count;
    if (r.nat === r.sides) p.high += r.count;
  }
  // The standard ladder always shows, in T's order, rolled or not; any
  // exotic die that has actually been rolled joins below it.
  const LADDER = [2, 4, 6, 8, 10, 12, 20];
  const extras = Object.keys(per).map(Number).filter(x => !LADDER.includes(x)).sort((a, b) => a - b);
  // Die as a heading, its line beneath, a blank between — the stanza
  // layout T asked for rather than one row per die.
  const lines = ['\u{1F3B2} **Dice**', ''];
  for (const sides of [...LADDER, ...extras]) {
    const p = per[sides];
    lines.push(`**d${sides}**`);
    if (!p) lines.push('no rolls yet');
    else {
      const avg = (p.sum / p.total).toFixed(1);
      lines.push(`**${p.total}** rolled \u00b7 avg **${avg}** \u00b7 🔴 nat 1 \u00d7${p.low} \u00b7 🟡 nat ${sides} \u00d7${p.high}`);
    }
    lines.push('');
  }
  return lines.join('\n').trimEnd().slice(0, 1900);
}

async function ensureCharTags(forum) {
  const fresh = await forum.fetch().catch(() => forum);
  const have = fresh.availableTags || [];
  const wanted = [...CHAR_TAG_ORDERS, ...CHAR_TAG_CLASSES, CHAR_TAG_FALLEN, CHAR_TAG_HERO];
  const missing = wanted.filter(w => !have.some(t => t.name.toLowerCase() === w.toLowerCase()));
  if (missing.length && have.length + missing.length <= 20) {
    await forum.setAvailableTags([...have, ...missing.map(name => ({ name: name.slice(0, 20) }))]).catch(() => {});
  }
  const map = {};
  for (const t of (await forum.fetch().catch(() => forum)).availableTags || []) map[t.name.toLowerCase()] = t.id;
  return map;
}

// The sheet a character's thread starts with — the character-side twin of
// npcPageBody, edited in place forever after.
function charPageBody(gid, ch, displayName) {
  const rules = rulesFor(gid);
  const lines = [`📜 **${displayName}**${ch.order_name ? ` — ${KNIGHT_EMOJIS[ch.order_name] ?? ''} ${ch.order_name}` : ''}${ch.char_class ? ` · ${ch.char_class}` : ''}`];
  if (isFallen(gid, ch.user_id)) lines.push(`⚰ **Fallen** — awaiting \`/gm revive\``);
  lines.push(`❤ HP **${ch.hp_current ?? 0}${ch.max_hp ? ` / ${ch.max_hp}` : ''}**`);
  const st = ['str','con','dex','wis','lck'].map(k => `${k.toUpperCase()} **${ch[k] ?? 0}**`).join(' · ');
  lines.push(st);
  lines.push(`🔄 Rerolls **${ch.rerolls_current ?? 0}** / ${maxRerolls(ch)}`);
  if (isWhiteKnight(ch)) {
    const maxC = getConfig(gid)?.heal_charges ?? 3;
    lines.push(`🛡 Heal **${getHealCharges(gid, ch.user_id, maxC).current ?? 0}** / ${maxC}`);
  }
  lines.push(`_This sheet updates itself. To adjust your lore, ask a Moderator or Expeditioner._`);
  return lines.join('\n');
}

async function ensureCharPage(client, guild, uid, displayName, scope = 'sheet') {
  const gid = guild.id;
  // GMs route to their own GM-only forum when one is set; with none set,
  // their privacy is absence, exactly as before.
  const gmUser = await isGm(guild, uid).catch(() => false);
  const forumId = gmUser ? (getConfig(gid)?.gm_char_forum ?? null) : getConfig(gid)?.char_forum;
  if (!forumId) {
    if (gmUser) {
      const ex0 = getCharPage(gid, uid);
      if (ex0?.thread_id) {
        const th0 = await client.channels.fetch(ex0.thread_id).catch(() => null);
        if (th0?.isThread?.()) await th0.delete('GM sheets are private').catch(() => {});
        clearCharPage(gid, uid);
      }
      return { skipped: 'gm-private' };
    }
    return { skipped: 'no forum set' };
  }
  const forum = await client.channels.fetch(forumId);
  if (!forum?.threads?.create) throw new Error('that channel is not a forum');
  displayName = displayName || await getDisplayName(guild, uid).catch(() => null) || 'Adventurer';


  // Mirror-grade now, the NPC forum's twin: the starter message IS the
  // sheet, edited in place; tags are order + class + Fallen; the thread
  // renames with them. Lore and art posted below are never touched.
  const ch = getChar(gid, uid);
  const tagMap = await ensureCharTags(forum);
  const applied = [];
  if (ch?.order_name && CHAR_TAG_ORDERS.some(o => o.toLowerCase() === ch.order_name.toLowerCase())) {
    const id = tagMap[ch.order_name.toLowerCase()]; if (id) applied.push(id);
  }
  if (ch?.char_class && CHAR_TAG_CLASSES.some(c => c.toLowerCase() === ch.char_class.toLowerCase())) {
    const id = tagMap[ch.char_class.toLowerCase()]; if (id) applied.push(id);
  }
  if (isFallen(gid, uid)) { const id = tagMap[CHAR_TAG_FALLEN.toLowerCase()]; if (id) applied.push(id); }
  if (ch?.is_hero) { const id = tagMap[CHAR_TAG_HERO.toLowerCase()]; if (id) applied.push(id); }
  const body = ch ? charPageBody(gid, ch, displayName) : `\u{1F4DC} **${displayName}** \u2014 no sheet yet.`;

  const existing = getCharPage(gid, uid);
  let thread = existing?.thread_id ? await client.channels.fetch(existing.thread_id).catch(() => null) : null;
  if (thread && !thread.isThread?.()) thread = null;
  // Promotion or demotion moved them between forums: a thread in the wrong
  // one is deleted and rebuilt where they now belong.
  if (thread && thread.parentId !== forum.id) {
    await thread.delete('Sheet moved between forums').catch(() => {});
    clearCharPage(gid, uid);
    thread = null;
  }
  if (!thread) {
    if (existing?.thread_id) clearCharPage(gid, uid);
    thread = await forum.threads.create({
      name: displayName.slice(0, 90),
      message: { content: body, allowedMentions: { parse: [] } },
      appliedTags: applied,
    });
    const url = `https://discord.com/channels/${gid}/${thread.id}`;
    setCharPage(gid, uid, thread.id, url, displayName);
    return { created: true, url };
  }
  await wakeThread(thread);
  if (thread.name !== displayName.slice(0, 90)) await thread.setName(displayName.slice(0, 90)).catch(() => {});
  const haveTags = [...(thread.appliedTags || [])].sort().join(',');
  if (haveTags !== [...applied].sort().join(',')) await thread.setAppliedTags(applied).catch(() => {});
  if (scope === 'all') {
    // The sheet rides the same hash economy as the blocks on sweep passes —
    // an unchanged sheet costs nothing. Event edits below stay immediate.
    const r = await ensureCharBlocks(client, guild, uid, thread, body).catch(() => null);
    return { existing: true, url: existing.url, blocks: r || { edited: 0, failed: 1 } };
  }
  const starter = await thread.messages.fetch(row.message_id || thread.id).catch(() => null);
  if (starter?.editable) await starter.edit({ content: body, allowedMentions: { parse: [] } }).catch(() => {});
  return { existing: true, url: existing.url };
}

// The three blocks below the sheet: created once, then edited only when
// their content hash moves — the hourly sweep's whole economy lives here.
const PACE_MS = 300;
const pace = () => new Promise(r => setTimeout(r, PACE_MS));

// Two menders running at once on the same character each read the row
// before either wrote it, each found the blocks missing, and each posted a
// full set — which is how T's threads ended up with two of everything once
// bootMend joined the hourly sweep (2026-08-19). One mend per character at
// a time; the loser simply skips.
const charMendLocks = new Set();
async function ensureCharBlocks(client, guild, uid, thread, sheetBody = null) {
  const lockKey = `${guild.id}:${uid}`;
  if (charMendLocks.has(lockKey)) return 0;
  charMendLocks.add(lockKey);
  try { return await ensureCharBlocksInner(client, guild, uid, thread, sheetBody); }
  finally { charMendLocks.delete(lockKey); }
}
async function ensureCharBlocksInner(client, guild, uid, thread, sheetBody = null) {
  const gid = guild.id;
  const row = getCharPage(gid, uid);
  if (!row) return;
  const bodies = { ...(sheetBody ? { sheet: sheetBody } : {}), inv: charInvBody(gid, uid), lore: charLoreBody(gid, uid), standing: charStandingBody(gid, uid), titles: charTitlesBody(gid, uid), rolls: charRollsBody(gid, uid), notice: CHAR_THREAD_NOTICE };
  let hashes = {};
  try { hashes = JSON.parse(row.block_hashes || '{}'); } catch {}
  // Order is a contract: Inventory · Lore · Standing · Dice · Notice.
  // Snowflake ids ascend with time, so a thread whose block ids don't
  // ascend in that order (a block deleted and re-sent, or one added by a
  // later build — the mixed-era threads of 2026-08-14) is rebuilt: the
  // bot's block messages are cleared and re-sent in sequence. Player
  // messages and the starter are never touched.
  {
    const seq = ['inv', 'lore', 'standing', 'titles', 'rolls', 'notice']
      .map(k => row[`${k === 'inv' ? 'inv' : k}_msg_id`])
      .filter(Boolean);
    const ordered = seq.every((v, i, a) => i === 0 || BigInt(a[i - 1]) < BigInt(v));
    if (!ordered) {
      for (const mid of new Set(seq)) {
        const m = await thread.messages.fetch(mid).catch(() => null);
        if (m?.author?.id === client.user.id) await m.delete().catch(() => {});
        await pace(150);
      }
      row.inv_msg_id = row.lore_msg_id = row.standing_msg_id = row.titles_msg_id = row.rolls_msg_id = row.notice_msg_id = null;
      hashes = {};
    }
  }
  const crypto = require('crypto');
  const h = (t) => crypto.createHash('sha1').update(t).digest('hex').slice(0, 12);
  let dirtyIds = false;
  const ids = { sheet: row.message_id || thread.id, inv: row.inv_msg_id, lore: row.lore_msg_id, standing: row.standing_msg_id, titles: row.titles_msg_id, rolls: row.rolls_msg_id, notice: row.notice_msg_id };
  // T's order, enforced at creation: Sheet (starter) · Inventory · Lore · Standing · Dice.
  let edited = 0, failed = 0;
  // Titles sit with Standing — both are what a character has earned.
  for (const key of ['sheet', 'inv', 'lore', 'standing', 'titles', 'rolls', 'notice']) {
    if (!(key in bodies)) continue;
    const want = bodies[key], hw = h(want);
    // Unchanged blocks cost zero traffic — except the notice, which is
    // fetched each pass so a hand-stripped button genuinely heals. (The
    // audit caught the old claim: the skip fired before the heal could.)
    if (ids[key] && hashes[key] === hw && key !== 'notice') continue;
    let msg = ids[key] ? await thread.messages.fetch(ids[key]).catch(() => null) : null;
    // The notice carries the lore-doc request button — pressable even in a
    // locked thread, since buttons ignore SendMessages. Self-heals if a
    // hand-edit ever strips it.
    const comp = key === 'notice' ? [(() => {
      const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
      return new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`loredoc:${uid}`).setLabel('📄 Request lore update').setStyle(ButtonStyle.Primary));
    })()] : undefined;
    if (msg?.editable) {
      const needsComp = key === 'notice' && !(msg.components?.length);
      if (hashes[key] !== hw || needsComp) {
        const ok = await msg.edit({ content: want, allowedMentions: { parse: [] }, ...(comp ? { components: comp } : {}) }).then(() => true).catch(() => false);
        ok ? edited++ : failed++;
        await pace();
      }
    }
    else if (key !== 'sheet') {   // a missing starter cannot be re-sent; the thread path rebuilds it
      msg = await thread.send({ content: want, allowedMentions: { parse: [] }, ...(comp ? { components: comp } : {}) }).catch(() => null);
      if (msg) { ids[key] = msg.id; dirtyIds = true; edited++; } else failed++;
      await pace();
    }
    hashes[key] = hw;
  }
  db.prepare('UPDATE char_pages SET inv_msg_id=?, lore_msg_id=?, standing_msg_id=?, titles_msg_id=?, rolls_msg_id=?, notice_msg_id=?, block_hashes=? WHERE guild_id=? AND user_id=?')
    .run(ids.inv, ids.lore, ids.standing, ids.titles, ids.rolls, ids.notice, JSON.stringify(hashes), gid, uid);

  // Duplicates left by an earlier race: the thread is locked to players, so
  // every bot message in it is a block. Anything not currently recorded —
  // and not the starter — is a stray, and goes.
  try {
    const keep = new Set([thread.id, ...Object.values(ids).filter(Boolean)]);
    const recent = await thread.messages.fetch({ limit: 50 }).catch(() => null);
    if (recent) {
      for (const m of recent.values()) {
        if (m.author?.id !== client.user.id || keep.has(m.id)) continue;
        await m.delete().catch(() => {});
        edited++;
        await pace(150);
      }
    }
  } catch {}
  return { edited, failed };
}

// The hourly sweep: every character's blocks reconciled, hash-skipped.
// Sheet edits stay event-live (rare, and players expect to see them);
// dice — the chatty source — only ever lands here.
function startCharBlockSweep(client) {
  const run = async () => {
    let edited = 0, failed = 0;
    for (const [gid, guild] of client.guilds.cache) {
      if (!getConfig(gid)?.char_forum) continue;
      for (const ch of db.prepare('SELECT user_id FROM characters WHERE guild_id=?').all(gid)) {
        const r = await ensureCharPage(client, guild, ch.user_id, null, 'all').catch(() => null);
        edited += r?.blocks?.edited ?? 0; failed += r?.blocks?.failed ?? 0;
      }
    }
    if (edited || failed) console.log(`[char-sweep] ${edited} edit(s) · ${failed} failed`);
  };
  setInterval(() => run().catch(() => {}), 60 * 60 * 1000);
  setTimeout(() => run().catch(() => {}), 90 * 1000);  // first pass shortly after boot
}

// ── Roster ordering ──────────────────────────────────────────────────────────
// Every list of characters reads the same way: Heroes first as their own group,
// then by knight order, then by class, then by name. One comparator so a roster,
// a global heal and an NPC list can't drift into three different orders.
const KNIGHT_ORDER_RANK = Object.keys(KNIGHT_EMOJIS)
  .reduce((m, name, i) => (m[name] = i, m), {});
const CLASS_RANK = { 'Vanguard': 0, 'Defender': 1, 'Siege Knight': 2 };

function rosterKey(row, name, isNpc = false) {
  return {
    // Players and NPCs are separate halves of a list, not interleaved.
    npc: isNpc ? 1 : 0,
    hero: isHero(row) ? 0 : 1,
    order: row?.order_name ? (KNIGHT_ORDER_RANK[row.order_name] ?? 98) : 99,
    cls: row?.class ? (CLASS_RANK[row.class] ?? 98) : 99,
    name: String(name ?? '').toLowerCase(),
  };
}
function compareRoster(a, b) {
  return a.npc - b.npc || a.hero - b.hero || a.order - b.order || a.cls - b.cls || a.name.localeCompare(b.name);
}
// Sort [{ row, name, ... }] into reading order and return it grouped for display.
function groupRoster(entries) {
  const keyed = entries.map(e => ({ ...e, _k: rosterKey(e.row, e.name, !!e.isNpc) }));
  keyed.sort((x, y) => compareRoster(x._k, y._k));
  const groups = [];
  let head = null;
  for (const e of keyed) {
    const inner = e._k.hero === 0 ? '🦸 Heroes'
      : e.row?.order_name ? `${KNIGHT_EMOJIS[e.row.order_name] ?? '⚪'} ${e.row.order_name}`
      : '⬜ No order';
    const label = e._k.npc ? `🎭 NPCs · ${inner}` : inner;
    if (label !== head) { groups.push({ label, rows: [], isNpc: !!e._k.npc }); head = label; }
    groups[groups.length - 1].rows.push(e);
  }
  return groups;
}
// Does this character/NPC row get advantage on `stat` right now?
function hasSignatureAdvantage(row, stat) {
  if (!row || !stat) return false;
  if (!isHero(row)) return false;
  if (String(row.signature_stat || '').toLowerCase() !== String(stat).toLowerCase()) return false;
  return (row[stat] ?? 0) >= SIGNATURE_MIN;
}
// Upgrade a roll mode to advantage when the signature applies. An explicit
// disadvantage from the caller still wins — the two cancel rather than stack.
function applySignatureMode(row, stat, mode) {
  if (mode === 'dis') return mode;
  return hasSignatureAdvantage(row, stat) ? 'adv' : mode;
}

// Optional real @mention when announcing a player's turn (opt-in: /config mechanics fightping).
function turnPing(gid, f) {
  if (!f || f.isNpc || !getConfig(gid)?.fight_ping) return '';
  return ` <@${f.id}>`;
}


// One forum, a thread per kind. The audit shelves and the approval threads
// are the same shape — adopt a surviving thread by id so every link already
// pointing at one stays good, otherwise make it — so they share a builder
// and cannot drift apart.
async function ensureForumThreads(client, gid, { configKey, types, routesOf }) {
  const prev = routesOf(gid) || {};
  if (!prev.forum) return null;
  const forum = await client.channels.fetch(prev.forum).catch(() => null);
  if (!forum || forum.type !== 15) return { error: `<#${prev.forum}> isn't a forum any more.` };
  const routes = { forum: forum.id };
  const made = [], kept = [];
  for (const [key, t] of Object.entries(types)) {
    let thread = null;
    if (prev[key]) {
      try {
        const old = await client.channels.fetch(prev[key]);
        if (old?.isThread?.() && old.parentId === forum.id) { thread = await wakeThread(old); kept.push(t.name); }
      } catch { /* stale — remade below */ }
    }
    if (!thread) {
      thread = await forum.threads.create({ name: t.name, autoArchiveDuration: 10080,
        message: { content: `${t.about}\n_I wake this thread whenever something new arrives — no need to keep it active._` } });
      made.push(t.name);
    }
    routes[key] = thread.id;
  }
  setConfig(gid, { [configKey]: JSON.stringify(routes) });
  return { made, kept };
}

const ensureAuditBooks = (client, gid) =>
  ensureForumThreads(client, gid, { configKey: 'audit_routes', types: AUDIT_KINDS, routesOf: auditRoutes });
const ensureApprovalThreads = (client, gid) =>
  ensureForumThreads(client, gid, { configKey: 'approval_routes', types: APPROVAL_TYPES, routesOf: approvalRoutes });

// The same for the quest pipeline's books.
async function ensureQuestBooks(client, guild, gid) {
  const forumId = getConfig(gid)?.quest_plan_forum;
  if (!forumId) return null;
  const forum = await client.channels.fetch(forumId).catch(() => null);
  if (!forum || forum.type !== 15) return { error: `<#${forumId}> isn't a forum any more.` };
  const prev = questBooks(gid);
  const map = {}, made = [], kept = [];
  for (const [bkey, emoji, label, about] of QUEST_BOOKS) {
    let thread = null;
    if (prev[bkey]) {
      try {
        const old = await client.channels.fetch(prev[bkey]);
        if (old?.isThread?.() && old.parentId === forum.id) { thread = await wakeThread(old); kept.push(label); }
      } catch { /* stale — remade below */ }
    }
    if (!thread) {
      thread = await forum.threads.create({ name: `${emoji} ${label}`, autoArchiveDuration: 10080,
        message: { content: `${emoji} **${label}**\n${about}\n_I wake this book whenever something new arrives — no need to keep it active._` } });
      await thread.pin().catch(() => {});
      made.push(label);
    }
    map[bkey] = thread.id;
  }
  setConfig(gid, { quest_plan_books: JSON.stringify(map), quest_dm_thread: map.dms });
  await refreshDmRoster(client, guild, gid);
  return { made, kept };
}

// ── Audit routing ────────────────────────────────────────────────────────────
// One forum, a thread per book — configured by /config channels rollauditforum, stored
// as JSON in guild_config.audit_routes. The single audit channel remains the
// per-book fallback, so a server without the forum behaves exactly as before.
const AUDIT_KINDS = {
  players: { name: '🎲 Player Rolls', about: 'Every roll a player makes — typed, slash, heals, fights, activities.' },
  gms:     { name: '🛡️ GM Rolls',     about: 'Rolls GMs make as themselves — secret `gmrs` rolls included.' },
  npcs:    { name: '🎭 NPC Rolls',    about: 'NPC dice — GM-driven and auto-pilot alike.' },
  say:     { name: '💬 NPC Say',      about: 'Who spoke as which NPC, with a jump to the line.' },
  scrolls: { name: '📜 Scrolls',      about: 'Every prop, both directions — the writing, the parchment, the woven PDF; unfurlings and read-backs alike.' },
  checks:  { name: '🎯 Called Checks', about: 'Every `/gm dc`: the call, who rolled what against it, and what it cost them.' },
  gmacts:  { name: '⚖️ GM Overrides', about: 'Corrections and decrees — rerolls granted, stats shifted, HP set, marks imposed.' },
  duels:   { name: '🤺 Duels',         about: 'Challenges, who stood in, the GM\'s verdict and the reason given.' },
  ranks:   { name: '🎖️ Advancement',   about: 'Merit awarded and rank earned — who granted it, and when.' },
  fallen:  { name: '🕯️ The Fallen',    about: 'Deaths and returns, in the order they happened.' },
  items:   { name: '🧳 Items',         about: 'Who gave what to whom — and who took it away again.' },
};
// Where scroll records go: a manually configured channel overrides; else the
// audit forum's 📜 Scrolls book; else nowhere. Threads are woken on the way.
// FORUM MODE: point the config at a forum and each GM gets their own 📜
// thread, opened on first use — pass gmId so the scroll files under its GM.
async function scrollArchiveChannel(client, gid, gmId = null) {
  const id = getConfig(gid)?.scroll_archive_id ?? auditRoutes(gid)?.scrolls ?? null;
  if (!id) return null;
  const ch = await client.channels.fetch(id);
  const { ChannelType } = require('discord.js');
  if (ch?.type === ChannelType.GuildForum) return ensureScrollThread(client, gid, ch, gmId);
  return ch?.isThread?.() ? wakeThread(ch) : ch;
}

// One thread per GM in the archive forum, keyed by id (names change), the
// map self-healing: a stored thread that's gone — or living in some OTHER
// forum after a config swap — is re-created here.
async function ensureScrollThread(client, gid, forum, gmId) {
  const key = gmId || '_shared';
  let map = {};
  try { map = JSON.parse(getConfig(gid)?.scroll_threads || '{}') || {}; } catch {}
  const tid = map[key];
  if (tid) {
    const th = await client.channels.fetch(tid).catch(() => null);
    if (th && th.parentId === forum.id) return wakeThread(th);
  }
  let label = '📜 Archive';
  if (gmId) {
    try { label = `📜 ${await getDisplayName(await client.guilds.fetch(gid), gmId)}`; } catch { label = `📜 GM ${gmId.slice(-4)}`; }
  }
  const thread = await forum.threads.create({
    name: label.slice(0, 100), autoArchiveDuration: 10080,
    message: { content: gmId
      ? `📜 The scrolls of <@${gmId}> — every prop they unfurl or read back files here.`
      : '📜 The shared archive — scrolls without a named hand file here.' },
  });
  map[key] = thread.id;
  setConfig(gid, { scroll_threads: JSON.stringify(map) });
  return thread;
}

function auditRoutes(gid) {
  const raw = getConfig(gid)?.audit_routes;
  if (!raw) return null;
  try { const o = JSON.parse(raw); return o && typeof o === 'object' ? o : null; }
  catch { return null; }
}
// Every ledger entry goes through here: resolve the shelf, wake it, write.
// Decoration-grade throughout — a book that can't be reached must never
// fail the command that fed it.
function bookLog(gid, kind, line, { channelId = null, messageId = null } = {}) {
  // Fire-and-forget by design, like mirrorRoll: a shelf that can't be
  // reached must never delay or fail the command that fed it.
  (async () => {
    try {
      const chId = auditDestination(gid, kind);
      if (!chId) return;
      const ch = await wakeThread(await client.channels.fetch(chId));
      if (!ch) return;
      const link = (channelId && messageId)
        ? `\n[↗ Jump](https://discord.com/channels/${gid}/${channelId}/${messageId})` : '';
      await ch.send({ content: `${line}${link}`.slice(0, 1990), allowedMentions: { parse: [] } });
    } catch (err) { console.error(`[book:${kind}]`, err?.message || err); }
  })();
}

function auditDestination(gid, kind) {
  const r = auditRoutes(gid);
  return (r && r[kind]) || getConfig(gid)?.roll_audit_channel_id || null;
}
// GM-ness by ids alone, for places that have no guild object in hand. Any
// failure answers false: the roll then files under players — the busiest
// book — rather than vanishing.
async function isGmId(gid, uid) {
  try { return await isGm(await client.guilds.fetch(gid), uid); }
  catch { return false; }
}
// One line per spoken NPC message: which GM said it, as whom, where, and a
// jump to the exact line. Only active when a Say thread is routed — with just
// the single audit channel this stays silent, exactly as before the forum.
function mirrorNpcSay(gid, { gmId, npcName, channelId, messageId = null, text }) {
  const dest = auditRoutes(gid)?.say || null;
  if (!dest) return;
  (async () => {
    const ch = await wakeThread(await client.channels.fetch(dest));
    if (!ch) { console.error(`[rollaudit] say fetch returned null for ${dest}`); return; }
    const quote = String(text ?? '').slice(0, 900).replace(/\n/g, '\n> ');
    const link = messageId ? `\n[↗ Jump to the line](https://discord.com/channels/${gid}/${channelId}/${messageId})` : '';
    await ch.send({ content: `💬 <@${gmId}> as **${npcName}** in <#${channelId}>\n> ${quote}${link}`,
      allowedMentions: { parse: [] } });
  })().catch(err => {
    console.error('[rollaudit] say mirror FAILED:', err?.message || err, err?.code ? `(code ${err.code})` : '');
  });
}

function recordRoll(gid, opts) {
  // Tally every die that was physically rolled, not just the one that counted:
  // an advantage roll threw two d20s and both belong in a lifetime history.
  // `result` is the object from rollNotation/rollAdvantage/rollDisadvantage;
  // `nat`/`sides` are the fallback for paths that build a roll line by hand.
  if (opts?.userId) {
    const r = opts.result;
    if (r && Array.isArray(r.rolls) && r.rolls.length) {
      for (const face of r.rolls) tallyRoll(gid, opts.userId, face, r.sides ?? 20);
    } else if (Number.isFinite(opts.nat)) {
      tallyRoll(gid, opts.userId, opts.nat, opts.sides ?? 20);
    }
  }
  mirrorRoll(gid, opts);
}

// Mirror one roll into the audit channel. Every roll goes through here — typed,
// slash, fight, GM, GM-as-NPC and bot-driven auto rolls alike.
//
// `userId` names a human roller; `actor` is used instead for rolls nobody made
// by hand (the NPC auto-pilot). Rolls made inside the audit channel are mirrored
// too: the previous self-skip meant a secret `gmrs` typed in that channel went
// to the GM's DMs and was never recorded anywhere, which is precisely the hole
// the audit exists to close.
function mirrorRoll(gid, { userId = null, actor = null, channelId, messageId = null, input, rollLine, context = null, interaction = null, kind = null, card = null }) {
  const routes = auditRoutes(gid);
  const plain = getConfig(gid)?.roll_audit_channel_id || null;
  // Verbose tracing: a silent mirror is impossible to diagnose otherwise.
  // These lines appear in the Railway logs and pinpoint where it stops.
  if (!routes && !plain) { console.log('[rollaudit] skip — no audit destination configured'); return; }
  let dest = '?';
  (async () => {
    // Which book does the entry belong in? An explicit kind wins (GM-as-NPC
    // fight rolls, /npc rolls); a bot-attributed roll is NPC by definition;
    // otherwise the roller's GM-ness decides.
    const k = kind ?? (actor ? 'npcs' : ((userId && await isGmId(gid, userId)) ? 'gms' : 'players'));
    const chId = auditDestination(gid, k);
    if (!chId) { console.log(`[rollaudit] skip — no destination for '${k}'`); return; }
    dest = `${k} @ ${chId}`;
    console.log(`[rollaudit] attempting mirror → ${dest} (roll from ${channelId})`);
    const ch = await wakeThread(await client.channels.fetch(chId));
    if (!ch) { console.error(`[rollaudit] fetch returned null for ${chId}`); return; }
    // Slash commands: resolve the bot's reply so the audit entry can still link.
    if (!messageId && interaction) {
      try { const rep = await interaction.fetchReply(); messageId = rep?.id ?? null; } catch {}
    }
    const clean = String(input ?? '').replace(/`/g, "'").slice(0, 120);
    const link = messageId ? `\n[↗ Jump to roll](https://discord.com/channels/${gid}/${channelId}/${messageId})` : '';
    const ctx = context ? ` · ${context}` : '';
    const who = userId ? `<@${userId}>` : (actor || '🤖 bot');
    const where = channelId ? ` in <#${channelId}>` : '';
    const cmd = clean ? ` — \`${clean}\`` : '';
    await ch.send({
      // A full reveal card, when one was built, stands in for the bare line.
      content: `🎲 ${who}${where}${ctx}${cmd}\n${card ?? rollLine}${link}`,
      allowedMentions: { parse: [] }, // identity without pinging anyone
    });
    console.log('[rollaudit] mirror sent OK');
  })().catch(err => {
    // Never break the roll itself, but do leave a trace — a silent mirror is
    // impossible to diagnose. Surfaced to the GM by /config channels rollaudit test.
    console.error(`[rollaudit] mirror (${dest}) FAILED:`, err?.message || err, err?.code ? `(code ${err.code})` : '');
  });
}

// Audit entry for a roll the bot made itself — auto-pilot fighters, initiative,
// demo bouts. There's no human to attribute it to, so the fighter is named
// instead and the entry is tagged so a GM can tell it from a hand-rolled one.
function mirrorAutoRoll(gid, cid, name, notation, nat, total, context) {
  // An NPC's dice belong in its own lifetime record, the same as a player's.
  try { if (getNpc(gid, name)) tallyRoll(gid, npcFighterId(name), nat, 20); } catch {}
  const mod = total - nat;
  const modStr = mod > 0 ? ` +${mod}` : (mod < 0 ? ` ${mod}` : '');
  // Auto-mode rolls for players too: those file under the players book. Auto
  // entries stay in line form — the audit copy was never masked, and a full
  // card for every auto exchange would bury the book.
  mirrorRoll(gid, {
    actor: `🤖 **${name}**`, channelId: cid, input: notation,
    kind: getNpc(gid, name) ? 'npcs' : 'players',
    rollLine: `🎲  ${notation} → [${nat}]${modStr} = **${total}**`,
    context: context ? `auto · ${context}` : 'auto',
  });
}

// Split a fighter id list into those able to fight (HP above the floor) and
// those who aren't. `floor` is 0 for a real fight, PRACTICE_FLOOR for a bout.
async function partitionDowned(guild, gid, fighters, floor = 0) {
  const active = [], downed = [];
  for (const fid of fighters) {
    const f = await resolveFighter(guild, gid, fid);
    const cur = f.isNpc ? (getNpc(gid, f.name)?.hp_current ?? 0) : (getChar(gid, fid)?.hp_current ?? 0);
    (cur > floor ? active : downed).push({ fid, name: f.name, isNpc: f.isNpc, hp: cur });
  }
  return { active, downed };
}

// Warning line listing fighters left out for sitting at or below the floor.
function downedWarning(downed, gid, floor = 0) {
  if (!downed.length) return null;
  // Don't print an NPC's exact (negative) HP when NPC stats are hidden.
  const hide = gid ? !npcStatsVisible(gid) : false;
  const names = downed.map(d => `**${d.name}**${d.isNpc ? ' 🎭' : ''}${(d.isNpc && hide) ? '' : ` (❤️ ${d.hp})`}`).join(', ');
  const why = floor > 0 ? `not fit to spar (at or below the ${floor} HP bout floor)` : 'knocked down';
  return `⚠️ Left out — ${why}: ${names}. Restore NPCs with \`/npc hp\`, players with \`hpfull @user\` or a rest.`;
}

// Build the same roll card a manual /fight atk or /fight def produces,
// for an automatic best-stat roll (stat tracker + exact dice breakdown).
async function autoFightCard(guild, gid, fighter, kind, stat, nat, total, targetName, isReroll = false, atkBonus = 0, flat = false, adv = false) {
  const statVal = fighter.stats[stat] ?? 0;
  const icon = kind === 'atk' ? '⚔️' : '🛡️';
  let rollLine;
  if (flat) {
    // Flat d20 defence — no stat, no modifier.
    rollLine = `${icon}  1d20 (flat — fumbled last attack) → [${nat}] = ${fightTotalStr(total, nat, 20)}`;
  } else {
    const eff = statVal + (kind === 'atk' ? atkBonus : 0);
    const bonusTag = (kind === 'atk' && atkBonus) ? ` +${atkBonus} riposte` : '';
    const advTag = adv ? ' ⭐ (signature advantage)' : '';
    // When NPC stats are hidden, don't print the modifier — it would give the
    // exact stat away. The natural die and final total still show.
    const hideMods = fighter.isNpc && !getConfig(gid)?.npc_stats_visible;
    const modStr = hideMods ? '' : (eff > 0 ? ` +${eff}` : eff < 0 ? ` ${eff}` : '');
    const statName = hideMods ? '' : `+${STAT_LABELS[stat]}`;
    rollLine = `${icon}  1d20${statName}${bonusTag}${advTag} → [${nat}]${modStr} = ${fightTotalStr(total, nat, 20)}`;
  }
  const who = `${fighter.name}${fighter.isNpc ? ' 🎭' : ''}`;
  const label = kind === 'atk'
    ? `⚔️ ${who} attacks ${targetName} with ${STAT_LABELS[stat]}`
    : `🛡️ ${who} defends with ${STAT_LABELS[stat]}`;
  const critType = nat === 20 ? 'crit' : (nat === 1 ? 'fail' : null);
  const charCard = await fighterCharCard(guild, gid, fighter.id);
  // The auto loop's rolls for a PLAYER honour their card style too; the
  // wrapper leaves NPC cards full on its own.
  return styledFightCard(gid, fighter.id, {
    rollLine, label, isReroll,
    char: charCard, healCharges: 0, maxCharges: 0,
    flavour: null, total, critType, tags: null, gid,
  });
}

// Give auto-piloted NPCs their reroll moment before an exchange resolves:
// a defender about to be hit, then an attacker who was blocked, may each
// spend one LCK reroll token (seeded per fight) on a fresh roll.
// Returns the up-to-date fight row.
async function applyAutoNpcRerolls(guild, gid, cid, channel) {
  let fight = getFight(gid, cid);
  if (!fight || !fight.auto_npc) return fight;
  const rr = JSON.parse(fight.rr_state || '{}');
  const turnOrder = fightOrder(fight);
  const attackerId = turnOrder[fight.turn_index];
  const defenderId = fight.current_target;
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  const tryReroll = async (fid, kind) => {
    if (!isNpcFighter(fid) || (rr[fid] ?? 0) <= 0) return;
    const f = await resolveFighter(guild, gid, fid);
    const stat = kind === 'atk' ? fight.atk_stat : fight.def_stat;
    // Preserve whatever modifier the ORIGINAL roll used (flat-d20 → 0, riposte → stat+2),
    // since carry-over effects were already consumed when that first roll was made.
    const origTotal = kind === 'atk' ? fight.atk_roll : fight.def_roll;
    const origNat = kind === 'atk' ? fight.atk_nat : fight.def_nat;
    const effMod = origTotal - origNat;
    const isFlat = kind === 'def' && effMod === 0 && (f.stats[stat] ?? 0) !== 0;
    const sigRow = f.isNpc ? getNpc(gid, f.name) : getChar(gid, fid);
    const roll = autoRoll(effMod, !isFlat && hasSignatureAdvantage(sigRow, stat));
    mirrorAutoRoll(gid, cid, f.name, `1d20${roll.adv ? ' (adv)' : ''}`, roll.nat, roll.total,
      `fight ${kind === 'atk' ? 'attack' : 'defence'} reroll`);
    rr[fid] = (rr[fid] ?? 0) - 1;
    // The pool is persistent now: the per-fight state mirrors it, and the
    // spend writes back so rest is what refills, mirroring characters.
    try { const nn = npcNameFromFighter(fid); if (nn) upsertNpc(gid, nn, { rerolls_current: rr[fid] }); } catch {}
    if (kind === 'atk') upsertFight(gid, cid, { atk_roll: roll.total, atk_nat: roll.nat, rr_state: JSON.stringify(rr) });
    else upsertFight(gid, cid, { def_roll: roll.total, def_nat: roll.nat, rr_state: JSON.stringify(rr) });
    bumpFightLog(gid, cid, (log, ensure) => { ensure(fid).rr++; });
    let targetName = null;
    if (kind === 'atk') {
      const tF = await resolveFighter(guild, gid, defenderId);
      targetName = `${tF.name}${tF.isNpc ? ' 🎭' : ''}`;
    }
    await sleep(700);
    await channel.send(`🔁 **${f.name}** 🎭 spends a reroll token! (${rr[fid]} left)`).catch(()=>{});
    const bonus = kind === 'atk' ? Math.max(0, effMod - (f.stats[stat] ?? 0)) : 0;
    const card = await autoFightCard(guild, gid, f, kind, stat, roll.nat, roll.total, targetName, true, bonus, isFlat, !!roll.adv);
    await postAsNpc(channel, gid, f.name, card);
    fight = getFight(gid, cid);
  };

  // Defender reacts first — only when the hit would land AND its natural die was poor (≤ guild threshold)
  const rrMax = getNpcRrThreshold(gid);
  let { hit } = resolveDamage(fight.atk_roll, fight.atk_nat, 20, fight.def_roll, fight.def_nat, 20);
  if (hit && fight.def_nat <= rrMax) await tryReroll(defenderId, 'def');
  // Attacker answers a block — likewise only on a poor natural die
  ({ hit } = resolveDamage(fight.atk_roll, fight.atk_nat, 20, fight.def_roll, fight.def_nat, 20));
  if (!hit && fight.atk_nat <= rrMax) await tryReroll(attackerId, 'atk');
  return getFight(gid, cid);
}

// Resolve a /fight subcommand's target / target_npc pair to a fighter id in
// the given fight, or an error string. Exactly one of the two must be set.
function resolveFightTarget(interaction, gid, fight) {
  const targetUser = interaction.options.getUser('target');
  const targetNpcName = interaction.options.getString('target_npc');
  if (!!targetUser === !!targetNpcName) return { error: '❌ Pick exactly one of `target` or `target_npc`.' };
  let fid;
  if (targetUser) fid = targetUser.id;
  else {
    const npc = getNpc(gid, targetNpcName);
    if (!npc) return { error: `❌ NPC **${targetNpcName}** not found.` };
    fid = npcFighterId(npc.name);
  }
  if (!fightOrder(fight).includes(fid)) return { error: '❌ That fighter is not in this fight.' };
  return { fid };
}

// What a live fight is waiting for from this player, if anything. Lets a custom
// /roll stand in for /fight atk or /fight def, so a GM can call for something
// unusual — 2d6 for a trap, a flat d100 — without the fight chain breaking and
// everyone falling back to rolling by hand.
function fightAwaiting(gid, cid, uid) {
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return null;
  const order = JSON.parse(fight.turn_order || '[]');
  const currentId = order[fight.turn_index];
  if (fight.phase === 'attack') return currentId === uid ? { fight, kind: 'atk' } : null;
  if (fight.phase === 'defend' && fight.def_roll === null) {
    // Grapples and feints have their own answers; a custom roll cannot stand in.
    if (fight.atk_kind) return null;
    return fight.current_target === uid ? { fight, kind: 'def' } : null;
  }
  return null;
}

// Write a custom roll into the fight in place of the usual stat roll. `label`
// stands in for the stat name so the recap still reads sensibly.
function submitFightRoll(gid, cid, kind, { total, nat, sides, label, targetId = null }) {
  if (kind === 'atk') {
    upsertFight(gid, cid, {
      phase: 'defend', current_target: targetId,
      atk_roll: total, atk_nat: nat, atk_stat: label, atk_mode: 'normal', atk_sides: sides,
      def_roll: null, def_nat: null, def_stat: null, def_mode: 'normal',
    });
  } else {
    upsertFight(gid, cid, { def_roll: total, def_nat: nat, def_stat: label, def_mode: 'normal', def_sides: sides });
  }
  return getFight(gid, cid);
}

// ── Fight log & recap ────────────────────────────────────────────────────────
// log_state: {
//   exchanges: n,
//   f: { fid: { dealt, taken, crit, fumble, rr, atk: TALLY, def: TALLY } },
//   r: [ { n, a, d, an, at, as, dn, dt, ds, h, dm } ]   // blow-by-blow
// }
// TALLY = { n, totSum, natHi, natLo } — enough for counts, averages and extremes.
const ROLL_TALLY = () => ({ n: 0, totSum: 0, natHi: 0, natLo: 99 });
const FIGHTER_LOG = () => ({ dealt: 0, taken: 0, crit: 0, fumble: 0, rr: 0, atk: ROLL_TALLY(), def: ROLL_TALLY() });
// Stored exchanges are capped so log_state can't grow without bound on a very
// long auto fight; the summary tallies still cover every exchange.
const ROLL_LOG_MAX = 150;
const ROLL_LOG_SHOW = 40;

function bumpFightLog(gid, cid, mutate) {
  const fight = getFight(gid, cid);
  if (!fight) return;
  const log = JSON.parse(fight.log_state || '{}');
  log.f = log.f || {};
  mutate(log, (fid) => (log.f[fid] = log.f[fid] || FIGHTER_LOG()));
  upsertFight(gid, cid, { log_state: JSON.stringify(log) });
}

// Record one resolved exchange into a log object (shared by DB fights and
// full-auto's in-memory log). `meta` carries the roll detail the recap needs:
// { atkTotal, defTotal, atkStat, defStat }.
function recordExchange(log, ensure, attackerId, defenderId, atkNat, defNat, hit, dmg, meta = {}) {
  log.exchanges = (log.exchanges || 0) + 1;
  const a = ensure(attackerId), d = ensure(defenderId);
  if (atkNat === 20) a.crit++;
  if (atkNat === 1) a.fumble++;
  if (defNat === 20) d.crit++;
  if (defNat === 1) d.fumble++;
  if (hit) { a.dealt += dmg; d.taken += dmg; }

  // Roll tallies, attack and defence kept apart. Seeded defensively so a fight
  // already in progress when this shipped doesn't blow up mid-exchange.
  const tally = (t, nat, total) => {
    t.n++;
    t.totSum += (typeof total === 'number' ? total : (nat || 0));
    if (typeof nat === 'number') {
      if (nat > (t.natHi ?? 0)) t.natHi = nat;
      if (nat < (t.natLo ?? 99)) t.natLo = nat;
    }
  };
  a.atk = a.atk || ROLL_TALLY();
  d.def = d.def || ROLL_TALLY();
  tally(a.atk, atkNat, meta.atkTotal);
  tally(d.def, defNat, meta.defTotal);

  // Blow-by-blow entry.
  log.r = Array.isArray(log.r) ? log.r : [];
  if (log.r.length < ROLL_LOG_MAX) {
    log.r.push({
      n: log.exchanges, a: attackerId, d: defenderId,
      an: atkNat, at: meta.atkTotal ?? null, as: meta.atkStat ?? null,
      dn: defNat, dt: meta.defTotal ?? null, ds: meta.defStat ?? null,
      h: hit ? 1 : 0, dm: hit ? dmg : 0,
    });
  } else {
    log.rTrim = (log.rTrim || 0) + 1;
  }
}

// Render the recap lines for a finished fight: how the dice fell for each
// fighter, the damage ledger, and the full blow-by-blow of every exchange.
// Pass { rolls: false } to omit the blow-by-blow.
async function buildFightRecap(guild, gid, log, opts = {}) {
  // Only the fighters who actually took part. Someone added to the roster
  // who never swung, defended or took a scratch is not part of this story —
  // they'd otherwise appear with a row of zeroes.
  const entries = Object.entries(log?.f ?? {}).filter(([, st]) =>
    (st.atk?.n ?? 0) || (st.def?.n ?? 0) || (st.dealt ?? 0) || (st.taken ?? 0)
    || (st.crit ?? 0) || (st.fumble ?? 0));
  if (!entries.length) return [];
  const ex = log.exchanges ?? 0;
  const lines = ['', `📜 **Fight Recap** — ${ex} exchange${ex === 1 ? '' : 's'}`];

  // Resolve every name once — used by all three sections.
  const rolls = Array.isArray(log.r) ? log.r : [];
  const ids = [...new Set([...entries.map(e => e[0]), ...rolls.flatMap(r => [r.a, r.d])])];
  const nameOf = {}, isNpcOf = {};
  for (const fid of ids) {
    // A fighter who left the server resolves to nothing — the recap names
    // them anyway instead of dying with 'reading username of undefined'
    // (live crash, 2026-08-13 03:35).
    const f = await resolveFighter(guild, gid, fid).catch(() => null);
    nameOf[fid] = f?.name ? `${f.name}${f.isNpc ? ' 🎭' : ''}` : 'A departed adventurer';
    isNpcOf[fid] = f?.isNpc ?? false;
  }
  const hideNpc = !npcStatsVisible(gid);
  // NPC stat names stay hidden here exactly as they are on the roll cards.
  const statTag = (fid, st) => (!st || (isNpcOf[fid] && hideNpc)) ? '' : ` ${STAT_LABELS[st] ?? ''}`;

  entries.sort((x, y) => (y[1].dealt ?? 0) - (x[1].dealt ?? 0));

  // ── Rolls: how the dice treated each fighter ──
  const tallyBits = (t) => {
    if (!t || !t.n) return null;
    const out = [`avg **${(t.totSum / t.n).toFixed(1)}**`];
    if (t.natHi) out.push(`best nat ${t.natHi}`);
    // Only worth printing when it differs — a single roll isn't a range.
    if (t.natLo != null && t.natLo < 99 && t.natLo !== t.natHi) out.push(`worst nat ${t.natLo}`);
    return out.join(' · ');
  };
  const rollLines = [];
  for (const [fid, st] of entries) {
    const bits = [];
    const a = tallyBits(st.atk), d = tallyBits(st.def);
    if (a) bits.push(`⚔️ ${st.atk.n} atk · ${a}`);
    if (d) bits.push(`🛡️ ${st.def.n} def · ${d}`);
    if (bits.length) rollLines.push(`**${nameOf[fid] ?? fid}** — ${bits.join('   ')}`);
  }
  if (rollLines.length) lines.push('', '**🎲 Rolls**', ...rollLines);

  // ── Damage ledger ──
  lines.push('', '**💥 Damage**');
  for (const [fid, st] of entries) {
    const bits = [`dealt **${st.dealt ?? 0}**`, `taken **${st.taken ?? 0}**`];
    if (st.crit) bits.push(`💥 ${st.crit} nat-20${st.crit > 1 ? 's' : ''}`);
    if (st.fumble) bits.push(`🔻 ${st.fumble} nat-1${st.fumble > 1 ? 's' : ''}`);
    if (st.rr) bits.push(`🔁 ${st.rr} reroll${st.rr > 1 ? 's' : ''}`);
    lines.push(`**${nameOf[fid] ?? fid}** — ${bits.join(' · ')}`);
  }

  // ── Blow by blow: every roll both sides made, in order ──
  if (opts.rolls !== false && rolls.length) {
    const shown = rolls.slice(-ROLL_LOG_SHOW);
    const trimmed = (rolls.length - shown.length) + (log.rTrim ?? 0);
    lines.push('', '**⚔️ Blow by blow**');
    if (trimmed > 0) lines.push(`*(earliest ${trimmed} exchange${trimmed === 1 ? '' : 's'} trimmed)*`);
    const nat = (v) => v === 20 ? `[**20**]💥` : v === 1 ? `[**1**]🔻` : `[${v}]`;
    for (const r of shown) {
      const res = r.h ? `💥 **${r.dm}**` : `🛡️ blocked`;
      lines.push(`\`${String(r.n).padStart(2, ' ')}\` ${nameOf[r.a] ?? '?'} ⚔️${statTag(r.a, r.as)} ${nat(r.an)}→**${r.at ?? '?'}**  ·  ${nameOf[r.d] ?? '?'} 🛡️${statTag(r.d, r.ds)} ${nat(r.dn)}→**${r.dt ?? '?'}**  ·  ${res}`);
    }
  }
  return lines;
}

// ── End-of-fight announcement ────────────────────────────────────────────────
// Every way a fight can finish — knockout, forfeit, kick, GM end, full auto —
// funnels through here, so the result is always posted publicly in the channel
// where everyone can read it, never buried in an ephemeral reply only the GM
// sees. Carries the victor, everyone's final standing, and the full recap.
async function announceFightEnd(guild, gid, cid, channel, opts = {}) {
  // A fight in a quest's channel is part of that quest's story.
  try { noteQuestActivity(gid, cid, 'combat', opts?.headline
    ? String(opts.headline).replace(/\*\*/g, '').replace(/[🏆🛑🏳️]/g, '').trim()
    : 'A fight ended'); } catch {}
  const { headline = null, log = {}, roster = [], hpState = {}, floor = 0 } = opts;
  const W = fightWords(floor);
  const lines = ['═════════════════════════════', floor > 0 ? '🏁 **Bout Over**' : '🏁 **Fight Over**'];
  if (headline) lines.push('', headline);

  // Everyone who took part: the roster passed in, plus anyone recorded in the
  // log or HP state — fighters knocked out earlier already left the turn order.
  const ids = [];
  for (const fid of [...(roster || []), ...Object.keys(log?.f ?? {}), ...Object.keys(hpState || {})]) {
    if (fid && !ids.includes(fid)) ids.push(fid);
  }
  if (ids.length) {
    lines.push('', '**Final standing**');
    for (const fid of ids) {
      const f = await resolveFighter(guild, gid, fid);
      const known = hpState && Object.prototype.hasOwnProperty.call(hpState, fid);
      const live = known ? hpState[fid]
        : (f.isNpc ? (getNpc(gid, f.name)?.hp_current ?? 0) : (getChar(gid, fid)?.hp_current ?? 0));
      const text = (f.isNpc && !npcStatsVisible(gid))
        ? hpCondition(live, f.maxHp, floor)
        : `❤️ ${live} / ${f.maxHp || '?'}${live <= floor ? ` ${W.icon}` : ''}`;
      lines.push(`**${f.name}${f.isNpc ? ' 🎭' : ''}** — ${text}`);
    }
  }

  lines.push(...await buildFightRecap(guild, gid, log));
  await sendLong(channel, lines);
}

// Expand category tokens in an NPC list, keeping unknown tokens as-is so the
// caller's normal "NPC not found" handling reports them.
function expandNpcList(gid, str) {
  const { names, missingCats } = expandNpcTokens(gid, str);
  // Unknown categories fall through as literal names → caller's not-found error fires
  return [...names, ...missingCats.map(c => 'category:' + c)];
}

// Expand "category:Bandits" tokens in a comma-separated NPC list into the
// category's members (case-insensitive category match). Returns { names, missingCats }.
function expandNpcTokens(gid, str) {
  const names = [], missingCats = [];
  for (const tok of parseNpcNames(str)) {
    const m = /^category:(.+)$/i.exec(tok);
    if (m) {
      const wanted = m[1].trim().toLowerCase();
      const cat = getCategories(gid).find(c => c.toLowerCase() === wanted);
      const members = cat ? getNpcsInCategory(gid, cat) : [];
      if (!members.length) missingCats.push(m[1].trim());
      for (const n of members) if (!names.includes(n)) names.push(n);
    } else if (!names.includes(tok)) names.push(tok);
  }
  return { names, missingCats };
}

// Build a character-shaped object for buildRollEmbed from any fighter id.
// Players use their real character row; NPCs are adapted from the NPC record.
// A fight card honours the roller's /char profile card style: Full stays the full
// sheet card; Compressed — and Off, since a fight roll is a stat roll and a
// bare total explains nothing — folds to the compact line + stat line, same
// as /roll. NPCs and the audit's reveal cards always render full.
function styledFightCard(gid, actorId, args) {
  if (isNpcFighter(actorId) || args.char?._isNpc) return buildRollEmbed(args);
  const char = getChar(gid, actorId);
  if (!char || cardMode(char) === CARD_FULL) return buildRollEmbed(args);
  const lines = [];
  if (args.label) lines.push(`${critPrefix(args.critType)}**${args.label}**${args.isReroll ? ' *(reroll)*' : ''}`);
  lines.push(args.rollLine, statLine(char, gid));
  if (args.flavour) lines.push(...flavourBlock(args.flavour, args.label, args.total, args.critType));
  return lines.join('\n');
}

async function fighterCharCard(guild, gid, fid) {
  if (isNpcFighter(fid)) {
    const name = npcNameFromFighter(fid);
    const npc = getNpc(gid, name) || {};
    return {
      displayName: name + ' 🎭',
      order_name: npc.order_name || null,
      // NPCs have classes, weapons and Hero status of their own now — this shim
      // predates all three and was blanking them on the fight card.
      class: npc.class || null,
      is_hero: npc.is_hero ? 1 : 0,
      signature_stat: npc.signature_stat || null,
      hp_current: npc.hp_current ?? 0,
      rerolls_current: 0,
      str: npc.str ?? 0, con: npc.con ?? 0, dex: npc.dex ?? 0, wis: npc.wis ?? 0, lck: npc.lck ?? 0,
      weapon1: npc.weapon1 || null, weapon2: npc.weapon2 || null, weapon1emoji: null, weapon2emoji: null,
      _isNpc: true,
    };
  }
  const member = await guild.members.fetch(fid).catch(()=>null);
  const displayName = member?.nickname || member?.user.username || fid;
  const char = getChar(gid, fid);
  return char ? { ...char, displayName } : { displayName, order_name:null, class:null, hp_current:0, rerolls_current:0, str:0,con:0,dex:0,wis:0,lck:0, weapon1:null,weapon2:null };
}

// Post a message into a channel AS an NPC (via its webhook, with name + avatar),
// matching how /npc posts. Falls back to a plain channel.send if the webhook fails.
// Returns the sent message when the API hands one back (so callers can build
// audit jump links), otherwise a bare truthy/falsy success flag.
// Speaking as an NPC in a quest's channel is a roleplay beat worth logging.
function noteNpcSpeech(gid, channel, npcName) {
  try { noteQuestActivity(gid, channel?.id, 'rp', `${npcName} speaks`); } catch {}
}

async function postAsNpc(channel, gid, npcName, content) {
  noteNpcSpeech(gid, channel, npcName);
  const npc = getNpc(gid, npcName);
  try {
    const face = npcFace(gid, npc);
    const webhookClient = await npcWebhookIn(channel, gid, npcName, face);
    const sent = await webhookClient.send({ content, username: npcName, avatarURL: face ?? BLANK_AVATAR });
    return sent ?? true;
  } catch (err) {
    // A stored webhook can be deleted server-side; drop it and retry once.
    console.error('postAsNpc webhook error:', err.message);
    try {
      forgetChannelWebhook(gid, channel);
      const face2 = npcFace(gid, npc);
      const fresh = await npcWebhookIn(channel, gid, npcName, face2);
      const sent2 = await fresh.send({ content, username: npcName, avatarURL: face2 ?? BLANK_AVATAR });
      return sent2 ?? true;
    } catch (err2) {
      console.error('postAsNpc retry failed:', err2.message);
      const plain = await channel.send(content).catch(()=>null);
      return plain ?? false;
    }
  }
}

// In an auto_npc fight, perform the current NPC's attack automatically against a
// random living opponent, then leave the (human) target to defend manually.
// If the next current fighter is also an NPC after resolution, the resolve handler
// will call this again. Returns true if it acted.
async function runAutoNpcTurn(guild, gid, cid, channel) {
  // A fallen NPC is skipped rather than refused — nobody pressed anything, and
  // the fight should carry on around them.
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active' || !fight.auto_npc) return false;
  if (fight.phase !== 'attack') return false;
  const order = fightOrder(fight);
  const hpState = fightHp(fight);
  const attackerId = order[fight.turn_index];
  if (!isNpcFighter(attackerId)) return false; // current fighter is a player — wait for them
  if (isFallen(gid, attackerId)) return false;  // fallen NPCs take no turn
  if (await retrievalTurn(guild, gid, cid, attackerId,
      async (l) => channel.send(l.join('\n')).catch(()=>{}))) return true;

  const attacker = await resolveFighter(guild, gid, attackerId);
  // pick a random opponent still standing (above the bout floor / 0)
  const npcFloor = fightFloor(fight);
  const opponents = order.filter(fid => fid !== attackerId && (hpState[fid] ?? 0) > npcFloor && !isFallen(gid, fid));
  if (!opponents.length) return false;
  const targetId = opponents[Math.floor(Math.random() * opponents.length)];
  const targetF = await resolveFighter(guild, gid, targetId);

  // The bot fights within the same rules a player does.
  const stat = chooseAutoStat(gid, attackerId, attacker.stats, 'atk');
  const fooledAuto = consumeFooled(gid, cid, attackerId);
  const atkBonus = fooledAuto ? 0 : consumeAtkBonus(gid, cid, attackerId);
  const attRow = attacker.isNpc ? getNpc(gid, attacker.name) : getChar(gid, attackerId);
  const a = autoRoll(fooledAuto ? 0 : ((attacker.stats[stat] ?? 0) + atkBonus), !fooledAuto && hasSignatureAdvantage(attRow, stat));
  mirrorAutoRoll(gid, cid, attacker.name, `1d20${a.adv ? ' (adv)' : ''}`, a.nat, a.total, fooledAuto ? `fight attack (${STAT_LABELS[stat]}, fooled — flat)` : `fight attack (${STAT_LABELS[stat]})`);

  upsertFight(gid, cid, {
    phase: 'defend', current_target: targetId,
    atk_roll: a.total, atk_nat: a.nat, atk_stat: stat, atk_mode: 'normal', atk_sides: 20,
    def_roll: null, def_nat: null, def_stat: null, def_mode: 'normal',
  });

  // The NPC's own roll card posts AS the NPC (webhook), matching manual rolls.
  const atkCard = await autoFightCard(guild, gid, attacker, 'atk', stat, a.nat, a.total, `${targetF.name}${targetF.isNpc ? ' 🎭' : ''}`, false, atkBonus, false, !!a.adv);
  await postAsNpc(channel, gid, attacker.name, atkCard);
  if (atkBonus) await channel.send(`✨ **${attacker.name}** presses the riposte (+${atkBonus}).`).catch(()=>{});

  // NPC targets are defended automatically by the chain — only prompt players.
  if (!targetF.isNpc) {
    await channel.send({ content: `🛡️ **${targetF.name}** — press a stat to defend, or \`/fight def\`; then \`/fight resolve\`.`, components: fightAnswerRows('def') }).catch(()=>{});
  }
  return true;
}

// In an auto_npc fight, roll the targeted NPC's defence automatically
// (best of STR/DEX) and post it under the NPC's name. Returns true if it acted.
async function autoNpcDefend(guild, gid, cid, channel) {
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active' || !fight.auto_npc) return false;
  if (fight.phase !== 'defend' || !isNpcFighter(fight.current_target)) return false;
  if (isFallen(gid, fight.current_target)) return false;   // the fallen do not defend

  const defender = await resolveFighter(guild, gid, fight.current_target);
  if (fight.atk_kind === 'grapple') {
    // Grapple saves are STR-only; the auto NPC rolls its own.
    const drow = getNpc(gid, defender.name);
    const d = autoRoll(defender.stats.str ?? 0, hasSignatureAdvantage(drow, 'str'));
    mirrorAutoRoll(gid, cid, defender.name, `1d20${d.adv ? ' (adv)' : ''}`, d.nat, d.total, 'grapple save (STR)');
    const r = await resolveGrappleSave(guild, gid, cid, fight, { nat: d.nat, total: d.total, mode: d.adv ? 'adv' : 'normal' });
    await channel.send(r.lines.join('\n')).catch(err => console.error('[auto] grapple save post -', err?.message || err));
    return true;
  }
  if (fight.atk_kind === 'feint') {
    // Insight checks are WIS-only; a fooled NPC rolls even this one flat.
    const drow = getNpc(gid, defender.name);
    const wasFooled = consumeFooled(gid, cid, fight.current_target);
    const d = autoRoll(wasFooled ? 0 : (defender.stats.wis ?? 0), !wasFooled && hasSignatureAdvantage(drow, 'wis'));
    mirrorAutoRoll(gid, cid, defender.name, `1d20${d.adv ? ' (adv)' : ''}`, d.nat, d.total, wasFooled ? 'feint insight (WIS, fooled — flat)' : 'feint insight (WIS)');
    const r = await resolveFeintInsight(guild, gid, cid, fight, { nat: d.nat, total: d.total, mode: d.adv ? 'adv' : 'normal' });
    await channel.send(r.lines.join('\n')).catch(err => console.error('[auto] feint insight post -', err?.message || err));
    return true;
  }
  const stat = chooseAutoStat(gid, fight.current_target, defender.stats, 'def');
  const flat = consumeFlatDef(gid, cid, fight.current_target) || consumeFooled(gid, cid, fight.current_target) || consumeFlatMark(gid, fight.current_target);
  const defRow = defender.isNpc ? getNpc(gid, defender.name) : getChar(gid, fight.current_target);
  const d = autoRoll(flat ? 0 : (defender.stats[stat] ?? 0), !flat && hasSignatureAdvantage(defRow, stat));
  mirrorAutoRoll(gid, cid, defender.name, `1d20${d.adv ? ' (adv)' : ''}`, d.nat, d.total,
    flat ? 'fight defence (flat d20 — fumbled)' : `fight defence (${STAT_LABELS[stat]})`);

  upsertFight(gid, cid, { def_roll: d.total, def_nat: d.nat, def_stat: stat, def_mode: 'normal', def_sides: 20 });

  const defCard = await autoFightCard(guild, gid, defender, 'def', stat, d.nat, d.total, null, false, 0, flat, !!d.adv);
  await postAsNpc(channel, gid, defender.name, defCard);
  if (flat) await channel.send(`🎲 **${defender.name}** defends on a flat d20 (fumbled last attack).`).catch(()=>{});
  return true;
}

// Advance to the next fighter still standing, starting AT from (wrapping).
function nextStandingIndex(turnOrder, hpState, floor, from) {
  let idx = ((from % turnOrder.length) + turnOrder.length) % turnOrder.length;
  let safety = 0;
  while (hpState[turnOrder[idx]] !== undefined && hpState[turnOrder[idx]] <= floor && safety < turnOrder.length) {
    idx = (idx + 1) % turnOrder.length;
    safety++;
  }
  return idx;
}

// Whose turn it becomes, and the reminder a GM needs when driving an NPC by
// hand. Shared by every path that hands the fight onward.
async function announceNextTurn(guild, gid, cid, lines, order, index) {
  const nextF = await resolveFighter(guild, gid, order[index]);
  const autoOn = !!getFight(gid, cid)?.auto_npc;
  const hint = (autoOn && nextF.isNpc) ? '' : nextF.isNpc
    ? `\n_A GM acts for them: \`/fight atk stat:str npc:${nextF.name} target:@player\`_`
    : '\n_\`/fight atk stat:str target:@player\` — or \`/roll dice:2d6+3 fight:true target:@player\` for a custom roll._';
  lines.push(`\n🎯 **${nextF.name}${nextF.isNpc ? ' 🎭' : ''}**'s turn to attack!${hint}${turnPing(gid, nextF)}`);
  return nextF;
}

// The fight is over: archive, reset the row, and shape the winner's announce.
async function buildFightEnd(guild, gid, cid, lines, hpState, roster, floor, winnerId) {
  const winF = await resolveFighter(guild, gid, winnerId);
  const W = fightWords(floor);
  const endLog = JSON.parse(getFight(gid, cid)?.log_state || '{}');
  archiveFight(gid, cid, endLog, roster, floor);
  upsertFight(gid, cid, { state: 'idle', turn_order: '[]', hp_state: JSON.stringify(hpState) });
  return { lines, ended: true, nextF: null, announce: {
    headline: `🏆 **${winF.name}${winF.isNpc ? ' 🎭' : ''}** ${W.win}!`,
    log: endLog, roster, hpState, floor,
  } };
}

// Auto-mode twin of the `/fight resolve` handler (channel-send based).
// Computes damage from the stored rolls, persists HP, handles knockdown /
// win / turn advance, and posts the summary. Returns true if the fight continues.
// Keep the rules here in lockstep with the `resolve` subcommand in handleFight.
// A held fighter pays 1 strain when their own turn ends. Re-reads the fight
// row (any purge already persisted is seen), handles a strain knockout in
// full — purge, roster shrink, and the fight end when only one stands.
// Returns { order, endedRet } like the resolver's inner paths.
async function applyTurnEndStrain(guild, gid, cid, hpState, order, roster, floor, lines, fid) {
  const f = getFight(gid, cid);
  const gmap = fightGrapples(f);
  if (!gmap[fid]) return { order };
  const prev = hpState[fid] ?? 0;
  if (prev <= floor) return { order };
  const F = await resolveFighter(guild, gid, fid);
  const name = F.name + (F.isNpc ? ' 🎭' : '');
  const W = fightWords(floor);
  const nh = applyFightDamage(prev, 1, floor);
  hpState[fid] = nh; setFighterHp(gid, fid, nh);
  lines.push('', `🤼 The hold takes its toll — **${name}** takes **1** strain.`);
  lines.push(hpChangeLine(gid, F.isNpc, F.name, prev, nh, F.maxHp, floor));
  if (nh <= floor) {
    lines.push('', `${W.icon} **${name}** ${W.out}! HP: **${nh}**`);
    for (const [t, h] of Object.entries(gmap)) if (t === fid || h === fid) delete gmap[t];
    setFightGrapples(gid, cid, gmap);
    const shrunk = order.filter(id => id !== fid);
    if (shrunk.length <= 1) return { order: shrunk, endedRet: await buildFightEnd(guild, gid, cid, lines, hpState, roster, floor, shrunk[0]) };
    return { order: shrunk };
  }
  return { order };
}

// ── Exchange resolution ───────────────────────────────────────────────────────
// One implementation of the combat rules, shared by /fight resolve and the NPC
// auto-pilot. These used to be two ~90-line copies that had to be edited in
// lockstep for every rules change; anything that touched damage, crit carry-over,
// the bout floor or the recap had to be applied twice and could silently drift.
//
// This computes the whole exchange and hands back what to say and what happened.
// The caller owns delivery (an interaction reply vs a channel post) and whether
// to keep the auto chain running.
//
// Returns { lines, ended, announce } where `announce` is the payload for
// announceFightEnd when the fight finished, and `nextF` is the fighter whose
// turn it now is (null when the fight ended).
async function resolveExchange(guild, gid, cid, fight) {
  const turnOrder = fightOrder(fight);
  const attackerId = turnOrder[fight.turn_index];
  const defenderId = fight.current_target;
  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  const W = fightWords(floor);

  // Under a target-number ruleset the attacker's own weapon and modifier
  // decide the damage, so they travel with the question.
  const rulesX = rulesFor(gid);
  let dmgCtx = {};
  if (rulesX.defence === 'ac') {
    const atkRow = isNpcFighter(attackerId) ? getNpc(gid, npcNameFromFighter(attackerId)) : getChar(gid, attackerId);
    const flat = damageBonusFor(atkRow);
    dmgCtx = { weaponDice: weaponDiceFor(gid, atkRow),
               mod: flat != null ? flat : rulesX.statBonus(atkRow, fight.atk_stat || 'str') };
  }
  // GM interjections land here — the one place every path converges. Each
  // fighter's pending adjustment applies to the roll they made THIS
  // exchange, then clears; the card says so out loud.
  const interjectLines = [];
  {
    const eff = JSON.parse(fight.effect_state || '{}');
    let effDirty = false;
    for (const [fid, roleKey] of [[attackerId, 'atk_roll'], [defenderId, 'def_roll']]) {
      const slot = eff[fid];
      if (!slot?.gmAdj) continue;
      fight[roleKey] = (fight[roleKey] ?? 0) + slot.gmAdj;
      const who = isNpcFighter(fid) ? `**${npcNameFromFighter(fid)}**` : `<@${fid}>`;
      const amt = `${slot.gmAdj > 0 ? '+' : ''}${slot.gmAdj}`;
      interjectLines.push(`\u2696\uFE0F GM interjection: ${amt} to ${who}'s roll${slot.gmAdjNote ? ` \u2014 ${slot.gmAdjNote}` : ''}`);
      delete slot.gmAdj; delete slot.gmAdjNote;
      effDirty = true;
    }
    if (effDirty) upsertFight(gid, cid, { effect_state: JSON.stringify(eff) });
  }
  const { hit, dmg, crit: atkCrit, detail: dmgDetail } = resolveDamage(
    fight.atk_roll, fight.atk_nat, 20,
    fight.def_roll, fight.def_nat, 20, gid, dmgCtx
  );

  // Carry-over effects from this exchange (nat-1 attack, nat-20 defence), and
  // the running fight log. Neither depends on the other's writes.
  const effNotes = applyExchangeEffects(gid, cid, attackerId, defenderId, fight.atk_nat, fight.def_nat);
  bumpFightLog(gid, cid, (log, ensure) =>
    recordExchange(log, ensure, attackerId, defenderId, fight.atk_nat, fight.def_nat, hit, dmg,
      { atkTotal: fight.atk_roll, defTotal: fight.def_roll, atkStat: fight.atk_stat, defStat: fight.def_stat }));

  const atkF = await resolveFighter(guild, gid, attackerId);
  const defF = await resolveFighter(guild, gid, defenderId);
  const atkName = atkF.name + (atkF.isNpc ? ' 🎭' : '');
  const defName = defF.name + (defF.isNpc ? ' 🎭' : '');

  const lines = ['─────────────────────────────', '⚔️  **Exchange Resolved**', ''];
  lines.push(`${atkName} (**${STAT_LABELS[fight.atk_stat]}**): ${fightTotalStr(fight.atk_roll, fight.atk_nat, 20)}`);
  lines.push(`${defName} (**${STAT_LABELS[fight.def_stat]}**): ${fightTotalStr(fight.def_roll, fight.def_nat, 20)}`);
  for (const l of interjectLines) lines.push(l);
  lines.push('');

  // The grapple layer: purge holds on any knockout, and a held attacker
  // takes 1 strain when their turn ends — with full down handling.
  const gmap = fightGrapples(fight);
  const purgeGrapple = (fid, nm) => {
    let changed = false;
    for (const [t, h] of Object.entries(gmap)) if (t === fid || h === fid) { delete gmap[t]; changed = true; }
    if (changed) { lines.push(`🤼 The hold involving **${nm}** breaks.`); setFightGrapples(gid, cid, gmap); }
  };
  // Delegates to the shared end-of-turn strain (re-reads the fight row, so a
  // purge persisted just above is seen).
  const applyEndStrain = (order) => applyTurnEndStrain(guild, gid, cid, hpState, order, turnOrder, floor, lines, attackerId);

  // Whose turn it becomes, and the reminder a GM needs when they're driving an
  // NPC by hand. Shared by the "fighter went down" and "fight continues" paths.
  const handOver = (order, index) => announceNextTurn(guild, gid, cid, lines, order, index);
  const clearRolls = {
    phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null,
    def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0,   // a new exchange, a fresh second chance
  };

  // A defence rolled as a feint: reading the blow leaves the attacker
  // off-balance, and the defender pays the usual flat next defence.
  if (consumeEffectFlag(gid, cid, defenderId, 'feintDef')) {
    lines.push(`🎭 **${defName}** read the blow rather than blocking it.`);
    setEffectFlag(gid, cid, defenderId, 'flatDef');
    if (!hit) {
      setEffectFlag(gid, cid, attackerId, 'flatAtk');
      lines.push(`↳ **${atkName}** is left **off-balance** — their next attack rolls flat.`);
    }
  }

  if (hit && dmgDetail) lines.push(`🎲 Damage: ${dmgDetail}${atkCrit ? ' — **critical!**' : ''}`);

  // A caster who takes a blow must hold their spell together.
  if (hit && dmg && rulesX.concentrationDC && !isNpcFighter(defenderId)) {
    const defRow = getChar(gid, defenderId);
    if (defRow?.concentrating) {
      lines.push(`🧠 <@${defenderId}> is concentrating on **${defRow.concentrating}** — **CON save, DC ${rulesX.concentrationDC(dmg)}** or it is lost.`);
    }
  }

  let dealt = dmg;
  if (hit && rulesX.applyResistance) {
    // Resistance halves, vulnerability doubles, immunity spares entirely —
    // and temporary hit points are spent before real ones.
    const defRowR = isNpcFighter(defenderId) ? getNpc(gid, npcNameFromFighter(defenderId)) : getChar(gid, defenderId);
    const atkRowR = isNpcFighter(attackerId) ? getNpc(gid, npcNameFromFighter(attackerId)) : getChar(gid, attackerId);
    const type = atkRowR?.damage_type || null;
    const res = rulesX.applyResistance(defRowR, type, dealt);
    if (res.note) lines.push(`🛡️ ${defName} ${res.note} — ${dealt} becomes ${res.dmg}.`);
    dealt = res.dmg;
    const temp = Number(defRowR?.temp_hp) || 0;
    if (temp > 0 && dealt > 0) {
      const soaked = Math.min(temp, dealt);
      dealt -= soaked;
      const patchT = { temp_hp: temp - soaked };
      if (isNpcFighter(defenderId)) upsertNpc(gid, npcNameFromFighter(defenderId), patchT);
      else upsertChar(gid, defenderId, patchT);
      lines.push(`🛡️ ${soaked} soaked by temporary hit points — ${temp - soaked} left.`);
    }
  }

  if (hit) {
    const prevHp = hpState[defenderId] ?? 0;
    const newHp = applyFightDamage(prevHp, dealt, floor);
    hpState[defenderId] = newHp;
    setFighterHp(gid, defenderId, newHp);           // persist to character or NPC
    lines.push(`💥 **${atkName}** hits **${defName}** for **${dmg}** damage!`);
    lines.push(hpChangeLine(gid, defF.isNpc, defName, prevHp, newHp, defF.maxHp, floor));
    for (const l of effectNoteLines(effNotes, atkName, defName)) lines.push(l);

    if (newHp <= floor) {
      lines.push('', `${W.icon} **${defName}** ${W.out}! HP: **${newHp}**`);
      purgeGrapple(defenderId, defName);
      let newOrder = turnOrder.filter(id => id !== defenderId);

      if (newOrder.length <= 1) {
        return buildFightEnd(guild, gid, cid, lines, hpState, turnOrder, floor, newOrder[0]);
      }
      // The victor's turn ends too — a held attacker still pays the strain.
      const st = await applyEndStrain(newOrder);
      if (st.endedRet) return st.endedRet;
      newOrder = st.order;
      if (newOrder.length <= 1) {
        return buildFightEnd(guild, gid, cid, lines, hpState, turnOrder, floor, newOrder[0]);
      }
      const newIndex = nextStandingIndex(newOrder, hpState, floor, fight.turn_index);
      const nextF = await handOver(newOrder, newIndex);
      upsertFight(gid, cid, { ...clearRolls,
        turn_order: JSON.stringify(newOrder), turn_index: newIndex,
        hp_state: JSON.stringify(hpState),
      });
      return { lines, ended: false, nextF, announce: null };
    }
  } else {
    // The doc's automatics get their own voices — a parry and a fumble are
    // stories, not mere arithmetic misses.
    if (dmgDetail === 'parried') lines.push(`🛡 **${defName}** turns the blow aside — a perfect parry! No damage.`);
    else if (dmgDetail === 'fumbled') lines.push(`💥 **${atkName}** fumbles the attack — it fails outright! No damage.`);
    else lines.push(`🛡 **${defName}** blocks the attack! No damage.`);
    for (const l of effectNoteLines(effNotes, atkName, defName)) lines.push(l);
  }

  // The attacker's turn ends — a held attacker pays the strain, then the
  // fight advances to the next fighter still standing.
  const st = await applyEndStrain([...turnOrder]);
  if (st.endedRet) return st.endedRet;
  const order = st.order;
  const shrunk = order.length !== turnOrder.length;
  const nextIndex = nextStandingIndex(order, hpState, floor, shrunk ? fight.turn_index : fight.turn_index + 1);
  const nextF = await handOver(order, nextIndex);
  upsertFight(gid, cid, { ...clearRolls, turn_index: nextIndex, hp_state: JSON.stringify(hpState),
    ...(shrunk ? { turn_order: JSON.stringify(order) } : {}) });
  return { lines, ended: false, nextF, announce: null };
}

// A grapple save resolves here, whoever rolled it. The grappler's stored
// attempt wins ties ("meets or exceeds"); a failed save writes the hold into
// the fight's grapple map. No damage moves, so no down handling is needed —
// the turn simply passes.
async function resolveGrappleSave(guild, gid, cid, fight, { nat, total, mode = 'normal' }) {
  const turnOrder = fightOrder(fight);
  const attackerId = turnOrder[fight.turn_index];
  const targetId = fight.current_target;
  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  const atkF = await resolveFighter(guild, gid, attackerId);
  const defF = await resolveFighter(guild, gid, targetId);
  const atkName = atkF.name + (atkF.isNpc ? ' 🎭' : '');
  const defName = defF.name + (defF.isNpc ? ' 🎭' : '');
  const lines = ['─────────────────────────────', '🤼  **Grapple Resolved**', ''];
  lines.push(`${atkName} (**STR**): ${fightTotalStr(fight.atk_roll, fight.atk_nat, 20)}`);
  lines.push(`${defName} (**STR** save${mode === 'adv' ? ', advantage' : mode === 'dis' ? ', disadvantage' : ''}): ${fightTotalStr(total, nat, 20)}`);
  lines.push('');
  const grappled = fight.atk_roll >= total;
  if (grappled) {
    const gmap = fightGrapples(fight);
    gmap[targetId] = attackerId;
    setFightGrapples(gid, cid, gmap);
    lines.push(`🔒 **${defName}** is **grappled** by **${atkName}**!`);
    lines.push(`_Immobile • 1 strain at each of their turn's ends • \`/fight act action:Escape\` (STR) or act on a flat d20. ${atkName} may \`/fight act action:Release\` freely, and cannot strike their captive._`);
  } else {
    lines.push(`💨 **${defName}** slips the hold — no grapple.`);
  }
  const clear = { phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null,
    def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0 };
  const nextIndex = nextStandingIndex(turnOrder, hpState, floor, fight.turn_index + 1);
  const nextF = await announceNextTurn(guild, gid, cid, lines, turnOrder, nextIndex);
  upsertFight(gid, cid, { ...clear, turn_index: nextIndex });
  return { lines, nextF, grappled };
}

// The ledger's voice for GM overrides: one line to the roll-audit channel
// when a GM reaches into the machine, so the record shows the hand.
function sendRollAudit(client, gid, text) {
  const chId = getConfig(gid)?.roll_audit_channel_id;
  if (!chId) return;
  client.channels.fetch(chId).then(ch => ch?.send({ content: text, allowedMentions: { parse: [] } })).catch(() => {});
}

// A bound dc card holds its target's fight actions in that channel until
// the card is pressed. The record is the card row itself; a pruned card
// simply stops holding, the same graceful dark the marks already have.
function boundDcHold(gid, cid, uid) {
  try {
    return db.prepare('SELECT message_id FROM dc_cards WHERE guild_id=? AND bind_channel=? AND bind_uid=? LIMIT 1')
      .get(gid, cid, uid) || null;
  } catch { return null; }
}
function clearDcBind(gid, msgId) {
  try { db.prepare('UPDATE dc_cards SET bind_channel=NULL, bind_uid=NULL, bind_skip=0 WHERE guild_id=? AND message_id=?').run(gid, msgId); } catch {}
}

// The GM reaches in and the turn passes: same clear-and-advance the normal
// resolution uses, announced plainly so the table knows it was a ruling,
// not the machine. Used by /gm override skip and by a failed bound check.
// /gm override interject \u2014 a hand on the scales, mid-fight. Works in every
// path (manual, NPCs-only, full auto) because it is CONSUMED at the one
// place all of them meet: the resolver. If the player's roll for this
// exchange is already on the table, the adjustment lands on it (current);
// otherwise it waits for their next roll \u2014 no timing option needed, the
// earliest unresolved roll is simply what it hits. Amounts sum if stacked;
// leaving the fight clears it with the other effects.
// Player feedback: a GM-only forum, one thread per room, and every
// player-facing step ephemeral so nobody sees who said what (T,
// 2026-08-16). GMs see the author on the card; other players see nothing
// at all — not the command, not the reply, not the entry.
// The players' chronicle entry: the GM's telling, headed by the quest and
// its party, with the mechanical detail deliberately absent — that lives
// in the GM log. Returns the jump link.
// The players' chronicle: a thread per adventurer, and a quest's tale
// mirrored into the thread of everyone who was there (T, 2026-08-16).
// Rewriting edits each copy in place — found via that player's own stored
// url — so a retelling never stacks. Returns a map of user_id -> url.
async function postQuestTale(interaction, gid, quest, text, party) {
  const chId = getConfig(gid)?.quest_log_channel;
  if (!chId) return {};
  const forum = await interaction.client.channels.fetch(chId).catch(() => null);
  if (!forum) return {};
  const out = {};
  const isForum = forum.type === 15;
  for (const uid of party) {
    const name = await getDisplayName(interaction.guild, uid).catch(() => 'Adventurer');
    const body = [`\u{1F4D6} **${questTag(quest)}**`, '', text].join('\n').slice(0, 1900);

    // Their thread, made once and kept.
    let thread = null;
    if (isForum) {
      const row = db.prepare('SELECT thread_id FROM chronicle_threads WHERE guild_id=? AND user_id=?').get(gid, uid);
      thread = row?.thread_id ? await interaction.client.channels.fetch(row.thread_id).catch(() => null) : null;
      if (thread && (!thread.isThread?.() || thread.parentId !== forum.id)) thread = null;
      if (!thread) {
        thread = await forum.threads.create({
          name: name.slice(0, 90),
          message: { content: `\u{1F4DC} **${name}** \u2014 the quests they have seen through.`, allowedMentions: { parse: [] } },
        }).catch(() => null);
        if (!thread) continue;
        db.prepare(`INSERT INTO chronicle_threads (guild_id, user_id, thread_id, at) VALUES (?,?,?,?)
                    ON CONFLICT(guild_id, user_id) DO UPDATE SET thread_id=excluded.thread_id, at=excluded.at`)
          .run(gid, uid, thread.id, Date.now());
      } else {
        await wakeThread(thread);
      }
      if (thread.name !== name.slice(0, 90)) await thread.setName(name.slice(0, 90)).catch(() => {});
    }
    const target = isForum ? thread : forum;

    // Their own copy, edited in place when it already exists.
    const prior = db.prepare('SELECT url FROM quest_summaries WHERE guild_id=? AND number=? AND user_id=?').get(gid, quest.number, uid);
    const priorId = prior?.url?.split('/').pop();
    let url = null;
    if (priorId) {
      const m = await target.messages.fetch(priorId).catch(() => null);
      if (m?.editable) { await m.edit({ content: body, allowedMentions: { parse: [] } }).catch(() => {}); url = prior.url; }
    }
    if (!url) {
      const sent = await target.send({ content: body, allowedMentions: { parse: [] } }).catch(() => null);
      if (sent) url = `https://discord.com/channels/${gid}/${target.id}/${sent.id}`;
    }
    if (url) out[uid] = url;
    await pace(150);
  }
  return out;
}

// Buttons a GM plants in a channel, pressed by anyone who comes along.
// Everything the press needs rides in the customId, so a button keeps
// working after a restart with no state to lose; the only stored thing is
// who has pressed, and only when `once` is asked for (T, 2026-08-16).
// Temporary targets: a thing in a channel to swing at, with no sheet and
// no roster entry. It has no HP — every hit asks the GM whether it falls,
// which is both simpler and truer to how a table actually plays (T,
// 2026-08-16). `secret` sends that question to the GM channel instead.
// Titles and associations, for players and NPCs through one door. The
// subject is whichever of `user:` or `npc:` was given; everything below
// reads a fighter id and neither knows nor cares which kind it is.
async function handleTitles(interaction, group) {
  const gid = interaction.guild.id;
  const leaf = interaction.options.getSubcommand();
  const gm = await isGm(interaction.guild, interaction.user.id);

  // `association list` asks about a GROUP, not a subject.
  if (group === 'association' && leaf === 'list') {
    const name = interaction.options.getString('group').trim();
    const rows = db.prepare('SELECT subject_id, note FROM subject_assocs WHERE guild_id=? AND name=? COLLATE NOCASE ORDER BY at').all(gid, name);
    if (!rows.length) return interaction.reply({ ephemeral: true, content: `\u{1F6E1}\uFE0F Nobody stands with **${name}** yet.` });
    const lines = [];
    for (const r of rows) {
      const who = isNpcFighter(r.subject_id)
        ? `**${npcNameFromFighter(r.subject_id)}** \u{1F3AD}`
        : `<@${r.subject_id}>`;
      lines.push(`\u00b7 ${who}${r.note ? ` \u2014 _${r.note}_` : ''}`);
    }
    return interaction.reply({ ephemeral: true, allowedMentions: { parse: [] },
      content: [`\u{1F6E1}\uFE0F **${name}**`, ...lines].join('\n').slice(0, 1900) });
  }

  const user = interaction.options.getUser('user');
  const npcName = (interaction.options.getString('npc') || '').trim();
  if (user && npcName) return interaction.reply({ ephemeral: true, content: '\u274C A player or an NPC, not both.' });
  if (!user && !npcName) return interaction.reply({ ephemeral: true, content: '\u274C Name a player with `user:` or an NPC with `npc:`.' });
  if (npcName && !getNpc(gid, npcName)) return interaction.reply({ ephemeral: true, content: `\u274C No NPC called **${npcName}**.` });
  const sid = user ? user.id : npcFighterId(getNpc(gid, npcName).name);
  const label = user ? `<@${user.id}>` : `**${getNpc(gid, npcName).name}**`;
  const refresh = () => {
    if (user) ensureCharPage(interaction.client, interaction.guild, user.id, null, 'all').catch(() => {});
    else mirrorNpcSheet(interaction.client, gid, getNpc(gid, npcName).name).catch(() => {});
  };

  if (leaf === 'list') {
    const body = titlesLine(gid, sid);
    return interaction.reply({ ephemeral: true, allowedMentions: { parse: [] },
      content: body ? `${label}\n${body}` : `${label} holds no titles and stands with no one yet.` });
  }
  if (!gm) return interaction.reply({ ephemeral: true, content: '\u274C Only GMs can grant or revoke these.' });

  if (group === 'title') {
    const title = interaction.options.getString('title').trim().slice(0, 60);
    if (leaf === 'grant') {
      const source = (interaction.options.getString('source') || '').trim() || null;
      grantTitle(gid, sid, title, { source, by: interaction.user.id });
      refresh();
      return interaction.reply({ allowedMentions: { parse: [] },
        content: `\u{1F3C5} ${label} is now **${title}**${source ? ` \u2014 _${source}_` : ''}.` });
    }
    if (leaf !== 'revoke') return interaction.reply({ ephemeral: true, content: '\u274C Unknown title command.' });
    const gone = revokeTitle(gid, sid, title);
    if (gone) refresh();
    return interaction.reply({ ephemeral: true, allowedMentions: { parse: [] },
      content: gone ? `\u2705 ${label} no longer holds **${title}**.` : `\u274C ${label} never held **${title}**.` });
  }

  const name = interaction.options.getString('group').trim().slice(0, 60);
  if (leaf === 'add') {
    addAssoc(gid, sid, name, (interaction.options.getString('note') || '').trim() || null);
    refresh();
    return interaction.reply({ allowedMentions: { parse: [] },
      content: `\u{1F6E1}\uFE0F ${label} now stands with **${name}**.` });
  }
  // Named rather than fallen-through, so a leaf added later cannot land
  // here by accident (the same smell fixed for /feedback send).
  if (leaf !== 'remove') return interaction.reply({ ephemeral: true, content: '\u274C Unknown association command.' });
  const parted = removeAssoc(gid, sid, name);
  if (parted) refresh();
  return interaction.reply({ ephemeral: true, allowedMentions: { parse: [] },
    content: parted ? `\u2705 ${label} has parted from **${name}**.` : `\u274C ${label} never stood with **${name}**.` });
}

async function handleTarget(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '\u274C Only GMs can set targets.', ephemeral: true });
  const sub = interaction.options.getSubcommand();
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');

  if (sub === 'list') {
    const rows = db.prepare('SELECT name, hits, dead FROM temp_targets WHERE guild_id=? AND channel_id=? ORDER BY at DESC LIMIT 20')
      .all(gid, interaction.channel.id);
    if (!rows.length) return interaction.reply({ ephemeral: true, content: '\u{1F5FF} Nothing standing here.' });
    return interaction.reply({ ephemeral: true, content: ['\u{1F5FF} **Targets here**', ...rows.map(r =>
      `${r.dead ? '\u{1FAA6}' : '\u2694\uFE0F'} **${r.name}** \u2014 ${r.hits} hit${r.hits === 1 ? '' : 's'}${r.dead ? ', fallen' : ''}`)].join('\n') });
  }

  const name = interaction.options.getString('name').trim();
  const dice = (interaction.options.getString('dice') || '').trim();
  const stat = interaction.options.getString('stat');
  const dc = interaction.options.getInteger('dc');
  const reason = (interaction.options.getString('reason') || '').trim();
  const forUser = interaction.options.getUser('for');
  const secret = interaction.options.getBoolean('secret') ? 1 : 0;
  if (dice && stat) return interaction.reply({ ephemeral: true, content: '\u274C Dice or a stat, not both.' });
  if (!dice && !stat) return interaction.reply({ ephemeral: true, content: '\u274C Give dice (`2d6+1`) or a stat to swing with.' });
  if (dice && !/^\d{0,2}d\d{1,3}([+-]\d{1,3})?$/i.test(dice))
    return interaction.reply({ ephemeral: true, content: '\u274C That is not dice I can read \u2014 try `2d6+1`.' });

  const face = dice || (stat === 'x' ? 'Flat d20' : STAT_LABELS[stat]);
  const head = [`\u2694\uFE0F **${name}** stands${dc ? ` \u2014 **${face}** against **DC ${dc}**` : ` \u2014 swing with **${face}**`}.`];
  if (reason) head.unshift(reason, '');
  if (forUser) head.unshift(`<@${forUser.id}> \u2014`);
  const msg = await interaction.channel.send({
    content: head.join('\n'),
    components: [new ActionRowBuilder().addComponents(new ButtonBuilder()
      .setCustomId('tgtatk').setLabel(`\u2694\uFE0F Attack ${name}`.slice(0, 80)).setStyle(ButtonStyle.Danger))],
    allowedMentions: forUser ? { users: [forUser.id] } : { parse: [] },
  }).catch(() => null);
  if (!msg) return interaction.reply({ ephemeral: true, content: '\u274C I could not post it here.' });

  // The button carries no state: the row keyed by its own message is the
  // target, so a restart loses nothing.
  db.prepare(`INSERT INTO temp_targets (guild_id, message_id, channel_id, name, dc, stat, dice, secret, owner, created_by, at)
              VALUES (?,?,?,?,?,?,?,?,?,?,?)`)
    .run(gid, msg.id, interaction.channel.id, name, dc || null, stat || null, dice || null, secret, forUser?.id || null, interaction.user.id, Date.now());
  try { noteQuestActivity(gid, interaction.channel.id, 'combat', `${name} stands as a target`, interaction.user.id); } catch {}
  return interaction.reply({ ephemeral: true, content: `\u2705 **${name}** is standing. Every hit will ask you whether it falls.` });
}

async function handleButton(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '\u274C Only GMs can plant buttons.', ephemeral: true });
  const sub = interaction.options.getSubcommand();
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  const prompt = (interaction.options.getString('prompt') || '').trim();
  const once = interaction.options.getBoolean('once') ? '1' : '0';
  // A button can be addressed to one player; anyone else pressing is
  // turned away (T, 2026-08-16). 'any' keeps the id slot filled so the
  // customId parses the same either way.
  const forUser = interaction.options.getUser?.('for');
  const owner = forUser?.id || 'any';

  if (sub === 'feedback') {
    const row = new ActionRowBuilder().addComponents(new ButtonBuilder()
      .setCustomId('btnfb').setLabel('\u{1F4DD} Send feedback').setStyle(ButtonStyle.Primary));
    await interaction.channel.send({ content: prompt || '\u{1F4DD} **Tell the GMs what you think** \u2014 only they will see it.',
      components: [row], allowedMentions: { parse: [] } });
    return interaction.reply({ ephemeral: true, content: '\u2705 Planted.' });
  }

  if (sub === 'roll') {
    // One leaf, T's order: dice or stat, an optional DC, the reason, then
    // who it is for. Dice and stat are alternatives — naming both is a
    // question with two answers, so it is refused rather than guessed.
    const dice = (interaction.options.getString('dice') || '').trim();
    const stat = interaction.options.getString('stat');
    const dc = interaction.options.getInteger('dc');
    const reason = (interaction.options.getString('reason') || '').trim();
    if (dice && stat)
      return interaction.reply({ ephemeral: true, content: '\u274C Dice or a stat, not both.' });
    if (!dice && !stat)
      return interaction.reply({ ephemeral: true, content: '\u274C Give dice (`2d6+1`) or a stat to roll.' });
    if (dice && !/^\d{0,2}d\d{1,3}([+-]\d{1,3})?$/i.test(dice))
      return interaction.reply({ ephemeral: true, content: '\u274C That is not dice I can read — try `2d6+1`.' });

    const faceName = dice || (stat === 'x' ? 'Flat d20' : STAT_LABELS[stat]);
    const label = (interaction.options.getString('label') || '').trim()
      || `\u{1F3B2} ${faceName}${dc ? ` vs DC ${dc}` : ''}`;
    const id = dice
      ? `btnroll:${dice}:${dc || 0}:${once}:${owner}`
      : `btnchk:${stat}:${dc || 0}:${once}:${owner}`;
    const row = new ActionRowBuilder().addComponents(new ButtonBuilder()
      .setCustomId(id).setLabel(label.slice(0, 80)).setStyle(ButtonStyle.Secondary));
    const addressed = forUser ? `<@${forUser.id}> — ` : '';
    const line = reason || (dc
      ? `\u{1F3AF} **${faceName}** against **DC ${dc}**.`
      : `\u{1F3B2} **${faceName}** — ${forUser ? 'yours to roll.' : 'anyone may roll.'}`);
    await interaction.channel.send({ content: addressed + line,
      components: [row],
      allowedMentions: forUser ? { users: [forUser.id] } : { parse: [] } });
    return interaction.reply({ ephemeral: true, content: '\u2705 Planted.' });
  }

  return interaction.reply({ ephemeral: true, content: '\u274C Unknown button.' });
}

// A press inside a quest's channel or thread joins that quest's timeline,
// and so reaches the GM's log when the run is completed. Outside a quest
// there is nothing to attach it to, so nothing is written (T, 2026-08-16).
async function logButtonPress(interaction, gid, uid, detail, passed) {
  try {
    const chId = interaction.channel?.id;
    const parentId = interaction.channel?.isThread?.() ? interaction.channel.parentId : null;
    const q = db.prepare(`SELECT number FROM quests WHERE guild_id=? AND status='active'
                            AND (run_channel_id=? OR run_thread_id=? OR run_channel_id=?) LIMIT 1`)
      .get(gid, chId, chId, parentId || chId);
    if (!q) return;
    const nm = await getDisplayName(interaction.guild, uid).catch(() => 'Someone');
    const mark = passed === null ? '' : passed ? ' \u2014 passed' : ' \u2014 failed';
    logQuestEvent(gid, q.number, 'roll', `${nm}: ${detail}${mark}`, uid);
  } catch {}
}

// One press each, when the GM asked for it.
function buttonPressGate(gid, messageId, uid) {
  const had = db.prepare('SELECT 1 FROM button_presses WHERE guild_id=? AND message_id=? AND user_id=?').get(gid, messageId, uid);
  if (had) return false;
  db.prepare('INSERT OR IGNORE INTO button_presses (guild_id, message_id, user_id, at) VALUES (?,?,?,?)')
    .run(gid, messageId, uid, Date.now());
  return true;
}

async function handleFeedback(interaction) {
  const gid = interaction.guild.id;
  const group = interaction.options.getSubcommandGroup(false);
  const sub = interaction.options.getSubcommand();

  if (group === 'category') {
    if (sub === 'list') {
      const types = feedbackTypes(gid), routes = feedbackRoutes(gid) || {};
      const rows = Object.entries(types).map(([k, t]) =>
        `${t.name} \u2014 ${routes[k] ? `<#${routes[k]}>` : '_no thread yet_'}`);
      return interaction.reply({ ephemeral: true, content: ['\u{1F4DD} **Feedback rooms**', ...rows].join('\n') });
    }
    if (!(await isGm(interaction.guild, interaction.user.id)))
      return interaction.reply({ content: '\u274C Only GMs can change the feedback rooms.', ephemeral: true });
    const name = interaction.options.getString('name').trim();
    const key = name.toLowerCase().replace(/[^a-z0-9]+/g, '').slice(0, 20);
    const cats = feedbackCats(gid);
    if (sub === 'add') {
      if (!key) return interaction.reply({ content: '\u274C That name has no letters in it.', ephemeral: true });
      if (FEEDBACK_TYPES_BASE[key] || cats.some(c => c.key === key))
        return interaction.reply({ content: `\u274C **${name}** already exists.`, ephemeral: true });
      cats.push({ key, name });
      setConfig(gid, { feedback_cats: JSON.stringify(cats) });
      await interaction.deferReply({ ephemeral: true });
      const res = await ensureFeedbackThreads(interaction.client, gid).catch(e => ({ error: e?.message }));
      return interaction.editReply({ content: res?.error
        ? `\u2705 **${name}** added \u2014 but its thread could not be made: ${res.error}`
        : `\u2705 **${name}** added \u2014 its thread is open and the room appears in \`/feedback send\` at once.` });
    }
    if (sub === 'remove') {
      const found = cats.find(c => c.key === key || c.name.toLowerCase() === name.toLowerCase());
      if (!found) return interaction.reply({ content: `\u274C No custom room named **${name}** \u2014 the seven built-in rooms cannot be retired.`, ephemeral: true });
      setConfig(gid, { feedback_cats: JSON.stringify(cats.filter(c => c !== found)) });
      return interaction.reply({ ephemeral: true, content: `\u2705 **${found.name}** retired \u2014 its thread and everything in it stays put.` });
    }
  }

  // `send` — the picker. Ephemeral, so no one else sees it happen. Named
  // explicitly rather than falling through, so a leaf added later cannot
  // silently land here (the scanner's unrouted-subcommand warning, made
  // moot 2026-08-16).
  if (sub !== 'send')
    return interaction.reply({ ephemeral: true, content: '\u274C Unknown feedback command.' });
  const types = feedbackTypes(gid);
  const routes = feedbackRoutes(gid);
  if (!routes?.forum && !getConfig(gid)?.feedback_forum)
    return interaction.reply({ ephemeral: true, content: '\u274C No feedback forum is set up yet \u2014 a GM needs `/gm check run`.' });
  const { ActionRowBuilder, StringSelectMenuBuilder } = require('discord.js');
  const menu = new StringSelectMenuBuilder().setCustomId('fbcat').setPlaceholder('Which room?')
    .addOptions(Object.entries(types).slice(0, 25).map(([k, t]) => ({ label: t.name.slice(0, 100), value: k, description: t.about?.slice(0, 100) })));
  return interaction.reply({ ephemeral: true, content: '\u{1F4DD} **Feedback** \u2014 pick a room, then score it and say your piece. Only the GMs will see it.',
    components: [new ActionRowBuilder().addComponents(menu)] });
}

// The card every route shares — GMs see who wrote it.
async function postFeedbackCard(interaction, gid, key, scale, body, extra = '') {
  let dest = feedbackDestination(gid, key);
  if (!dest) {
    await ensureFeedbackThreads(interaction.client, gid).catch(() => null);
    dest = feedbackDestination(gid, key);
  }
  if (!dest) return null;
  const ch = await interaction.client.channels.fetch(dest).catch(() => null);
  if (!ch) return null;
  const n = Math.max(1, Math.min(10, scale || 0));
  const bar = '\u2B50'.repeat(n) + '\u00B7'.repeat(10 - n);
  const nm = await getDisplayName(interaction.guild, interaction.user.id).catch(() => null);
  const pg = getCharPage(gid, interaction.user.id);
  const out = [
    `\u{1F4DD} **Feedback** \u2014 <@${interaction.user.id}>${nm ? ` (${nm})` : ''}`,
    `${bar}  **${n}/10**`,
    extra || '',
    '',
    body.slice(0, 1600),
    pg?.thread_id ? `\n\u{1F3F7}\uFE0F Their page: <#${pg.thread_id}>` : '',
  ].filter(Boolean).join('\n');
  return ch.send({ content: out, allowedMentions: { parse: [] } }).catch(() => null);
}

async function gmInterject(interaction) {
  const gid = interaction.guild.id, cid = interaction.channel.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '\u274C Only GMs can interject.', ephemeral: true });
  const fight = getFight(gid, cid);
  if (!fight) return interaction.reply({ content: '\u274C No fight in this channel.', ephemeral: true });
  const target = interaction.options.getUser('user');
  const amount = interaction.options.getInteger('amount') ?? 0;
  const mode = interaction.options.getString('mode');
  const forceStat = interaction.options.getString('stat');
  const die = interaction.options.getInteger('die');
  if (!amount && !mode && !forceStat && !die)
    return interaction.reply({ content: '\u274C Nothing to apply \u2014 give an amount, a mode, a stat, or a die.', ephemeral: true });
  const order = JSON.parse(fight.turn_order || '[]');
  if (!order.includes(target.id))
    return interaction.reply({ content: `\u274C <@${target.id}> is not in this fight.`, ephemeral: true });
  const note = (interaction.options.getString('note') || '').trim();
  const all = JSON.parse(fight.effect_state || '{}');
  const slot = all[target.id] ??= {};
  if (amount) {
    slot.gmAdj = (slot.gmAdj || 0) + amount;
    // Stacked interjections join their notes; bounded so a long chain
    // cannot push the exchange card past Discord's 2000 (audit, 2026-08-16).
    if (note) slot.gmAdjNote = (slot.gmAdjNote ? `${slot.gmAdjNote}; ${note}` : note).slice(0, 200);
  }
  if (forceStat) slot.gmStat = forceStat;
  upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
  // Advantage / disadvantage / flat rides the same mark the /gm mark tool
  // uses — consumed by their next roll, spoken on it as ever.
  if (mode) upsertChar(gid, target.id, { next_mark: mode });
  // The die declaration — the one lever that CAN rewrite a cast die. The
  // fight keeps natural and total apart until resolve, so the total
  // recomputes around their existing modifier, and every automatic (parry,
  // fumble, crit damage) honors the declared face.
  let dieLine = '';
  if (die) {
    const isAtk = JSON.parse(fight.turn_order || '[]')[fight.turn_index] === target.id && fight.atk_nat != null;
    const isDef = fight.current_target === target.id && fight.def_nat != null;
    if (!isAtk && !isDef)
      return interaction.reply({ content: '\u274C Nothing cast to override \u2014 `die:` only rewrites a roll already on the table.', ephemeral: true });
    const natKey = isAtk ? 'atk_nat' : 'def_nat', rollKey = isAtk ? 'atk_roll' : 'def_roll';
    const was = fight[natKey];
    const delta = die - was;
    upsertFight(gid, cid, { [natKey]: die, [rollKey]: (fight[rollKey] ?? was) + delta });
    dieLine = `; die declared **${die}** (was ${was})`;
  }
  const nm = await getDisplayName(interaction.guild, target.id);
  const parts = [];
  if (amount) parts.push(slot.gmAdj > 0 ? `+${slot.gmAdj}` : `${slot.gmAdj}`);
  if (mode) parts.push(mode === 'adv' ? 'advantage' : mode === 'dis' ? 'disadvantage' : 'a flat d20');
  if (forceStat) parts.push(`stat forced to ${STAT_LABELS[forceStat]}`);
  if (die) parts.push(`die declared ${die}`);
  const sign = parts.join(' \u00B7 ');
  await interaction.channel.send({ content: `\u2696\uFE0F **GM interjects:** **${nm}**'s pending or next roll: ${sign}${note ? ` \u2014 ${note}` : ''}`, allowedMentions: { parse: [] } }).catch(() => {});
  sendRollAudit(interaction.client, gid, `\u2696\uFE0F Interject \u2014 **${nm}** ${sign}${note ? ` \u00B7 ${note}` : ''} \u00B7 by ${interaction.user.tag}`);
  return interaction.reply({ content: `\u2705 Interjection recorded \u2014 ${sign} \u2014 on **${nm}**'s earliest unresolved roll (mode and stat bind the next roll made).`, ephemeral: true });
}

async function gmSkipTurn(guild, gid, cid, reason) {
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return null;
  const order = fightOrder(fight);
  const skippedId = order[fight.turn_index];
  const skipped = await resolveFighter(gid, skippedId);
  const hpState = fightHp(fight);
  const floor = hpFloor(gid);
  const clear = { phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null,
    def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0 };
  const lines = [`⏭ **${skipped?.displayName ?? 'Their'}**'s turn is skipped by the GM${reason ? ` — ${reason}` : ''}.`];
  const nextIndex = nextStandingIndex(order, hpState, floor, fight.turn_index + 1);
  await announceNextTurn(guild, gid, cid, lines, order, nextIndex);
  upsertFight(gid, cid, { ...clear, turn_index: nextIndex });
  sendRollAudit(guild.client, gid, `⏭ Override — **${skipped?.displayName ?? skippedId}**'s turn skipped${reason ? ` (${reason})` : ''} in <#${cid}>.`);
  return skipped?.displayName ?? skippedId;
}

// A feint's insight check resolves here, whoever rolled it. Ties go to the
// TARGET as written ("Failure: target's roll >= deceiver's"); a failed
// insight sets the fooled flag — the target's very next rolled action is a
// straight d20. No damage moves, so the turn simply passes.
async function resolveFeintInsight(guild, gid, cid, fight, { nat, total, mode = 'normal' }) {
  const turnOrder = fightOrder(fight);
  const attackerId = turnOrder[fight.turn_index];
  const targetId = fight.current_target;
  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  const atkF = await resolveFighter(guild, gid, attackerId);
  const defF = await resolveFighter(guild, gid, targetId);
  const atkName = atkF.name + (atkF.isNpc ? ' 🎭' : '');
  const defName = defF.name + (defF.isNpc ? ' 🎭' : '');
  const lines = ['─────────────────────────────', '🎭  **Feint Resolved**', ''];
  lines.push(`${atkName} (**WIS** feint): ${fightTotalStr(fight.atk_roll, fight.atk_nat, 20)}`);
  lines.push(`${defName} (**WIS** insight${mode === 'adv' ? ', advantage' : mode === 'dis' ? ', disadvantage' : ''}): ${fightTotalStr(total, nat, 20)}`);
  lines.push('');
  const fooled = fight.atk_roll > total;   // ties go to the target, as written
  if (fooled) {
    // A feint that lands IS a blow. The insight roll becomes the defence roll
    // and the ordinary exchange resolves it — same damage, same crit rules,
    // same knockout and log handling, so a feint can finish a fight.
    setEffectFlag(gid, cid, targetId, 'fooled');
    lines.push(`🎭 **${defName}** is **completely fooled** — the real blow follows!`);
    lines.push(`_And their very next rolled action is a straight d20, no bonuses._`);
    lines.push(`_🎭 Trade-off: **${atkName}**'s next defence roll is a flat d20._`);
    setEffectFlag(gid, cid, attackerId, 'flatDef');
    upsertFight(gid, cid, { def_roll: total, def_nat: nat, def_stat: 'wis', def_mode: mode, def_sides: 20 });
    const res = await resolveExchange(guild, gid, cid, getFight(gid, cid));
    return { lines: [...lines, ...res.lines], nextF: res.nextF, fooled: true, ended: res.ended };
  }
  {
    lines.push(`👁️ **${defName}** sees through the feint — combat continues normally.`);
  }
  lines.push(`_🎭 Trade-off: **${atkName}**'s next defence roll is a flat d20._`);
  const clear = { phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null,
    def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0 };
  const nextIndex = nextStandingIndex(turnOrder, hpState, floor, fight.turn_index + 1);
  const nextF = await announceNextTurn(guild, gid, cid, lines, turnOrder, nextIndex);
  upsertFight(gid, cid, { ...clear, turn_index: nextIndex });
  // The deceiver pays the flat-defence trade-off whether the feint took or not.
  setEffectFlag(gid, cid, attackerId, 'flatDef');
  return { lines, nextF, fooled };
}

// Auto-pilot wrapper: posts to the channel. Returns whether the fight goes on.
async function autoResolveExchange(guild, gid, cid, channel) {
  let fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active' || fight.phase !== 'defend' || fight.def_roll === null) return false;

  fight = await applyAutoNpcRerolls(guild, gid, cid, channel);
  if (!fight || fight.state !== 'active') return false;

  const r = await resolveExchange(guild, gid, cid, fight);
  await sendLong(channel, r.lines);
  if (r.ended) await announceFightEnd(guild, gid, cid, channel, r.announce);
  return !r.ended;
}

// Drive automatic NPC actions in an NPCs-only fight: take NPC attacks,
// auto-defend when an NPC is the target, and resolve — looping until a
// player needs to act or the fight ends.
async function runAutoNpcChain(guild, gid, cid, channel) {
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  let safety = 0;
  while (safety++ < 300) {
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active' || !fight.auto_npc) return;
    if (fight.phase === 'attack') {
      const acted = await runAutoNpcTurn(guild, gid, cid, channel);
      if (!acted) return; // a player's turn — wait for them
      await sleep(1100);
    } else if (fight.phase === 'defend') {
      if (!isNpcFighter(fight.current_target)) return; // a player defends manually
      const defended = await autoNpcDefend(guild, gid, cid, channel);
      if (!defended) return;
      await sleep(900);
      const cont = await autoResolveExchange(guild, gid, cid, channel);
      if (!cont) return;
      await sleep(1100);
    } else return;
  }
  // Safety cap reached — tell the GM instead of stalling silently
  await channel.send('⚠️ Auto chain paused after a very long fight (safety limit). Use `/fight status` to review, `/fight resolve` to continue a pending exchange, or `/fight end`.').catch(()=>{});
}

// ── Shared attack executor ───────────────────────────────────────────────
// The whole strike — validation, roll, card, phase flip — lifted out of the
// atk subcommand so two surfaces share one path:
//   · handleFight 'atk' (slash command; turn/actor already validated upstream,
//     so the re-checks here pass straight through)
//   · the fighttarget: select menu, where the fight may have moved on between
//     the menu appearing and the click — every gate is re-checked before any
//     die is thrown.
// `refuse` adapts to the surface: ephemeral reply for the command, an in-place
// update that also strips the stale menu for the picker.
async function runFightAttack({ interaction, gid, cid, actorId, targetId, stat, mode, flavour }) {
  // A GM interjection can force the stat — consumed HERE so every caller
  // (slash command and the target-picker button replay) obeys it.
  let gmStatNote = '';
  {
    const forced = consumeGmStat(gid, cid, actorId);
    if (forced && forced !== stat) { gmStatNote = ` \u2696\uFE0F stat set to ${STAT_LABELS[forced]} by the GM`; stat = forced; }
    else if (forced) { gmStatNote = ` \u2696\uFE0F GM confirmed ${STAT_LABELS[forced]}`; }
  }

  const uid = interaction.user.id;
  const fromMenu = !!interaction.isStringSelectMenu?.();
  const refuse = (content) => fromMenu
    ? interaction.update({ components: [], content })
    : interaction.reply({ content, ephemeral: true });

  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);

  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);

  if (isNpcFighter(actorId) && !(await isGm(interaction.guild, uid))) {
    return refuse('❌ Only GMs can act as an NPC.');
  }
  {
    const gate0 = deathGate(gid, actorId);
    if (gate0) return refuse(gate0);
  }
  const turnOrder = fightOrder(fight);
  const currentId = turnOrder[fight.turn_index];
  if (currentId !== actorId) {
    const cur = await resolveFighter(interaction.guild, gid, currentId);
    return refuse(`⚠️ It's **${cur.name}**'s turn to attack.`);
  }
  if (fight.phase !== 'attack') return refuse(fight.atk_kind === 'grapple'
    ? '🤼 A grapple is pending — the target answers with `/fight act action:Save` (STR only).'
    : fight.atk_kind === 'feint'
    ? '🎭 A feint is pending — the target answers with `/fight act action:Insight` (WIS only).'
    : '❌ Waiting for defender to roll first.');
  if (!isNpcFighter(actorId)) {
    const gateMsg = sheetGate(gid, actorId);
    if (gateMsg && !(await isGm(interaction.guild, uid))) return refuse(gateMsg);
  }
  {
    // What you are carrying decides what you can swing, shoot or brace with.
    const refusal = weaponStatRefusal(gid, pageSubject(gid, actorId), 'atk', stat);
    if (refusal) return refuse(refusal);
  }
  if (!turnOrder.includes(targetId)) return refuse('❌ That target is not in this fight.');
  if (targetId === actorId) return refuse('❌ You cannot target yourself.');

  const hpState = fightHp(fight);
  const atkFloor = fightFloor(fight);
  if (hpState[targetId] !== undefined && hpState[targetId] <= atkFloor) {
    return refuse(atkFloor > 0 ? '❌ That fighter has already yielded the bout.' : '❌ That target is already down.');
  }

    // Grapple rules on the attack path: a holder cannot strike their captive,
    // and a held fighter swings on a flat d20 — no stat, no riposte, no edge.
    if (grappleHolderOf(fight, targetId) === actorId) {
      return refuse('🤼 You are holding them — a grappler cannot strike their captive. `/fight act action:Release` first (it costs nothing).');
    }
    const restrained = !!grappleHolderOf(fight, actorId);
    // A deflection's trade-off: the very next attack roll is a flat d20.
    const offBalance = !restrained && consumeFlatAtk(gid, cid, actorId);
    const fooledA = consumeFooled(gid, cid, actorId) || consumeFlatMark(gid, actorId);
    const flatSwing = restrained || offBalance || fooledA;
    clearRoundFlag(gid, cid, actorId);
    if (await retrievalTurn(interaction.guild, gid, cid, actorId,
        async (l) => interaction.reply({ content: l.join('\n') }))) {
      return kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
    }
    const actor = await resolveFighter(interaction.guild, gid, actorId);
    const targetF = await resolveFighter(interaction.guild, gid, targetId);
    // Under 5e a monster adds the bonus off its statblock, and a character
    // adds their ability modifier plus proficiency — never the raw score.
    const rulesAtk = rulesFor(gid);
    let statVal;
    if (flatSwing) statVal = 0;
    else if (rulesAtk.defence === 'ac') {
      const rowA = actor.isNpc ? getNpc(gid, actor.name) : getChar(gid, actorId);
      const rowD = targetF?.isNpc ? getNpc(gid, targetF.name) : (targetId ? getChar(gid, targetId) : null);
      mode = conditionMode(rulesAtk, rowA, rowD, mode);
      const monster = rulesAtk.monsterAttack(rowA);
      statVal = monster != null ? monster
              : rulesAtk.statBonus(rowA, stat) + rulesAtk.profBonus(rowA);
    } else statVal = (actor.stats[stat] ?? 0);
    // Consume a pending riposte bonus from a previous nat-20 defence.
    const atkBonus = flatSwing ? 0 : consumeAtkBonus(gid, cid, actorId);
    // Hero signature advantage (players and Hero NPCs alike)
    const sigRowA = isNpcFighter(actorId) ? getNpc(gid, npcNameFromFighter(actorId)) : getChar(gid, actorId);
    mode = flatSwing ? 'normal' : applySignatureMode(sigRowA, stat, mode);
    mode = applyNextMark(gid, actorId, mode);
    const effTotal = statVal + atkBonus;
    const bonusTag = atkBonus ? ` +${atkBonus} riposte` : '';
    const modStr = effTotal > 0 ? ` +${effTotal}` : effTotal < 0 ? ` ${effTotal}` : '';

    let nat, dropped = null, advNote = restrained ? ' 🤼 restrained — flat d20' : offBalance ? ' 🛡️ off-balance — flat d20' : fooledA ? ' 🎭 fooled — flat d20' : '';
    if (mode === 'adv') {
      const r1 = rollDie(20), r2 = rollDie(20);
      nat = Math.max(r1, r2); dropped = Math.min(r1, r2); advNote = ' (advantage)';
    } else if (mode === 'dis') {
      const r1 = rollDie(20), r2 = rollDie(20);
      nat = Math.min(r1, r2); dropped = Math.max(r1, r2); advNote = ' (disadvantage)';
    } else {
      nat = rollDie(20);
    }
    const total = nat + effTotal;
    const diceBit = dropped === null ? `[${nat}]` : `[${nat}, ~~${dropped}~~]`;
    // Two renderings of the same throw: the full line is what the audit keeps;
    // when this server hides NPC stats, the public card drops the stat name
    // and modifier — same convention as the auto-pilot cards.
    const lineFor = (show) => `⚔️  1d20${show ? `+${STAT_LABELS[stat]}` : ''}${bonusTag}${advNote} → ${diceBit}${show ? modStr : ''} = ${fightTotalStr(total, nat, 20)}`;
    const rollLine = lineFor(true);
    const publicLine = (actor.isNpc && !npcStatsVisible(gid)) ? lineFor(false) : rollLine;
    const targetName = targetF.name + (targetF.isNpc ? ' 🎭' : '');
    const critType = nat === 20 ? 'crit' : (nat === 1 ? 'fail' : null);
    const actorCard = await fighterCharCard(interaction.guild, gid, actorId);

    const headerLabel = `⚔️ Attacks ${targetName} with ${STAT_LABELS[stat]}${gmStatNote}`;
    const card = styledFightCard(gid, actorId, {
      rollLine: publicLine, label: headerLabel, isReroll: false,
      char: actorCard, healCharges: 0, maxCharges: 0,
      flavour: flavour || null, total, critType, tags: null, gid,
    });
    // The audit's copy: the same card with every number shown.
    const auditCard = actor.isNpc ? buildRollEmbed({
      rollLine, label: headerLabel, isReroll: false,
      char: actorCard, healCharges: 0, maxCharges: 0,
      flavour: flavour || null, total, critType, tags: null, gid, reveal: true,
    }) : null;
    const autoOn = !!fight.auto_npc;
    const defHint = targetF.isNpc
      ? (autoOn ? `🤖 **${targetF.name}** defends automatically...` : `🛡️ A GM defends for **${targetF.name}** with \`/fight def npc:${targetF.name}\`.`)
      : `🛡️ <@${targetId}> — \`/fight def stat:dex\`, or \`/roll dice:2d6 fight:true\` for a custom roll.`;

    // In 5e nobody rolls to defend: the blow is measured against Armour
    // Class. The AC takes the defence slot and the exchange resolves at once.
    const rulesA = rulesFor(gid);
    if (rulesA.defence === 'ac') {
      const defRow = targetF.isNpc ? getNpc(gid, npcNameFromFighter(targetId)) : getChar(gid, targetId);
      const ac = rulesA.targetNumber(defRow);
      upsertFight(gid, cid, {
        phase: 'defend', current_target: targetId,
        atk_roll: total, atk_nat: nat, atk_stat: stat, atk_mode: mode, atk_sides: 20,
        def_roll: ac, def_nat: 0, def_stat: 'ac', def_mode: 'normal',
        atk_rerolled: 0, def_rerolled: 0,
      });
      // Those who fight for a living swing more than once, so the turn is
      // held until the action is spent.
      const rowSelf = actor.isNpc ? getNpc(gid, actor.name) : getChar(gid, actorId);
      const allowed = actor.isNpc ? 1 : rulesA.attacksPerAction(rowSelf);
      const usedSoFar = (Number(fight.atk_used) || 0) + 1;
      const heldIndex = fight.turn_index;
      const res = await resolveExchange(interaction.guild, gid, cid, getFight(gid, cid));
      const head = `⚔️  **${actor.name}** strikes at **${targetF.name}** — ${fightTotalStr(total, nat, 20)} vs **AC ${ac}**`;
      const extra = [];
      const after = getFight(gid, cid);
      if (usedSoFar < allowed && after?.state === 'active' && !res.ended) {
        upsertFight(gid, cid, { turn_index: heldIndex, phase: 'attack', current_target: null, atk_used: usedSoFar });
        extra.push(`⚔️ **Attack ${usedSoFar} of ${allowed}** — swing again.`);
      } else {
        upsertFight(gid, cid, { atk_used: 0 });
      }
      await interaction.reply({ content: [head, ...res.lines, ...extra].join('\n') });
      return kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
    }
    upsertFight(gid, cid, {
      phase: 'defend', current_target: targetId,
      atk_roll: total, atk_nat: nat, atk_stat: stat, atk_mode: mode, atk_sides: 20,
      def_roll: null, def_nat: null, def_stat: null, def_mode: 'normal',
      atk_rerolled: 0, def_rerolled: 0,
    });
    if (!actor.isNpc) saveRoll(gid, cid, uid, `1d20+${statVal}`, `atk ${STAT_LABELS[stat]}`);
    // The audit mirror links to the public card. Webhook and follow-up posts
    // can't be resolved via fetchReply, so their ids are captured here; a plain
    // public slash reply stays null and the mirror falls back to fetchReply.
    let auditMsgId = null;
    if (actor.isNpc) {
      // Menu path: ack the picker first (interaction tokens are short-lived),
      // then post the NPC's card through its webhook. Slash path keeps its
      // original order: card, hint, then the private ack.
      if (fromMenu) await interaction.update({ components: [], content: `✅ Attacked as **${actor.name}**.` })
        .catch(err => console.error('[fighttarget] ack', err?.message || err));
      const npcMsg = await postAsNpc(chan, gid, actor.name, card);
      auditMsgId = npcMsg?.id ?? null;
      await chan.send({ content: defHint, components: fightAnswerRows('def', { forNpc: targetF.isNpc }) }).catch(()=>{});
      if (!fromMenu) await interaction.reply({ content: `✅ Attacked as **${actor.name}**.`, ephemeral: true });
    } else if (fromMenu) {
      // The picker message is ephemeral, so the card can't live there: collapse
      // the menu in place and send the card as a public follow-up.
      await interaction.update({ components: [], content: `🎯 **${targetName}** it is.` })
        .catch(err => console.error('[fighttarget] ack', err?.message || err));
      const pub = await interaction.followUp({ content: `${card}\n\n${defHint}`, ephemeral: false });
      auditMsgId = pub?.id ?? null;
    } else {
      await interaction.reply({ content: `${card}\n\n${defHint}`, components: fightAnswerRows('def', { forNpc: targetF.isNpc }) });
    }
    recordRoll(gid, { userId: uid, channelId: cid, interaction, messageId: auditMsgId,
      kind: isNpcFighter(actorId) ? 'npcs' : null, card: auditCard,
      input: `/fight atk stat:${stat}${isNpcFighter(actorId) ? ` npc:${actor.name}` : ''}`, rollLine, nat, sides: 20,
      context: isNpcFighter(actorId) ? `fight · GM as ${actor.name} 🎭 attacks ${targetF.name}` : `fight · attacks ${targetF.name}` });
    // NPCs-only mode: the bot rolls the targeted NPC's defence and resolves.
    if (autoOn && targetF.isNpc) {
      await new Promise(r=>setTimeout(r,1200));
      await runAutoNpcChain(interaction.guild, gid, cid, chan);
    }
    return;
}

// ── Grappling ────────────────────────────────────────────────────────
// STR-only, contested. The attempt fills the same pending-attack slot as a
// normal strike (atk_kind 'grapple'); the save resolves it; a held fighter
// pays 1 strain when their own turn ends (the resolver and escape both apply
// it); the holder may release freely and can never strike their captive.

// One d20 under a roll mode: {nat, dropped}. The grapple family shares it.
function rollD20Mode(mode) {
  if (mode === 'adv') { const r1 = rollDie(20), r2 = rollDie(20); return { nat: Math.max(r1, r2), dropped: Math.min(r1, r2) }; }
  if (mode === 'dis') { const r1 = rollDie(20), r2 = rollDie(20); return { nat: Math.min(r1, r2), dropped: Math.max(r1, r2) }; }
  return { nat: rollDie(20), dropped: null };
}

async function runFightGrapple({ interaction, gid, cid, actorId, targetId, mode, flavour }) {
  const uid = interaction.user.id;
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  if (isNpcFighter(actorId) && !(await isGm(interaction.guild, uid))) return refuse('❌ Only GMs can act as an NPC.');
  {
    const gate0 = deathGate(gid, actorId);
    if (gate0) return refuse(gate0);
  }
  const turnOrder = fightOrder(fight);
  if (turnOrder[fight.turn_index] !== actorId) {
    const cur = await resolveFighter(interaction.guild, gid, turnOrder[fight.turn_index]);
    return refuse(`⚠️ It's **${cur.name}**'s turn to attack.`);
  }
  if (fight.phase !== 'attack') return refuse(fight.atk_kind === 'grapple'
    ? '🤼 A grapple is already pending — the target answers with `/fight act action:Save`.'
    : '❌ Waiting for defender to roll first.');
  if (!isNpcFighter(actorId)) {
    const gateMsg = sheetGate(gid, actorId);
    if (gateMsg && !(await isGm(interaction.guild, uid))) return refuse(gateMsg);
  }
  if (!turnOrder.includes(targetId)) return refuse('❌ That target is not in this fight.');
  if (targetId === actorId) return refuse('❌ You cannot target yourself.');
  if (grappleHeldTargetOf(fight, actorId)) return refuse('🤼 You are already holding someone — `/fight act action:Release` first.');
  if (grappleHolderOf(fight, actorId)) return refuse('🤼 You are held — `/fight act action:Escape`, or act on a flat d20.');
  if (grappleHolderOf(fight, targetId)) return refuse('🤼 They are already held.');

  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  if (hpState[targetId] !== undefined && hpState[targetId] <= floor) {
    return refuse(floor > 0 ? '❌ That fighter has already yielded the bout.' : '❌ That target is already down.');
  }

  // A grapple attempt is an attack roll — the deflection and feint penalties
  // clamp it too.
  const offBalance = consumeFlatAtk(gid, cid, actorId) || consumeFooled(gid, cid, actorId) || consumeFlatMark(gid, actorId);
  clearRoundFlag(gid, cid, actorId);
  if (await retrievalTurn(interaction.guild, gid, cid, actorId,
      async (l) => interaction.reply({ content: l.join('\n') }))) {
    return kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
  }
  const actor = await resolveFighter(interaction.guild, gid, actorId);
  const targetF = await resolveFighter(interaction.guild, gid, targetId);
  const statVal = offBalance ? 0 : (actor.stats.str ?? 0);
  const sigRowA = isNpcFighter(actorId) ? getNpc(gid, npcNameFromFighter(actorId)) : getChar(gid, actorId);
  mode = offBalance ? 'normal' : applySignatureMode(sigRowA, 'str', mode);
  mode = applyNextMark(gid, actorId, mode);
  const modStr = statVal > 0 ? ` +${statVal}` : statVal < 0 ? ` ${statVal}` : '';

  const { nat, dropped } = rollD20Mode(mode);
  const advNote = offBalance ? ' 🛡️ off-balance — flat d20' : mode === 'adv' ? ' (advantage)' : mode === 'dis' ? ' (disadvantage)' : '';
  const total = nat + statVal;
  const diceBit = dropped !== null ? `[${nat}~~${dropped}~~]` : `[${nat}]`;
  const lineFor = (show) => `🤼  1d20${show ? '+STR' : ''}${advNote} → ${diceBit}${show ? modStr : ''} = ${fightTotalStr(total, nat, 20)}`;
  const rollLine = lineFor(true);
  const publicLine = (actor.isNpc && !npcStatsVisible(gid)) ? lineFor(false) : rollLine;
  const targetName = targetF.name + (targetF.isNpc ? ' 🎭' : '');
  const critType = nat === 20 ? 'crit' : (nat === 1 ? 'fail' : null);
  const actorCard = await fighterCharCard(interaction.guild, gid, actorId);

  const headerLabel = `🤼 Attempts to grapple ${targetName}`;
  const card = styledFightCard(gid, actorId, {
    rollLine: publicLine, label: headerLabel, isReroll: false,
    char: actorCard, healCharges: 0, maxCharges: 0,
    flavour: flavour || null, total, critType, tags: null, gid,
  });
  const auditCard = actor.isNpc ? buildRollEmbed({
    rollLine, label: headerLabel, isReroll: false,
    char: actorCard, healCharges: 0, maxCharges: 0,
    flavour: flavour || null, total, critType, tags: null, gid, reveal: true,
  }) : null;
  const autoOn = !!fight.auto_npc;
  const saveHint = targetF.isNpc
    ? (autoOn ? `🤖 **${targetF.name}** saves automatically...` : `🤼 A GM saves for **${targetF.name}** with \`/fight act action:Save npc:${targetF.name}\`.`)
    : `🤼 <@${targetId}> — \`/fight act action:Save\` (STR only) to resist the hold.`;

  upsertFight(gid, cid, {
    phase: 'defend', current_target: targetId, atk_kind: 'grapple',
    atk_roll: total, atk_nat: nat, atk_stat: 'str', atk_mode: mode, atk_sides: 20,
    def_roll: null, def_nat: null, def_stat: null, def_mode: 'normal',
    atk_rerolled: 0, def_rerolled: 0,
  });
  if (!actor.isNpc) saveRoll(gid, cid, uid, `1d20+${statVal}`, 'grapple STR');
  let auditMsgId = null;
  if (actor.isNpc) {
    const npcMsg = await postAsNpc(chan, gid, actor.name, card);
    auditMsgId = npcMsg?.id ?? null;
    await chan.send({ content: saveHint, components: fightAnswerRows('save', { forNpc: targetF.isNpc }) }).catch(()=>{});
    await interaction.reply({ content: `✅ Grappled as **${actor.name}**.`, ephemeral: true });
  } else {
    await interaction.reply({ content: `${card}\n\n${saveHint}`, components: fightAnswerRows('save', { forNpc: targetF.isNpc }) });
  }
  recordRoll(gid, { userId: uid, channelId: cid, interaction, messageId: auditMsgId,
    kind: isNpcFighter(actorId) ? 'npcs' : null, card: auditCard,
    input: `/fight act action:Grapple${isNpcFighter(actorId) ? ` npc:${actor.name}` : ''}`, rollLine, nat, sides: 20,
    context: isNpcFighter(actorId) ? `fight · GM as ${actor.name} 🎭 grapples ${targetF.name}` : `fight · grapples ${targetF.name}` });
  if (autoOn && targetF.isNpc) {
    await new Promise(r=>setTimeout(r,1200));
    await runAutoNpcChain(interaction.guild, gid, cid, chan);
  }
  return;
}

// Deception — the feint. An attack-phase action, WIS-only, WIS 4+ gate,
// PvE and PvP alike, no weapon needed. The required feint: text is the
// declaration: what you pretend to do. A held fighter cannot feint.
async function runFightFeint({ interaction, gid, cid, actorId, targetId, feintText, mode, flavour }) {
  const uid = interaction.user.id;
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  if (isNpcFighter(actorId) && !(await isGm(interaction.guild, uid))) return refuse('❌ Only GMs can act as an NPC.');
  {
    const gate0 = deathGate(gid, actorId);
    if (gate0) return refuse(gate0);
  }
  const turnOrder = fightOrder(fight);
  if (turnOrder[fight.turn_index] !== actorId) {
    const cur = await resolveFighter(interaction.guild, gid, turnOrder[fight.turn_index]);
    return refuse(`⚠️ It's **${cur.name}**'s turn to attack, or a strike must be pending on you to read one.`);
  }
  if (fight.phase !== 'attack') return refuse(fight.atk_kind === 'feint'
    ? '🎭 A feint is already pending — the target answers with `/fight act action:Insight`.'
    : '❌ Waiting for defender to roll first.');
  if (!isNpcFighter(actorId)) {
    const gateMsg = sheetGate(gid, actorId);
    if (gateMsg && !(await isGm(interaction.guild, uid))) return refuse(gateMsg);
  }
  if (!turnOrder.includes(targetId)) return refuse('❌ That target is not in this fight.');
  if (targetId === actorId) return refuse('❌ You cannot target yourself.');
  if (grappleHolderOf(fight, actorId)) return refuse('🤼 You are held — flat-d20 strikes or `/fight act action:Escape` only; no feinting from a hold.');

  const actor = await resolveFighter(interaction.guild, gid, actorId);
  const subjectRow = isNpcFighter(actorId) ? getNpc(gid, npcNameFromFighter(actorId)) : getChar(gid, actorId);
  const barF = abilityNeeds(gid, 'feint');
  if (belowBar(actor.stats, barF)) return refuse(`🎭 Deception needs **${barF.label} ${barF.need}+** — the mind has to be sharp.`);
  // A feint is an attack roll: the deflection trade-off and an earlier feint
  // that fooled YOU both clamp it flat.
  const flatFeint = consumeFlatAtk(gid, cid, actorId) || consumeFooled(gid, cid, actorId) || consumeFlatMark(gid, actorId);
  const targetF = await resolveFighter(interaction.guild, gid, targetId);

  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  if (hpState[targetId] !== undefined && hpState[targetId] <= floor) {
    return refuse(floor > 0 ? '❌ That fighter has already yielded the bout.' : '❌ That target is already down.');
  }

  const statVal = flatFeint ? 0 : (actor.stats.wis ?? 0);
  mode = flatFeint ? 'normal' : applySignatureMode(subjectRow, 'wis', mode);
  mode = applyNextMark(gid, actorId, mode);
  const modStr = statVal > 0 ? ` +${statVal}` : statVal < 0 ? ` ${statVal}` : '';
  const { nat, dropped } = rollD20Mode(mode);
  const advNote = flatFeint ? ' 🎭 flat d20' : mode === 'adv' ? ' (advantage)' : mode === 'dis' ? ' (disadvantage)' : '';
  const total = nat + statVal;
  const diceBit = dropped !== null ? `[${nat}~~${dropped}~~]` : `[${nat}]`;
  const lineFor = (show) => `🎭  1d20${show ? '+WIS' : ''}${advNote} → ${diceBit}${show ? modStr : ''} = ${fightTotalStr(total, nat, 20)}`;
  const rollLine = lineFor(true);
  const publicLine = (actor.isNpc && !npcStatsVisible(gid)) ? lineFor(false) : rollLine;
  const targetName = targetF.name + (targetF.isNpc ? ' 🎭' : '');
  const critType = nat === 20 ? 'crit' : (nat === 1 ? 'fail' : null);
  const actorCard = await fighterCharCard(interaction.guild, gid, actorId);

  const headerLabel = `🎭 Feints at ${targetName}`;
  const card = styledFightCard(gid, actorId, {
    rollLine: publicLine, label: headerLabel, isReroll: false,
    char: actorCard, healCharges: 0, maxCharges: 0,
    flavour: flavour ? `${feintText} — ${flavour}` : feintText, total, critType, tags: null, gid,
  });
  const auditCard = actor.isNpc ? buildRollEmbed({
    rollLine, label: headerLabel, isReroll: false,
    char: actorCard, healCharges: 0, maxCharges: 0,
    flavour: flavour ? `${feintText} — ${flavour}` : feintText, total, critType, tags: null, gid, reveal: true,
  }) : null;
  const autoOn = !!fight.auto_npc;
  const insightHint = targetF.isNpc
    ? (autoOn ? `🤖 **${targetF.name}** checks its insight automatically...` : `🎭 A GM rolls insight for **${targetF.name}** with \`/fight act action:Insight npc:${targetF.name}\`.`)
    : `🎭 <@${targetId}> — \`/fight act action:Insight\` (WIS only) to see through it.`;

  setEffectFlag(gid, cid, actorId, 'feintUsed');
  spendDeception(gid, actorId);
  upsertFight(gid, cid, {
    phase: 'defend', current_target: targetId, atk_kind: 'feint',
    atk_roll: total, atk_nat: nat, atk_stat: 'wis', atk_mode: mode, atk_sides: 20,
    def_roll: null, def_nat: null, def_stat: null, def_mode: 'normal',
    atk_rerolled: 0, def_rerolled: 0,
  });
  if (!actor.isNpc) saveRoll(gid, cid, uid, `1d20+${statVal}`, 'feint WIS');
  let auditMsgId = null;
  if (actor.isNpc) {
    const npcMsg = await postAsNpc(chan, gid, actor.name, card);
    auditMsgId = npcMsg?.id ?? null;
    await chan.send({ content: insightHint, components: fightAnswerRows('insight', { forNpc: targetF.isNpc }) }).catch(()=>{});
    await interaction.reply({ content: `✅ Feinted as **${actor.name}**.`, ephemeral: true });
  } else {
    await interaction.reply({ content: `${card}\n\n${insightHint}`, components: fightAnswerRows('insight', { forNpc: targetF.isNpc }) });
  }
  recordRoll(gid, { userId: uid, channelId: cid, interaction, messageId: auditMsgId,
    kind: isNpcFighter(actorId) ? 'npcs' : null, card: auditCard,
    input: `/fight act action:Feint${isNpcFighter(actorId) ? ` npc:${actor.name}` : ''}`, rollLine, nat, sides: 20,
    context: isNpcFighter(actorId) ? `fight · GM as ${actor.name} 🎭 feints at ${targetF.name}` : `fight · feints at ${targetF.name}` });
  if (autoOn && targetF.isNpc) {
    await new Promise(r=>setTimeout(r,1200));
    await runAutoNpcChain(interaction.guild, gid, cid, chan);
  }
  return;
}

async function runFightInsight({ interaction, gid, cid, actorId, mode }) {
  const uid = interaction.user.id;
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  if (fight.phase !== 'defend' || fight.atk_kind !== 'feint') return refuse('❌ No feint to see through.');
  if (isNpcFighter(actorId) && !(await isGm(interaction.guild, uid))) return refuse('❌ Only GMs can act as an NPC.');
  if (fight.current_target !== actorId) {
    const t = await resolveFighter(interaction.guild, gid, fight.current_target);
    return refuse(`⚠️ The feint is aimed at **${t.name}** — the insight is theirs.`);
  }
  const actor = await resolveFighter(interaction.guild, gid, actorId);
  // Already fooled from an earlier feint? Even the insight rolls flat.
  const fooledI = consumeFooled(gid, cid, actorId) || consumeFlatMark(gid, actorId);
  const statVal = fooledI ? 0 : (actor.stats.wis ?? 0);
  const sigRow = isNpcFighter(actorId) ? getNpc(gid, npcNameFromFighter(actorId)) : getChar(gid, actorId);
  mode = fooledI ? 'normal' : applySignatureMode(sigRow, 'wis', mode);
  mode = applyNextMark(gid, actorId, mode);
  const { nat, dropped } = rollD20Mode(mode);
  const total = nat + statVal;
  const diceBit = dropped !== null ? `[${nat}~~${dropped}~~]` : `[${nat}]`;
  const rollLine = `🎭  1d20${fooledI ? '' : '+WIS'} (insight)${fooledI ? ' 🎭 fooled — flat d20' : ''} → ${diceBit}${statVal ? ` +${statVal}` : ''} = ${fightTotalStr(total, nat, 20)}`;
  if (!actor.isNpc) saveRoll(gid, cid, uid, `1d20+${statVal}`, 'feint insight WIS');
  recordRoll(gid, { userId: uid, channelId: cid, interaction,
    kind: isNpcFighter(actorId) ? 'npcs' : null, card: null,
    input: `/fight act action:Insight${isNpcFighter(actorId) ? ` npc:${actor.name}` : ''}`, rollLine, nat, sides: 20,
    context: isNpcFighter(actorId) ? `fight · GM as ${actor.name} 🎭 feint insight` : 'fight · feint insight' });
  const r = await resolveFeintInsight(interaction.guild, gid, cid, fight, { nat, total, mode });
  if (actor.isNpc) {
    await sendLong(chan, r.lines);
    await interaction.reply({ content: `✅ Insight rolled as **${actor.name}**.`, ephemeral: true });
  } else {
    await replyLong(interaction, r.lines);
  }
  await kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
  return;
}

async function runFightGrappleSave({ interaction, gid, cid, actorId, mode }) {
  const uid = interaction.user.id;
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  if (fight.phase !== 'defend' || fight.atk_kind !== 'grapple') return refuse('❌ No grapple to save against.');
  if (isNpcFighter(actorId) && !(await isGm(interaction.guild, uid))) return refuse('❌ Only GMs can act as an NPC.');
  if (fight.current_target !== actorId) {
    const t = await resolveFighter(interaction.guild, gid, fight.current_target);
    return refuse(`⚠️ The grapple is on **${t.name}** — the save is theirs.`);
  }
  const actor = await resolveFighter(interaction.guild, gid, actorId);
  const fooledR = consumeFooled(gid, cid, actorId) || consumeFlatMark(gid, actorId);
  const statVal = fooledR ? 0 : (actor.stats.str ?? 0);
  const sigRow = isNpcFighter(actorId) ? getNpc(gid, npcNameFromFighter(actorId)) : getChar(gid, actorId);
  mode = fooledR ? 'normal' : applySignatureMode(sigRow, 'str', mode);
  const { nat, dropped } = rollD20Mode(mode);
  const total = nat + statVal;
  const diceBit = dropped !== null ? `[${nat}~~${dropped}~~]` : `[${nat}]`;
  const rollLine = `🤼  1d20+STR (save) → ${diceBit}${statVal ? ` +${statVal}` : ''} = ${fightTotalStr(total, nat, 20)}`;
  if (!actor.isNpc) saveRoll(gid, cid, uid, `1d20+${statVal}`, 'grapple save STR');
  recordRoll(gid, { userId: uid, channelId: cid, interaction,
    kind: isNpcFighter(actorId) ? 'npcs' : null, card: null,
    input: `/fight act action:Save${isNpcFighter(actorId) ? ` npc:${actor.name}` : ''}`, rollLine, nat, sides: 20,
    context: isNpcFighter(actorId) ? `fight · GM as ${actor.name} 🎭 grapple save` : 'fight · grapple save' });
  const r = await resolveGrappleSave(interaction.guild, gid, cid, fight, { nat, total, mode });
  if (actor.isNpc) {
    await sendLong(chan, r.lines);
    await interaction.reply({ content: `✅ Saved as **${actor.name}**.`, ephemeral: true });
  } else {
    await replyLong(interaction, r.lines);
  }
  await kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
  return;
}

async function runFightEscape({ interaction, gid, cid, actorId, mode }) {
  const uid = interaction.user.id;
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  if (isNpcFighter(actorId) && !(await isGm(interaction.guild, uid))) return refuse('❌ Only GMs can act as an NPC.');
  const turnOrder = fightOrder(fight);
  if (turnOrder[fight.turn_index] !== actorId) {
    const cur = await resolveFighter(interaction.guild, gid, turnOrder[fight.turn_index]);
    return refuse(`⚠️ It's **${cur.name}**'s turn.`);
  }
  if (fight.phase !== 'attack') return refuse('❌ Resolve the pending exchange first.');
  const holderId = grappleHolderOf(fight, actorId);
  if (!holderId) return refuse('🤼 You are not held — nothing to escape.');
  clearRoundFlag(gid, cid, actorId);
  {
    const gate0 = deathGate(gid, actorId);
    if (gate0) return refuse(gate0);
  }
  const actor = await resolveFighter(interaction.guild, gid, actorId);
  const holderF = await resolveFighter(interaction.guild, gid, holderId);
  // The hold answers with a live roll of its own: STR vs STR every attempt.
  const holderRow = isNpcFighter(holderId) ? getNpc(gid, npcNameFromFighter(holderId)) : getChar(gid, holderId);
  const hold = autoRoll(holderF.stats.str ?? 0, hasSignatureAdvantage(holderRow, 'str'));
  mirrorAutoRoll(gid, cid, holderF.name, `1d20${hold.adv ? ' (adv)' : ''}`, hold.nat, hold.total, 'grapple hold (STR)');
  const fooledE = consumeFooled(gid, cid, actorId);
  const statVal = fooledE ? 0 : (actor.stats.str ?? 0);
  const sigRow = isNpcFighter(actorId) ? getNpc(gid, npcNameFromFighter(actorId)) : getChar(gid, actorId);
  mode = fooledE ? 'normal' : applySignatureMode(sigRow, 'str', mode);
  const { nat, dropped } = rollD20Mode(mode);
  const total = nat + statVal;
  const diceBit = dropped !== null ? `[${nat}~~${dropped}~~]` : `[${nat}]`;
  const actorName = actor.name + (actor.isNpc ? ' 🎭' : '');
  const holderName = holderF.name + (holderF.isNpc ? ' 🎭' : '');
  const rollLine = `🤼  1d20+STR → ${diceBit}${statVal ? ` +${statVal}` : ''} = ${fightTotalStr(total, nat, 20)} vs hold ${fightTotalStr(hold.total, hold.nat, 20)}`;
  if (!actor.isNpc) saveRoll(gid, cid, uid, `1d20+${statVal}`, 'grapple escape STR');
  recordRoll(gid, { userId: uid, channelId: cid, interaction,
    kind: isNpcFighter(actorId) ? 'npcs' : null, card: null,
    input: `/fight act action:Escape${isNpcFighter(actorId) ? ` npc:${actor.name}` : ''}`, rollLine, nat, sides: 20,
    context: isNpcFighter(actorId) ? `fight · GM as ${actor.name} 🎭 escape attempt` : 'fight · escape attempt' });

  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  const gmap = fightGrapples(fight);
  const lines = ['─────────────────────────────', '🤼  **Escape Attempt**', ''];
  lines.push(`${actorName} (**STR** escape): ${fightTotalStr(total, nat, 20)}`);
  lines.push(`${holderName} (**STR** hold${hold.adv ? ', advantage' : ''}): ${fightTotalStr(hold.total, hold.nat, 20)}`);
  lines.push('');
  const freed = total > hold.total;   // ties keep the hold — the grappler's tie rule
  if (freed) {
    delete gmap[actorId];
    setFightGrapples(gid, cid, gmap);
    lines.push(`🔓 **${actorName}** breaks free of **${holderName}**!`);
  } else {
    lines.push(`⛓️ The hold holds — **${holderName}**'s grip beats **${total}**${total === hold.total ? ' (ties go to the grappler)' : ''}.`);
  }
  // The turn is spent either way, and the strain lands either way.
  const st = await applyTurnEndStrain(interaction.guild, gid, cid, hpState, [...turnOrder], turnOrder, floor, lines, actorId);
  if (st.endedRet) {
    await replyLong(interaction, st.endedRet.lines);
    return announceFightEnd(interaction.guild, gid, cid, chan, st.endedRet.announce);
  }
  const order = st.order;
  const shrunk = order.length !== turnOrder.length;
  const nextIndex = nextStandingIndex(order, hpState, floor, shrunk ? fight.turn_index : fight.turn_index + 1);
  await announceNextTurn(interaction.guild, gid, cid, lines, order, nextIndex);
  upsertFight(gid, cid, { phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null, def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0,
    turn_index: nextIndex, hp_state: JSON.stringify(hpState),
    ...(shrunk ? { turn_order: JSON.stringify(order) } : {}) });

  if (actor.isNpc) {
    await sendLong(chan, lines);
    await interaction.reply({ content: `✅ Escape rolled as **${actor.name}**.`, ephemeral: true });
  } else {
    await replyLong(interaction, lines);
  }
  await kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
  return;
}

// A knockout inside a special defence (deflect redirect, deflect failure,
// disarm failure): purge holds, shrink the roster, end the fight if only one
// stands. Returns { order, endedRet } like the strain helper.
async function knockoutFromSpecial(guild, gid, cid, fight, hpState, order, roster, floor, lines, fid, nm) {
  const W = fightWords(floor);
  lines.push('', `${W.icon} **${nm}** ${W.out}! HP: **${hpState[fid]}**`);
  const gmap = fightGrapples(fight);
  let changed = false;
  for (const [t, h] of Object.entries(gmap)) if (t === fid || h === fid) { delete gmap[t]; changed = true; }
  if (changed) { lines.push(`🤼 The hold involving **${nm}** breaks.`); setFightGrapples(gid, cid, gmap); }
  const shrunk = order.filter(id => id !== fid);
  if (shrunk.length <= 1) {
    return { order: shrunk, endedRet: await buildFightEnd(guild, gid, cid, lines, hpState, roster, floor, shrunk[0]) };
  }
  return { order: shrunk };
}

// After a slash-side resolution: if the fight is on auto-pilot and the turn
// now sits with an NPC, resume the chain. Never called from the auto side
// (the loop handles its own succession), so no call cycle.
async function kickAutoIfNpcTurn(guild, gid, cid, channel) {
  const f = getFight(gid, cid);
  if (f?.auto_npc && isNpcFighter(fightOrder(f)[f.turn_index])) {
    await new Promise(r=>setTimeout(r,1200));
    await runAutoNpcChain(guild, gid, cid, channel);
  }
}

// A disarmed fighter's turn is spent retrieving the weapon. Consumes the flag
// and the turn; returns true if it did.
async function retrievalTurn(guild, gid, cid, actorId, deliver) {
  if (!consumeEffectFlag(gid, cid, actorId, 'disarmed')) return false;
  const fight = getFight(gid, cid);
  const turnOrder = fightOrder(fight);
  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  const F = await resolveFighter(guild, gid, actorId);
  const lines = [`⚔️ **${F.name}${F.isNpc ? ' 🎭' : ''}** spends the turn retrieving their weapon.`];
  const nextIndex = nextStandingIndex(turnOrder, hpState, floor, fight.turn_index + 1);
  await announceNextTurn(guild, gid, cid, lines, turnOrder, nextIndex);
  upsertFight(gid, cid, { phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null, def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0, turn_index: nextIndex });
  await deliver(lines);
  return true;
}

// Shield Deflection: a defend-phase alternative for players facing a PvE
// strike. STR 4+ and a shield required; a natural-20 strike cannot be turned;
// once per round (the flag clears when your own turn comes). Exceed the
// attack roll and the blow is turned — optionally into another enemy for 1
// damage with full down handling. Fall short and it lands on you for 1.
// Either way your next attack roll is a flat d20, the attacker's turn ends
// (a held attacker still pays strain), and the fight advances.
async function runFightDeflect({ interaction, gid, cid, stat = 'str', redirectId, mode, flavour }) {
  const uid = interaction.user.id;
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  if (fight.phase !== 'defend') return refuse('❌ No attack to deflect — nothing is pending.');
  if (fight.atk_kind === 'grapple') return refuse('🤼 A grapple cannot be deflected — answer with `/fight act action:Save`.');
  if (fight.atk_kind === 'feint') return refuse('🎭 A feint cannot be deflected — answer with `/fight act action:Insight`.');
  if (fight.current_target !== uid) {
    const t = await resolveFighter(interaction.guild, gid, fight.current_target);
    return refuse(`⚠️ The attack is on **${t.name}** — the deflection is theirs.`);
  }
  const turnOrder = fightOrder(fight);
  const attackerId = turnOrder[fight.turn_index];
  if (!isNpcFighter(attackerId)) return refuse('🛡️ Deflection works against PvE enemies only — not another player\'s strike.');
  if (fight.atk_nat === 20) return refuse('🛡️ A **natural 20** cannot be deflected — brace with `/fight def` instead.');
  {
    const gate0 = deathGate(gid, uid);
    if (gate0) return refuse(gate0);
  }
  const subject = getChar(gid, uid);
  if (!hasShieldEquipped(subject)) return refuse('🛡️ Deflection needs a **shield** equipped (any type).');
  const barDef = abilityNeeds(gid, 'deflect');
  if (belowBar(subject, barDef)) return refuse(`🛡️ Deflection needs **${barDef.label} ${barDef.need}+** to hold the shield — whichever stat rolls.`);
  {
    const fx = JSON.parse(fight.effect_state || '{}');
    if (fx[uid]?.deflected) return refuse('🛡️ Already deflected this round — it clears when your turn comes.');
  }

  const actor = await resolveFighter(interaction.guild, gid, uid);
  const attackerF = await resolveFighter(interaction.guild, gid, attackerId);
  const actorName = actor.name;
  const attackerName = attackerF.name + ' 🎭';

  // The redirect target, if named, must be a standing enemy other than the attacker.
  const hpState = fightHp(fight);
  const floor = fightFloor(fight);
  let redirectF = null;
  if (redirectId) {
    if (!isNpcFighter(redirectId)) return refuse('🛡️ Redirect into an **enemy** — pick an NPC.');
    if (redirectId === attackerId) return refuse('🛡️ Redirect it into **another** enemy, not the one who swung.');
    if (!turnOrder.includes(redirectId)) return refuse('❌ That enemy is not in this fight.');
    if (hpState[redirectId] !== undefined && hpState[redirectId] <= floor) {
      return refuse(floor > 0 ? '❌ That enemy has already yielded the bout.' : '❌ That enemy is already down.');
    }
    redirectF = await resolveFighter(interaction.guild, gid, redirectId);
  }

  const fooledD = consumeFooled(gid, cid, uid);
  const statVal = fooledD ? 0 : (actor.stats[stat] ?? 0);
  mode = fooledD ? 'normal' : applySignatureMode(subject, stat, mode);
  const { nat, dropped } = rollD20Mode(mode);
  const total = nat + statVal;
  const diceBit = dropped !== null ? `[${nat}~~${dropped}~~]` : `[${nat}]`;
  const advNote = mode === 'adv' ? ' (advantage)' : mode === 'dis' ? ' (disadvantage)' : '';
  const rollLine = `🛡️  1d20+${STAT_LABELS[stat]}${advNote} → ${diceBit}${statVal ? ` +${statVal}` : ''} = ${fightTotalStr(total, nat, 20)} vs atk **${fight.atk_roll}**`;
  saveRoll(gid, cid, uid, `1d20+${statVal}`, `shield deflection ${STAT_LABELS[stat]}`);
  recordRoll(gid, { userId: uid, channelId: cid, interaction,
    kind: null, card: null,
    input: '/fight act action:Deflect', rollLine, nat, sides: 20,
    context: `fight · shield deflection vs ${attackerF.name}` });

  const lines = ['─────────────────────────────', '🛡️  **Shield Deflection**', ''];
  if (flavour) lines.push(`_${flavour}_`, '');
  lines.push(`${attackerName} attacks: ${fightTotalStr(fight.atk_roll, fight.atk_nat, 20)}`);
  lines.push(`**${actorName}** (**${STAT_LABELS[stat]}**): ${rollLine.replace('🛡️  ', '')}`);
  lines.push('');

  let order = [...turnOrder];
  const downFromDeflect = async (fid, nm) => {
    const r = await knockoutFromSpecial(interaction.guild, gid, cid, fight, hpState, order, turnOrder, floor, lines, fid, nm);
    order = r.order;
    return r.endedRet ?? null;
  };
  const deflected = total > fight.atk_roll;   // must EXCEED the attack roll
  if (deflected) {
    if (redirectF) {
      const rName = redirectF.name + ' 🎭';
      const prevR = hpState[redirectId] ?? 0;
      const nhR = applyFightDamage(prevR, 1, floor);
      hpState[redirectId] = nhR; setFighterHp(gid, redirectId, nhR);
      lines.push(`🛡️ **${actorName}** turns the blow aside — and into **${rName}** for **1** damage!`);
      lines.push(hpChangeLine(gid, true, redirectF.name, prevR, nhR, redirectF.maxHp, floor));
      if (nhR <= floor) {
        const end = await downFromDeflect(redirectId, rName);
        if (end) {
          markDeflectUsed(gid, cid, uid);
          await replyLong(interaction, end.lines);
          return announceFightEnd(interaction.guild, gid, cid, chan, end.announce);
        }
      }
    } else {
      lines.push(`🛡️ **${actorName}** turns the blow aside — it strikes nothing.`);
    }
  } else {
    const prev = hpState[uid] ?? 0;
    const nh = applyFightDamage(prev, 1, floor);
    hpState[uid] = nh; setFighterHp(gid, uid, nh);
    lines.push(`💥 The shield is beaten aside — **${actorName}** takes **1** damage.`);
    lines.push(hpChangeLine(gid, false, actor.name, prev, nh, actor.maxHp, floor));
    if (nh <= floor) {
      const end = await downFromDeflect(uid, actorName);
      if (end) {
        markDeflectUsed(gid, cid, uid);
        await replyLong(interaction, end.lines);
        return announceFightEnd(interaction.guild, gid, cid, chan, end.announce);
      }
    }
  }
  lines.push('', `_🛡️ Trade-off: **${actorName}**'s next attack roll is a flat d20._`);

  // The attacker's turn ends — a held attacker still pays the strain.
  const aiBefore = order.indexOf(attackerId);
  const st = await applyTurnEndStrain(interaction.guild, gid, cid, hpState, order, turnOrder, floor, lines, attackerId);
  if (st.endedRet) {
    markDeflectUsed(gid, cid, uid);
    await replyLong(interaction, st.endedRet.lines);
    return announceFightEnd(interaction.guild, gid, cid, chan, st.endedRet.announce);
  }
  order = st.order;
  const ai = order.indexOf(attackerId);
  const from = ai >= 0 ? ai + 1 : aiBefore;
  const nextIndex = nextStandingIndex(order, hpState, floor, from);
  await announceNextTurn(interaction.guild, gid, cid, lines, order, nextIndex);
  const shrunkOrder = order.length !== turnOrder.length;
  upsertFight(gid, cid, { phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null, def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0,
    turn_index: nextIndex, hp_state: JSON.stringify(hpState),
    ...(shrunkOrder ? { turn_order: JSON.stringify(order) } : {}) });
  markDeflectUsed(gid, cid, uid);
  await replyLong(interaction, lines);
  await kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
  return;
}

// Both deflection after-effects in one write: the once-per-round flag and the
// flat next attack.
const markDeflectUsed = (gid, cid, fid) => markRoundSpecial(gid, cid, fid, 'deflected', 'flatAtk');

// Disarming: a defend-phase alternative for players facing a PvE strike.
// DEX 4+ and a blade required; once per round; PvE only. Exceed the attack
// roll and the enemy is disarmed — zero damage, their next turn spent
// retrieving (see retrievalTurn). Fall short and the strike lands on you
// for 1. Either way your next DEFENCE roll is a flat d20 (the flatDef flag,
// consumed by both manual and auto defence). The spec sets no crit
// exception here, so a natural 20 may be disarmed — as written.
async function runFightDisarm({ interaction, gid, cid, mode, flavour }) {
  const uid = interaction.user.id;
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  if (fight.phase !== 'defend') return refuse('❌ No attack to disarm — nothing is pending.');
  if (fight.atk_kind === 'grapple') return refuse('🤼 A grapple cannot be disarmed — answer with `/fight act action:Save`.');
  if (fight.atk_kind === 'feint') return refuse('🎭 A feint cannot be disarmed — answer with `/fight act action:Insight`.');
  if (fight.current_target !== uid) {
    const t = await resolveFighter(interaction.guild, gid, fight.current_target);
    return refuse(`⚠️ The attack is on **${t.name}** — the disarm is theirs.`);
  }
  const turnOrder = fightOrder(fight);
  const attackerId = turnOrder[fight.turn_index];
  if (!isNpcFighter(attackerId)) return refuse('⚔️ Disarming works against PvE enemies only — not another player\'s strike.');
  {
    const gate0 = deathGate(gid, uid);
    if (gate0) return refuse(gate0);
  }
  const subject = getChar(gid, uid);
  if (!hasBladeEquipped(subject)) return refuse('⚔️ Disarming needs a **blade** equipped — maces, shields and firearms can\'t do it.');
  const barDis = abilityNeeds(gid, 'disarm');
  if (belowBar(subject, barDis)) return refuse(`⚔️ Disarming needs **${barDis.label} ${barDis.need}+** — the hands have to be quick.`);
  {
    const fx = JSON.parse(fight.effect_state || '{}');
    if (fx[uid]?.disarmUsed) return refuse('⚔️ Already attempted a disarm this round — it clears when your turn comes.');
  }

  const actor = await resolveFighter(interaction.guild, gid, uid);
  const attackerF = await resolveFighter(interaction.guild, gid, attackerId);
  const actorName = actor.name;
  const attackerName = attackerF.name + ' 🎭';
  const hpState = fightHp(fight);
  const floor = fightFloor(fight);

  const fooledDi = consumeFooled(gid, cid, uid);
  const statVal = fooledDi ? 0 : (actor.stats.dex ?? 0);
  mode = fooledDi ? 'normal' : applySignatureMode(subject, 'dex', mode);
  const { nat, dropped } = rollD20Mode(mode);
  const total = nat + statVal;
  const diceBit = dropped !== null ? `[${nat}~~${dropped}~~]` : `[${nat}]`;
  const advNote = mode === 'adv' ? ' (advantage)' : mode === 'dis' ? ' (disadvantage)' : '';
  const rollLine = `⚔️  1d20+DEX${advNote} → ${diceBit}${statVal ? ` +${statVal}` : ''} = ${fightTotalStr(total, nat, 20)} vs atk **${fight.atk_roll}**`;
  saveRoll(gid, cid, uid, `1d20+${statVal}`, 'weapon disarm DEX');
  recordRoll(gid, { userId: uid, channelId: cid, interaction,
    kind: null, card: null,
    input: '/fight act action:Disarm', rollLine, nat, sides: 20,
    context: `fight · weapon disarm vs ${attackerF.name}` });

  const lines = ['─────────────────────────────', '⚔️  **Disarming Attempt**', ''];
  if (flavour) lines.push(`_${flavour}_`, '');
  lines.push(`${attackerName} attacks: ${fightTotalStr(fight.atk_roll, fight.atk_nat, 20)}`);
  lines.push(`**${actorName}** (**DEX**): ${rollLine.replace('⚔️  ', '')}`);
  lines.push('');

  let order = [...turnOrder];
  const disarmed = total > fight.atk_roll;   // must EXCEED the attack roll
  if (disarmed) {
    setEffectFlag(gid, cid, attackerId, 'disarmed');
    lines.push(`⚔️ The blade spins from **${attackerName}**'s grip — **no damage**, and their next turn is spent retrieving it!`);
  } else {
    const prev = hpState[uid] ?? 0;
    const nh = applyFightDamage(prev, 1, floor);
    hpState[uid] = nh; setFighterHp(gid, uid, nh);
    lines.push(`💥 The parry misses the wrist — **${actorName}** takes **1** damage.`);
    lines.push(hpChangeLine(gid, false, actor.name, prev, nh, actor.maxHp, floor));
    if (nh <= floor) {
      const r = await knockoutFromSpecial(interaction.guild, gid, cid, fight, hpState, order, turnOrder, floor, lines, uid, actorName);
      order = r.order;
      if (r.endedRet) {
        markDisarmUsed(gid, cid, uid);
        await replyLong(interaction, r.endedRet.lines);
        return announceFightEnd(interaction.guild, gid, cid, chan, r.endedRet.announce);
      }
    }
  }
  lines.push('', `_⚔️ Trade-off: **${actorName}**'s next defence roll is a flat d20._`);

  // The attacker's turn ends — a held attacker still pays the strain.
  const aiBefore = order.indexOf(attackerId);
  const st = await applyTurnEndStrain(interaction.guild, gid, cid, hpState, order, turnOrder, floor, lines, attackerId);
  if (st.endedRet) {
    markDisarmUsed(gid, cid, uid);
    await replyLong(interaction, st.endedRet.lines);
    return announceFightEnd(interaction.guild, gid, cid, chan, st.endedRet.announce);
  }
  order = st.order;
  const ai = order.indexOf(attackerId);
  const from = ai >= 0 ? ai + 1 : aiBefore;
  const nextIndex = nextStandingIndex(order, hpState, floor, from);
  await announceNextTurn(interaction.guild, gid, cid, lines, order, nextIndex);
  const shrunkOrder = order.length !== turnOrder.length;
  upsertFight(gid, cid, { phase: 'attack', current_target: null, atk_kind: null,
    atk_roll: null, atk_nat: null, atk_stat: null, def_roll: null, def_nat: null, def_stat: null,
    atk_rerolled: 0, def_rerolled: 0,
    turn_index: nextIndex, hp_state: JSON.stringify(hpState),
    ...(shrunkOrder ? { turn_order: JSON.stringify(order) } : {}) });
  markDisarmUsed(gid, cid, uid);
  await replyLong(interaction, lines);
  await kickAutoIfNpcTurn(interaction.guild, gid, cid, chan);
  return;
}

async function runFightRelease({ interaction, gid, cid, actorId, forceTargetId = null }) {
  const refuse = (content) => interaction.reply({ content, ephemeral: true });
  const chan = await interactionChannel(interaction);
  if (!chan) return refuse(MSG_NO_ACCESS_HERE);
  const fight = getFight(gid, cid);
  if (!fight || fight.state !== 'active') return refuse(NO_ACTIVE_FIGHT);
  const gmap = fightGrapples(fight);
  let heldId, holderId;
  if (forceTargetId) {
    heldId = forceTargetId;
    holderId = gmap[heldId];
    if (!holderId) return refuse('🤼 They are not held.');
  } else {
    heldId = grappleHeldTargetOf(fight, actorId);
    if (!heldId) return refuse('🤼 You are not holding anyone.');
    holderId = actorId;
  }
  delete gmap[heldId];
  setFightGrapples(gid, cid, gmap);
  const holderF = await resolveFighter(interaction.guild, gid, holderId);
  const heldF = await resolveFighter(interaction.guild, gid, heldId);
  const line = `🖐️ **${holderF.name}${holderF.isNpc ? ' 🎭' : ''}** releases **${heldF.name}${heldF.isNpc ? ' 🎭' : ''}** — a free action; the turn stands.`;
  if (forceTargetId || isNpcFighter(actorId)) {
    await chan.send(line).catch(()=>{});
    return interaction.reply({ content: '✅ Released.', ephemeral: true });
  }
  return interaction.reply({ content: line });
}

// The answer buttons a fight prompt carries. NPC targets keep their GM hint
// instead — a button cannot say which NPC it acts for.
function fightAnswerRows(kind, { forNpc = false } = {}) {
  if (forNpc) return [];
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  const B = (id, label, style = ButtonStyle.Primary) => new ButtonBuilder().setCustomId(id).setLabel(label).setStyle(style);
  const rr = B('frr', '🔁 Reroll', ButtonStyle.Secondary);
  if (kind === 'def') return [
    new ActionRowBuilder().addComponents(B('fdef:str', '💪 STR'), B('fdef:con', '🫀 CON'), B('fdef:dex', '⚡ DEX'), B('fdef:wis', '🧠 WIS'), B('fdef:lck', '🍀 LCK')),
    new ActionRowBuilder().addComponents(rr)];
  if (kind === 'save') return [new ActionRowBuilder().addComponents(B('fsave', '💪 Save (STR)'), rr)];
  if (kind === 'insight') return [new ActionRowBuilder().addComponents(B('finsight', '👁️ Insight (WIS)'), rr)];
  if (kind === 'resolve') return [new ActionRowBuilder().addComponents(B('fresolve', '⚖️ Resolve', ButtonStyle.Success), rr)];
  return [];
}

async function handleFight(interaction, forced) {
  let sub = (forced && typeof forced === 'object') ? forced.sub : (forced ?? interaction.options?.getSubcommand?.());
  if (sub === 'act') sub = interaction.options?.getString?.('action');
  if (sub === 'feint' && !interaction.options?.getString?.('feint')) {
    return interaction.reply({ content: '❌ A feint needs `feint:` — what you pretend to do.', ephemeral: true });
  }
  const gid = interaction.guild.id;
  {
    // A GM's bound check outranks the queue: until the card is pressed,
    // the bound player's fight actions wait. Everyone else is untouched.
    const holdGid = interaction.guild?.id, holdCid = interaction.channelId, holdUid = interaction.user?.id;
    if (holdGid && holdUid && boundDcHold(holdGid, holdCid, holdUid)) {
      return interaction.reply({ ephemeral: true, content:
        '⏳ The GM has called a check on you — resolve that card first; your fight actions wait on it.' });
    }
  }
  const cid = interactionChannelId(interaction);
  const uid = interaction.user.id;
  // A feint spends either half of a fight, and which half is decided by the
  // state of play: with a plain strike pending on you it is a DEFENCE roll,
  // WIS in place of your usual stat. Decided here, before dispatch, so the
  // feint path never has to call back into this function.
  if (sub === 'feint') {
    const f0 = getFight(gid, cid);
    const meId = interaction.options?.getString?.('npc') ? npcFighterId(interaction.options.getString('npc')) : uid;
    // One trick per honest roll, either half of the fight.
    const npcSpent = isNpcFighter(meId) && f0 && (JSON.parse(f0.effect_state || '{}')[meId]?.feintUsed);
    if (deceptionSpent(gid, meId) || npcSpent) {
      return interaction.reply({ ephemeral: true, content:
        '🎭 That trick is spent — make an ordinary stat roll before trying another. A lie only sells once until you fight straight.' });
    }
    if (f0?.state === 'active' && f0.phase === 'defend' && f0.current_target === meId
        && f0.atk_kind !== 'feint' && f0.atk_kind !== 'grapple') {
      const meRow = isNpcFighter(meId) ? getNpc(gid, npcNameFromFighter(meId)) : getChar(gid, meId);
      const barR = abilityNeeds(gid, 'feint');
      if (belowBar(meRow, barR)) {
        return interaction.reply({ content: `🎭 Reading a blow takes **${barR.label} ${barR.need}+** — you cannot feint on the back foot.`, ephemeral: true });
      }
      setEffectFlag(gid, cid, meId, 'feintDef');
      setEffectFlag(gid, cid, meId, 'feintUsed');
      spendDeception(gid, meId);
      forced = { sub: 'def', stat: 'wis' };
      sub = 'def';
    }
  }
  // Unapproved sheets can't take fight actions. Read-only and GM subcommands pass.
  if (['atk','def','rr','forfeit','start'].includes(sub)) {
    const gateMsg = sheetGate(gid, uid);
    if (gateMsg && !(await isGm(interaction.guild, uid))) return interaction.reply({ content: gateMsg, ephemeral: true });
  }
  // interaction.channel can be null (thread / uncached); fetch it lazily so the
  // fight flow can still post its cards and prompts.
  const chan = await interactionChannel(interaction);
  if (!chan) return interaction.reply({ content: MSG_NO_ACCESS_HERE, ephemeral: true });

  // ── START ──────────────────────────────────────────────────────────────────
  if (sub === 'start') {
    const existing = getFight(gid, cid);
    if (existing && existing.state !== 'idle') {
      return interaction.reply({ content: '❌ A fight is already in progress in this channel. Use `/fight end` to stop it first.', ephemeral: true });
    }

    const fighters = [];
    // Players from the @mention list
    for (const id of parsePlayerMentions(interaction.options?.getString?.('players'))) {
      fighters.push(id);
    }
    // GM NPCs from the comma list (only a GM may add NPCs)
    const npcNames = expandNpcList(gid, interaction.options?.getString?.('npcs'));
    if (npcNames.length && !(await isGm(interaction.guild, uid))) {
      return interaction.reply({ content: '❌ Only GMs can add NPCs to a fight.', ephemeral: true });
    }
    for (const n of npcNames) {
      const npc = getNpc(gid, n);
      if (!npc) return interaction.reply({ content: `❌ NPC **${n}** not found. Separate multiple NPCs with **commas** (e.g. \`npcs:Goblin, Orc, Rat\`), and check the spelling. Create new ones with \`/npc create\`.`, ephemeral: true });
      const fid = npcFighterId(npc.name); // use the canonical stored name, not the typed casing
      if (!fighters.includes(fid)) fighters.push(fid);
    }
    // Guard against duplicate fighters
    if (new Set(fighters).size !== fighters.length) {
      return interaction.reply({ content: '❌ A fighter was listed more than once.', ephemeral: true });
    }

    if (fighters.length < 2) return interaction.reply({ content: '❌ Need at least 2 fighters. Add players via `players:` (@mention them) and/or NPCs via `npcs:` (comma-separated names).', ephemeral: true });

    // A practice bout stops at the floor instead of 0 — nobody gets hurt.
    const floor = (interaction.options?.getBoolean?.('practice') ?? false) ? PRACTICE_FLOOR : 0;
    const W = fightWords(floor);
    const banner = practiceBanner(floor);

    // Leave out anyone who can't take the field (below the floor / already down)
    const { active: startActive, downed: startDowned } = await partitionDowned(interaction.guild, gid, fighters, floor);
    const startWarn = downedWarning(startDowned, gid, floor);
    if (startActive.length < 2) {
      return interaction.reply({ content: `❌ Need at least 2 fighters with HP above ${floor}.${startWarn ? `\n${startWarn}` : ''}`, ephemeral: true });
    }
    fighters.length = 0; fighters.push(...startActive.map(a => a.fid));
    if (startWarn) await chan.send(startWarn).catch(()=>{});

    const manual = interaction.options?.getBoolean?.('manual') ?? false;

    if (manual) {
      // Skip initiative — keep the order the fighters were listed in
      const hpState = {};
      const rrState = {};
      const ordered = [];
      for (const fid of fighters) {
        const f = await resolveFighter(interaction.guild, gid, fid);
        hpState[fid] = f.isNpc ? (getNpc(gid, f.name)?.hp_current ?? 0) : (getChar(gid, fid)?.hp_current ?? 0);
        if (f.isNpc) rrState[fid] = Math.max(0, getNpc(gid, f.name)?.rerolls_current ?? f.stats.lck ?? 0);
        ordered.push({ id: fid, name: f.name, isNpc: f.isNpc });
      }
      const turnOrder = ordered.map(o => o.id);
      const lines = [`⚔️ **${W.started} Turn order (manual):**`, ''];
      if (banner) { lines.splice(1, 0, banner); }
      ordered.forEach((f,i) => lines.push(`${i+1}. **${f.name}**${f.isNpc ? ' 🎭' : ''}`));
      lines.push('', `🎯 **${ordered[0].name}** goes first!${turnPrompt(ordered[0])}${turnPing(gid, ordered[0])}`);
      upsertFight(gid, cid, {
        state: 'active', turn_order: JSON.stringify(turnOrder), turn_index: 0,
        phase: 'attack', current_target: null, atk_kind: null,
        grapples: '{}', effect_state: '{}',
        atk_roll: null, atk_nat: null, atk_stat: null,
        def_roll: null, def_nat: null, def_stat: null,
        hp_state: JSON.stringify(hpState), rr_state: JSON.stringify(rrState),
        floor_hp: floor,
        log_state: '{}',   // a new fight, a new recap — never the last one's
      });
      return interaction.reply({ content: lines.join('\n') });
    }

    // Roll initiative for each fighter (players and NPCs alike)
    const initiatives = [];
    const hpState = {};
    const rrState = {};
    for (const fid of fighters) {
      const f = await resolveFighter(interaction.guild, gid, fid);
      // Knightfall adds the score; 5e adds the modifier. The ruleset knows which.
      const dex = rulesFor(gid).statBonus(f.stats, 'dex');
      const roll = rollDie(20);
      const total = roll + dex;
      mirrorAutoRoll(gid, cid, f.name, '1d20', roll, total, 'initiative');
      hpState[fid] = f.isNpc ? (getNpc(gid, f.name)?.hp_current ?? 0) : (getChar(gid, fid)?.hp_current ?? 0);
      if (f.isNpc) rrState[fid] = Math.max(0, getNpc(gid, f.name)?.rerolls_current ?? f.stats.lck ?? 0);
      initiatives.push({ id: fid, name: f.name, roll, dex, total, isNpc: f.isNpc });
    }

    // Sort by total descending, ties broken by raw roll
    initiatives.sort((a,b) => b.total - a.total || b.roll - a.roll);

    const turnOrder = initiatives.map(i => i.id);
    const npcCount = initiatives.filter(i => i.isNpc).length;
    const playerCount = initiatives.length - npcCount;
    const lines = [`⚔️ **${W.started}** ${playerCount} player${playerCount===1?'':'s'} + ${npcCount} NPC${npcCount===1?'':'s'} — initiative order:`, ''];
    if (banner) lines.splice(1, 0, banner);
    initiatives.forEach((f,i) => {
      lines.push(`${i+1}. **${f.name}**${f.isNpc ? ' 🎭' : ''} — 🎲 [${f.roll}] + ⚡ ${f.dex} DEX = **${f.total} initiative**`);
    });
    lines.push('');
    const first = initiatives[0];
    lines.push(`🎯 **${first.name}** goes first!${turnPrompt(first)}${turnPing(gid, first)}`);

    upsertFight(gid, cid, {
      state: 'active',
      turn_order: JSON.stringify(turnOrder),
      turn_index: 0,
      phase: 'attack',
      current_target: null,
      atk_roll: null, atk_nat: null, atk_stat: null,
      def_roll: null, def_nat: null, def_stat: null,
      hp_state: JSON.stringify(hpState), rr_state: JSON.stringify(rrState),
      floor_hp: floor,
      log_state: '{}',   // a new fight, a new recap
    });

    return interaction.reply({ content: lines.join('\n') });
  }

  // ── ADDNPC (add one or more GM NPCs to an active fight) ───────────────────
  if (sub === 'addnpc') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can add NPCs to a fight.', ephemeral: true });
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });

    const names = expandNpcList(gid, interaction.options?.getString?.('npc'));
    if (!names.length) return interaction.reply({ content: '❌ Name at least one NPC.', ephemeral: true });

    const turnOrder = fightOrder(fight);
    const hpState = fightHp(fight);
    const rrState = JSON.parse(fight.rr_state || '{}');
    const added = [];
    for (const npcName of names) {
      const npc = getNpc(gid, npcName);
      if (!npc) return interaction.reply({ content: `❌ NPC **${npcName}** not found.`, ephemeral: true });
      const addFloor = fightFloor(fight);
      if ((npc.hp_current ?? 0) <= addFloor) return interaction.reply({ content: `❌ **${npc.name}** ${addFloor > 0 ? `isn't fit to spar (❤️ ${npc.hp_current}, bout floor is ${addFloor})` : `is knocked down (❤️ ${npc.hp_current})`}. Restore with \`/npc hp name:${npc.name}\` first.`, ephemeral: true });
      const fid = npcFighterId(npc.name); // canonical stored name
      if (turnOrder.includes(fid)) return interaction.reply({ content: `❌ **${npc.name}** is already in this fight.`, ephemeral: true });
      const roll = rollDie(20);
      const total = roll + (npc.dex ?? 0);
      mirrorAutoRoll(gid, cid, npc.name, '1d20', roll, total, 'initiative (joined mid-fight)');
      hpState[fid] = npc.hp_current;
      rrState[fid] = Math.max(0, npc.rerolls_current ?? npc.lck ?? 0);
      turnOrder.push(fid);
      added.push(`🎭 **${npc.name}** — 🎲 [${roll}] + ⚡ ${npc.dex} DEX = **${total} initiative**`);
    }
    upsertFight(gid, cid, { turn_order: JSON.stringify(turnOrder), hp_state: JSON.stringify(hpState), rr_state: JSON.stringify(rrState) });
    return interaction.reply({ content: [`**Joined the fight** (added to the end of the turn order — use \`/fight order\` to reposition):`, '', ...added].join('\n') });
  }

  // ── HP (GM sets a fighter's HP mid-fight; sheet + fight stay in sync) ─────
  if (sub === 'hp') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can adjust fight HP.', ephemeral: true });
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });
    const t = resolveFightTarget(interaction, gid, fight);
    if (t.error) return interaction.reply({ content: t.error, ephemeral: true });
    const fid = t.fid;
    const f = await resolveFighter(interaction.guild, gid, fid);
    const value = interaction.options?.getInteger?.('value');
    const newHp = Math.min(value, f.maxHp || value);
    const prev = fightHp(fight)[fid] ?? '?';
    setFighterHp(gid, fid, newHp); // sheet write → syncFightHp mirrors into hp_state
    const note = value > (f.maxHp || value) ? ' (capped at max)' : '';
    const hpFloor = fightFloor(fight);
    const down = newHp <= hpFloor
      ? (hpFloor > 0 ? ` 🏳️ **${f.name}** is at or below the ${hpFloor} HP bout floor and will be skipped.`
                     : ` 💀 **${f.name}** is at 0 or less and will be skipped.`)
      : '';
    return interaction.reply({ content: `❤️ **${f.name}${f.isNpc ? ' 🎭' : ''}** HP: **${prev} → ${newHp}**${note}.${down}` });
  }

  // ── KICK (remove a fighter without ending the fight) ──────────────────────
  if (sub === 'kick') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can kick fighters.', ephemeral: true });
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });
    const t = resolveFightTarget(interaction, gid, fight);
    if (t.error) return interaction.reply({ content: t.error, ephemeral: true });
    const fid = t.fid;
    const turnOrder = fightOrder(fight);
    const removedPos = turnOrder.indexOf(fid);

    const f = await resolveFighter(interaction.guild, gid, fid);
    const hpState = fightHp(fight);
    const rrState = JSON.parse(fight.rr_state || '{}');
    const newOrder = turnOrder.filter(id => id !== fid);
    delete hpState[fid]; delete rrState[fid];
    clearEffects(gid, cid, fid);
    {
      const gmap = fightGrapples(fight);
      let kchanged = false;
      for (const [t, h] of Object.entries(gmap)) if (t === fid || h === fid) { delete gmap[t]; kchanged = true; }
      if (kchanged) setFightGrapples(gid, cid, gmap);
    }
    const lines = [`👢 **${f.name}${f.isNpc ? ' 🎭' : ''}** has been removed from the fight.`];

    if (newOrder.length <= 1) {
      const kickFloor = fightFloor(fight);
      const kickW = fightWords(kickFloor);
      let headline = `👢 **${f.name}${f.isNpc ? ' 🎭' : ''}** was removed by the GM.`;
      if (newOrder.length === 1) {
        const winF = await resolveFighter(interaction.guild, gid, newOrder[0]);
        headline = `🏆 **${winF.name}${winF.isNpc ? ' 🎭' : ''}** ${kickW.win} — last one standing after the GM removed **${f.name}**.`;
      }
      const kickLog = JSON.parse(fight.log_state || '{}');
      archiveFight(gid, cid, kickLog, turnOrder, kickFloor);
      upsertFight(gid, cid, { state: 'idle', turn_order: '[]', hp_state: JSON.stringify(hpState), rr_state: JSON.stringify(rrState) });
      await interaction.reply({ content: lines.join('\n') });
      await announceFightEnd(interaction.guild, gid, cid, chan, {
        headline, log: kickLog, roster: turnOrder, hpState: fightHp(fight), floor: kickFloor,
      });
      return;
    }

    let newIndex = (removedPos < fight.turn_index ? fight.turn_index - 1 : fight.turn_index) % newOrder.length;
    const patch = { turn_order: JSON.stringify(newOrder), turn_index: newIndex,
                    hp_state: JSON.stringify(hpState), rr_state: JSON.stringify(rrState) };
    // If the pending exchange involved them, reset it
    const attackerId = turnOrder[fight.turn_index];
    if (fight.phase === 'defend' && (fid === attackerId || fid === fight.current_target)) {
      Object.assign(patch, { phase: 'attack', current_target: null,
        atk_roll: null, atk_nat: null, atk_stat: null, def_roll: null, def_nat: null, def_stat: null });
      lines.push('↩️ The pending exchange was reset.');
    }
    upsertFight(gid, cid, patch);
    const nextF = await resolveFighter(interaction.guild, gid, newOrder[newIndex]);
    lines.push(`🎯 **${nextF.name}${nextF.isNpc ? ' 🎭' : ''}**'s turn to attack.${turnPing(gid, nextF)}`);
    return interaction.reply({ content: lines.join('\n') });
  }

  // ── REFILL (restore NPC reroll tokens mid-fight) ──────────────────────────
  if (sub === 'refill') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can refill NPC rerolls.', ephemeral: true });
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });
    const turnOrder = fightOrder(fight);
    const rrState = JSON.parse(fight.rr_state || '{}');
    const raw = (interaction.options?.getString?.('npcs') || '').trim();
    let targets;
    if (raw.toLowerCase() === 'all') {
      targets = turnOrder.filter(isNpcFighter).map(fid => getNpc(gid, npcNameFromFighter(fid))).filter(Boolean);
      if (!targets.length) return interaction.reply({ content: '❌ No NPCs in this fight.', ephemeral: true });
    } else {
      targets = [];
      for (const n of expandNpcList(gid, raw)) {
        const npc = getNpc(gid, n);
        if (!npc) return interaction.reply({ content: `❌ NPC **${n}** not found.`, ephemeral: true });
        if (!turnOrder.includes(npcFighterId(npc.name))) return interaction.reply({ content: `❌ **${npc.name}** isn't in this fight.`, ephemeral: true });
        if (!targets.some(t => t.name === npc.name)) targets.push(npc);
      }
      if (!targets.length) return interaction.reply({ content: '❌ Name at least one NPC, or use `npcs:all`.', ephemeral: true });
    }
    const lines = targets.map(npc => {
      const fid = npcFighterId(npc.name);
      rrState[fid] = Math.max(0, npc.rerolls_current ?? npc.lck ?? 0);
      return `🔁 **${npc.name}** 🎭 — **${rrState[fid]}** reroll token${rrState[fid] === 1 ? '' : 's'}`;
    });
    upsertFight(gid, cid, { rr_state: JSON.stringify(rrState) });
    return interaction.reply({ content: ['✨ **NPC rerolls refilled:**', '', ...lines].join('\n') });
  }

  // ── AUTO (auto-run a fight: full / npconly / demo) ────────────────────────
  if (sub === 'auto') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can use /fight auto.', ephemeral: true });
    const mode = interaction.options?.getString?.('mode');
    const sleep = (ms) => new Promise(r => setTimeout(r, ms));
    const channel = chan;
    const send = async (txt) => { await channel.send(txt).catch(()=>{}); };
    // A practice bout stops at the floor instead of 0, in every auto mode.
    const floor = (interaction.options?.getBoolean?.('practice') ?? false) ? PRACTICE_FLOOR : 0;
    const W = fightWords(floor);
    const banner = practiceBanner(floor);

    // ---- DEMO: throwaway example fighters, nothing persisted ----
    if (mode === 'demo') {
      const existing = getFight(gid, cid);
      if (existing && existing.state !== 'idle') return interaction.reply({ content: '❌ Finish or `/fight end` the current fight first.', ephemeral: true });
      await interaction.reply({ content: `🎬 **Running a demo ${W.noun} with two example combatants...**` });
      const A = { name: 'Sir Aldric (demo)', dex: 4, str: 5, hp: 7 };
      const B = { name: 'Cave Troll (demo)', dex: 2, str: 6, hp: 8 };
      const aInitRoll = rollDie(20), bInitRoll = rollDie(20);
      const aInit = aInitRoll + A.dex, bInit = bInitRoll + B.dex;
      mirrorAutoRoll(gid, cid, A.name, '1d20', aInitRoll, aInit, 'demo initiative');
      mirrorAutoRoll(gid, cid, B.name, '1d20', bInitRoll, bInit, 'demo initiative');
      const order = aInit >= bInit ? [A, B] : [B, A];
      await sleep(900);
      await send([`⚔️ **Demo ${W.noun} — initiative:**`, ...(banner ? [banner] : []), '', `1. **${order[0].name}**`, `2. **${order[1].name}**`, '', `🎯 **${order[0].name}** goes first!`].join('\n'));
      let turn = 0, round = 1, safety = 0;
      while (A.hp > floor && B.hp > floor && safety < 12) {
        safety++;
        const atk = order[turn % 2], def = order[(turn + 1) % 2];
        await sleep(1100);
        const aStat = autoFightStat(atk), dStat = autoFightStat(def);
        const a = autoRoll(atk[aStat]), d = autoRoll(def[dStat]);
        mirrorAutoRoll(gid, cid, atk.name, '1d20', a.nat, a.total, `demo attack (${STAT_LABELS[aStat]})`);
        mirrorAutoRoll(gid, cid, def.name, '1d20', d.nat, d.total, `demo defence (${STAT_LABELS[dStat]})`);
        const { hit, dmg } = resolveDamage(a.total, a.nat, 20, d.total, d.nat, 20);
        const lines = ['─────────────────────────────', `**Round ${round}** — ${atk.name} attacks ${def.name}`,
          `⚔️ ${STAT_LABELS[aStat]} → [${a.nat}] +${atk[aStat]} = ${fightTotalStr(a.total, a.nat, 20)}`,
          `🛡️ ${STAT_LABELS[dStat]} → [${d.nat}] +${def[dStat]} = ${fightTotalStr(d.total, d.nat, 20)}`];
        if (hit) { const was = def.hp; def.hp = applyFightDamage(def.hp, dmg, floor); lines.push('', `💥 Hit for **${dmg}**! ${def.name} HP: **${was} → ${def.hp}**`); if (def.hp <= floor) lines.push('', `${W.icon} **${def.name}** ${W.out}!`); }
        else lines.push('', `🛡️ **${def.name}** blocks — no damage.`);
        await send(lines.join('\n'));
        turn++; if (turn % 2 === 0) round++;
      }
      await sleep(900);
      const winner = A.hp > floor ? A : B;
      await send(`\n🏆 **${winner.name}** wins the demo ${W.noun}!\n\n*That's the basic flow: initiative → attack vs defend → damage on a hit. In a real fight, players use \`/fight atk\` and \`/fight def\`, and a GM acts for NPCs with the \`npc:\` option (or runs \`/fight auto\` in full / NPCs-only mode).*`);
      return;
    }

    // ---- Build the real fighter roster from the named players + NPCs ----
    // Parse one side of a teams string into fighter ids (mentions + NPC names/categories)
    const parseSide = (text) => {
      const ids = [];
      for (const id of parsePlayerMentions(text)) ids.push(id);
      const rest = text.replace(/<@!?\d+>/g, ' ');
      for (const n of expandNpcList(gid, rest)) {
        const npc = getNpc(gid, n);
        if (!npc) return { error: `❌ NPC **${n}** not found.` };
        const fid = npcFighterId(npc.name);
        if (!ids.includes(fid)) ids.push(fid);
      }
      return { ids };
    };

    const teamsRaw = (interaction.options?.getString?.('teams') || '').trim();
    const sideOf = {}; // fid -> 1|2 when teams are in play (full mode only)
    let useTeams = false;
    const fighters = [];

    if (teamsRaw && mode === 'full') {
      const parts = teamsRaw.split(/\s+vs\s+/i);
      if (parts.length !== 2) return interaction.reply({ content: '❌ Teams format: `teams:@a @b vs Goblin, Orc` (exactly one "vs").', ephemeral: true });
      const s1 = parseSide(parts[0]), s2 = parseSide(parts[1]);
      if (s1.error) return interaction.reply({ content: s1.error, ephemeral: true });
      if (s2.error) return interaction.reply({ content: s2.error, ephemeral: true });
      if (!s1.ids.length || !s2.ids.length) return interaction.reply({ content: '❌ Both teams need at least one fighter.', ephemeral: true });
      for (const fid of s1.ids) { if (sideOf[fid]) return interaction.reply({ content: '❌ A fighter appears on both teams.', ephemeral: true }); sideOf[fid] = 1; fighters.push(fid); }
      for (const fid of s2.ids) { if (sideOf[fid]) return interaction.reply({ content: '❌ A fighter appears on both teams.', ephemeral: true }); sideOf[fid] = 2; fighters.push(fid); }
      useTeams = true;
    } else {
      if (teamsRaw) return interaction.reply({ content: '❌ `teams:` only applies to `mode:Full`.', ephemeral: true });
      for (const id of parsePlayerMentions(interaction.options?.getString?.('players'))) fighters.push(id);
      const npcNames = expandNpcList(gid, interaction.options?.getString?.('npcs'));
      for (const n of npcNames) {
        const npc = getNpc(gid, n);
        if (!npc) return interaction.reply({ content: `❌ NPC **${n}** not found. Tip: \`category:Name\` adds a whole category.`, ephemeral: true });
        const fid = npcFighterId(npc.name); // canonical stored name
        if (!fighters.includes(fid)) fighters.push(fid);
      }
    }
    if (new Set(fighters).size !== fighters.length) return interaction.reply({ content: '❌ A fighter was listed more than once.', ephemeral: true });

    if (fighters.length < 2) return interaction.reply({ content: '❌ Need at least 2 fighters. Use `players:` (@mention) and/or `npcs:` (comma-separated).', ephemeral: true });

    // Leave out anyone who can't take the field (below the floor / already down)
    const { active: autoActive, downed: autoDowned } = await partitionDowned(interaction.guild, gid, fighters, floor);
    const autoWarn = downedWarning(autoDowned, gid, floor);
    if (autoActive.length < 2) {
      return interaction.reply({ content: `❌ Need at least 2 fighters with HP above ${floor}.${autoWarn ? `\n${autoWarn}` : ''}`, ephemeral: true });
    }
    fighters.length = 0; fighters.push(...autoActive.map(a => a.fid));
    if (useTeams) {
      const t1 = fighters.some(fid => sideOf[fid] === 1), t2 = fighters.some(fid => sideOf[fid] === 2);
      if (!t1 || !t2) return interaction.reply({ content: `❌ Team ${t1 ? 2 : 1} has no able fighters.${autoWarn ? `\n${autoWarn}` : ''}`, ephemeral: true });
    }
    if (autoWarn) await chan.send(autoWarn).catch(()=>{});

    // Resolve everyone up front
    const F = {}; // fid -> resolved fighter (+ live hp)
    for (const fid of fighters) {
      const rf = await resolveFighter(interaction.guild, gid, fid);
      F[fid] = rf;
    }

    // Initiative for all
    const inits = fighters.map(fid => ({ fid, roll: 0, total: 0 }));
    for (const it of inits) {
      const r = rollDie(20); it.roll = r; it.total = r + (F[it.fid].stats.dex ?? 0);
      mirrorAutoRoll(gid, cid, F[it.fid].name, '1d20', r, it.total, 'initiative (auto fight)');
    }
    inits.sort((a,b) => b.total - a.total || b.roll - a.roll);
    const order = inits.map(i => i.fid);

    // Live HP for each fighter (from their sheet's current HP)
    const hp = {};
    const rrTokens = {}; // per-fight NPC reroll tokens (LCK) — full mode
    const fxState = {};  // carry-over effects (nat-1 atk / nat-20 def) — full mode
    for (const fid of fighters) {
      hp[fid] = F[fid].isNpc ? (getNpc(gid, F[fid].name)?.hp_current ?? 0) : (getChar(gid, fid)?.hp_current ?? 0);
      // Seeded from the persistent pool, and spends write back — mirroring
      // players, whose rerolls survive a fight and come back on rest.
      if (F[fid].isNpc) rrTokens[fid] = Math.max(0, getNpc(gid, F[fid].name)?.rerolls_current ?? F[fid].stats.lck ?? 0);
    }

    // ---- NPCONLY: set up a real, persisted fight where the bot will auto-take NPC turns ----
    if (mode === 'npconly') {
      const existing = getFight(gid, cid);
      if (existing && existing.state !== 'idle') return interaction.reply({ content: '❌ Finish or `/fight end` the current fight first.', ephemeral: true });
      const hpState = {}; for (const fid of fighters) hpState[fid] = hp[fid];
      const rrState = {}; for (const fid of fighters) if (F[fid].isNpc) rrState[fid] = Math.max(0, F[fid].stats.lck ?? 0);
      upsertFight(gid, cid, {
        state: 'active', turn_order: JSON.stringify(order), turn_index: 0,
        phase: 'attack', current_target: null, atk_kind: null,
        grapples: '{}', effect_state: '{}',
        atk_roll: null, atk_nat: null, atk_stat: null,
        def_roll: null, def_nat: null, def_stat: null,
        hp_state: JSON.stringify(hpState), rr_state: JSON.stringify(rrState), auto_npc: 1,
        log_state: '{}',   // a new fight, a new recap
        floor_hp: floor,
      });
      const lines = [`⚔️ **${W.started} (NPCs auto-piloted)**`, ...(banner ? [banner] : []), '', '**Initiative:**'];
      inits.forEach((it,i)=>{ const f=F[it.fid]; lines.push(`${i+1}. **${f.name}${f.isNpc?' 🎭':''}** — 🎲 [${it.roll}] + ⚡ ${f.stats.dex} DEX = **${it.total}**`); });
      const firstF = F[order[0]];
      lines.push('', firstF.isNpc
        ? `🤖 **${firstF.name}** is an NPC — the bot will take its turn automatically.`
        : `🎯 **${firstF.name}** goes first!${turnPrompt(firstF)}${turnPing(gid, firstF)}`);
      await interaction.reply({ content: lines.join('\n') });
      // If the first fighter is an NPC, kick off its turn
      if (firstF.isNpc) { await sleep(1200); await runAutoNpcChain(interaction.guild, gid, cid, channel); }
      return;
    }

    // ---- FULL: bot rolls everything to a winner, persists final HP, stores nothing ongoing ----
    await interaction.reply({ content: `🎬 **Auto-resolving the ${W.noun}...**` });
    const lines0 = ['⚔️ **Initiative:**', ...(banner ? [banner] : [])];
    inits.forEach((it,i)=>{ const f=F[it.fid]; lines0.push(`${i+1}. **${f.name}${f.isNpc?' 🎭':''}** — 🎲 [${it.roll}] + ⚡ ${f.stats.dex} DEX = **${it.total}**`); });
    await sleep(800); await send(lines0.join('\n'));

    const alive = () => order.filter(fid => hp[fid] > floor);
    const sideAlive = (t) => order.some(fid => sideOf[fid] === t && hp[fid] > floor);
    const fightOn = () => useTeams ? (sideAlive(1) && sideAlive(2)) : alive().length > 1;
    const autoLog = { exchanges: 0, f: {} };
    const ensureLog = (fid) => (autoLog.f[fid] = autoLog.f[fid] || FIGHTER_LOG());
    let idx = 0, round = 1, safety = 0, exchanges = 0;
    while (fightOn() && safety < 200) {
      safety++;
      // find next living attacker starting at idx
      let guard = 0;
      while (hp[order[idx]] <= floor && guard < order.length) { idx = (idx + 1) % order.length; guard++; }
      const attackerId = order[idx];
      // One round = every living fighter has taken one attack. Count completed
      // exchanges against the current number of living fighters rather than
      // watching the index wrap, which mislabelled the second half of a round.
      const livingCount = Math.max(1, order.filter(fid => hp[fid] > floor).length);
      round = Math.floor(exchanges / livingCount) + 1;
      exchanges++;
      // pick a random living opponent
      const opponents = alive().filter(fid => useTeams ? sideOf[fid] !== sideOf[attackerId] : fid !== attackerId);
      if (!opponents.length) break;
      const defenderId = opponents[Math.floor(Math.random() * opponents.length)];

      const atkF = F[attackerId], defF = F[defenderId];
      const aStat = chooseAutoStat(gid, atkF.id, atkF.stats, 'atk');
      const dStat = chooseAutoStat(gid, defF.id, defF.stats, 'def');
      // Consume carry-over effects: attacker's riposte bonus, defender's flat-d20.
      const atkBonus = fxState[attackerId]?.atkBonus ?? 0;
      const defFlat = !!fxState[defenderId]?.flatDef;
      if (fxState[attackerId]) delete fxState[attackerId].atkBonus;
      if (fxState[defenderId]) delete fxState[defenderId].flatDef;
      const atkRow = atkF.isNpc ? getNpc(gid, atkF.name) : getChar(gid, attackerId);
      const defRow = defF.isNpc ? getNpc(gid, defF.name) : getChar(gid, defenderId);
      const atkAdv = hasSignatureAdvantage(atkRow, aStat);
      const defAdv = !defFlat && hasSignatureAdvantage(defRow, dStat);
      let a = autoRoll((atkF.stats[aStat] ?? 0) + atkBonus, atkAdv);
      let d = autoRoll(defFlat ? 0 : (defF.stats[dStat] ?? 0), defAdv);
      mirrorAutoRoll(gid, cid, atkF.name, `1d20${a.adv ? ' (adv)' : ''}`, a.nat, a.total, `auto fight attack (${STAT_LABELS[aStat]})`);
      mirrorAutoRoll(gid, cid, defF.name, `1d20${d.adv ? ' (adv)' : ''}`, d.nat, d.total,
        defFlat ? 'auto fight defence (flat d20 — fumbled)' : `auto fight defence (${STAT_LABELS[dStat]})`);
      let { hit, dmg } = resolveDamage(a.total, a.nat, 20, d.total, d.nat, 20);

      // Round header (system line)
      await sleep(900);
      await send(`─────────────────────────────\n**Round ${round}**`);

      // Attacker's roll card — posts AS the NPC if it's an NPC, else a normal card
      const atkCard = await autoFightCard(interaction.guild, gid, atkF, 'atk', aStat, a.nat, a.total, `${defF.name}${defF.isNpc?' 🎭':''}`, false, atkBonus, false, !!a.adv);
      await sleep(700);
      if (atkF.isNpc) await postAsNpc(channel, gid, atkF.name, atkCard);
      else await send(atkCard);
      if (atkBonus) await send(`✨ **${atkF.name}** presses the riposte (+${atkBonus}).`);

      // Defender's roll card — same treatment
      const defCard = await autoFightCard(interaction.guild, gid, defF, 'def', dStat, d.nat, d.total, null, false, 0, defFlat, !!d.adv);
      await sleep(700);
      if (defF.isNpc) await postAsNpc(channel, gid, defF.name, defCard);
      else await send(defCard);
      if (defFlat) await send(`🎲 **${defF.name}** defends on a flat d20 (fumbled last attack).`);

      // NPC reroll window: only on a poor natural die (≤ guild threshold) —
      // defender answers an incoming hit, attacker a block
      const rrMax = getNpcRrThreshold(gid);
      if (hit && d.nat <= rrMax && defF.isNpc && (rrTokens[defenderId] ?? 0) > 0) {
        rrTokens[defenderId]--;
        try { upsertNpc(gid, defF.name, { rerolls_current: rrTokens[defenderId] }); } catch {}
        d = autoRoll(defFlat ? 0 : (defF.stats[dStat] ?? 0), defAdv);
        mirrorAutoRoll(gid, cid, defF.name, `1d20${d.adv ? ' (adv)' : ''}`, d.nat, d.total, 'auto fight defence reroll');
        await sleep(800);
        await send(`🔁 **${defF.name}** 🎭 spends a reroll token! (${rrTokens[defenderId]} left)`);
        const rrCard = await autoFightCard(interaction.guild, gid, defF, 'def', dStat, d.nat, d.total, null, true, 0, defFlat, !!d.adv);
        await postAsNpc(channel, gid, defF.name, rrCard);
        ensureLog(defenderId).rr++;
        ({ hit, dmg } = resolveDamage(a.total, a.nat, 20, d.total, d.nat, 20));
      }
      if (!hit && a.nat <= rrMax && atkF.isNpc && (rrTokens[attackerId] ?? 0) > 0) {
        rrTokens[attackerId]--;
        try { upsertNpc(gid, atkF.name, { rerolls_current: rrTokens[attackerId] }); } catch {}
        a = autoRoll((atkF.stats[aStat] ?? 0) + atkBonus, atkAdv);
        mirrorAutoRoll(gid, cid, atkF.name, `1d20${a.adv ? ' (adv)' : ''}`, a.nat, a.total, 'auto fight attack reroll');
        await sleep(800);
        await send(`🔁 **${atkF.name}** 🎭 spends a reroll token! (${rrTokens[attackerId]} left)`);
        const rrCard = await autoFightCard(interaction.guild, gid, atkF, 'atk', aStat, a.nat, a.total, `${defF.name}${defF.isNpc?' 🎭':''}`, true, atkBonus, false, !!a.adv);
        await postAsNpc(channel, gid, atkF.name, rrCard);
        ensureLog(attackerId).rr++;
        ({ hit, dmg } = resolveDamage(a.total, a.nat, 20, d.total, d.nat, 20));
      }

      recordExchange(autoLog, ensureLog, attackerId, defenderId, a.nat, d.nat, hit, dmg,
        { atkTotal: a.total, defTotal: d.total, atkStat: aStat, defStat: dStat });

      // Set carry-over effects from this exchange (in-memory mirror of applyExchangeEffects)
      const fxNotes = [];
      if (a.nat === 1) { (fxState[attackerId] = fxState[attackerId] || {}).flatDef = true; fxNotes.push('flat_def'); }
      if (d.nat === 20 && a.nat !== 20) { (fxState[defenderId] = fxState[defenderId] || {}).atkBonus = 2; fxNotes.push('atk_bonus'); }

      // Outcome (system line)
      let outcome;
      if (hit) {
        const wasHp = hp[defenderId];
        hp[defenderId] = applyFightDamage(hp[defenderId], dmg, floor);
        setFighterHp(gid, defenderId, hp[defenderId]); // keep sheets live so the next card is accurate
        outcome = `💥 Hit for **${dmg}**! ` + (defF.isNpc && !npcStatsVisible(gid)
          ? `${defF.name}: ${hpCondition(hp[defenderId], defF.maxHp, floor)}`
          : `${defF.name} HP: **${wasHp} → ${hp[defenderId]}**`);
        if (hp[defenderId] <= floor) outcome += `\n${W.icon} **${defF.name}** ${W.out}!`;
      } else {
        outcome = `🛡️ **${defF.name}** blocks — no damage.`;
      }
      for (const l of effectNoteLines(fxNotes, `**${atkF.name}${atkF.isNpc?' 🎭':''}**`, `**${defF.name}${defF.isNpc?' 🎭':''}**`)) outcome += `\n${l}`;
      await sleep(700); await send(outcome);

      idx = (idx + 1) % order.length;
    }

    // Persist final HP to real sheets
    for (const fid of fighters) setFighterHp(gid, fid, hp[fid]);

    await sleep(800);
    const survivors = alive();
    let winLine;
    if (useTeams && (sideAlive(1) !== sideAlive(2))) {
      const winner = sideAlive(1) ? 1 : 2;
      const names = survivors.filter(fid => sideOf[fid] === winner).map(fid => `**${F[fid].name}${F[fid].isNpc?' 🎭':''}**`).join(', ');
      winLine = `🏆 **Team ${winner}** ${W.win}! Survivors: ${names}. Final HP has been saved to all combatants' sheets.`;
    } else if (!useTeams && survivors.length === 1) {
      const w = F[survivors[0]];
      winLine = `🏆 **${w.name}${w.isNpc?' 🎭':''}** ${W.win}! Final HP has been saved to all combatants' sheets.`;
    } else {
      winLine = `⚖️ The ${W.noun} ended without a clear winner. Final HP saved to all combatants' sheets.`;
    }
    archiveFight(gid, interactionChannelId(interaction), autoLog, order, floor);
    await announceFightEnd(interaction.guild, gid, interactionChannelId(interaction), channel, {
      headline: winLine, log: autoLog, roster: order, hpState: hp, floor,
    });
    return;
  }

  // ── ORDER (rearrange turn order of an active fight) ───────────────────────
  if (sub === 'order') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can change the turn order.', ephemeral: true });
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });

    const currentOrder = fightOrder(fight);
    const seqStr = interaction.options?.getString?.('sequence');
    const playersStr = interaction.options?.getString?.('players');

    let newOrder = [];
    if (seqStr) {
      // Comma-separated, preserving order. Each item is either a mention or an NPC name.
      for (const raw of seqStr.split(',')) {
        const item = raw.trim();
        if (!item) continue;
        const m = item.match(/<@!?(\d+)>|^(\d{15,21})$/);
        if (m) {
          newOrder.push(m[1] || m[2]);
        } else {
          // Treat as an NPC name — match against the fight's NPC fighters (case-insensitive)
          const match = currentOrder.find(fid => isNpcFighter(fid) && npcNameFromFighter(fid).toLowerCase() === item.toLowerCase());
          newOrder.push(match || npcFighterId(item));
        }
      }
    } else if (playersStr) {
      newOrder = parsePlayerMentions(playersStr);
    } else {
      return interaction.reply({ content: '❌ Provide a `sequence` (e.g. `@Alice, Goblin, @Bob`) or a `players` list.', ephemeral: true });
    }

    // The new order must contain exactly the same fighters as the current fight
    const sameSet = newOrder.length === currentOrder.length &&
      newOrder.every(id => currentOrder.includes(id)) &&
      new Set(newOrder).size === newOrder.length;
    if (!sameSet) {
      const roster = [];
      for (const fid of currentOrder) {
        const f = await resolveFighter(interaction.guild, gid, fid);
        roster.push(`• ${f.name}${f.isNpc ? ' (NPC)' : ''}`);
      }
      return interaction.reply({ content: `❌ The new order must list every current fighter exactly once — no additions, removals, or duplicates.\n\n**Current fighters:**\n${roster.join('\n')}\n\nList them in order in \`sequence\`, separated by commas — @mention players and type NPC names (e.g. \`@Alice, Goblin, @Bob\`).`, ephemeral: true });
    }

    // Keep the same fighter on their turn if possible, else reset to the top
    const currentActiveId = currentOrder[fight.turn_index];
    const newIndex = Math.max(0, newOrder.indexOf(currentActiveId));

    upsertFight(gid, cid, { turn_order: JSON.stringify(newOrder), turn_index: newIndex });

    const lines = ['🔀 **Turn order updated:**', ''];
    for (let i = 0; i < newOrder.length; i++) {
      const f = await resolveFighter(interaction.guild, gid, newOrder[i]);
      const marker = i === newIndex ? '  ⬅️ current turn' : '';
      lines.push(`${i+1}. **${f.name}${f.isNpc ? ' 🎭' : ''}**${marker}`);
    }
    return interaction.reply({ content: lines.join('\n') });
  }

  // ── ATK (normal / adv / dis) ──────────────────────────────────────────────
  if (sub === 'atk') {
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });

    const turnOrder = fightOrder(fight);
    const currentId = turnOrder[fight.turn_index];
    const npcActAs = interaction.options?.getString?.('npc'); // GM acting as an NPC

    // Determine who is acting (a user, or a GM-controlled NPC)
    let actorId;
    if (npcActAs) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can act as an NPC.', ephemeral: true });
      actorId = npcFighterId(npcActAs);
      {
        const gate0 = deathGate(gid, actorId);
        if (gate0) return interaction.reply({ content: gate0, ephemeral: true });
      }
      if (!isNpcFighter(currentId) || currentId !== actorId) {
        const cur = await resolveFighter(interaction.guild, gid, currentId);
        return interaction.reply({ content: `⚠️ It's **${cur.name}**'s turn, not **${npcActAs}**'s.`, ephemeral: true });
      }
    } else {
      actorId = uid;
      if (uid !== currentId) {
        const cur = await resolveFighter(interaction.guild, gid, currentId);
        const hint = cur.isNpc ? ` (a GM must act with \`npc:${cur.name}\`)` : '';
        return interaction.reply({ content: `⚠️ It's **${cur.name}**'s turn to attack.${hint}`, ephemeral: false });
      }
    }

    if (fight.phase !== 'attack') return interaction.reply({ content: '❌ Waiting for defender to roll first.', ephemeral: true });

    const stat = interaction.options?.getString?.('stat');
    const targetUser = interaction.options?.getUser?.('target');
    const targetNpc = interaction.options?.getString?.('target_npc');
    const flavour = interaction.options?.getString?.('flavour') ?? null;
    let mode = interaction.options?.getString?.('roll') ?? 'normal';

    if (!targetUser && !targetNpc) {
      // Rather than making someone type a name, offer what is actually there.
      // With one opponent left there is nothing to choose, so just say who.
      const order = fightOrder(fight);
      const hp = fightHp(fight);
      const floor = fight.practice ? PRACTICE_FLOOR : 0;
      const live = order.filter(fid => fid !== actorId && (hp[fid] ?? 0) > floor && !isFallen(gid, fid));
      if (!live.length) return interaction.reply({ content: '❌ Nobody left standing to attack.', ephemeral: true });
      if (live.length === 1) {
        const only = await resolveFighter(interaction.guild, gid, live[0]);
        return interaction.reply({ ephemeral: true, content:
          `❌ Say who you are attacking — there is only **${only.name}** left, so: \`/fight atk stat:${stat} `
          + `${only.isNpc ? `target_npc:${only.name}` : `target:@${only.name}`}\`` });
      }
      const { ActionRowBuilder, StringSelectMenuBuilder } = require('discord.js');
      const opts = [];
      for (const fid of live.slice(0, 25)) {
        const f = await resolveFighter(interaction.guild, gid, fid);
        opts.push({ label: `${f.name}`.slice(0, 100), value: fid,
          description: `${hp[fid] ?? 0} HP${f.isNpc ? ' · NPC' : ''}`.slice(0, 100),
          emoji: f.isNpc ? '🎭' : '⚔️' });
      }
      const row = new ActionRowBuilder().addComponents(
        new StringSelectMenuBuilder()
          .setCustomId(`fighttarget:${actorId}:${stat}:${mode}:${encodeURIComponent(flavour ?? '')}`)
          .setPlaceholder('Who are you attacking?')
          .addOptions(opts));
      return interaction.reply({ ephemeral: true, components: [row],
        content: `🎯 **${live.length} still standing.** Pick your target.` });
    }
    if (targetUser && targetNpc) return interaction.reply({ content: '❌ Choose either a player target or an NPC target, not both.', ephemeral: true });
    const targetId = targetNpc ? npcFighterId(targetNpc) : targetUser.id;
    return await runFightAttack({ interaction, gid, cid, actorId, targetId, stat, mode, flavour });
  }

  // ── DEF (normal / adv / dis) ──────────────────────────────────────────────
  if (sub === 'def') {
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });
    if (fight.phase !== 'defend') return interaction.reply({ content: '❌ No attack to defend against yet.', ephemeral: true });
    if (fight.atk_kind === 'grapple') return interaction.reply({ content: '🤼 That is a grapple — answer with `/fight act action:Save` (STR only).', ephemeral: true });
    if (fight.atk_kind === 'feint') return interaction.reply({ content: '🎭 That is a feint — answer with `/fight act action:Insight` (WIS only).', ephemeral: true });

    const npcActAs = interaction.options?.getString?.('npc'); // GM defending as an NPC
    const forcedStat = (forced && typeof forced === 'object') ? forced.stat : null;
    const targetId = fight.current_target;

    let defenderId;
    if (npcActAs) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can defend as an NPC.', ephemeral: true });
      defenderId = npcFighterId(npcActAs);
      if (!isNpcFighter(targetId) || targetId !== defenderId) {
        const tf = await resolveFighter(interaction.guild, gid, targetId);
        return interaction.reply({ content: `⚠️ **${tf.name}** is the one defending, not **${npcActAs}**.`, ephemeral: true });
      }
    } else {
      defenderId = uid;
      if (uid !== targetId) {
        const tf = await resolveFighter(interaction.guild, gid, targetId);
        const hint = tf.isNpc ? ` (a GM defends with \`npc:${tf.name}\`)` : '';
        return interaction.reply({ content: `⚠️ **${tf.name}** is the one defending.${hint}`, ephemeral: false });
      }
    }

    let stat = forcedStat ?? interaction.options?.getString?.('stat');
    const gmStatD = consumeGmStat(gid, cid, defenderId);
    let gmStatNoteD = '';
    if (gmStatD && gmStatD !== stat) { gmStatNoteD = ` \u2696\uFE0F stat set to ${STAT_LABELS[gmStatD]} by the GM`; stat = gmStatD; }
    else if (gmStatD) { gmStatNoteD = ` \u2696\uFE0F GM confirmed ${STAT_LABELS[gmStatD]}`; }
    const flavour = interaction.options?.getString?.('flavour') ?? null;
    let mode = interaction.options?.getString?.('roll') ?? 'normal';

    const defender = await resolveFighter(interaction.guild, gid, defenderId);
    {
      const refusal = weaponStatRefusal(gid, pageSubject(gid, defenderId), 'def', stat);
      if (refusal) return interaction.reply({ content: refusal, ephemeral: true });
    }
    const statVal = defender.stats[stat] ?? 0;
    // A previous nat-1 attack — or a feint that fooled you — forces a flat d20.
    const flat = consumeFlatDef(gid, cid, defenderId) || consumeFooled(gid, cid, defenderId);
    // Hero signature advantage (ignored when the roll is forced flat)
    const sigRowD = isNpcFighter(defenderId) ? getNpc(gid, npcNameFromFighter(defenderId)) : getChar(gid, defenderId);
    if (!flat) mode = applySignatureMode(sigRowD, stat, mode);
    mode = applyNextMark(gid, targetId, mode);
    const effVal = flat ? 0 : statVal;
    const effMode = flat ? 'normal' : mode;
    const modStr = flat ? '' : (effVal > 0 ? ` +${effVal}` : effVal < 0 ? ` ${effVal}` : '');
    const flatTag = flat ? ' (flat d20 — fumbled last attack)' : '';

    let nat, dropped = null, advNote = '';
    if (effMode === 'adv') {
      const r1 = rollDie(20), r2 = rollDie(20);
      nat = Math.max(r1, r2); dropped = Math.min(r1, r2); advNote = ' (advantage)';
    } else if (effMode === 'dis') {
      const r1 = rollDie(20), r2 = rollDie(20);
      nat = Math.min(r1, r2); dropped = Math.max(r1, r2); advNote = ' (disadvantage)';
    } else {
      nat = rollDie(20);
    }
    const total = nat + effVal;
    const diceBit = dropped === null ? `[${nat}]` : `[${nat}, ~~${dropped}~~]`;
    // Same dual rendering as the attack: full line for the audit, stat name
    // and modifier dropped from the public card when NPC stats are hidden.
    // A flat defence has nothing to hide — no stat, no modifier.
    const lineFor = (show) => flat
      ? `🛡️  1d20${flatTag} → ${diceBit} = ${fightTotalStr(total, nat, 20)}`
      : `🛡️  1d20${show ? `+${STAT_LABELS[stat]}` : ''}${advNote} → ${diceBit}${show ? modStr : ''} = ${fightTotalStr(total, nat, 20)}`;
    const rollLine = lineFor(true);
    const publicLine = (defender.isNpc && !npcStatsVisible(gid)) ? lineFor(false) : rollLine;
    const critType = nat === 20 ? 'crit' : (nat === 1 ? 'fail' : null);
    const defCard = await fighterCharCard(interaction.guild, gid, defenderId);
    const card = styledFightCard(gid, defenderId, {
      rollLine: publicLine, label: `🛡️ Defends with ${STAT_LABELS[stat]}`, isReroll: false,
      char: defCard, healCharges: 0, maxCharges: 0,
      flavour: flavour || null, total, critType, tags: null, gid,
    });
    // The audit's copy: the same card with every number shown.
    const auditCard = defender.isNpc ? buildRollEmbed({
      rollLine, label: `🛡️ Defends with ${STAT_LABELS[stat]}`, isReroll: false,
      char: defCard, healCharges: 0, maxCharges: 0,
      flavour: flavour || null, total, critType, tags: null, gid, reveal: true,
    }) : null;

    upsertFight(gid, cid, { def_roll: total, def_nat: nat, def_stat: stat, def_mode: mode, def_sides: 20 });
    if (!defender.isNpc) saveRoll(gid, cid, uid, `1d20+${statVal}`, `def ${STAT_LABELS[stat]}`);
    // Same audit-link discipline as the attack: capture the public card's id
    // so the mirror can link to it; a plain public reply resolves via fetchReply.
    let auditMsgId = null;
    if (defender.isNpc) {
      const npcMsg = await postAsNpc(chan, gid, defender.name, card);
      auditMsgId = npcMsg?.id ?? null;
      await chan.send({ content: '⚡ Use `/fight resolve` to resolve this exchange — or press the button.', components: fightAnswerRows('resolve') }).catch(()=>{});
      await interaction.reply({ content: `✅ Defended as **${defender.name}**.`, ephemeral: true });
    } else {
      await interaction.reply({ content: `${card}\n\n⚡ Use \`/fight resolve\` to resolve this exchange — or press the button.`, components: fightAnswerRows('resolve') });
    }
    recordRoll(gid, { userId: uid, channelId: cid, interaction, messageId: auditMsgId,
      kind: isNpcFighter(defenderId) ? 'npcs' : null, card: auditCard,
      input: `/fight def stat:${stat}${isNpcFighter(defenderId) ? ` npc:${defender.name}` : ''}`, rollLine, nat, sides: 20,
      context: isNpcFighter(defenderId) ? `fight · GM as ${defender.name} 🎭 defends` : 'fight · defends' });
    return;
  }

  // ── REROLLS ────────────────────────────────────────────────────────────────
  if (sub === 'feint') {
    const npcActAs = interaction.options?.getString?.('npc');
    let actorId = interaction.user.id;
    if (npcActAs) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can act as an NPC.', ephemeral: true });
      actorId = npcFighterId(npcActAs);
    }
    const tUser = interaction.options?.getUser?.('target');
    const tNpc = interaction.options?.getString?.('target_npc');
    if (!tUser && !tNpc) return interaction.reply({ content: '❌ Name a target — `target:@player` or `target_npc:Name`.', ephemeral: true });
    const targetId = tNpc ? npcFighterId(tNpc) : tUser.id;
    const feintText = interaction.options?.getString?.('feint');
    const mode = interaction.options?.getString?.('roll') || 'normal';
    const flavour = interaction.options?.getString?.('flavour');
    return runFightFeint({ interaction, gid, cid, actorId, targetId, feintText, mode, flavour });
  }
  if (sub === 'insight') {
    const npcActAs = interaction.options?.getString?.('npc');
    let actorId = interaction.user.id;
    if (npcActAs) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can act as an NPC.', ephemeral: true });
      actorId = npcFighterId(npcActAs);
    }
    const mode = interaction.options?.getString?.('roll') || 'normal';
    return runFightInsight({ interaction, gid, cid, actorId, mode });
  }
  if (sub === 'disarm') {
    const mode = interaction.options?.getString?.('roll') || 'normal';
    const flavour = interaction.options?.getString?.('flavour');
    return runFightDisarm({ interaction, gid, cid, mode, flavour });
  }
  if (sub === 'deflect') {
    const redirectNpc = interaction.options?.getString?.('redirect_npc');
    // /roll's stat option offers five stats; deflection takes STR or DEX only —
    // anything else folds to the STR default (the /fight act choices already constrain).
    const statRaw = interaction.options?.getString?.('stat');
    const stat = statRaw === 'dex' ? 'dex' : 'str';
    const mode = interaction.options?.getString?.('roll') || 'normal';
    const flavour = interaction.options?.getString?.('flavour');
    return runFightDeflect({ interaction, gid, cid, stat,
      redirectId: redirectNpc ? npcFighterId(redirectNpc) : null, mode, flavour });
  }
  if (sub === 'grapple') {
    const npcActAs = interaction.options?.getString?.('npc');
    let actorId = interaction.user.id;
    if (npcActAs) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can act as an NPC.', ephemeral: true });
      actorId = npcFighterId(npcActAs);
    }
    const tUser = interaction.options?.getUser?.('target');
    const tNpc = interaction.options?.getString?.('target_npc');
    if (!tUser && !tNpc) return interaction.reply({ content: '❌ Name a target — `target:@player` or `target_npc:Name`.', ephemeral: true });
    const targetId = tNpc ? npcFighterId(tNpc) : tUser.id;
    const mode = interaction.options?.getString?.('roll') || 'normal';
    const flavour = interaction.options?.getString?.('flavour');
    return runFightGrapple({ interaction, gid, cid, actorId, targetId, mode, flavour });
  }
  if (sub === 'save') {
    const npcActAs = interaction.options?.getString?.('npc');
    let actorId = interaction.user.id;
    if (npcActAs) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can act as an NPC.', ephemeral: true });
      actorId = npcFighterId(npcActAs);
    }
    const mode = interaction.options?.getString?.('roll') || 'normal';
    return runFightGrappleSave({ interaction, gid, cid, actorId, mode });
  }
  if (sub === 'escape') {
    const npcActAs = interaction.options?.getString?.('npc');
    let actorId = interaction.user.id;
    if (npcActAs) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can act as an NPC.', ephemeral: true });
      actorId = npcFighterId(npcActAs);
    }
    const mode = interaction.options?.getString?.('roll') || 'normal';
    return runFightEscape({ interaction, gid, cid, actorId, mode });
  }
  if (sub === 'release') {
    const npcActAs = interaction.options?.getString?.('npc');
    const tUser = interaction.options?.getUser?.('target');
    const tNpc = interaction.options?.getString?.('target_npc');
    let actorId = interaction.user.id;
    if (npcActAs || tUser || tNpc) {
      if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can release as an NPC or part someone else\'s hold.', ephemeral: true });
      if (npcActAs) actorId = npcFighterId(npcActAs);
    }
    const forceTargetId = tNpc ? npcFighterId(tNpc) : (tUser ? tUser.id : null);
    return runFightRelease({ interaction, gid, cid, actorId, forceTargetId });
  }
  if (sub === 'rr') {
    let fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });

    const turnOrder = fightOrder(fight);
    const isAttacker = turnOrder[fight.turn_index] === uid;
    const isDefender = fight.current_target === uid && fight.phase === 'defend';

    if (!isAttacker && !isDefender) return interaction.reply({ content: '❌ It is not your turn to reroll.', ephemeral: true });
    // One reroll per roll: each side of an exchange gets a single second chance.
    if (isAttacker && fight.atk_rerolled) return interaction.reply({ content: '❌ You have already rerolled this attack — one reroll per roll.', ephemeral: true });
    if (isDefender && fight.def_rerolled) return interaction.reply({ content: '❌ You have already rerolled this defence — one reroll per roll.', ephemeral: true });

    // Make sure there's actually a roll to reroll BEFORE spending the token
    const stat = isAttacker ? fight.atk_stat : fight.def_stat;
    if (!stat) return interaction.reply({ content: '❌ No roll to reroll yet.', ephemeral: true });

    // Check reroll tokens
    const char = getChar(gid, uid);
    if (!char || char.rerolls_current <= 0) return interaction.reply({ content: '❌ No rerolls remaining.', ephemeral: true });
    upsertChar(gid, uid, { rerolls_current: char.rerolls_current - 1 });
    bumpFightLog(gid, cid, (log, ensure) => { ensure(uid).rr++; });

    const mode = interaction.options?.getString?.('roll') ?? 'normal';

    // Preserve whatever modifier the ORIGINAL roll used: a nat-1 fumble made the
    // defence a flat d20 (mod 0), a nat-20 riposte gave the attack +2. Those effects
    // were consumed when the first roll was made, so reconstruct the modifier from it.
    const rawStat = char?.[stat] ?? 0;
    const origTotal = isAttacker ? fight.atk_roll : fight.def_roll;
    const origNat = isAttacker ? fight.atk_nat : fight.def_nat;
    const effMod = (origTotal != null && origNat != null) ? (origTotal - origNat) : rawStat;
    // A flat-d20 defence has mod 0 while the fighter's stat is non-zero — keep it flat
    // (no stat, no advantage/disadvantage) on the reroll too.
    // A flat roll (fumbled defence, restrained/off-balance/fooled attack) stays
    // flat on the reroll: mod 0 while the fighter's real stat is non-zero.
    const isFlat = effMod === 0 && rawStat !== 0;
    const bonus = isAttacker ? Math.max(0, effMod - rawStat) : 0; // riposte carried into the reroll
    const effMode = isFlat ? 'normal' : mode;
    const modStr = isFlat ? '' : (effMod > 0 ? ` +${effMod}` : effMod < 0 ? ` ${effMod}` : '');
    const bonusTag = bonus ? ` +${bonus} riposte` : '';
    let nat, total, rollLine;
    const icon = isAttacker ? '⚔️' : '🛡️';

    if (effMode === 'adv') {
      const r1 = rollDie(20), r2 = rollDie(20);
      nat = Math.max(r1, r2); const dropped = Math.min(r1, r2);
      total = nat + effMod;
      rollLine = `${icon}  1d20+${STAT_LABELS[stat]}${bonusTag} (advantage) → [${nat}, ~~${dropped}~~]${modStr} = ${fightTotalStr(total, nat, 20)}`;
    } else if (effMode === 'dis') {
      const r1 = rollDie(20), r2 = rollDie(20);
      nat = Math.min(r1, r2); const dropped = Math.max(r1, r2);
      total = nat + effMod;
      rollLine = `${icon}  1d20+${STAT_LABELS[stat]}${bonusTag} (disadvantage) → [${nat}, ~~${dropped}~~]${modStr} = ${fightTotalStr(total, nat, 20)}`;
    } else {
      nat = rollDie(20); total = nat + effMod;
      const label = isFlat ? `${icon}  1d20 (flat — fumbled last attack)` : `${icon}  1d20+${STAT_LABELS[stat]}${bonusTag}`;
      rollLine = `${label} → [${nat}]${modStr} = ${fightTotalStr(total, nat, 20)}`;
    }
    recordRoll(gid, { userId: uid, channelId: cid, interaction,
      input: `/fight rr${mode !== 'normal' ? ` roll:${mode}` : ''}`, rollLine, nat, sides: 20, context: 'fight · reroll' });

    const member = await interaction.guild.members.fetch(uid).catch(()=>null);
    const name = member?.nickname || member?.user.username || uid;
    const lines = [`**${name}** rerolls *(reroll)* — ${isAttacker ? 'attack' : 'defence'} with ${STAT_LABELS[stat]}!`, rollLine];
    lines.push('', '⚡ Use \`/fight resolve\` to resolve this exchange.');

    if (isAttacker) {
      upsertFight(gid, cid, { atk_roll: total, atk_nat: nat, atk_mode: mode, atk_rerolled: 1 });
    } else {
      upsertFight(gid, cid, { def_roll: total, def_nat: nat, def_mode: mode, def_rerolled: 1 });
    }

    return interaction.reply({ content: lines.join('\n') });
  }

  // ── RESOLVE ────────────────────────────────────────────────────────────────
  // Rule changes here must be mirrored in autoResolveExchange (the auto-mode twin).
  if (sub === 'resolve') {
    let fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });
    if (fight.phase !== 'defend' || fight.def_roll === null) return interaction.reply({ content: '❌ Both attack and defend rolls needed before resolving.', ephemeral: true });

    // NPC reroll window in auto mode: defender may answer an incoming hit, attacker a block
    if (fight.auto_npc) {
      fight = await applyAutoNpcRerolls(interaction.guild, gid, cid, chan);
      if (!fight || fight.state !== 'active') return interaction.reply({ content: '❌ The fight is no longer active.', ephemeral: true });
    }

    const r = await resolveExchange(interaction.guild, gid, cid, fight);
    await replyLong(interaction, r.lines);
    if (r.ended) {
      await announceFightEnd(interaction.guild, gid, cid, chan, r.announce);
      return;
    }
    // Hand straight back to the bot when the next fighter is an auto-piloted NPC.
    if (fight.auto_npc && r.nextF?.isNpc) {
      await new Promise(res => setTimeout(res, 1200));
      await runAutoNpcChain(interaction.guild, gid, cid, chan);
    }
    return;
  }

  // ── FORFEIT ────────────────────────────────────────────────────────────────
  if (sub === 'forfeit') {
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });

    const turnOrder = fightOrder(fight);
    if (!turnOrder.includes(uid)) return interaction.reply({ content: '❌ You are not in this fight.', ephemeral: true });

    const member = await interaction.guild.members.fetch(uid).catch(()=>null);
    const name = member?.nickname || member?.user.username || uid;
    const hpState = fightHp(fight);

    // HP state preserved as-is; any hold they were part of breaks with them.
    const newOrder = turnOrder.filter(id => id !== uid);
    const lines = [`🏳️ **${name}** forfeits the fight! Their HP remains at **${hpState[uid] ?? 0}**.`];
    {
      const gmap = fightGrapples(fight);
      let changed = false;
      for (const [t, h] of Object.entries(gmap)) if (t === uid || h === uid) { delete gmap[t]; changed = true; }
      if (changed) { lines.push(`🤼 The hold involving **${name}** breaks.`); setFightGrapples(gid, cid, gmap); }
    }
    clearEffects(gid, cid, uid);

    let ffAnnounce = null;
    if (newOrder.length <= 1) {
      const ffFloor = fightFloor(fight);
      const ffW = fightWords(ffFloor);
      let headline = `🏳️ **${name}** conceded — the ${ffW.noun} is over.`;
      if (newOrder.length === 1) {
        const winF = await resolveFighter(interaction.guild, gid, newOrder[0]);
        headline = `🏆 **${winF.name}${winF.isNpc ? ' 🎭' : ''}** ${ffW.win} — **${name}** conceded.`;
      }
      const ffLog = JSON.parse(fight.log_state || '{}');
      archiveFight(gid, cid, ffLog, turnOrder, ffFloor);
      upsertFight(gid, cid, { state: 'idle', turn_order: '[]' });
      ffAnnounce = { headline, log: ffLog, roster: turnOrder, hpState, floor: ffFloor };
    } else {
      let newIndex = fight.turn_index % newOrder.length;
      const nextF = await resolveFighter(interaction.guild, gid, newOrder[newIndex]);
      const nextHint = nextF.isNpc ? ` (GM acts with \`npc:${nextF.name}\`)` : '';
      lines.push(`🎯 Fight continues — **${nextF.name}${nextF.isNpc ? ' 🎭' : ''}**'s turn!${nextHint}${turnPing(gid, nextF)}`);
      upsertFight(gid, cid, {
        turn_order: JSON.stringify(newOrder),
        turn_index: newIndex,
        phase: 'attack',
        current_target: null,
        atk_roll: null, atk_nat: null, def_roll: null, def_nat: null,
      });
    }

    await interaction.reply({ content: lines.join('\n') });
    if (ffAnnounce) await announceFightEnd(interaction.guild, gid, cid, chan, ffAnnounce);
    return;
  }

  // ── STATUS ─────────────────────────────────────────────────────────────────
  if (sub === 'status') {
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: false });

    const turnOrder = fightOrder(fight);
    const hpState = fightHp(fight);
    const rrState = JSON.parse(fight.rr_state || '{}');
    const fxState = JSON.parse(fight.effect_state || '{}');
    const currentId = turnOrder[fight.turn_index];
    const floor = fightFloor(fight);
    const stBanner = practiceBanner(floor);

    const lines = [floor > 0 ? '🏳️ **Practice Bout Status**' : '⚔️ **Fight Status**', ...(stBanner ? [stBanner] : []), ''];
    for (let i = 0; i < turnOrder.length; i++) {
      const fid = turnOrder[i];
      const f = await resolveFighter(interaction.guild, gid, fid);
      const rawHp = hpState[fid] ?? 0;
      const hideHp = f.isNpc && !npcStatsVisible(gid);
      const hp = hpState[fid] ?? '?';
      const arrow = fid === currentId ? ' ◀ current' : '';
      const hpMax = f.maxHp || '?';
      const rrNote = f.isNpc && fight.auto_npc ? ` · 🔁 ${rrState[fid] ?? 0}` : '';
      const fx = fxState[fid] || {};
      const fxBits = [];
      if (fx.atkBonus) fxBits.push(`✨ +${fx.atkBonus} next attack`);
      if (fx.flatDef) fxBits.push('🎲 flat-d20 next defence');
      const fxNote = fxBits.length ? ` · ${fxBits.join(' · ')}` : '';
      const hpText = hideHp ? hpCondition(rawHp, f.maxHp, floor) : `❤️ ${hp} / ${hpMax}${floor > 0 && rawHp <= floor ? ' 🏳️ yielded' : ''}`;
      lines.push(`${i+1}. **${f.name}${f.isNpc ? ' 🎭' : ''}** — ${hpText}${rrNote}${fxNote}${arrow}`);
    }
    lines.push('');
    lines.push(`Phase: **${fight.phase === 'attack' ? 'Waiting for attack' : 'Waiting for defence'}**`);
    if (fight.atk_roll) lines.push(`Latest attack roll: **${fight.atk_roll}** (${STAT_LABELS[fight.atk_stat] ?? '?'})`);
    if (fight.def_roll) lines.push(`Latest defence roll: **${fight.def_roll}** (${STAT_LABELS[fight.def_stat] ?? '?'})`);

    return interaction.reply({ content: lines.join('\n') });
  }

  // ── LOG (re-post the last finished fight's recap) ──────────────────────────
  if (sub === 'log') {
    const arch = getArchivedFight(gid, cid);
    if (!arch) return interaction.reply({ content: '📋 No finished fight recorded in this channel yet.', ephemeral: true });
    const log = JSON.parse(arch.log_state || '{}');
    const recap = await buildFightRecap(interaction.guild, gid, log);
    if (!recap.length) return interaction.reply({ content: '📋 The last fight here ended before any exchanges were resolved.', ephemeral: true });
    const archFloor = Number(arch.floor_hp ?? 0) > 0 ? Number(arch.floor_hp) : 0;
    // (recap already includes the roll tables and blow-by-blow)
    const lines = [`📜 **Last ${archFloor > 0 ? 'practice bout' : 'fight'} in this channel** — ended ${formatHistDate(arch.ended_at)}`,
                   ...(archFloor > 0 ? [`🏳️ Friendly sparring — fighters bowed out at ${archFloor} HP.`] : []),
                   ...recap.slice(1)];
    return replyLong(interaction, lines);
  }

  // ── SKIP (pass the current turn; the fighter stays in the fight) ───────────
  if (sub === 'skip') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can skip turns.', ephemeral: true });
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: NO_ACTIVE_FIGHT, ephemeral: true });
    const turnOrder = fightOrder(fight);
    const hpState = JSON.parse(fight.hp_state || '{}');
    const attackerId = turnOrder[fight.turn_index];
    const waitedOnId = fight.phase === 'defend' ? fight.current_target : attackerId;
    const waitedF = await resolveFighter(interaction.guild, gid, waitedOnId);
    const lines = [`⏭️ **${waitedF.name}${waitedF.isNpc ? ' 🎭' : ''}**'s turn skipped by the GM — they stay in the fight.`];

    const patch = {};
    if (fight.phase === 'defend') {
      Object.assign(patch, { phase: 'attack', current_target: null,
        atk_roll: null, atk_nat: null, atk_stat: null, def_roll: null, def_nat: null, def_stat: null });
      lines.push('↩️ The pending exchange was reset.');
    }
    // Advance past the current attacker, skipping anyone at or below the floor
    const skipFloor = fightFloor(fight);
    let nextIndex = (fight.turn_index + 1) % turnOrder.length;
    let safety = 0;
    while ((hpState[turnOrder[nextIndex]] ?? 0) <= skipFloor && safety < turnOrder.length) {
      nextIndex = (nextIndex + 1) % turnOrder.length; safety++;
    }
    patch.turn_index = nextIndex;
    upsertFight(gid, cid, patch);
    const nextF = await resolveFighter(interaction.guild, gid, turnOrder[nextIndex]);
    lines.push(`🎯 **${nextF.name}${nextF.isNpc ? ' 🎭' : ''}**'s turn to attack.${turnPing(gid, nextF)}`);
    return interaction.reply({ content: lines.join('\n') });
  }

  // ── END (GM only) ──────────────────────────────────────────────────────────
  if (sub === 'end') {
    if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can end a fight.', ephemeral: true });
    // One closer serves both hands: archive, idle the row, release any dc
    // binds still holding fighters in that channel, and post the recap
    // where that fight lived.
    const endOne = async (cid2, channel2, gmName) => {
      const endRow = getFight(gid, cid2);
      if (!endRow || endRow.state !== 'active') return false;
      const endLog = JSON.parse(endRow?.log_state || '{}');
      const endFloor = fightFloor(endRow);
      const endRoster = JSON.parse(endRow?.turn_order || '[]');
      const endHp = JSON.parse(endRow?.hp_state || '{}');
      archiveFight(gid, cid2, endLog, endRoster, endFloor);
      upsertFight(gid, cid2, { state: 'idle', turn_order: '[]' });
      try { db.prepare('UPDATE dc_cards SET bind_channel=NULL, bind_uid=NULL, bind_skip=0 WHERE guild_id=? AND bind_channel=?').run(gid, cid2); } catch {}
      // The throwaway cast leaves with the fight. Anyone still standing in
      // another brawl is spared — sweepTempNpcs checks before it deletes.
      try {
        const sweptT = sweepTempNpcs(gid, { client: guild?.client ?? interaction?.client ?? null });
        if (sweptT) console.log(`[temp-npcs] swept ${sweptT} after the fight in ${cid2}`);
      } catch {}
      await announceFightEnd(interaction.guild, gid, cid2, channel2, {
        headline: `🏁 Called by **${gmName}** — no victor. HP states are preserved.`,
        log: endLog, roster: endRoster, hpState: endHp, floor: endFloor,
      }).catch(() => {});
      return true;
    };
    if (interaction.options?.getBoolean?.('all')) {
      const rows = db.prepare("SELECT channel_id FROM fights WHERE guild_id=? AND state='active'").all(gid);
      if (!rows.length) return interaction.reply({ content: '❌ No active fights anywhere on the server.', ephemeral: true });
      return requestConfirm(interaction, `End **${rows.length}** active fight${rows.length === 1 ? '' : 's'} across the server? Turn orders clear; HP states are preserved.`, async () => {
        const gmName = await getDisplayName(interaction.guild, interaction.user.id);
        let ended = 0;
        for (const r of rows) {
          const ch2 = await interaction.client.channels.fetch(r.channel_id).catch(() => null);
          if (await endOne(r.channel_id, ch2, gmName)) ended++;
        }
        return `🏁 **${ended}** fight${ended === 1 ? '' : 's'} ended — recaps posted in their channels.`;
      });
    }
    const fight = getFight(gid, cid);
    if (!fight || fight.state !== 'active') return interaction.reply({ content: '❌ No active fight to end.', ephemeral: true });
    return requestConfirm(interaction, 'End the current fight? Turn order clears but HP states are preserved.', async () => {
      const gmName = await getDisplayName(interaction.guild, interaction.user.id);
      await endOne(cid, chan, gmName);
      return '🏁 Fight ended — the result and recap have been posted in the channel.';
    });
  }
}

// ─────────────────────────────────────────────
//  NPC SYSTEM
// ─────────────────────────────────────────────

async function handleNpc(interaction) {
  {
    const sub0 = interaction.options.getSubcommand();
    if (['sheet', 'give', 'take', 'npclore'].includes(sub0)) return handleNpcPages(interaction, sub0);
  }
  // The category group reuses top-level leaf names (create, list, remove),
  // so the group is read FIRST and prefixed back onto the leaf — the six
  // category branches below run unchanged, and /npc create still means an
  // NPC. /npc edit is create's update half under its own name: same body,
  // opposite existence guard.
  let sub = interaction.options.getSubcommand();
  if (interaction.options.getSubcommandGroup(false) === 'category') sub = 'category' + sub;
  // The throwaway cast folds the same way: /npc temp list → 'templist'.
  if (interaction.options.getSubcommandGroup(false) === 'temp') sub = 'temp' + sub;
  const wantsEdit = sub === 'edit';
  if (wantsEdit) sub = 'create';
  const gid = interaction.guild.id;
  const uid = interaction.user.id;

  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can manage NPCs.', ephemeral: true });

  if (sub === 'export') {
    const name = interaction.options.getString('name');
    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ No NPC called **${name}** here.`, ephemeral: true });
    await interaction.deferReply({ ephemeral: true });
    try {
      const charLike = { order_name: npc.order_name, class: npc.class, str: npc.str, con: npc.con,
        dex: npc.dex, wis: npc.wis, lck: npc.lck, hp_current: npc.hp_current, rerolls_current: npc.lck ?? 0 };
      const buf = embedSheetData(renderSheetParchment(charLike, npc.name, gid, null, true), npcPayloadObj(npc));
      const { AttachmentBuilder } = require('discord.js');
      return interaction.editReply({ content: `🎭 **${npc.name}**, packed for the road — the PDF survives Discord; \`/npc manage import\` unpacks it anywhere.`,
        files: [new AttachmentBuilder(buf, { name: `${fileSlug(npc.name, 'npc')}-npc.pdf` })] });
    } catch (err) {
      console.error('[npc] export failed -', err?.message || err);
      return interaction.editReply({ content: `❌ Couldn't pack them — ${err?.message || err}` });
    }
  }
  if (sub === 'import') {
    const att = interaction.options.getAttachment('file');
    if (!/\.(png|pdf)$/i.test(att?.name || '')) {
      return interaction.reply({ content: '❌ That isn\'t a .png or .pdf — use a file made by `/npc manage export`.', ephemeral: true });
    }
    if ((att.size ?? 0) > 8_000_000) {
      return interaction.reply({ content: '❌ That file is over 8 MB — not one of mine.', ephemeral: true });
    }
    await interaction.deferReply({ ephemeral: true });
    let bytes;
    try { bytes = await fetchBytes(att.url); }
    catch (err) {
      console.error('[npc] import fetch failed -', err?.message || err);
      return interaction.editReply({ content: `❌ Couldn't read that attachment — ${err?.message || err}` });
    }
    const imp = validateImportedNpc(extractSheetData(bytes));
    if (!imp) {
      return interaction.editReply({ content: '❌ No NPC is woven into that file — only PDFs made by `/npc manage export` carry one.' });
    }
    const existed = !!getNpc(gid, imp.name);
    // GM-direct: you clicked it, you approved it. Webhooks and standing stay local.
    upsertNpc(gid, imp.name, {
      order_name: imp.order, class: imp.class,
      str: imp.str, con: imp.con, dex: imp.dex, wis: imp.wis, lck: imp.lck,
      weapon1: imp.weapon1, weapon2: imp.weapon2,
      is_hero: imp.is_hero, signature_stat: imp.signature,
      preferred_atk: imp.atk, preferred_def: imp.def,
      lore: imp.lore, died_at: null,
      ...(imp.image ? { image_url: imp.image } : {}),
    });
    const fresh = getNpc(gid, imp.name);
    upsertNpc(gid, imp.name, { hp_current: maxHpFromCon(gid, fresh.con) });
    return interaction.editReply({ content: [
      `✅ **${imp.name}** ${existed ? 'overwritten' : 'arrives'} — HP full, ready for the board.`,
      '', ...npcCardFooter(gid, getNpc(gid, imp.name), getNpc(gid, imp.name), true),
    ].join('\n') });
  }
  if (sub === 'rename') {
    if (!(await isGm(interaction.guild, uid))) {
      return interaction.reply({ content: '❌ Renaming NPCs is for GMs.', ephemeral: true });
    }
    const from = interaction.options.getString('name');
    const to = interaction.options.getString('to')?.trim();
    const npc = getNpc(gid, from);
    if (!npc) return interaction.reply({ content: `❌ No NPC named **${from}**.`, ephemeral: true });
    if (!to) return interaction.reply({ content: '❌ Give them a name.', ephemeral: true });
    if (to.length > 50) return interaction.reply({ content: '❌ NPC name is too long (max 50 characters).', ephemeral: true });
    if (to === from) return interaction.reply({ content: '❌ That is already their name.', ephemeral: true });
    // A case-variant of another NPC is refused outright: several lookups
    // fold case (order faces, the portrait caption match), so "garrick"
    // beside "Garrick" is two rows fighting over one identity. Changing
    // only the CASE of this NPC's own name is fine and flows through.
    const clash = getAllNpcs(gid).find(n => n.name.toLowerCase() === to.toLowerCase() && n.name.toLowerCase() !== from.toLowerCase());
    if (clash) return interaction.reply({ content: `❌ **${clash.name}** already exists — that name is taken.`, ephemeral: true });
    // Fight state (turn order, hp, reroll tokens) keys by the fighter id,
    // which derives from the name — renaming mid-fight orphans all of it.
    if (fightingNpcNames(gid).has(from)) {
      return interaction.reply({ ephemeral: true, content: `❌ **${from}** is in an active fight — finish or end it first; renaming now would orphan their place in it.` });
    }
    await interaction.deferReply();

    // The rename mirrors deleteNpc's purge list as UPDATEs: everything the
    // delete would destroy under the old identity, the rename carries to
    // the new one. If purgeSubjectRecords gains a table, this list gains a
    // row — the pin below holds the two in step.
    const idOld = npcFighterId(from), idNew = npcFighterId(to);
    const moved = {};
    for (const [table, col] of [['inventory', 'user_id'], ['roll_tally', 'user_id'],
                                ['renown_log', 'user_id'], ['lore', 'user_id'],
                                ['deaths', 'subject_id'], ['quest_members', 'user_id'],
                                ['quest_summaries', 'user_id'], ['heal_charges', 'user_id'], ['history', 'user_id']]) {
      try { moved[table] = db.prepare(`UPDATE ${table} SET ${col}=? WHERE guild_id=? AND ${col}=?`).run(idNew, gid, idOld).changes; }
      catch { moved[table] = 0; }
    }
    try { db.prepare('UPDATE npcs SET name=? WHERE guild_id=? AND name=?').run(to, gid, from); } catch {}
    try { db.prepare('UPDATE npc_category_members SET npc_name=? WHERE guild_id=? AND npc_name=?').run(to, gid, from); } catch {}
    try { db.prepare('UPDATE npc_pages SET name=? WHERE guild_id=? AND name=?').run(to, gid, from); } catch {}
    try { db.prepare('UPDATE npc_portrait_posts SET npc_name=? WHERE guild_id=? AND npc_name=?').run(to, gid, from); } catch {}
    // Webhooks carry the display name baked in — cleared, not migrated;
    // the next /npc say makes fresh ones under the new name.
    try { clearNpcWebhooks(gid, from); } catch {}
    try { db.prepare('DELETE FROM npc_webhooks WHERE guild_id=? AND name=?').run(gid, from); } catch {}

    // The visible layer follows: the page entry rewrites in place, and the
    // portrait post's caption is edited so it still names its wearer.
    await mirrorNpcSheet(interaction.client, gid, to).catch(() => null);
    try {
      const pr = db.prepare('SELECT thread_id, message_id FROM npc_portrait_posts WHERE guild_id=? AND npc_name=?').get(gid, to);
      if (pr?.message_id) {
        const th = await interaction.client.channels.fetch(pr.thread_id).catch(() => null);
        const m = th?.isThread?.() ? await th.messages.fetch(pr.message_id).catch(() => null) : null;
        if (m && m.editable) await m.edit({ content: to }).catch(() => {});
      }
    } catch {}

    const carried = Object.values(moved).reduce((a, b) => a + b, 0);
    return interaction.editReply({ content:
      `📝 **${from}** is now **${to}** — page, portrait and ${carried} record${carried === 1 ? '' : 's'} followed. Their webhooks remake themselves on the next \`/npc say\`.` });
  }

  if (sub === 'create' || sub === 'pr_create') {
    const name = interaction.options.getString('name');
    if (name.length > 50) return interaction.reply({ content: '❌ NPC name is too long (max 50 characters).', ephemeral: true });
    const already = !!getNpc(gid, name);
    // Temporary NPCs are flagged at birth; the forum mirror, the roster and
    // the sweeps all read that flag rather than a second table.
    const wantTemp = interaction.options?.getBoolean?.('temp') ? 1 : 0;
    if (!wantsEdit && already) {
      return interaction.reply({ content: `❌ **${name}** already exists — \`/npc edit name:${name}\` changes them; \`/npc manage copy\` duplicates them.`, ephemeral: true });
    }
    if (wantsEdit && !already) {
      return interaction.reply({ content: `❌ No NPC named **${name}** — \`/npc create\` makes a new one.`, ephemeral: true });
    }
    const str  = interaction.options.getInteger('str');
    const con  = interaction.options.getInteger('con');
    const dex  = interaction.options.getInteger('dex');
    const wis  = interaction.options.getInteger('wis');
    const lck  = interaction.options.getInteger('lck');
    for (const [n,v] of [['STR',str],['CON',con],['DEX',dex],['WIS',wis],['LCK',lck]]) {
      if (v !== null && (v < 0 || v > 99)) return interaction.reply({ content: `❌ ${n} must be between 0 and 99.`, ephemeral: true });
    }
    const order = interaction.options.getString('order') ?? null;
    // Weapons behave like stats here: supply one to set it, "none" to clear it,
    // omit it entirely to leave whatever they already carry alone.
    const weap = {};
    const unlisted = [];
    for (const slot of ['weapon1', 'weapon2']) {
      const v = interaction.options.getString(slot);
      if (v === null) continue;
      const t = v.trim();
      if (/^(none|clear|-)$/i.test(t)) { weap[slot] = null; continue; }
      // Anything goes. A weapon on the list brings its stat rules with it;
      // anything else is simply carried, restricting nothing — better to let a
      // GM write "a broken chair leg" than to make them register it first.
      const known = getWeaponRow(gid, t);
      weap[slot] = known ? known.name : t;      // canonical casing when known
      if (!known) unlisted.push(t);
    }
    for (const [opt, col] of [['atk_stat', 'preferred_atk'], ['def_stat', 'preferred_def'], ['class', 'class']]) {
      const v = interaction.options.getString(opt);
      if (v === null) continue;
      weap[col] = (v === 'none') ? null : v;
    }
    const existed = !!getNpc(gid, name);

    // Only write what was actually supplied — omitting a stat leaves it as-is
    // (so an NPC can be registered by name now and statted up later).
    const fields = { ...weap };
    for (const [k, v] of [['str',str],['con',con],['dex',dex],['wis',wis],['lck',lck]]) {
      if (v !== null) fields[k] = v;
    }
    // Mirrors the character rule: setting LCK sets the reroll pool.
    if (lck !== null) fields.rerolls_current = lck;
    if (order) fields.order_name = order;
    upsertNpc(gid, name, fields);
    // And the White Knight gate mirrors too: order + WIS >= 5 grants the
    // server's heal charges under the fighter id; losing either zeroes
    // them. Only when the gate's own inputs move (or on creation) — an
    // unrelated stat edit must not hand a spent healer a full refill.
    if (!already || order !== null || wis !== null) {
      const after = getNpc(gid, name);
      if (isWhiteKnight(after)) setHealCharges(gid, npcFighterId(name), getConfig(gid)?.heal_charges ?? 3);
      else setHealCharges(gid, npcFighterId(name), 0);
    }

    // A brand-new NPC with no CON has 0 max HP, which would exclude them from
    // fights — start them at full so they're usable straight away.
    if (!existed) {
      const made = getNpc(gid, name);
      upsertNpc(gid, name, { hp_current: maxHpFromCon(gid, made?.con),
        ...(wantTemp ? { is_temp: 1, temp_at: Date.now() } : {}) });
    }

    const filed = fileNpcByCategory(interaction, gid, name);
    touchNpcPage(gid, name);
    const madeNpc = getNpc(gid, name);
    const orderLine = (order ? ` | ${KNIGHT_EMOJIS[order]??'⚪'} ${order}` : '')
      + (madeNpc?.class ? ` | 🏅 ${madeNpc.class}` : '');
    // Only the five stats count toward "statted up" — a class or a weapon is
    // not a stat, and counting them would suppress the hint that stats are due.
    const statsSet = Object.keys(fields).filter(k => STATS.includes(k)).length;
    const statNote = statsSet === 0
      ? '\n📋 No stats set yet — add them any time with `/npc edit name:' + name + ' str:… con:…`.'
      : statsSet < 5
        ? '\n📋 Some stats still unset (showing as 0) — fill them in later with `/npc edit`.'
        : '';
    const unlistedNote = unlisted.length
      ? `\n📝 ${unlisted.map(w => `**${w}**`).join(' and ')} ${unlisted.length === 1 ? 'is' : 'are'} not on the weapon list, so ${unlisted.length === 1 ? 'it restricts' : 'they restrict'} nothing. \`/char weapon add\` to give ${unlisted.length === 1 ? 'it' : 'them'} stat rules.`
      : '';
    await interaction.reply({ content: `✅ NPC **${name}** ${existed ? 'updated' : 'created'}.${orderLine}${statNote}${unlistedNote}${portraitHint(gid, name)}` });
    if (filed) {
      await interaction.followUp({ ephemeral: true, content:
        `\u{1f4c1} Filed under **${filed.cat}**${filed.made ? ' \u2014 a new category, made just now' : ''}.` }).catch(()=>{});
    }
    registerSlashCommands(gid).catch(console.error);
  }

  if (sub === 'delete') {
    const name = interaction.options.getString('name');
    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ NPC **${name}** not found.`, ephemeral: true });
    return requestConfirm(interaction, `Delete NPC **${name}**? This removes their stats and avatar permanently.`, async () => {
      // Delete webhook if exists
      if (npc.webhook_id && npc.webhook_token) {
        try {
          const { WebhookClient } = require('discord.js');
          const wh = new WebhookClient({ id: npc.webhook_id, token: npc.webhook_token });
          await wh.delete();
        } catch {}
      }
      // Same orphaning risk as rename: their fighter id anchors live fight
      // state. The fight has to end before they can.
      if (fightingNpcNames(gid).has(name)) {
        return interaction.reply({ ephemeral: true, content: `❌ **${name}** is in an active fight — finish or end it before deleting them.` });
      }
      deleteNpc(gid, name, interaction.client);
      registerSlashCommands(gid).catch(console.error);
      return `🗑️ NPC **${name}** deleted.`;
    });
  }

  if (sub === 'hp') {
    const name = interaction.options.getString('name');
    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ NPC **${name}** not found.`, ephemeral: true });
    const max = maxHpFromCon(gid, npc.con);
    const raw = interaction.options.getInteger('value');
    const newHp = raw === null ? max : Math.min(raw, max);
    upsertNpc(gid, npc.name, { hp_current: newHp });
    const note = raw !== null && raw > max ? ` (capped at max)` : raw === null ? ' — fully healed' : '';
    return interaction.reply({ content: `❤️ **${npc.name}** HP set to **${newHp} / ${max}**${note}.` });
  }

  if (sub === 'heal') {
    const raw = (interaction.options.getString('names') || '').trim();
    let targets;
    if (raw.toLowerCase() === 'all') {
      targets = getAllNpcs(gid);
      if (!targets.length) return interaction.reply({ content: '❌ No NPCs created yet. Use `/npc create` to add one.', ephemeral: true });
    } else {
      targets = [];
      for (const n of expandNpcList(gid, raw)) {
        const npc = getNpc(gid, n);
        if (!npc) return interaction.reply({ content: `❌ NPC **${n}** not found. Separate multiple NPCs with **commas** (e.g. \`names:Goblin, Orc\`), or use \`names:all\`.`, ephemeral: true });
        if (!targets.some(t => t.name === npc.name)) targets.push(npc);
      }
      if (!targets.length) return interaction.reply({ content: '❌ Name at least one NPC, or use `names:all`.', ephemeral: true });
    }
    const lines = targets.map(npc => {
      const max = maxHpFromCon(gid, npc.con);
      upsertNpc(gid, npc.name, { hp_current: max });
      return `❤️ **${npc.name}** — **${max} / ${max}**`;
    });
    return interaction.reply({ content: [`✨ Fully healed **${targets.length}** NPC${targets.length === 1 ? '' : 's'}:`, '', ...lines].join('\n') });
  }

  if (sub === 'copy') {
    const srcName = interaction.options.getString('name');
    const newName = (interaction.options.getString('new_name') || '').trim();
    const src = getNpc(gid, srcName);
    if (!src) return interaction.reply({ content: `❌ NPC **${srcName}** not found.`, ephemeral: true });
    if (!newName) return interaction.reply({ content: '❌ Give the copy a name.', ephemeral: true });
    if (newName.length > 60) return interaction.reply({ content: '❌ Name too long (max 60 characters).', ephemeral: true });
    if (getNpc(gid, newName)) return interaction.reply({ content: `❌ An NPC named **${getNpc(gid, newName).name}** already exists.`, ephemeral: true });
    upsertNpc(gid, newName, {
      order_name: src.order_name, str: src.str, con: src.con, dex: src.dex, wis: src.wis, lck: src.lck,
      hp_current: maxHpFromCon(gid, src.con), image_url: src.image_url ?? null,
    });
    return interaction.reply({ content: `🎭 Copied **${src.name}** → **${newName}** (fresh ❤️ ${maxHpFromCon(gid, src.con)} / ${maxHpFromCon(gid, src.con)}${src.image_url ? ', avatar carried over' : ''}).` });
  }

  if (sub === 'hero') {
    const name = interaction.options.getString('name');
    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ NPC **${name}** not found.`, ephemeral: true });
    if (interaction.options.getBoolean('remove')) {
      upsertNpc(gid, npc.name, { is_hero: 0, signature_stat: null });   // clear the flag, keep any class
      return interaction.reply({ content: `✅ **${npc.name}** is no longer a Hero.` });
    }
    const stat = interaction.options.getString('stat');
    if (!stat) {
      upsertNpc(gid, npc.name, { is_hero: 1 });
      return interaction.reply({ content: `🦸 **${npc.name}** is now a **Hero**. Give them a signature stat with \`/npc hero name:${npc.name} stat:…\`.` });
    }
    const val = npc[stat] ?? 0;
    if (val < SIGNATURE_MIN) return interaction.reply({ content: `❌ **${npc.name}**'s ${STAT_LABELS[stat]} is **${val}** — a signature stat needs **${SIGNATURE_MIN}+**.`, ephemeral: true });
    upsertNpc(gid, npc.name, { class: 'Hero', signature_stat: stat });
    return interaction.reply({ content: `⭐ **${npc.name}** is a **Hero** with signature **${STAT_LABELS[stat]}** (${val}) — their ${STAT_LABELS[stat]} rolls now have **advantage**.` });
  }

  if (sub === 'show') {
    const name = interaction.options.getString('name');
    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ NPC **${name}** not found.`, ephemeral: true });
    const cats = getCategoriesForNpc(gid, npc.name);
    const lines = [
      `🎭 **${npc.name}**${npc.order_name ? ` · ${npc.order_name}` : ''}`,
      '─────────────────────────────',
      `💪 STR ${npc.str}   🛡️ CON ${npc.con}   ⚡ DEX ${npc.dex}`,
      `🦉 WIS ${npc.wis}   🍀 LCK ${npc.lck}`,
      `❤️ HP **${npc.hp_current} / ${maxHpFromCon(gid, npc.con)}**   🔁 ${Math.max(0, npc.lck ?? 0)} reroll token${(npc.lck ?? 0) === 1 ? '' : 's'} per fight`,
      `🖼️ Avatar: ${npc.image_url ? 'set' : (sharedFaceLabelFor(gid, npc) ? `shared (${sharedFaceLabelFor(gid, npc)})` : 'none')}`,
      ...(isHero(npc) ? [`🦸 **Hero**${npc.signature_stat ? ` · ⭐ signature **${STAT_LABELS[npc.signature_stat]}**${hasSignatureAdvantage(npc, npc.signature_stat) ? ' (advantage active)' : ` (inactive — needs ${SIGNATURE_MIN}+)`}` : ''}`] : []),
    ];
    return interaction.reply({ content: lines.join('\n') });
  }

  if (sub === 'list') {
    const wantCat = (interaction.options.getString('category') || '').trim();
    const compact = interaction.options.getBoolean('compact') ?? false;
    const pg = buildNpcPage(gid, { page: 0, compact, cat: wantCat });
    if (!pg) return interaction.reply({ content: `❌ No category named **${wantCat}**. Categories: ${getCategories(gid).join(', ') || 'none'}.`, ephemeral: true });
    if (!pg.total) return interaction.reply({ ephemeral: true, content: wantCat
      ? `📁 Category **${wantCat}** has no NPCs.`
      : '❌ No NPCs created yet. Use `/npc create` to add one.' });
    return interaction.reply({ content: pg.content, components: npcPageRows(pg) });
  }

  if (sub === 'categorycreate') {
    const name = interaction.options.getString('name');
    createCategory(gid, name);
    // Both forums get a thread for it now, rather than on the first NPC —
    // so a GM can post a portrait before the statblock exists.
    ensurePortraitThreads(interaction.client, gid).catch(() => {});
    await interaction.reply({ content: `✅ Category **${name}** created. Menus updating...` });
    registerSlashCommands(gid).catch(console.error);
    return;
  }
  if (sub === 'categoryrename') {
    const name = interaction.options.getString('name');
    const to = interaction.options.getString('to')?.trim();
    if (!getCategories(gid).includes(name)) return interaction.reply({ content: `\u274c Category **${name}** not found.`, ephemeral: true });
    if (!to) return interaction.reply({ content: '\u274c Give it a name.', ephemeral: true });
    if (to.toLowerCase() !== name.toLowerCase() && getCategories(gid).some(c => c.toLowerCase() === to.toLowerCase())) {
      return interaction.reply({ content: `\u274c **${to}** already exists \u2014 merging categories is a different thing. Move the NPCs with \`/npc category assign\` and delete the empty one.`, ephemeral: true });
    }
    await interaction.deferReply();
    // In place, not delete-and-recreate: membership rows keep their rowids,
    // and rowid order is what decides every member's HOME category \u2014 a
    // recreate would re-home NPCs who hold this as their first category.
    db.prepare('UPDATE npc_categories SET name=? WHERE guild_id=? AND name=?').run(to, gid, name);
    // The pages-forum TAG renames with it — the tag keeps its id, so every
    // NPC thread wearing it follows for free.
    try {
      const forumId = getConfig(gid)?.npc_forum;
      const forum = forumId ? await interaction.client.channels.fetch(forumId).catch(() => null) : null;
      if (forum?.type === 15) {
        const tags = (await forum.fetch().catch(() => forum)).availableTags || [];
        if (tags.some(t => t.name.toLowerCase() === name.toLowerCase())) {
          await forum.setAvailableTags(tags.map(t => t.name.toLowerCase() === name.toLowerCase()
            ? { ...t, name: to.slice(0, 20) } : t)).catch(() => {});
        }
      }
    } catch {}
    db.prepare('UPDATE npc_category_members SET category=? WHERE guild_id=? AND category=?').run(to, gid, name);
    for (const table of Object.values(NPC_THREAD_TABLES)) {
      db.prepare(`UPDATE ${table} SET category=? WHERE guild_id=? AND category=?`).run(to, gid, name);
      // The thread itself follows. Best-effort: renames are rate-limited to
      // roughly two per ten minutes per thread, so a second rename inside
      // that window keeps the mapping and catches up on the next sweep.
      try {
        const row = db.prepare(`SELECT thread_id FROM ${table} WHERE guild_id=? AND category=?`).get(gid, to);
        if (row?.thread_id) {
          const th = await interaction.client.channels.fetch(row.thread_id).catch(() => null);
          if (th?.isThread?.()) await th.setName(to.slice(0, 100)).catch(() => {});
        }
      } catch {}
    }
    // The forum tag carries the category's name in the sidebar filter.
    try {
      const forum = await interaction.client.channels.fetch(getConfig(gid)?.npc_forum).catch(() => null);
      if (forum?.availableTags?.some(t => t.name.toLowerCase() === name.toLowerCase())) {
        await forum.setAvailableTags(forum.availableTags.map(t =>
          t.name.toLowerCase() === name.toLowerCase() ? { ...t, name: to.slice(0, 20) } : t)).catch(() => {});
      }
    } catch {}
    registerSlashCommands(gid).catch(console.error);
    return interaction.editReply({ content: `\u270f\ufe0f **${name}** is now **${to}** \u2014 members, threads and tags followed. Menus updating...` });
  }
  if (sub === 'categorydelete') {
    const name = interaction.options.getString('name');
    if (!getCategories(gid).includes(name)) return interaction.reply({ content: `❌ Category **${name}** not found.`, ephemeral: true });
    return requestConfirm(interaction, `Delete category **${name}**? NPCs in it won't be deleted — they'll just become uncategorised.`, async () => {
      // Who is about to lose their home. Read before the membership rows go.
      const orphans = getNpcsInCategory(gid, name);
      deleteCategory(gid, name);
      // The pages-forum tag retires with the category; Discord strips a
      // removed tag from every thread wearing it.
      try {
        const forumId = getConfig(gid)?.npc_forum;
        const forum = forumId ? await client.channels.fetch(forumId).catch(() => null) : null;
        if (forum?.type === 15) {
          const tags = (await forum.fetch().catch(() => forum)).availableTags || [];
          if (tags.some(t => t.name.toLowerCase() === name.toLowerCase())) {
            await forum.setAvailableTags(tags.filter(t => t.name.toLowerCase() !== name.toLowerCase())).catch(() => {});
          }
        }
      } catch {}
      registerSlashCommands(gid).catch(console.error);
      // Close the category's thread in both forums and drop the mappings.
      // The NPCs themselves re-home on the mirror pass below — their entries
      // move to wherever they now belong, Uncategorised included.
      (async () => {
        try {
          for (const table of Object.values(NPC_THREAD_TABLES)) {
            const row = db.prepare(`SELECT thread_id FROM ${table} WHERE guild_id=? AND category=?`).get(gid, name);
            if (row?.thread_id) {
              const th = await client.channels.fetch(row.thread_id).catch(() => null);
              if (th?.isThread?.()) await th.delete(`Category "${name}" deleted`).catch(() => {});
            }
            db.prepare(`DELETE FROM ${table} WHERE guild_id=? AND category=?`).run(gid, name);
          }
          for (const npcName of orphans) await mirrorNpcSheet(client, gid, npcName).catch(() => null);
        } catch (err) { console.error('[npcforum] category sweep -', err?.message || err); }
      })();
      return `🗑️ Category **${name}** deleted. Its threads are closing; the NPCs in it are moving to their next category.`;
    });
  }
  if (sub === 'templist') {
    const temps = getTempNpcs(gid);
    if (!temps.length) return interaction.reply({ ephemeral: true, content: '\u{1F5FF} No temporary NPCs are lying about.' });
    return interaction.reply({ ephemeral: true, content: ['\u{1F5FF} **The throwaway cast**', ...temps.map(t =>
      `\u2022 **${t.name}** \u2014 HP ${t.hp_current}${t.max_hp ? `/${t.max_hp}` : ''}${fightingNpcNames(gid).includes(t.name.toLowerCase()) ? ' \u00b7 _in a fight_' : ''}`),
      '', '_`/npc temp keep` makes one permanent \u00b7 `/npc temp clear` sweeps the rest._'].join('\n') });
  }

  if (sub === 'tempkeep') {
    if (!gm) return interaction.reply({ content: '\u274C Only GMs can keep an NPC.', ephemeral: true });
    const nameK = interaction.options.getString('name').trim();
    const npcK = getNpc(gid, nameK);
    if (!npcK || !npcK.is_temp) return interaction.reply({ ephemeral: true, content: `\u274C **${nameK}** is not a temporary NPC.` });
    upsertNpc(gid, npcK.name, { is_temp: 0 });
    // Promotion is the one moment a throwaway earns a page.
    mirrorNpcSheet(interaction.client, gid, npcK.name).catch(() => {});
    return interaction.reply({ content: `\u2705 **${npcK.name}** joins the cast \u2014 they have a page now.` });
  }

  if (sub === 'tempclear') {
    if (!gm) return interaction.reply({ content: '\u274C Only GMs can sweep.', ephemeral: true });
    const swept = sweepTempNpcs(gid, { force: true });
    return interaction.reply({ ephemeral: true, content: swept
      ? `\u{1F9F9} Swept **${swept}** temporary NPC${swept === 1 ? '' : 's'} away.`
      : '\u{1F5FF} There was nothing to sweep.' });
  }

  if (sub === 'categorylist') {
    const cats = getCategories(gid);
    const uncategorised = getUncategorisedNpcs(gid);
    const lines2 = ['**📂 NPC Categories:**', ''];
    cats.forEach(c => { const m = getNpcsInCategory(gid, c); lines2.push(`• **${c}** (${m.length}): ${m.join(', ')||'empty'}`); });
    if (uncategorised.length) lines2.push(`• **Uncategorised** (${uncategorised.length}): ${uncategorised.join(', ')}`);
    return interaction.reply({ content: lines2.join('\n') });
  }
  if (sub === 'categoryassign') {
    const npcName = interaction.options.getString('npc');
    const category = interaction.options.getString('category');
    if (!getNpc(gid, npcName)) return interaction.reply({ content: `❌ NPC **${npcName}** not found.`, ephemeral: true });
    if (!getCategories(gid).includes(category)) return interaction.reply({ content: `❌ Category **${category}** not found.`, ephemeral: true });
    assignNpcToCategory(gid, npcName, category);
    await interaction.reply({ content: `✅ **${npcName}** added to **${category}**. Menus updating...` });
    mirrorNpcSheet(interaction.client, gid, npcName).catch(() => {});  // tags follow on the spot
    registerSlashCommands(gid).catch(console.error);
    return;
  }
  if (sub === 'categoryremove') {
    const npcName = interaction.options.getString('npc');
    const category = interaction.options.getString('category');
    removeNpcFromCategory(gid, npcName, category);
    await interaction.reply({ content: `✅ **${npcName}** removed from **${category}**. Menus updating...` });
    mirrorNpcSheet(interaction.client, gid, npcName).catch(() => {});  // tags follow on the spot
    registerSlashCommands(gid).catch(console.error);
    return;
  }
}

async function handlePr(interaction) {
  const sub = interaction.options.getSubcommand();
  const gid = interaction.guild.id;
  const uid = interaction.user.id;

  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can use NPC commands.', ephemeral: true });

  // Delegate create/delete/list to handleNpc
  if (sub === 'create' || sub === 'delete' || sub === 'list') {
    return handleNpc(interaction);
  }

  if (sub === 'sync') {
    if (!getConfig(gid)?.npc_forum) {
      return interaction.reply({ ephemeral: true, content: '❌ No NPC forum set — `/config channels npcforum channel:#your-forum` first.' });
    }
    const one = interaction.options.getString('name');
    const list = one ? [getNpc(gid, one)].filter(Boolean) : getAllNpcs(gid);
    if (!list.length) return interaction.reply({ content: one ? `❌ No NPC called **${one}**.` : '❌ No NPCs yet.', ephemeral: true });
    await interaction.deferReply({ ephemeral: true });
    let done = 0, failed = 0;
    for (const n of list) {
      try { await mirrorNpcSheet(interaction.client, gid, n.name); done++; }
      catch { failed++; }
    }
    return interaction.editReply({ content: `🎭 Wrote up **${done}** NPC${done === 1 ? '' : 's'}${failed ? ` · ${failed} failed` : ''}.` });
  }

  if (sub === 'create5e') return handleNpcCreate5e(interaction);

  if (sub === 'reroll') {
    const name     = interaction.options.getString('name');
    const rollType = interaction.options.getString('roll') ?? 'normal';
    const mode     = rollType === 'adv' ? 'adv' : rollType === 'dis' ? 'dis' : 'normal';

    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ NPC **${name}** not found.`, ephemeral: true });

    // Check NPC reroll tokens (based on LCK)
    if ((npc.rerolls_current ?? 0) <= 0) return interaction.reply({ content: `❌ **${name}** has no reroll tokens left (pool ${npc.lck ?? 0}, from LCK) — rest refills them.`, ephemeral: true });

    // Get last roll for this NPC in this channel
    const last = getLastRoll(gid, interactionChannelId(interaction), `npc_${name}`);
    if (!last) return interaction.reply({ content: `❌ No previous roll found for **${name}** in this channel.`, ephemeral: true });

    // Deduct reroll — track via hp_current field repurposed as reroll tracker
    // The pool is rerolls_current, refilled by rest. The old line here
    // decremented the LCK stat itself and nothing ever restored it — an NPC
    // that rerolled lost real Luck, permanently.
    upsertNpc(gid, name, { rerolls_current: (npc.rerolls_current ?? 0) - 1 });

    let result;
    if (mode === 'adv') result = rollAdvantage(last.notation);
    else if (mode === 'dis') result = rollDisadvantage(last.notation);
    else result = rollNotation(last.notation);
    if (!result) return interaction.reply({ content: '❌ Could not reroll.', ephemeral: true });

    const updatedNpc = getNpc(gid, name);
    saveRoll(gid, interactionChannelId(interaction), `npc_${name}`, last.notation, last.label);

    const critType = detectCrit(result, mode);
    const rollLine = maskNpcRollLine(gid, buildRollLine(result, mode, critType, null));
    const auditCard = [
      last.label ? `${critPrefix(critType)}**${last.label}** *(reroll)*` : '*(reroll)*',
      buildRollLine(result, mode, critType, null),
      '',
      ...npcCardFooter(gid, npc, updatedNpc, true),
    ].join('\n');
    recordRoll(gid, { userId: interaction.user.id, channelId: interactionChannelId(interaction), interaction, result,
      kind: 'npcs', card: auditCard,
      input: `/npc reroll ${last.notation}${last.label ? ' ' + last.label : ''}`,
      rollLine: buildRollLine(result, mode, critType, null),
      context: `as NPC **${npc.name}** · reroll` });
    const lines = [];
    if (last.label) lines.push(`${critPrefix(critType)}**${last.label}** *(reroll)*`);
    else lines.push('*(reroll)*');
    lines.push(rollLine, '');
    lines.push(...npcCardFooter(gid, npc, updatedNpc));

    const content2 = lines.join('\n');

    try {
      const { WebhookClient } = require('discord.js');
      await interaction.deferReply({ ephemeral: true });
      const prChan = await interactionChannel(interaction);
      if (!prChan) return interaction.editReply({ content: MSG_NO_ACCESS }).catch(()=>{});
      const webhookClient = await npcWebhookIn(prChan, gid, npc.name, npcFace(gid, npc));
      await webhookClient.send({ content: content2 });
      return interaction.editReply({ content: `✅ Rerolled as **${npc.name}**. Rerolls remaining: ${updatedNpc.lck}` });
    } catch (err) {
      console.error('Webhook error:', err);
      return interaction.reply({ content: content2 });
    }
  }

  if (sub === 'say') {
    {
      // Roleplay included: a fallen NPC has no more lines.
      const npcName0 = (interaction.options.getString('name') || '').trim();
      const gate0 = npcName0 ? deathGate(gid, npcFighterId(npcName0)) : null;
      if (gate0) return interaction.reply({ content: gate0, ephemeral: true });
    }
    const name = interaction.options.getString('name');
    const action = interaction.options.getString('action');
    const speech = interaction.options.getString('speech');
    const raw = interaction.options.getString('raw');
    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ NPC **${name}** not found. Create one with \`/npc create\`.`, ephemeral: true });

    // Nothing supplied → open a proper writing box with multi-line fields.
    if (!action && !speech && !raw) {
      const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
      const modal = new ModalBuilder()
        .setCustomId(`npcsay:${npc.name}`.slice(0, 100))
        .setTitle(`Speak as ${npc.name}`.slice(0, 45));
      const actionInput = new TextInputBuilder()
        .setCustomId('action').setLabel('Action (optional)')
        .setPlaceholder('draws his blade').setStyle(TextInputStyle.Paragraph)
        .setRequired(false).setMaxLength(900);
      const speechInput = new TextInputBuilder()
        .setCustomId('speech').setLabel('Speech (optional)')
        .setPlaceholder('Halt! Who goes there?').setStyle(TextInputStyle.Paragraph)
        .setRequired(false).setMaxLength(900);
      modal.addComponents(
        new ActionRowBuilder().addComponents(actionInput),
        new ActionRowBuilder().addComponents(speechInput),
      );
      return interaction.showModal(modal);
    }

    const text = composeNpcSay({ action, speech, raw });
    if (!text) return interaction.reply({ content: '❌ Nothing to post.', ephemeral: true });
    if (text.length > 1800) return interaction.reply({ content: '❌ Message too long (max 1800 characters).', ephemeral: true });

    const body = text;

    const chan = await interactionChannel(interaction);
    if (!chan) return interaction.reply({ content: MSG_NO_ACCESS, ephemeral: true });
    const said = await postAsNpc(chan, gid, npc.name, body);
    if (!said) return interaction.reply({ content: `❌ I couldn't post in this channel — check my permissions here.`, ephemeral: true });
    mirrorNpcSay(gid, { gmId: interaction.user.id, npcName: npc.name, channelId: chan.id,
      messageId: said?.id ?? null, text: body });
    return interaction.reply({ content: `🎭 Spoke as **${npc.name}**.`, ephemeral: true });
  }

  if (sub === 'roll') {
    {
      const npcName0 = (interaction.options.getString('name') || '').trim();
      const gate0 = npcName0 ? deathGate(gid, npcFighterId(npcName0)) : null;
      if (gate0) return interaction.reply({ content: gate0, ephemeral: true });
    }
    const category = interaction.options.getString('category') ?? 'all';
    const name     = interaction.options.getString('name');
    // Creating an NPC's webhook is slow; defer so we never miss the 3s ack.
    let prDeferred = false;
    const notationRaw = interaction.options.getString('notation') ?? '1d20';
    const stat     = interaction.options.getString('stat') ?? null;

    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ NPC **${name}** not found.`, ephemeral: true });

    // Validate NPC is in selected category
    if (category !== 'all') {
      const npcCats = getCategoriesForNpc(gid, name);
      const inCategory = category === 'Uncategorised' ? npcCats.length === 0 : npcCats.includes(category);
      if (!inCategory) return interaction.reply({ content: `❌ **${name}** is not in the **${category}** category.`, ephemeral: true });
    }
    await interaction.deferReply({ ephemeral: true }).catch(()=>{});
    prDeferred = true;

    const labelRaw = interaction.options.getString('label') ?? null;
    const flavour  = interaction.options.getString('flavour') ?? null;
    const rollType = interaction.options.getString('roll') ?? 'normal';
    const mode     = rollType === 'adv' ? 'adv' : rollType === 'dis' ? 'dis' : 'normal';
    // Combine stat and label: stat first, then label, separated by ' — '
    const label = stat && labelRaw ? `${stat} — ${labelRaw}` : stat ?? labelRaw ?? null;

    // Apply stat modifier to notation
    let notation = notationRaw;
    if (stat) {
      const statKey = stat.toLowerCase();
      const statVal = npc[statKey] ?? 0;
      if (statVal !== 0) {
        // Check if notation already has a modifier
        if (/[+-]\d+$/.test(notation)) {
          notation = notation + (statVal >= 0 ? `+${statVal}` : `${statVal}`);
        } else {
          notation = notation + (statVal >= 0 ? `+${statVal}` : `${statVal}`);
        }
      }
    }

    let result;
    if (mode === 'adv') result = rollAdvantage(notation);
    else if (mode === 'dis') result = rollDisadvantage(notation);
    else result = rollNotation(notation);
    if (!result) return interaction.editReply({ content: '❌ Invalid dice notation.' });

    const critType = detectCrit(result, mode);
    const rollLine = maskNpcRollLine(gid, buildRollLine(result, mode, critType, null));
    // Posted through the NPC's webhook, so the audit is the only place this ties
    // back to the GM who actually rolled it — as the full card, fully revealed.
    const auditCard = [
      ...(label ? [`${critPrefix(critType)}**${label}**`] : []),
      buildRollLine(result, mode, critType, null),
      '',
      ...npcCardFooter(gid, npc, npc, true),
    ].join('\n');
    recordRoll(gid, { userId: interaction.user.id, channelId: interactionChannelId(interaction), interaction, result,
      kind: 'npcs', card: auditCard,
      input: `/npc roll ${notation}${label ? ' ' + label : ''}`,
      rollLine: buildRollLine(result, mode, critType, null),
      context: `as NPC **${npc.name}**` });

    // Build embed text
    const lines = [];
    if (label) lines.push(`${critPrefix(critType)}**${label}**`);
    lines.push(rollLine);
    lines.push('');
    lines.push(...npcCardFooter(gid, npc));
    if (flavour) {
      lines.push('');
      lines.push('─────────────────────────────');
      lines.push(`**${label??'roll'}** — ${totalStr(result.total, critType)}`);
      lines.push(flavour);
    }
    const content = lines.join('\n');

    // Save roll history for NPC reroll
    saveRoll(gid, interactionChannelId(interaction), `npc_${npc.name}`, notation, label);

    // Get or create webhook for this NPC
    try {
      const prChan2 = await interactionChannel(interaction);
      if (!prChan2) return interaction.editReply({ content: MSG_NO_ACCESS }).catch(()=>{});
      // Webhook for THIS channel — otherwise the post lands wherever the NPC
      // first spoke, which looked like "nothing happened".
      const webhookClient = await npcWebhookIn(prChan2, gid, npc.name, npcFace(gid, npc));

      await webhookClient.send({
        content,
        username: npc.name,
        avatarURL: npcFace(gid, npc) ?? BLANK_AVATAR,
      });
      return interaction.editReply({ content: `✅ Posted as **${npc.name}**.` });
    } catch (err) {
      console.error('Webhook error:', err);
      // A stored webhook may have been deleted server-side — drop it and retry.
      const fallbackChan = await interactionChannel(interaction);
      if (fallbackChan) {
        try {
          const hostChan = webhookHost(fallbackChan);
          db.prepare('DELETE FROM npc_webhooks WHERE guild_id=? AND channel_id=? AND npc_name=?')
            .run(gid, hostChan?.id ?? fallbackChan.id, npc.name);
          const face3 = npcFace(gid, npc);
          const fresh = await npcWebhookIn(fallbackChan, gid, npc.name, face3);
          await fresh.send({ content, username: npc.name, avatarURL: face3 ?? BLANK_AVATAR });
          return interaction.editReply({ content: `✅ Posted as **${npc.name}**.` }).catch(()=>{});
        } catch (err2) {
          console.error('Webhook retry failed:', err2.message);
          const host = webhookHost(fallbackChan);
          const where = host && host.id !== fallbackChan.id ? ` on the parent channel <#${host.id}>` : '';
          await interaction.editReply({ content:
            `⚠️ Couldn't speak as **${npc.name}** — posted as me instead.\n`
            + `_I need **Manage Webhooks**${where} for NPC voices. In a thread the webhook has to live on the parent._`
          }).catch(()=>{});
          await fallbackChan.send({ content }).catch(()=>{});
        }
      }
    }
  }
}


